INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141000, '《中华人民共和国职业教育法》', '第一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第一章 总 则', NULL, '为了推动职业教育高质量发展，提高劳动者素质和技术技能水平，促进就业创业，建设教育强国、人力资源强国和技能型社会，推进社会主义现代化建设，根据宪法，制定本法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141001, '《中华人民共和国职业教育法》', '第二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第一章 总 则', NULL, '本法所称职业教育，是指为了培养高素质技术技能人才，使受教育者具备从事某种职业或者实现职业发展所需要的职业道德、科学文化与专业知识、技术技能等职业综合素质和行动能力而实施的教育，包括职业学校教育和职业培训。 机关、事业单位对其工作人员实施的专门培训由法律、行政法规另行规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141002, '《中华人民共和国职业教育法》', '第三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第一章 总 则', NULL, '职业教育是与普通教育具有同等重要地位的教育类型，是国民教育体系和人力资源开发的重要组成部分，是培养多样化人才、传承技术技能、促进就业创业的重要途径。 国家大力发展职业教育，推进职业教育改革，提高职业教育质量，增强职业教育适应性，建立健全适应社会主义市场经济和社会发展需要、符合技术技能人才成长规律的职业教育制度体系，为全面建设社会主义现代化国家提供有力人才和技能支撑。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141003, '《中华人民共和国职业教育法》', '第四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第一章 总 则', NULL, '职业教育必须坚持中国共产党的领导，坚持社会主义办学方向，贯彻国家的教育方针，坚持立德树人、德技并修，坚持产教融合、校企合作，坚持面向市场、促进就业，坚持面向实践、强化能力，坚持面向人人、因材施教。 实施职业教育应当弘扬社会主义核心价值观，对受教育者进行思想政治教育和职业道德教育，培育劳模精神、劳动精神、工匠精神，传授科学文化与专业知识，培养技术技能，进行职业指导，全面提高受教育者的素质。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141004, '《中华人民共和国职业教育法》', '第五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第一章 总 则', NULL, '公民有依法接受职业教育的权利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141005, '《中华人民共和国职业教育法》', '第六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第一章 总 则', NULL, '职业教育实行政府统筹、分级管理、地方为主、行业指导、校企合作、社会参与。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141006, '《中华人民共和国职业教育法》', '第七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第一章 总 则', NULL, '各级人民政府应当将发展职业教育纳入国民经济和社会发展规划，与促进就业创业和推动发展方式转变、产业结构调整、技术优化升级等整体部署、统筹实施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141007, '《中华人民共和国职业教育法》', '第八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第一章 总 则', NULL, '国务院建立职业教育工作协调机制，统筹协调全国职业教育工作。 国务院教育行政部门负责职业教育工作的统筹规划、综合协调、宏观管理。国务院教育行政部门、人力资源社会保障行政部门和其他有关部门在国务院规定的职责范围内，分别负责有关的职业教育工作。 省、自治区、直辖市人民政府应当加强对本行政区域内职业教育工作的领导，明确设区的市、县级人民政府职业教育具体工作职责，统筹协调职业教育发展，组织开展督导评估。 县级以上地方人民政府有关部门应当加强沟通配合，共同推进职业教育工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141008, '《中华人民共和国职业教育法》', '第九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第一章 总 则', NULL, '国家鼓励发展多种层次和形式的职业教育，推进多元办学，支持社会力量广泛、平等参与职业教育。 国家发挥企业的重要办学主体作用，推动企业深度参与职业教育，鼓励企业举办高质量职业教育。 有关行业主管部门、工会和中华职业教育社等群团组织、行业组织、企业、事业单位等应当依法履行实施职业教育的义务，参与、支持或者开展职业教育。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141009, '《中华人民共和国职业教育法》', '第十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第一章 总 则', NULL, '国家采取措施，大力发展技工教育，全面提高产业工人素质。 国家采取措施，支持举办面向农村的职业教育，组织开展农业技能培训、返乡创业就业培训和职业技能培训，培养高素质乡村振兴人才。 国家采取措施，扶持革命老区、民族地区、边远地区、欠发达地区职业教育的发展。 国家采取措施，组织各类转岗、再就业、失业人员以及特殊人群等接受各种形式的职业教育，扶持残疾人职业教育的发展。 国家保障妇女平等接受职业教育的权利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141010, '《中华人民共和国职业教育法》', '第十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第一章 总 则', NULL, '实施职业教育应当根据经济社会发展需要，结合职业分类、职业标准、职业发展需求，制定教育标准或者培训方案，实行学历证书及其他学业证书、培训证书、职业资格证书和职业技能等级证书制度。 国家实行劳动者在就业前或者上岗前接受必要的职业教育的制度。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141011, '《中华人民共和国职业教育法》', '第十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第一章 总 则', NULL, '国家采取措施，提高技术技能人才的社会地位和待遇，弘扬劳动光荣、技能宝贵、创造伟大的时代风尚。 国家对在职业教育工作中做出显著成绩的单位和个人按照有关规定给予表彰、奖励。 每年5月的第二周为职业教育活动周。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141012, '《中华人民共和国职业教育法》', '第十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第一章 总 则', NULL, '国家鼓励职业教育领域的对外交流与合作，支持引进境外优质资源发展职业教育，鼓励有条件的职业教育机构赴境外办学，支持开展多种形式的职业教育学习成果互认。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141013, '《中华人民共和国职业教育法》', '第十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第二章 职业教育体系', NULL, '国家建立健全适应经济社会发展需要，产教深度融合，职业学校教育和职业培训并重，职业教育与普通教育相互融通，不同层次职业教育有效贯通，服务全民终身学习的现代职业教育体系。 国家优化教育结构，科学配置教育资源，在义务教育后的不同阶段因地制宜、统筹推进职业教育与普通教育协调发展。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141014, '《中华人民共和国职业教育法》', '第十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第二章 职业教育体系', NULL, '职业学校教育分为中等职业学校教育、高等职业学校教育。 中等职业学校教育由高级中等教育层次的中等职业学校（含技工学校）实施。 高等职业学校教育由专科、本科及以上教育层次的高等职业学校和普通高等学校实施。根据高等职业学校设置制度规定，将符合条件的技师学院纳入高等职业学校序列。 其他学校、教育机构或者符合条件的企业、行业组织按照教育行政部门的统筹规划，可以实施相应层次的职业学校教育或者提供纳入人才培养方案的学分课程。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141015, '《中华人民共和国职业教育法》', '第十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第二章 职业教育体系', NULL, '职业培训包括就业前培训、在职培训、再就业培训及其他职业性培训，可以根据实际情况分级分类实施。 职业培训可以由相应的职业培训机构、职业学校实施。 其他学校或者教育机构以及企业、社会组织可以根据办学能力、社会需求，依法开展面向社会的、多种形式的职业培训。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141016, '《中华人民共和国职业教育法》', '第十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第二章 职业教育体系', NULL, '国家建立健全各级各类学校教育与职业培训学分、资历以及其他学习成果的认证、积累和转换机制，推进职业教育国家学分银行建设，促进职业教育与普通教育的学习成果融通、互认。 军队职业技能等级纳入国家职业资格认证和职业技能等级评价体系。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141017, '《中华人民共和国职业教育法》', '第十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第二章 职业教育体系', NULL, '残疾人职业教育除由残疾人教育机构实施外，各级各类职业学校和职业培训机构及其他教育机构应当按照国家有关规定接纳残疾学生，并加强无障碍环境建设，为残疾学生学习、生活提供必要的帮助和便利。 国家采取措施，支持残疾人教育机构、职业学校、职业培训机构及其他教育机构开展或者联合开展残疾人职业教育。 从事残疾人职业教育的特殊教育教师按照规定享受特殊教育津贴。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141018, '《中华人民共和国职业教育法》', '第十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第二章 职业教育体系', NULL, '县级以上人民政府教育行政部门应当鼓励和支持普通中小学、普通高等学校，根据实际需要增加职业教育相关教学内容，进行职业启蒙、职业认知、职业体验，开展职业规划指导、劳动教育，并组织、引导职业学校、职业培训机构、企业和行业组织等提供条件和支持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141019, '《中华人民共和国职业教育法》', '第二十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第三章 职业教育的实施', NULL, '国务院教育行政部门会同有关部门根据经济社会发展需要和职业教育特点，组织制定、修订职业教育专业目录，完善职业教育教学等标准，宏观管理指导职业学校教材建设。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141020, '《中华人民共和国职业教育法》', '第二十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第三章 职业教育的实施', NULL, '县级以上地方人民政府应当举办或者参与举办发挥骨干和示范作用的职业学校、职业培训机构，对社会力量依法举办的职业学校和职业培训机构给予指导和扶持。 国家根据产业布局和行业发展需要，采取措施，大力发展先进制造等产业需要的新兴专业，支持高水平职业学校、专业建设。 国家采取措施，加快培养托育、护理、康养、家政等方面技术技能人才。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141021, '《中华人民共和国职业教育法》', '第二十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第三章 职业教育的实施', NULL, '县级人民政府可以根据县域经济社会发展的需要，设立职业教育中心学校，开展多种形式的职业教育，实施实用技术培训。 教育行政部门可以委托职业教育中心学校承担教育教学指导、教育质量评价、教师培训等职业教育公共管理和服务工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141022, '《中华人民共和国职业教育法》', '第二十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第三章 职业教育的实施', NULL, '行业主管部门按照行业、产业人才需求加强对职业教育的指导，定期发布人才需求信息。 行业主管部门、工会和中华职业教育社等群团组织、行业组织可以根据需要，参与制定职业教育专业目录和相关职业教育标准，开展人才需求预测、职业生涯发展研究及信息咨询，培育供需匹配的产教融合服务组织，举办或者联合举办职业学校、职业培训机构，组织、协调、指导相关企业、事业单位、社会组织举办职业学校、职业培训机构。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141023, '《中华人民共和国职业教育法》', '第二十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第三章 职业教育的实施', NULL, '企业应当根据本单位实际，有计划地对本单位的职工和准备招用的人员实施职业教育，并可以设置专职或者兼职实施职业教育的岗位。 企业应当按照国家有关规定实行培训上岗制度。企业招用的从事技术工种的劳动者，上岗前必须进行安全生产教育和技术培训；招用的从事涉及公共安全、人身健康、生命财产安全等特定职业（工种）的劳动者，必须经过培训并依法取得职业资格或者特种作业资格。 企业开展职业教育的情况应当纳入企业社会责任报告。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141024, '《中华人民共和国职业教育法》', '第二十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第三章 职业教育的实施', NULL, '企业可以利用资本、技术、知识、设施、设备、场地和管理等要素，举办或者联合举办职业学校、职业培训机构。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141025, '《中华人民共和国职业教育法》', '第二十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第三章 职业教育的实施', NULL, '国家鼓励、指导、支持企业和其他社会力量依法举办职业学校、职业培训机构。 地方各级人民政府采取购买服务，向学生提供助学贷款、奖助学金等措施，对企业和其他社会力量依法举办的职业学校和职业培训机构予以扶持；对其中的非营利性职业学校和职业培训机构还可以采取政府补贴、基金奖励、捐资激励等扶持措施，参照同级同类公办学校生均经费等相关经费标准和支持政策给予适当补助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141026, '《中华人民共和国职业教育法》', '第二十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第三章 职业教育的实施', NULL, '对深度参与产教融合、校企合作，在提升技术技能人才培养质量、促进就业中发挥重要主体作用的企业，按照规定给予奖励；对符合条件认定为产教融合型企业的，按照规定给予金融、财政、土地等支持，落实教育费附加、地方教育附加减免及其他税费优惠。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141027, '《中华人民共和国职业教育法》', '第二十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第三章 职业教育的实施', NULL, '联合举办职业学校、职业培训机构的，举办者应当签订联合办学协议，约定各方权利义务。 地方各级人民政府及行业主管部门支持社会力量依法参与联合办学，举办多种形式的职业学校、职业培训机构。 行业主管部门、工会等群团组织、行业组织、企业、事业单位等委托学校、职业培训机构实施职业教育的，应当签订委托合同。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141028, '《中华人民共和国职业教育法》', '第二十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第三章 职业教育的实施', NULL, '县级以上人民政府应当加强职业教育实习实训基地建设，组织行业主管部门、工会等群团组织、行业组织、企业等根据区域或者行业职业教育的需要建设高水平、专业化、开放共享的产教融合实习实训基地，为职业学校、职业培训机构开展实习实训和企业开展培训提供条件和支持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141029, '《中华人民共和国职业教育法》', '第三十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第三章 职业教育的实施', NULL, '国家推行中国特色学徒制，引导企业按照岗位总量的一定比例设立学徒岗位，鼓励和支持有技术技能人才培养能力的企业特别是产教融合型企业与职业学校、职业培训机构开展合作，对新招用职工、在岗职工和转岗职工进行学徒培训，或者与职业学校联合招收学生，以工学结合的方式进行学徒培养。有关企业可以按照规定享受补贴。 企业与职业学校联合招收学生，以工学结合的方式进行学徒培养的，应当签订学徒培养协议。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141030, '《中华人民共和国职业教育法》', '第三十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第三章 职业教育的实施', NULL, '国家鼓励行业组织、企业等参与职业教育专业教材开发，将新技术、新工艺、新理念纳入职业学校教材，并可以通过活页式教材等多种方式进行动态更新；支持运用信息技术和其他现代化教学方式，开发职业教育网络课程等学习资源，创新教学方式和学校管理方式，推动职业教育信息化建设与融合应用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141031, '《中华人民共和国职业教育法》', '第三十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第三章 职业教育的实施', NULL, '国家通过组织开展职业技能竞赛等活动，为技术技能人才提供展示技能、切磋技艺的平台，持续培养更多高素质技术技能人才、能工巧匠和大国工匠。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141032, '《中华人民共和国职业教育法》', '第三十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第四章 职业学校和职业培训机构', NULL, '职业学校的设立，应当符合下列基本条件： （一）有组织机构和章程； （二）有合格的教师和管理人员； （三）有与所实施职业教育相适应、符合规定标准和安全要求的教学及实习实训场所、设施、设备以及课程体系、教育教学资源等； （四）有必备的办学资金和与办学规模相适应的稳定经费来源。 设立中等职业学校，由县级以上地方人民政府或者有关部门按照规定的权限审批；设立实施专科层次教育的高等职业学校，由省、自治区、直辖市人民政府审批，报国务院教育行政部门备案；设立实施本科及以上层次教育的高等职业学校，由国务院教育行政部门审批。 专科层次高等职业学校设置的培养高端技术技能人才的部分专业，符合产教深度融合、办学特色鲜明、培养质量较高等条件的，经国务院教育行政部门审批，可以实施本科层次的职业教育。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141033, '《中华人民共和国职业教育法》', '第三十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第四章 职业学校和职业培训机构', NULL, '职业培训机构的设立，应当符合下列基本条件： （一）有组织机构和管理制度； （二）有与培训任务相适应的课程体系、教师或者其他授课人员、管理人员； （三）有与培训任务相适应、符合安全要求的场所、设施、设备； （四）有相应的经费。 职业培训机构的设立、变更和终止，按照国家有关规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141034, '《中华人民共和国职业教育法》', '第三十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第四章 职业学校和职业培训机构', NULL, '公办职业学校实行中国共产党职业学校基层组织领导的校长负责制，中国共产党职业学校基层组织按照中国共产党章程和有关规定，全面领导学校工作，支持校长独立负责地行使职权。民办职业学校依法健全决策机制，强化学校的中国共产党基层组织政治功能，保证其在学校重大事项决策、监督、执行各环节有效发挥作用。 校长全面负责本学校教学、科学研究和其他行政管理工作。校长通过校长办公会或者校务会议行使职权，依法接受监督。 职业学校可以通过咨询、协商等多种形式，听取行业组织、企业、学校毕业生等方面代表的意见，发挥其参与学校建设、支持学校发展的作用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141035, '《中华人民共和国职业教育法》', '第三十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第四章 职业学校和职业培训机构', NULL, '职业学校应当依法办学，依据章程自主管理。 职业学校在办学中可以开展下列活动： （一）根据产业需求，依法自主设置专业； （二）基于职业教育标准制定人才培养方案，依法自主选用或者编写专业课程教材； （三）根据培养技术技能人才的需要，自主设置学习制度，安排教学过程； （四）在基本学制基础上，适当调整修业年限，实行弹性学习制度； （五）依法自主选聘专业课教师。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141036, '《中华人民共和国职业教育法》', '第三十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第四章 职业学校和职业培训机构', NULL, '国家建立符合职业教育特点的考试招生制度。 中等职业学校可以按照国家有关规定，在有关专业实行与高等职业学校教育的贯通招生和培养。 高等职业学校可以按照国家有关规定，采取文化素质与职业技能相结合的考核方式招收学生；对有突出贡献的技术技能人才，经考核合格，可以破格录取。 省级以上人民政府教育行政部门会同同级人民政府有关部门建立职业教育统一招生平台，汇总发布实施职业教育的学校及其专业设置、招生情况等信息，提供查询、报考等服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141037, '《中华人民共和国职业教育法》', '第三十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第四章 职业学校和职业培训机构', NULL, '职业学校应当加强校风学风、师德师风建设，营造良好学习环境，保证教育教学质量。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141038, '《中华人民共和国职业教育法》', '第三十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第四章 职业学校和职业培训机构', NULL, '职业学校应当建立健全就业创业促进机制，采取多种形式为学生提供职业规划、职业体验、求职指导等就业创业服务，增强学生就业创业能力。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141039, '《中华人民共和国职业教育法》', '第四十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第四章 职业学校和职业培训机构', NULL, '职业学校、职业培训机构实施职业教育应当注重产教融合，实行校企合作。 职业学校、职业培训机构可以通过与行业组织、企业、事业单位等共同举办职业教育机构、组建职业教育集团、开展订单培养等多种形式进行合作。 国家鼓励职业学校在招生就业、人才培养方案制定、师资队伍建设、专业规划、课程设置、教材开发、教学设计、教学实施、质量评价、科学研究、技术服务、科技成果转化以及技术技能创新平台、专业化技术转移机构、实习实训基地建设等方面，与相关行业组织、企业、事业单位等建立合作机制。开展合作的，应当签订协议，明确双方权利义务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141040, '《中华人民共和国职业教育法》', '第四十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第四章 职业学校和职业培训机构', NULL, '职业学校、职业培训机构开展校企合作、提供社会服务或者以实习实训为目的举办企业、开展经营活动取得的收入用于改善办学条件；收入的一定比例可以用于支付教师、企业专家、外聘人员和受教育者的劳动报酬，也可以作为绩效工资来源，符合国家规定的可以不受绩效工资总量限制。 职业学校、职业培训机构实施前款规定的活动，符合国家有关规定的，享受相关税费优惠政策。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141041, '《中华人民共和国职业教育法》', '第四十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第四章 职业学校和职业培训机构', NULL, '职业学校按照规定的收费标准和办法，收取学费和其他必要费用；符合国家规定条件的，应当予以减免；不得以介绍工作、安排实习实训等名义违法收取费用。 职业培训机构、职业学校面向社会开展培训的，按照国家有关规定收取费用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141042, '《中华人民共和国职业教育法》', '第四十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第四章 职业学校和职业培训机构', NULL, '职业学校、职业培训机构应当建立健全教育质量评价制度，吸纳行业组织、企业等参与评价，并及时公开相关信息，接受教育督导和社会监督。 县级以上人民政府教育行政部门应当会同有关部门、行业组织建立符合职业教育特点的质量评价体系，组织或者委托行业组织、企业和第三方专业机构，对职业学校的办学质量进行评估，并将评估结果及时公开。 职业教育质量评价应当突出就业导向，把受教育者的职业道德、技术技能水平、就业质量作为重要指标，引导职业学校培养高素质技术技能人才。 有关部门应当按照各自职责，加强对职业学校、职业培训机构的监督管理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141043, '《中华人民共和国职业教育法》', '第四十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第五章 职业教育的教师与受教育者', NULL, '国家保障职业教育教师的权利，提高其专业素质与社会地位。 县级以上人民政府及其有关部门应当将职业教育教师的培养培训工作纳入教师队伍建设规划，保证职业教育教师队伍适应职业教育发展的需要。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141044, '《中华人民共和国职业教育法》', '第四十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第五章 职业教育的教师与受教育者', NULL, '国家建立健全职业教育教师培养培训体系。 各级人民政府应当采取措施，加强职业教育教师专业化培养培训，鼓励设立专门的职业教育师范院校，支持高等学校设立相关专业，培养职业教育教师；鼓励行业组织、企业共同参与职业教育教师培养培训。 产教融合型企业、规模以上企业应当安排一定比例的岗位，接纳职业学校、职业培训机构教师实践。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141045, '《中华人民共和国职业教育法》', '第四十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第五章 职业教育的教师与受教育者', NULL, '国家建立健全符合职业教育特点和发展要求的职业学校教师岗位设置和职务（职称）评聘制度。 职业学校的专业课教师（含实习指导教师）应当具有一定年限的相应工作经历或者实践经验，达到相应的技术技能水平。 具备条件的企业、事业单位经营管理和专业技术人员，以及其他有专业知识或者特殊技能的人员，经教育教学能力培训合格的，可以担任职业学校的专职或者兼职专业课教师；取得教师资格的，可以根据其技术职称聘任为相应的教师职务。取得职业学校专业课教师资格可以视情况降低学历要求。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141046, '《中华人民共和国职业教育法》', '第四十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第五章 职业教育的教师与受教育者', NULL, '国家鼓励职业学校聘请技能大师、劳动模范、能工巧匠、非物质文化遗产代表性传承人等高技能人才，通过担任专职或者兼职专业课教师、设立工作室等方式，参与人才培养、技术开发、技能传承等工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141047, '《中华人民共和国职业教育法》', '第四十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第五章 职业教育的教师与受教育者', NULL, '国家制定职业学校教职工配备基本标准。省、自治区、直辖市应当根据基本标准，制定本地区职业学校教职工配备标准。 县级以上地方人民政府应当根据教职工配备标准、办学规模等，确定公办职业学校教职工人员规模，其中一定比例可以用于支持职业学校面向社会公开招聘专业技术人员、技能人才担任专职或者兼职教师。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141048, '《中华人民共和国职业教育法》', '第四十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第五章 职业教育的教师与受教育者', NULL, '职业学校学生应当遵守法律、法规和学生行为规范，养成良好的职业道德、职业精神和行为习惯，努力学习，完成规定的学习任务，按照要求参加实习实训，掌握技术技能。 职业学校学生的合法权益，受法律保护。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141049, '《中华人民共和国职业教育法》', '第五十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第五章 职业教育的教师与受教育者', NULL, '国家鼓励企业、事业单位安排实习岗位，接纳职业学校和职业培训机构的学生实习。接纳实习的单位应当保障学生在实习期间按照规定享受休息休假、获得劳动安全卫生保护、参加相关保险、接受职业技能指导等权利；对上岗实习的，应当签订实习协议，给予适当的劳动报酬。 职业学校和职业培训机构应当加强对实习实训学生的指导，加强安全生产教育，协商实习单位安排与学生所学专业相匹配的岗位，明确实习实训内容和标准，不得安排学生从事与所学专业无关的实习实训，不得违反相关规定通过人力资源服务机构、劳务派遣单位，或者通过非法从事人力资源服务、劳务派遣业务的单位或个人组织、安排、管理学生实习实训。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141050, '《中华人民共和国职业教育法》', '第五十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第五章 职业教育的教师与受教育者', NULL, '接受职业学校教育，达到相应学业要求，经学校考核合格的，取得相应的学业证书；接受职业培训，经职业培训机构或者职业学校考核合格的，取得相应的培训证书；经符合国家规定的专门机构考核合格的，取得相应的职业资格证书或者职业技能等级证书。 学业证书、培训证书、职业资格证书和职业技能等级证书，按照国家有关规定，作为受教育者从业的凭证。 接受职业培训取得的职业技能等级证书、培训证书等学习成果，经职业学校认定，可以转化为相应的学历教育学分；达到相应职业学校学业要求的，可以取得相应的学业证书。 接受高等职业学校教育，学业水平达到国家规定的学位标准的，可以依法申请相应学位。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141051, '《中华人民共和国职业教育法》', '第五十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第五章 职业教育的教师与受教育者', NULL, '国家建立对职业学校学生的奖励和资助制度，对特别优秀的学生进行奖励，对经济困难的学生提供资助，并向艰苦、特殊行业等专业学生适当倾斜。国家根据经济社会发展情况适时调整奖励和资助标准。 国家支持企业、事业单位、社会组织及公民个人按照国家有关规定设立职业教育奖学金、助学金，奖励优秀学生，资助经济困难的学生。 职业学校应当按照国家有关规定从事业收入或者学费收入中提取一定比例资金，用于奖励和资助学生。 省、自治区、直辖市人民政府有关部门应当完善职业学校资助资金管理制度，规范资助资金管理使用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141052, '《中华人民共和国职业教育法》', '第五十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第五章 职业教育的教师与受教育者', NULL, '职业学校学生在升学、就业、职业发展等方面与同层次普通学校学生享有平等机会。 高等职业学校和实施职业教育的普通高等学校应当在招生计划中确定相应比例或者采取单独考试办法，专门招收职业学校毕业生。 各级人民政府应当创造公平就业环境。用人单位不得设置妨碍职业学校毕业生平等就业、公平竞争的报考、录用、聘用条件。机关、事业单位、国有企业在招录、招聘技术技能岗位人员时，应当明确技术技能要求，将技术技能水平作为录用、聘用的重要条件。事业单位公开招聘中有职业技能等级要求的岗位，可以适当降低学历要求。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141053, '《中华人民共和国职业教育法》', '第五十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第六章 职业教育的保障', NULL, '国家优化教育经费支出结构，使职业教育经费投入与职业教育发展需求相适应，鼓励通过多种渠道依法筹集发展职业教育的资金。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141054, '《中华人民共和国职业教育法》', '第五十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第六章 职业教育的保障', NULL, '各级人民政府应当按照事权和支出责任相适应的原则，根据职业教育办学规模、培养成本和办学质量等落实职业教育经费，并加强预算绩效管理，提高资金使用效益。 省、自治区、直辖市人民政府应当制定本地区职业学校生均经费标准或者公用经费标准。职业学校举办者应当按照生均经费标准或者公用经费标准按时、足额拨付经费，不断改善办学条件。不得以学费、社会服务收入冲抵生均拨款。 民办职业学校举办者应当参照同层次职业学校生均经费标准，通过多种渠道筹措经费。 财政专项安排、社会捐赠指定用于职业教育的经费，任何组织和个人不得挪用、克扣。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141055, '《中华人民共和国职业教育法》', '第五十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第六章 职业教育的保障', NULL, '地方各级人民政府安排地方教育附加等方面的经费，应当将其中可用于职业教育的资金统筹使用；发挥失业保险基金作用，支持职工提升职业技能。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141056, '《中华人民共和国职业教育法》', '第五十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第六章 职业教育的保障', NULL, '各级人民政府加大面向农村的职业教育投入，可以将农村科学技术开发、技术推广的经费适当用于农村职业培训。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141057, '《中华人民共和国职业教育法》', '第五十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第六章 职业教育的保障', NULL, '企业应当根据国务院规定的标准，按照职工工资总额一定比例提取和使用职工教育经费。职工教育经费可以用于举办职业教育机构、对本单位的职工和准备招用人员进行职业教育等合理用途，其中用于企业一线职工职业教育的经费应当达到国家规定的比例。用人单位安排职工到职业学校或者职业培训机构接受职业教育的，应当在其接受职业教育期间依法支付工资，保障相关待遇。 企业设立具备生产与教学功能的产教融合实习实训基地所发生的费用，可以参照职业学校享受相应的用地、公用事业费等优惠。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141058, '《中华人民共和国职业教育法》', '第五十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第六章 职业教育的保障', NULL, '国家鼓励金融机构通过提供金融服务支持发展职业教育。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141059, '《中华人民共和国职业教育法》', '第六十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第六章 职业教育的保障', NULL, '国家鼓励企业、事业单位、社会组织及公民个人对职业教育捐资助学，鼓励境外的组织和个人对职业教育提供资助和捐赠。提供的资助和捐赠，必须用于职业教育。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141060, '《中华人民共和国职业教育法》', '第六十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第六章 职业教育的保障', NULL, '国家鼓励和支持开展职业教育的科学技术研究、教材和教学资源开发，推进职业教育资源跨区域、跨行业、跨部门共建共享。 国家逐步建立反映职业教育特点和功能的信息统计和管理体系。 县级以上人民政府及其有关部门应当建立健全职业教育服务和保障体系，组织、引导工会等群团组织、行业组织、企业、学校等开展职业教育研究、宣传推广、人才供需对接等活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141061, '《中华人民共和国职业教育法》', '第六十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第六章 职业教育的保障', NULL, '新闻媒体和职业教育有关方面应当积极开展职业教育公益宣传，弘扬技术技能人才成长成才典型事迹，营造人人努力成才、人人皆可成才、人人尽展其才的良好社会氛围。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141062, '《中华人民共和国职业教育法》', '第六十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第七章 法律责任', NULL, '在职业教育活动中违反《中华人民共和国教育法》、《中华人民共和国劳动法》等有关法律规定的，依照有关法律的规定给予处罚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141063, '《中华人民共和国职业教育法》', '第六十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第七章 法律责任', NULL, '企业未依照本法规定对本单位的职工和准备招用的人员实施职业教育、提取和使用职工教育经费的，由有关部门责令改正；拒不改正的，由县级以上人民政府收取其应当承担的职工教育经费，用于职业教育。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141064, '《中华人民共和国职业教育法》', '第六十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第七章 法律责任', NULL, '职业学校、职业培训机构在职业教育活动中违反本法规定的，由教育行政部门或者其他有关部门责令改正；教育教学质量低下或者管理混乱，造成严重后果的，责令暂停招生、限期整顿；逾期不整顿或者经整顿仍达不到要求的，吊销办学许可证或者责令停止办学。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141065, '《中华人民共和国职业教育法》', '第六十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第七章 法律责任', NULL, '接纳职业学校和职业培训机构学生实习的单位违反本法规定，侵害学生休息休假、获得劳动安全卫生保护、参加相关保险、接受职业技能指导等权利的，依法承担相应的法律责任。 职业学校、职业培训机构违反本法规定，通过人力资源服务机构、劳务派遣单位或者非法从事人力资源服务、劳务派遣业务的单位或个人组织、安排、管理学生实习实训的，由教育行政部门、人力资源社会保障行政部门或者其他有关部门责令改正，没收违法所得，并处违法所得一倍以上五倍以下的罚款；违法所得不足一万元的，按一万元计算。 对前款规定的人力资源服务机构、劳务派遣单位或者非法从事人力资源服务、劳务派遣业务的单位或个人，由人力资源社会保障行政部门或者其他有关部门责令改正，没收违法所得，并处违法所得一倍以上五倍以下的罚款；违法所得不足一万元的，按一万元计算。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141066, '《中华人民共和国职业教育法》', '第六十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第七章 法律责任', NULL, '教育行政部门、人力资源社会保障行政部门或者其他有关部门的工作人员违反本法规定，滥用职权、玩忽职守、徇私舞弊的，依法给予处分；构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141067, '《中华人民共和国职业教育法》', '第六十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第八章 附 则', NULL, '境外的组织和个人在境内举办职业学校、职业培训机构，适用本法；法律、行政法规另有规定的，从其规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1141068, '《中华人民共和国职业教育法》', '第六十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2022-04-20', '第八章 附 则', NULL, '本法自2022年5月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349500, '《中华人民共和国工会法》', '第一条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第一章 总 则', NULL, '为保障工会在国家政治、经济和社会生活中的地位，确定工会的权利与义务，发挥工会在社会主义现代化建设事业中的作用，根据宪法，制定本法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349501, '《中华人民共和国工会法》', '第二条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第一章 总 则', NULL, '工会是中国共产党领导的职工自愿结合的工人阶级群众组织，是中国共产党联系职工群众的桥梁和纽带。 中华全国总工会及其各工会组织代表职工的利益，依法维护职工的合法权益。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349502, '《中华人民共和国工会法》', '第三条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第一章 总 则', NULL, '在中国境内的企业、事业单位、机关、社会组织（以下统称用人单位）中以工资收入为主要生活来源的劳动者，不分民族、种族、性别、职业、宗教信仰、教育程度，都有依法参加和组织工会的权利。任何组织和个人不得阻挠和限制。 工会适应企业组织形式、职工队伍结构、劳动关系、就业形态等方面的发展变化，依法维护劳动者参加和组织工会的权利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349503, '《中华人民共和国工会法》', '第四条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第一章 总 则', NULL, '工会必须遵守和维护宪法，以宪法为根本的活动准则，以经济建设为中心，坚持社会主义道路，坚持人民民主专政，坚持中国共产党的领导，坚持马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想，坚持改革开放，保持和增强政治性、先进性、群众性，依照工会章程独立自主地开展工作。 工会会员全国代表大会制定或者修改《中国工会章程》，章程不得与宪法和法律相抵触。 国家保护工会的合法权益不受侵犯。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349504, '《中华人民共和国工会法》', '第五条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第一章 总 则', NULL, '工会组织和教育职工依照宪法和法律的规定行使民主权利，发挥国家主人翁的作用，通过各种途径和形式，参与管理国家事务、管理经济和文化事业、管理社会事务；协助人民政府开展工作，维护工人阶级领导的、以工农联盟为基础的人民民主专政的社会主义国家政权。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349505, '《中华人民共和国工会法》', '第六条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第一章 总 则', NULL, '维护职工合法权益、竭诚服务职工群众是工会的基本职责。工会在维护全国人民总体利益的同时，代表和维护职工的合法权益。 工会通过平等协商和集体合同制度等，推动健全劳动关系协调机制，维护职工劳动权益，构建和谐劳动关系。 工会依照法律规定通过职工代表大会或者其他形式，组织职工参与本单位的民主选举、民主协商、民主决策、民主管理和民主监督。 工会建立联系广泛、服务职工的工会工作体系，密切联系职工，听取和反映职工的意见和要求，关心职工的生活，帮助职工解决困难，全心全意为职工服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349506, '《中华人民共和国工会法》', '第七条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第一章 总 则', NULL, '工会动员和组织职工积极参加经济建设，努力完成生产任务和工作任务。教育职工不断提高思想道德、技术业务和科学文化素质，建设有理想、有道德、有文化、有纪律的职工队伍。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349507, '《中华人民共和国工会法》', '第八条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第一章 总 则', NULL, '工会推动产业工人队伍建设改革，提高产业工人队伍整体素质，发挥产业工人骨干作用，维护产业工人合法权益，保障产业工人主人翁地位，造就一支有理想守信念、懂技术会创新、敢担当讲奉献的宏大产业工人队伍。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349508, '《中华人民共和国工会法》', '第九条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第一章 总 则', NULL, '中华全国总工会根据独立、平等、互相尊重、互不干涉内部事务的原则，加强同各国工会组织的友好合作关系。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349509, '《中华人民共和国工会法》', '第十条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第二章 工会组织', NULL, '工会各级组织按照民主集中制原则建立。 各级工会委员会由会员大会或者会员代表大会民主选举产生。企业主要负责人的近亲属不得作为本企业基层工会委员会成员的人选。 各级工会委员会向同级会员大会或者会员代表大会负责并报告工作，接受其监督。 工会会员大会或者会员代表大会有权撤换或者罢免其所选举的代表或者工会委员会组成人员。 上级工会组织领导下级工会组织。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349510, '《中华人民共和国工会法》', '第十一条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第二章 工会组织', NULL, '用人单位有会员二十五人以上的，应当建立基层工会委员会；不足二十五人的，可以单独建立基层工会委员会，也可以由两个以上单位的会员联合建立基层工会委员会，也可以选举组织员一人，组织会员开展活动。女职工人数较多的，可以建立工会女职工委员会，在同级工会领导下开展工作；女职工人数较少的，可以在工会委员会中设女职工委员。 企业职工较多的乡镇、城市街道，可以建立基层工会的联合会。 县级以上地方建立地方各级总工会。 同一行业或者性质相近的几个行业，可以根据需要建立全国的或者地方的产业工会。 全国建立统一的中华全国总工会。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349511, '《中华人民共和国工会法》', '第十二条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第二章 工会组织', NULL, '基层工会、地方各级总工会、全国或者地方产业工会组织的建立，必须报上一级工会批准。 上级工会可以派员帮助和指导企业职工组建工会，任何单位和个人不得阻挠。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349512, '《中华人民共和国工会法》', '第十三条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第二章 工会组织', NULL, '任何组织和个人不得随意撤销、合并工会组织。 基层工会所在的用人单位终止或者被撤销，该工会组织相应撤销，并报告上一级工会。 依前款规定被撤销的工会，其会员的会籍可以继续保留，具体管理办法由中华全国总工会制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349513, '《中华人民共和国工会法》', '第十四条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第二章 工会组织', NULL, '职工二百人以上的企业、事业单位、社会组织的工会，可以设专职工会主席。工会专职工作人员的人数由工会与企业、事业单位、社会组织协商确定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349514, '《中华人民共和国工会法》', '第十五条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第二章 工会组织', NULL, '中华全国总工会、地方总工会、产业工会具有社会团体法人资格。 基层工会组织具备民法典规定的法人条件的，依法取得社会团体法人资格。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349515, '《中华人民共和国工会法》', '第十六条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第二章 工会组织', NULL, '基层工会委员会每届任期三年或者五年。各级地方总工会委员会和产业工会委员会每届任期五年。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349516, '《中华人民共和国工会法》', '第十七条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第二章 工会组织', NULL, '基层工会委员会定期召开会员大会或者会员代表大会，讨论决定工会工作的重大问题。经基层工会委员会或者三分之一以上的工会会员提议，可以临时召开会员大会或者会员代表大会。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349517, '《中华人民共和国工会法》', '第十八条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第二章 工会组织', NULL, '工会主席、副主席任期未满时，不得随意调动其工作。因工作需要调动时，应当征得本级工会委员会和上一级工会的同意。 罢免工会主席、副主席必须召开会员大会或者会员代表大会讨论，非经会员大会全体会员或者会员代表大会全体代表过半数通过，不得罢免。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349518, '《中华人民共和国工会法》', '第十九条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第二章 工会组织', NULL, '基层工会专职主席、副主席或者委员自任职之日起，其劳动合同期限自动延长，延长期限相当于其任职期间；非专职主席、副主席或者委员自任职之日起，其尚未履行的劳动合同期限短于任期的，劳动合同期限自动延长至任期期满。但是，任职期间个人严重过失或者达到法定退休年龄的除外。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349519, '《中华人民共和国工会法》', '第二十条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第三章 工会的权利和义务', NULL, '企业、事业单位、社会组织违反职工代表大会制度和其他民主管理制度，工会有权要求纠正，保障职工依法行使民主管理的权利。 法律、法规规定应当提交职工大会或者职工代表大会审议、通过、决定的事项，企业、事业单位、社会组织应当依法办理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349520, '《中华人民共和国工会法》', '第二十一条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第三章 工会的权利和义务', NULL, '工会帮助、指导职工与企业、实行企业化管理的事业单位、社会组织签订劳动合同。 工会代表职工与企业、实行企业化管理的事业单位、社会组织进行平等协商，依法签订集体合同。集体合同草案应当提交职工代表大会或者全体职工讨论通过。 工会签订集体合同，上级工会应当给予支持和帮助。 企业、事业单位、社会组织违反集体合同，侵犯职工劳动权益的，工会可以依法要求企业、事业单位、社会组织予以改正并承担责任；因履行集体合同发生争议，经协商解决不成的，工会可以向劳动争议仲裁机构提请仲裁，仲裁机构不予受理或者对仲裁裁决不服的，可以向人民法院提起诉讼。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349521, '《中华人民共和国工会法》', '第二十二条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第三章 工会的权利和义务', NULL, '企业、事业单位、社会组织处分职工，工会认为不适当的，有权提出意见。 用人单位单方面解除职工劳动合同时，应当事先将理由通知工会，工会认为用人单位违反法律、法规和有关合同，要求重新研究处理时，用人单位应当研究工会的意见，并将处理结果书面通知工会。 职工认为用人单位侵犯其劳动权益而申请劳动争议仲裁或者向人民法院提起诉讼的，工会应当给予支持和帮助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349522, '《中华人民共和国工会法》', '第二十三条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第三章 工会的权利和义务', NULL, '企业、事业单位、社会组织违反劳动法律法规规定，有下列侵犯职工劳动权益情形，工会应当代表职工与企业、事业单位、社会组织交涉，要求企业、事业单位、社会组织采取措施予以改正；企业、事业单位、社会组织应当予以研究处理，并向工会作出答复；企业、事业单位、社会组织拒不改正的，工会可以提请当地人民政府依法作出处理： （一）克扣、拖欠职工工资的； （二）不提供劳动安全卫生条件的； （三）随意延长劳动时间的； （四）侵犯女职工和未成年工特殊权益的； （五）其他严重侵犯职工劳动权益的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349523, '《中华人民共和国工会法》', '第二十四条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第三章 工会的权利和义务', NULL, '工会依照国家规定对新建、扩建企业和技术改造工程中的劳动条件和安全卫生设施与主体工程同时设计、同时施工、同时投产使用进行监督。对工会提出的意见，企业或者主管部门应当认真处理，并将处理结果书面通知工会。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349524, '《中华人民共和国工会法》', '第二十五条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第三章 工会的权利和义务', NULL, '工会发现企业违章指挥、强令工人冒险作业，或者生产过程中发现明显重大事故隐患和职业危害，有权提出解决的建议，企业应当及时研究答复；发现危及职工生命安全的情况时，工会有权向企业建议组织职工撤离危险现场，企业必须及时作出处理决定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349525, '《中华人民共和国工会法》', '第二十六条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第三章 工会的权利和义务', NULL, '工会有权对企业、事业单位、社会组织侵犯职工合法权益的问题进行调查，有关单位应当予以协助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349526, '《中华人民共和国工会法》', '第二十七条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第三章 工会的权利和义务', NULL, '职工因工伤亡事故和其他严重危害职工健康问题的调查处理，必须有工会参加。工会应当向有关部门提出处理意见，并有权要求追究直接负责的主管人员和有关责任人员的责任。对工会提出的意见，应当及时研究，给予答复。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349527, '《中华人民共和国工会法》', '第二十八条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第三章 工会的权利和义务', NULL, '企业、事业单位、社会组织发生停工、怠工事件，工会应当代表职工同企业、事业单位、社会组织或者有关方面协商，反映职工的意见和要求并提出解决意见。对于职工的合理要求，企业、事业单位、社会组织应当予以解决。工会协助企业、事业单位、社会组织做好工作，尽快恢复生产、工作秩序。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349528, '《中华人民共和国工会法》', '第二十九条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第三章 工会的权利和义务', NULL, '工会参加企业的劳动争议调解工作。 地方劳动争议仲裁组织应当有同级工会代表参加。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349529, '《中华人民共和国工会法》', '第三十条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第三章 工会的权利和义务', NULL, '县级以上各级总工会依法为所属工会和职工提供法律援助等法律服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349530, '《中华人民共和国工会法》', '第三十一条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第三章 工会的权利和义务', NULL, '工会协助用人单位办好职工集体福利事业，做好工资、劳动安全卫生和社会保险工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349531, '《中华人民共和国工会法》', '第三十二条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第三章 工会的权利和义务', NULL, '工会会同用人单位加强对职工的思想政治引领，教育职工以国家主人翁态度对待劳动，爱护国家和单位的财产；组织职工开展群众性的合理化建议、技术革新、劳动和技能竞赛活动，进行业余文化技术学习和职工培训，参加职业教育和文化体育活动，推进职业安全健康教育和劳动保护工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349532, '《中华人民共和国工会法》', '第三十三条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第三章 工会的权利和义务', NULL, '根据政府委托，工会与有关部门共同做好劳动模范和先进生产（工作）者的评选、表彰、培养和管理工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349533, '《中华人民共和国工会法》', '第三十四条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第三章 工会的权利和义务', NULL, '国家机关在组织起草或者修改直接涉及职工切身利益的法律、法规、规章时，应当听取工会意见。 县级以上各级人民政府制定国民经济和社会发展计划，对涉及职工利益的重大问题，应当听取同级工会的意见。 县级以上各级人民政府及其有关部门研究制定劳动就业、工资、劳动安全卫生、社会保险等涉及职工切身利益的政策、措施时，应当吸收同级工会参加研究，听取工会意见。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349534, '《中华人民共和国工会法》', '第三十五条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第三章 工会的权利和义务', NULL, '县级以上地方各级人民政府可以召开会议或者采取适当方式，向同级工会通报政府的重要的工作部署和与工会工作有关的行政措施，研究解决工会反映的职工群众的意见和要求。 各级人民政府劳动行政部门应当会同同级工会和企业方面代表，建立劳动关系三方协商机制，共同研究解决劳动关系方面的重大问题。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349535, '《中华人民共和国工会法》', '第三十六条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第四章 基层工会组织', NULL, '国有企业职工代表大会是企业实行民主管理的基本形式，是职工行使民主管理权力的机构，依照法律规定行使职权。 国有企业的工会委员会是职工代表大会的工作机构，负责职工代表大会的日常工作，检查、督促职工代表大会决议的执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349536, '《中华人民共和国工会法》', '第三十七条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第四章 基层工会组织', NULL, '集体企业的工会委员会，应当支持和组织职工参加民主管理和民主监督，维护职工选举和罢免管理人员、决定经营管理的重大问题的权力。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349537, '《中华人民共和国工会法》', '第三十八条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第四章 基层工会组织', NULL, '本法第三十六条、第三十七条规定以外的其他企业、事业单位的工会委员会，依照法律规定组织职工采取与企业、事业单位相适应的形式，参与企业、事业单位民主管理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349538, '《中华人民共和国工会法》', '第三十九条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第四章 基层工会组织', NULL, '企业、事业单位、社会组织研究经营管理和发展的重大问题应当听取工会的意见；召开会议讨论有关工资、福利、劳动安全卫生、工作时间、休息休假、女职工保护和社会保险等涉及职工切身利益的问题，必须有工会代表参加。 企业、事业单位、社会组织应当支持工会依法开展工作，工会应当支持企业、事业单位、社会组织依法行使经营管理权。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349539, '《中华人民共和国工会法》', '第四十条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第四章 基层工会组织', NULL, '公司的董事会、监事会中职工代表的产生，依照公司法有关规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349540, '《中华人民共和国工会法》', '第四十一条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第四章 基层工会组织', NULL, '基层工会委员会召开会议或者组织职工活动，应当在生产或者工作时间以外进行，需要占用生产或者工作时间的，应当事先征得企业、事业单位、社会组织的同意。 基层工会的非专职委员占用生产或者工作时间参加会议或者从事工会工作，每月不超过三个工作日，其工资照发，其他待遇不受影响。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349541, '《中华人民共和国工会法》', '第四十二条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第四章 基层工会组织', NULL, '用人单位工会委员会的专职工作人员的工资、奖励、补贴，由所在单位支付。社会保险和其他福利待遇等，享受本单位职工同等待遇。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349542, '《中华人民共和国工会法》', '第四十三条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第五章 工会的经费和财产', NULL, '工会经费的来源： （一）工会会员缴纳的会费； （二）建立工会组织的用人单位按每月全部职工工资总额的百分之二向工会拨缴的经费； （三）工会所属的企业、事业单位上缴的收入； （四）人民政府的补助； （五）其他收入。 前款第二项规定的企业、事业单位、社会组织拨缴的经费在税前列支。 工会经费主要用于为职工服务和工会活动。经费使用的具体办法由中华全国总工会制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349543, '《中华人民共和国工会法》', '第四十四条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第五章 工会的经费和财产', NULL, '企业、事业单位、社会组织无正当理由拖延或者拒不拨缴工会经费，基层工会或者上级工会可以向当地人民法院申请支付令；拒不执行支付令的，工会可以依法申请人民法院强制执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349544, '《中华人民共和国工会法》', '第四十五条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第五章 工会的经费和财产', NULL, '工会应当根据经费独立原则，建立预算、决算和经费审查监督制度。 各级工会建立经费审查委员会。 各级工会经费收支情况应当由同级工会经费审查委员会审查，并且定期向会员大会或者会员代表大会报告，接受监督。工会会员大会或者会员代表大会有权对经费使用情况提出意见。 工会经费的使用应当依法接受国家的监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349545, '《中华人民共和国工会法》', '第四十六条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第五章 工会的经费和财产', NULL, '各级人民政府和用人单位应当为工会办公和开展活动，提供必要的设施和活动场所等物质条件。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349546, '《中华人民共和国工会法》', '第四十七条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第五章 工会的经费和财产', NULL, '工会的财产、经费和国家拨给工会使用的不动产，任何组织和个人不得侵占、挪用和任意调拨。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349547, '《中华人民共和国工会法》', '第四十八条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第五章 工会的经费和财产', NULL, '工会所属的为职工服务的企业、事业单位，其隶属关系不得随意改变。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349548, '《中华人民共和国工会法》', '第四十九条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第五章 工会的经费和财产', NULL, '县级以上各级工会的离休、退休人员的待遇，与国家机关工作人员同等对待。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349549, '《中华人民共和国工会法》', '第五十条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第六章 法律责任', NULL, '工会对违反本法规定侵犯其合法权益的，有权提请人民政府或者有关部门予以处理，或者向人民法院提起诉讼。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349550, '《中华人民共和国工会法》', '第五十一条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第六章 法律责任', NULL, '违反本法第三条、第十二条规定，阻挠职工依法参加和组织工会或者阻挠上级工会帮助、指导职工筹建工会的，由劳动行政部门责令其改正；拒不改正的，由劳动行政部门提请县级以上人民政府处理；以暴力、威胁等手段阻挠造成严重后果，构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349551, '《中华人民共和国工会法》', '第五十二条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第六章 法律责任', NULL, '违反本法规定，对依法履行职责的工会工作人员无正当理由调动工作岗位，进行打击报复的，由劳动行政部门责令改正、恢复原工作；造成损失的，给予赔偿。 对依法履行职责的工会工作人员进行侮辱、诽谤或者进行人身伤害，构成犯罪的，依法追究刑事责任；尚未构成犯罪的，由公安机关依照治安管理处罚法的规定处罚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349552, '《中华人民共和国工会法》', '第五十三条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第六章 法律责任', NULL, '违反本法规定，有下列情形之一的，由劳动行政部门责令恢复其工作，并补发被解除劳动合同期间应得的报酬，或者责令给予本人年收入二倍的赔偿： （一）职工因参加工会活动而被解除劳动合同的； （二）工会工作人员因履行本法规定的职责而被解除劳动合同的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349553, '《中华人民共和国工会法》', '第五十四条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第六章 法律责任', NULL, '违反本法规定，有下列情形之一的，由县级以上人民政府责令改正，依法处理： （一）妨碍工会组织职工通过职工代表大会和其他形式依法行使民主权利的； （二）非法撤销、合并工会组织的； （三）妨碍工会参加职工因工伤亡事故以及其他侵犯职工合法权益问题的调查处理的； （四）无正当理由拒绝进行平等协商的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349554, '《中华人民共和国工会法》', '第五十五条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第六章 法律责任', NULL, '违反本法第四十七条规定，侵占工会经费和财产拒不返还的，工会可以向人民法院提起诉讼，要求返还，并赔偿损失。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349555, '《中华人民共和国工会法》', '第五十六条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第六章 法律责任', NULL, '工会工作人员违反本法规定，损害职工或者工会权益的，由同级工会或者上级工会责令改正，或者予以处分；情节严重的，依照《中国工会章程》予以罢免；造成损失的，应当承担赔偿责任；构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349556, '《中华人民共和国工会法》', '第五十七条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第七章 附 则', NULL, '中华全国总工会会同有关国家机关制定机关工会实施本法的具体办法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1349557, '《中华人民共和国工会法》', '第五十八条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第七章 附 则', NULL, '本法自公布之日起施行。1950年6月29日中央人民政府颁布的《中华人民共和国工会法》同时废止。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358500, '《中华人民共和国职业病防治法》', '第一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '为了预防、控制和消除职业病危害，防治职业病，保护劳动者健康及其相关权益，促进经济社会发展，根据宪法，制定本法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358501, '《中华人民共和国职业病防治法》', '第二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '本法适用于中华人民共和国领域内的职业病防治活动。 本法所称职业病，是指企业、事业单位和个体经济组织等用人单位的劳动者在职业活动中，因接触粉尘、放射性物质和其他有毒、有害因素而引起的疾病。 职业病的分类和目录由国务院卫生行政部门会同国务院劳动保障行政部门制定、调整并公布。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358502, '《中华人民共和国职业病防治法》', '第三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '职业病防治工作坚持预防为主、防治结合的方针，建立用人单位负责、行政机关监管、行业自律、职工参与和社会监督的机制，实行分类管理、综合治理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358503, '《中华人民共和国职业病防治法》', '第四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '劳动者依法享有职业卫生保护的权利。 用人单位应当为劳动者创造符合国家职业卫生标准和卫生要求的工作环境和条件，并采取措施保障劳动者获得职业卫生保护。 工会组织依法对职业病防治工作进行监督，维护劳动者的合法权益。用人单位制定或者修改有关职业病防治的规章制度，应当听取工会组织的意见。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358504, '《中华人民共和国职业病防治法》', '第五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '用人单位应当建立、健全职业病防治责任制，加强对职业病防治的管理，提高职业病防治水平，对本单位产生的职业病危害承担责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358505, '《中华人民共和国职业病防治法》', '第六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '用人单位的主要负责人对本单位的职业病防治工作全面负责。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358506, '《中华人民共和国职业病防治法》', '第七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '用人单位必须依法参加工伤保险。 国务院和县级以上地方人民政府劳动保障行政部门应当加强对工伤保险的监督管理，确保劳动者依法享受工伤保险待遇。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358507, '《中华人民共和国职业病防治法》', '第八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '国家鼓励和支持研制、开发、推广、应用有利于职业病防治和保护劳动者健康的新技术、新工艺、新设备、新材料，加强对职业病的机理和发生规律的基础研究，提高职业病防治科学技术水平；积极采用有效的职业病防治技术、工艺、设备、材料；限制使用或者淘汰职业病危害严重的技术、工艺、设备、材料。 国家鼓励和支持职业病医疗康复机构的建设。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358508, '《中华人民共和国职业病防治法》', '第九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '国家实行职业卫生监督制度。 国务院卫生行政部门、劳动保障行政部门依照本法和国务院确定的职责，负责全国职业病防治的监督管理工作。国务院有关部门在各自的职责范围内负责职业病防治的有关监督管理工作。 县级以上地方人民政府卫生行政部门、劳动保障行政部门依据各自职责，负责本行政区域内职业病防治的监督管理工作。县级以上地方人民政府有关部门在各自的职责范围内负责职业病防治的有关监督管理工作。 县级以上人民政府卫生行政部门、劳动保障行政部门（以下统称职业卫生监督管理部门）应当加强沟通，密切配合，按照各自职责分工，依法行使职权，承担责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358509, '《中华人民共和国职业病防治法》', '第十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '国务院和县级以上地方人民政府应当制定职业病防治规划，将其纳入国民经济和社会发展计划，并组织实施。 县级以上地方人民政府统一负责、领导、组织、协调本行政区域的职业病防治工作，建立健全职业病防治工作体制、机制，统一领导、指挥职业卫生突发事件应对工作；加强职业病防治能力建设和服务体系建设，完善、落实职业病防治工作责任制。 乡、民族乡、镇的人民政府应当认真执行本法，支持职业卫生监督管理部门依法履行职责。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358510, '《中华人民共和国职业病防治法》', '第十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '县级以上人民政府职业卫生监督管理部门应当加强对职业病防治的宣传教育，普及职业病防治的知识，增强用人单位的职业病防治观念，提高劳动者的职业健康意识、自我保护意识和行使职业卫生保护权利的能力。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358511, '《中华人民共和国职业病防治法》', '第十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '有关防治职业病的国家职业卫生标准，由国务院卫生行政部门组织制定并公布。 国务院卫生行政部门应当组织开展重点职业病监测和专项调查，对职业健康风险进行评估，为制定职业卫生标准和职业病防治政策提供科学依据。 县级以上地方人民政府卫生行政部门应当定期对本行政区域的职业病防治情况进行统计和调查分析。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358512, '《中华人民共和国职业病防治法》', '第十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '任何单位和个人有权对违反本法的行为进行检举和控告。有关部门收到相关的检举和控告后，应当及时处理。 对防治职业病成绩显著的单位和个人，给予奖励。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358513, '《中华人民共和国职业病防治法》', '第十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 前期预防', NULL, '用人单位应当依照法律、法规要求，严格遵守国家职业卫生标准，落实职业病预防措施，从源头上控制和消除职业病危害。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358514, '《中华人民共和国职业病防治法》', '第十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 前期预防', NULL, '产生职业病危害的用人单位的设立除应当符合法律、行政法规规定的设立条件外，其工作场所还应当符合下列职业卫生要求： （一）职业病危害因素的强度或者浓度符合国家职业卫生标准； （二）有与职业病危害防护相适应的设施； （三）生产布局合理，符合有害与无害作业分开的原则； （四）有配套的更衣间、洗浴间、孕妇休息间等卫生设施； （五）设备、工具、用具等设施符合保护劳动者生理、心理健康的要求； （六）法律、行政法规和国务院卫生行政部门关于保护劳动者健康的其他要求。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358515, '《中华人民共和国职业病防治法》', '第十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 前期预防', NULL, '国家建立职业病危害项目申报制度。 用人单位工作场所存在职业病目录所列职业病的危害因素的，应当及时、如实向所在地卫生行政部门申报危害项目，接受监督。 职业病危害因素分类目录由国务院卫生行政部门制定、调整并公布。职业病危害项目申报的具体办法由国务院卫生行政部门制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358516, '《中华人民共和国职业病防治法》', '第十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 前期预防', NULL, '新建、扩建、改建建设项目和技术改造、技术引进项目（以下统称建设项目）可能产生职业病危害的，建设单位在可行性论证阶段应当进行职业病危害预评价。 医疗机构建设项目可能产生放射性职业病危害的，建设单位应当向卫生行政部门提交放射性职业病危害预评价报告。卫生行政部门应当自收到预评价报告之日起三十日内，作出审核决定并书面通知建设单位。未提交预评价报告或者预评价报告未经卫生行政部门审核同意的，不得开工建设。 职业病危害预评价报告应当对建设项目可能产生的职业病危害因素及其对工作场所和劳动者健康的影响作出评价，确定危害类别和职业病防护措施。 建设项目职业病危害分类管理办法由国务院卫生行政部门制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358517, '《中华人民共和国职业病防治法》', '第十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 前期预防', NULL, '建设项目的职业病防护设施所需费用应当纳入建设项目工程预算，并与主体工程同时设计，同时施工，同时投入生产和使用。 建设项目的职业病防护设施设计应当符合国家职业卫生标准和卫生要求；其中，医疗机构放射性职业病危害严重的建设项目的防护设施设计，应当经卫生行政部门审查同意后，方可施工。 建设项目在竣工验收前，建设单位应当进行职业病危害控制效果评价。 医疗机构可能产生放射性职业病危害的建设项目竣工验收时，其放射性职业病防护设施经卫生行政部门验收合格后，方可投入使用；其他建设项目的职业病防护设施应当由建设单位负责依法组织验收，验收合格后，方可投入生产和使用。卫生行政部门应当加强对建设单位组织的验收活动和验收结果的监督核查。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358518, '《中华人民共和国职业病防治法》', '第十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 前期预防', NULL, '国家对从事放射性、高毒、高危粉尘等作业实行特殊管理。具体管理办法由国务院制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358519, '《中华人民共和国职业病防治法》', '第二十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '用人单位应当采取下列职业病防治管理措施： （一）设置或者指定职业卫生管理机构或者组织，配备专职或者兼职的职业卫生管理人员，负责本单位的职业病防治工作； （二）制定职业病防治计划和实施方案； （三）建立、健全职业卫生管理制度和操作规程； （四）建立、健全职业卫生档案和劳动者健康监护档案； （五）建立、健全工作场所职业病危害因素监测及评价制度； （六）建立、健全职业病危害事故应急救援预案。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358520, '《中华人民共和国职业病防治法》', '第二十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '用人单位应当保障职业病防治所需的资金投入，不得挤占、挪用，并对因资金投入不足导致的后果承担责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358521, '《中华人民共和国职业病防治法》', '第二十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '用人单位必须采用有效的职业病防护设施，并为劳动者提供个人使用的职业病防护用品。 用人单位为劳动者个人提供的职业病防护用品必须符合防治职业病的要求；不符合要求的，不得使用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358522, '《中华人民共和国职业病防治法》', '第二十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '用人单位应当优先采用有利于防治职业病和保护劳动者健康的新技术、新工艺、新设备、新材料，逐步替代职业病危害严重的技术、工艺、设备、材料。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358523, '《中华人民共和国职业病防治法》', '第二十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '产生职业病危害的用人单位，应当在醒目位置设置公告栏，公布有关职业病防治的规章制度、操作规程、职业病危害事故应急救援措施和工作场所职业病危害因素检测结果。 对产生严重职业病危害的作业岗位，应当在其醒目位置，设置警示标识和中文警示说明。警示说明应当载明产生职业病危害的种类、后果、预防以及应急救治措施等内容。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358524, '《中华人民共和国职业病防治法》', '第二十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '对可能发生急性职业损伤的有毒、有害工作场所，用人单位应当设置报警装置，配置现场急救用品、冲洗设备、应急撤离通道和必要的泄险区。 对放射工作场所和放射性同位素的运输、贮存，用人单位必须配置防护设备和报警装置，保证接触放射线的工作人员佩戴个人剂量计。 对职业病防护设备、应急救援设施和个人使用的职业病防护用品，用人单位应当进行经常性的维护、检修，定期检测其性能和效果，确保其处于正常状态，不得擅自拆除或者停止使用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358525, '《中华人民共和国职业病防治法》', '第二十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '用人单位应当实施由专人负责的职业病危害因素日常监测，并确保监测系统处于正常运行状态。 用人单位应当按照国务院卫生行政部门的规定，定期对工作场所进行职业病危害因素检测、评价。检测、评价结果存入用人单位职业卫生档案，定期向所在地卫生行政部门报告并向劳动者公布。 职业病危害因素检测、评价由依法设立的取得国务院卫生行政部门或者设区的市级以上地方人民政府卫生行政部门按照职责分工给予资质认可的职业卫生技术服务机构进行。职业卫生技术服务机构所作检测、评价应当客观、真实。 发现工作场所职业病危害因素不符合国家职业卫生标准和卫生要求时，用人单位应当立即采取相应治理措施，仍然达不到国家职业卫生标准和卫生要求的，必须停止存在职业病危害因素的作业；职业病危害因素经治理后，符合国家职业卫生标准和卫生要求的，方可重新作业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358526, '《中华人民共和国职业病防治法》', '第二十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '职业卫生技术服务机构依法从事职业病危害因素检测、评价工作，接受卫生行政部门的监督检查。卫生行政部门应当依法履行监督职责。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358527, '《中华人民共和国职业病防治法》', '第二十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '向用人单位提供可能产生职业病危害的设备的，应当提供中文说明书，并在设备的醒目位置设置警示标识和中文警示说明。警示说明应当载明设备性能、可能产生的职业病危害、安全操作和维护注意事项、职业病防护以及应急救治措施等内容。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358528, '《中华人民共和国职业病防治法》', '第二十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '向用人单位提供可能产生职业病危害的化学品、放射性同位素和含有放射性物质的材料的，应当提供中文说明书。说明书应当载明产品特性、主要成份、存在的有害因素、可能产生的危害后果、安全使用注意事项、职业病防护以及应急救治措施等内容。产品包装应当有醒目的警示标识和中文警示说明。贮存上述材料的场所应当在规定的部位设置危险物品标识或者放射性警示标识。 国内首次使用或者首次进口与职业病危害有关的化学材料，使用单位或者进口单位按照国家规定经国务院有关部门批准后，应当向国务院卫生行政部门报送该化学材料的毒性鉴定以及经有关部门登记注册或者批准进口的文件等资料。 进口放射性同位素、射线装置和含有放射性物质的物品的，按照国家有关规定办理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358529, '《中华人民共和国职业病防治法》', '第三十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '任何单位和个人不得生产、经营、进口和使用国家明令禁止使用的可能产生职业病危害的设备或者材料。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358530, '《中华人民共和国职业病防治法》', '第三十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '任何单位和个人不得将产生职业病危害的作业转移给不具备职业病防护条件的单位和个人。不具备职业病防护条件的单位和个人不得接受产生职业病危害的作业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358531, '《中华人民共和国职业病防治法》', '第三十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '用人单位对采用的技术、工艺、设备、材料，应当知悉其产生的职业病危害，对有职业病危害的技术、工艺、设备、材料隐瞒其危害而采用的，对所造成的职业病危害后果承担责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358532, '《中华人民共和国职业病防治法》', '第三十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '用人单位与劳动者订立劳动合同（含聘用合同，下同）时，应当将工作过程中可能产生的职业病危害及其后果、职业病防护措施和待遇等如实告知劳动者，并在劳动合同中写明，不得隐瞒或者欺骗。 劳动者在已订立劳动合同期间因工作岗位或者工作内容变更，从事与所订立劳动合同中未告知的存在职业病危害的作业时，用人单位应当依照前款规定，向劳动者履行如实告知的义务，并协商变更原劳动合同相关条款。 用人单位违反前两款规定的，劳动者有权拒绝从事存在职业病危害的作业，用人单位不得因此解除与劳动者所订立的劳动合同。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358533, '《中华人民共和国职业病防治法》', '第三十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '用人单位的主要负责人和职业卫生管理人员应当接受职业卫生培训，遵守职业病防治法律、法规，依法组织本单位的职业病防治工作。 用人单位应当对劳动者进行上岗前的职业卫生培训和在岗期间的定期职业卫生培训，普及职业卫生知识，督促劳动者遵守职业病防治法律、法规、规章和操作规程，指导劳动者正确使用职业病防护设备和个人使用的职业病防护用品。 劳动者应当学习和掌握相关的职业卫生知识，增强职业病防范意识，遵守职业病防治法律、法规、规章和操作规程，正确使用、维护职业病防护设备和个人使用的职业病防护用品，发现职业病危害事故隐患应当及时报告。 劳动者不履行前款规定义务的，用人单位应当对其进行教育。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358534, '《中华人民共和国职业病防治法》', '第三十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '对从事接触职业病危害的作业的劳动者，用人单位应当按照国务院卫生行政部门的规定组织上岗前、在岗期间和离岗时的职业健康检查，并将检查结果书面告知劳动者。职业健康检查费用由用人单位承担。 用人单位不得安排未经上岗前职业健康检查的劳动者从事接触职业病危害的作业；不得安排有职业禁忌的劳动者从事其所禁忌的作业；对在职业健康检查中发现有与所从事的职业相关的健康损害的劳动者，应当调离原工作岗位，并妥善安置；对未进行离岗前职业健康检查的劳动者不得解除或者终止与其订立的劳动合同。 职业健康检查应当由取得《医疗机构执业许可证》的医疗卫生机构承担。卫生行政部门应当加强对职业健康检查工作的规范管理，具体管理办法由国务院卫生行政部门制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358535, '《中华人民共和国职业病防治法》', '第三十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '用人单位应当为劳动者建立职业健康监护档案，并按照规定的期限妥善保存。 职业健康监护档案应当包括劳动者的职业史、职业病危害接触史、职业健康检查结果和职业病诊疗等有关个人健康资料。 劳动者离开用人单位时，有权索取本人职业健康监护档案复印件，用人单位应当如实、无偿提供，并在所提供的复印件上签章。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358536, '《中华人民共和国职业病防治法》', '第三十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '发生或者可能发生急性职业病危害事故时，用人单位应当立即采取应急救援和控制措施，并及时报告所在地卫生行政部门和有关部门。卫生行政部门接到报告后，应当及时会同有关部门组织调查处理；必要时，可以采取临时控制措施。卫生行政部门应当组织做好医疗救治工作。 对遭受或者可能遭受急性职业病危害的劳动者，用人单位应当及时组织救治、进行健康检查和医学观察，所需费用由用人单位承担。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358537, '《中华人民共和国职业病防治法》', '第三十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '用人单位不得安排未成年工从事接触职业病危害的作业；不得安排孕期、哺乳期的女职工从事对本人和胎儿、婴儿有危害的作业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358538, '《中华人民共和国职业病防治法》', '第三十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '劳动者享有下列职业卫生保护权利： （一）获得职业卫生教育、培训； （二）获得职业健康检查、职业病诊疗、康复等职业病防治服务； （三）了解工作场所产生或者可能产生的职业病危害因素、危害后果和应当采取的职业病防护措施； （四）要求用人单位提供符合防治职业病要求的职业病防护设施和个人使用的职业病防护用品，改善工作条件； （五）对违反职业病防治法律、法规以及危及生命健康的行为提出批评、检举和控告； （六）拒绝违章指挥和强令进行没有职业病防护措施的作业； （七）参与用人单位职业卫生工作的民主管理，对职业病防治工作提出意见和建议。 用人单位应当保障劳动者行使前款所列权利。因劳动者依法行使正当权利而降低其工资、福利等待遇或者解除、终止与其订立的劳动合同的，其行为无效。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358539, '《中华人民共和国职业病防治法》', '第四十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '工会组织应当督促并协助用人单位开展职业卫生宣传教育和培训，有权对用人单位的职业病防治工作提出意见和建议，依法代表劳动者与用人单位签订劳动安全卫生专项集体合同，与用人单位就劳动者反映的有关职业病防治的问题进行协调并督促解决。 工会组织对用人单位违反职业病防治法律、法规，侵犯劳动者合法权益的行为，有权要求纠正；产生严重职业病危害时，有权要求采取防护措施，或者向政府有关部门建议采取强制性措施；发生职业病危害事故时，有权参与事故调查处理；发现危及劳动者生命健康的情形时，有权向用人单位建议组织劳动者撤离危险现场，用人单位应当立即作出处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358540, '《中华人民共和国职业病防治法》', '第四十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '用人单位按照职业病防治要求，用于预防和治理职业病危害、工作场所卫生检测、健康监护和职业卫生培训等费用，按照国家有关规定，在生产成本中据实列支。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358541, '《中华人民共和国职业病防治法》', '第四十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '职业卫生监督管理部门应当按照职责分工，加强对用人单位落实职业病防护管理措施情况的监督检查，依法行使职权，承担责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358542, '《中华人民共和国职业病防治法》', '第四十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 职业病诊断与职业病病人保障', NULL, '职业病诊断应当由取得《医疗机构执业许可证》的医疗卫生机构承担。卫生行政部门应当加强对职业病诊断工作的规范管理，具体管理办法由国务院卫生行政部门制定。 承担职业病诊断的医疗卫生机构还应当具备下列条件： （一）具有与开展职业病诊断相适应的医疗卫生技术人员； （二）具有与开展职业病诊断相适应的仪器、设备； （三）具有健全的职业病诊断质量管理制度。 承担职业病诊断的医疗卫生机构不得拒绝劳动者进行职业病诊断的要求。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358543, '《中华人民共和国职业病防治法》', '第四十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 职业病诊断与职业病病人保障', NULL, '劳动者可以在用人单位所在地、本人户籍所在地或者经常居住地依法承担职业病诊断的医疗卫生机构进行职业病诊断。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358544, '《中华人民共和国职业病防治法》', '第四十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 职业病诊断与职业病病人保障', NULL, '职业病诊断标准和职业病诊断、鉴定办法由国务院卫生行政部门制定。职业病伤残等级的鉴定办法由国务院劳动保障行政部门会同国务院卫生行政部门制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358545, '《中华人民共和国职业病防治法》', '第四十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 职业病诊断与职业病病人保障', NULL, '职业病诊断，应当综合分析下列因素： （一）病人的职业史； （二）职业病危害接触史和工作场所职业病危害因素情况； （三）临床表现以及辅助检查结果等。 没有证据否定职业病危害因素与病人临床表现之间的必然联系的，应当诊断为职业病。 职业病诊断证明书应当由参与诊断的取得职业病诊断资格的执业医师签署，并经承担职业病诊断的医疗卫生机构审核盖章。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358546, '《中华人民共和国职业病防治法》', '第四十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 职业病诊断与职业病病人保障', NULL, '用人单位应当如实提供职业病诊断、鉴定所需的劳动者职业史和职业病危害接触史、工作场所职业病危害因素检测结果等资料；卫生行政部门应当监督检查和督促用人单位提供上述资料；劳动者和有关机构也应当提供与职业病诊断、鉴定有关的资料。 职业病诊断、鉴定机构需要了解工作场所职业病危害因素情况时，可以对工作场所进行现场调查，也可以向卫生行政部门提出，卫生行政部门应当在十日内组织现场调查。用人单位不得拒绝、阻挠。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358547, '《中华人民共和国职业病防治法》', '第四十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 职业病诊断与职业病病人保障', NULL, '职业病诊断、鉴定过程中，用人单位不提供工作场所职业病危害因素检测结果等资料的，诊断、鉴定机构应当结合劳动者的临床表现、辅助检查结果和劳动者的职业史、职业病危害接触史，并参考劳动者的自述、卫生行政部门提供的日常监督检查信息等，作出职业病诊断、鉴定结论。 劳动者对用人单位提供的工作场所职业病危害因素检测结果等资料有异议，或者因劳动者的用人单位解散、破产，无用人单位提供上述资料的，诊断、鉴定机构应当提请卫生行政部门进行调查，卫生行政部门应当自接到申请之日起三十日内对存在异议的资料或者工作场所职业病危害因素情况作出判定；有关部门应当配合。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358548, '《中华人民共和国职业病防治法》', '第四十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 职业病诊断与职业病病人保障', NULL, '职业病诊断、鉴定过程中，在确认劳动者职业史、职业病危害接触史时，当事人对劳动关系、工种、工作岗位或者在岗时间有争议的，可以向当地的劳动人事争议仲裁委员会申请仲裁；接到申请的劳动人事争议仲裁委员会应当受理，并在三十日内作出裁决。 当事人在仲裁过程中对自己提出的主张，有责任提供证据。劳动者无法提供由用人单位掌握管理的与仲裁主张有关的证据的，仲裁庭应当要求用人单位在指定期限内提供；用人单位在指定期限内不提供的，应当承担不利后果。 劳动者对仲裁裁决不服的，可以依法向人民法院提起诉讼。 用人单位对仲裁裁决不服的，可以在职业病诊断、鉴定程序结束之日起十五日内依法向人民法院提起诉讼；诉讼期间，劳动者的治疗费用按照职业病待遇规定的途径支付。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358549, '《中华人民共和国职业病防治法》', '第五十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 职业病诊断与职业病病人保障', NULL, '用人单位和医疗卫生机构发现职业病病人或者疑似职业病病人时，应当及时向所在地卫生行政部门报告。确诊为职业病的，用人单位还应当向所在地劳动保障行政部门报告。接到报告的部门应当依法作出处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358550, '《中华人民共和国职业病防治法》', '第五十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 职业病诊断与职业病病人保障', NULL, '县级以上地方人民政府卫生行政部门负责本行政区域内的职业病统计报告的管理工作，并按照规定上报。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358551, '《中华人民共和国职业病防治法》', '第五十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 职业病诊断与职业病病人保障', NULL, '当事人对职业病诊断有异议的，可以向作出诊断的医疗卫生机构所在地地方人民政府卫生行政部门申请鉴定。 职业病诊断争议由设区的市级以上地方人民政府卫生行政部门根据当事人的申请，组织职业病诊断鉴定委员会进行鉴定。 当事人对设区的市级职业病诊断鉴定委员会的鉴定结论不服的，可以向省、自治区、直辖市人民政府卫生行政部门申请再鉴定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358552, '《中华人民共和国职业病防治法》', '第五十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 职业病诊断与职业病病人保障', NULL, '职业病诊断鉴定委员会由相关专业的专家组成。 省、自治区、直辖市人民政府卫生行政部门应当设立相关的专家库，需要对职业病争议作出诊断鉴定时，由当事人或者当事人委托有关卫生行政部门从专家库中以随机抽取的方式确定参加诊断鉴定委员会的专家。 职业病诊断鉴定委员会应当按照国务院卫生行政部门颁布的职业病诊断标准和职业病诊断、鉴定办法进行职业病诊断鉴定，向当事人出具职业病诊断鉴定书。职业病诊断、鉴定费用由用人单位承担。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358553, '《中华人民共和国职业病防治法》', '第五十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 职业病诊断与职业病病人保障', NULL, '职业病诊断鉴定委员会组成人员应当遵守职业道德，客观、公正地进行诊断鉴定，并承担相应的责任。职业病诊断鉴定委员会组成人员不得私下接触当事人，不得收受当事人的财物或者其他好处，与当事人有利害关系的，应当回避。 人民法院受理有关案件需要进行职业病鉴定时，应当从省、自治区、直辖市人民政府卫生行政部门依法设立的相关的专家库中选取参加鉴定的专家。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358554, '《中华人民共和国职业病防治法》', '第五十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 职业病诊断与职业病病人保障', NULL, '医疗卫生机构发现疑似职业病病人时，应当告知劳动者本人并及时通知用人单位。 用人单位应当及时安排对疑似职业病病人进行诊断；在疑似职业病病人诊断或者医学观察期间，不得解除或者终止与其订立的劳动合同。 疑似职业病病人在诊断、医学观察期间的费用，由用人单位承担。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358555, '《中华人民共和国职业病防治法》', '第五十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 职业病诊断与职业病病人保障', NULL, '用人单位应当保障职业病病人依法享受国家规定的职业病待遇。 用人单位应当按照国家有关规定，安排职业病病人进行治疗、康复和定期检查。 用人单位对不适宜继续从事原工作的职业病病人，应当调离原岗位，并妥善安置。 用人单位对从事接触职业病危害的作业的劳动者，应当给予适当岗位津贴。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358556, '《中华人民共和国职业病防治法》', '第五十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 职业病诊断与职业病病人保障', NULL, '职业病病人的诊疗、康复费用，伤残以及丧失劳动能力的职业病病人的社会保障，按照国家有关工伤保险的规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358557, '《中华人民共和国职业病防治法》', '第五十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 职业病诊断与职业病病人保障', NULL, '职业病病人除依法享有工伤保险外，依照有关民事法律，尚有获得赔偿的权利的，有权向用人单位提出赔偿要求。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358558, '《中华人民共和国职业病防治法》', '第五十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 职业病诊断与职业病病人保障', NULL, '劳动者被诊断患有职业病，但用人单位没有依法参加工伤保险的，其医疗和生活保障由该用人单位承担。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358559, '《中华人民共和国职业病防治法》', '第六十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 职业病诊断与职业病病人保障', NULL, '职业病病人变动工作单位，其依法享有的待遇不变。 用人单位在发生分立、合并、解散、破产等情形时，应当对从事接触职业病危害的作业的劳动者进行健康检查，并按照国家有关规定妥善安置职业病病人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358560, '《中华人民共和国职业病防治法》', '第六十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 职业病诊断与职业病病人保障', NULL, '用人单位已经不存在或者无法确认劳动关系的职业病病人，可以向地方人民政府医疗保障、民政部门申请医疗救助和生活等方面的救助。 地方各级人民政府应当根据本地区的实际情况，采取其他措施，使前款规定的职业病病人获得医疗救治。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358561, '《中华人民共和国职业病防治法》', '第六十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 监督检查', NULL, '县级以上人民政府职业卫生监督管理部门依照职业病防治法律、法规、国家职业卫生标准和卫生要求，依据职责划分，对职业病防治工作进行监督检查。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358562, '《中华人民共和国职业病防治法》', '第六十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 监督检查', NULL, '卫生行政部门履行监督检查职责时，有权采取下列措施： （一）进入被检查单位和职业病危害现场，了解情况，调查取证； （二）查阅或者复制与违反职业病防治法律、法规的行为有关的资料和采集样品； （三）责令违反职业病防治法律、法规的单位和个人停止违法行为。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358563, '《中华人民共和国职业病防治法》', '第六十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 监督检查', NULL, '发生职业病危害事故或者有证据证明危害状态可能导致职业病危害事故发生时，卫生行政部门可以采取下列临时控制措施： （一）责令暂停导致职业病危害事故的作业； （二）封存造成职业病危害事故或者可能导致职业病危害事故发生的材料和设备； （三）组织控制职业病危害事故现场。 在职业病危害事故或者危害状态得到有效控制后，卫生行政部门应当及时解除控制措施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358564, '《中华人民共和国职业病防治法》', '第六十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 监督检查', NULL, '职业卫生监督执法人员依法执行职务时，应当出示监督执法证件。 职业卫生监督执法人员应当忠于职守，秉公执法，严格遵守执法规范；涉及用人单位的秘密的，应当为其保密。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358565, '《中华人民共和国职业病防治法》', '第六十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 监督检查', NULL, '职业卫生监督执法人员依法执行职务时，被检查单位应当接受检查并予以支持配合，不得拒绝和阻碍。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358566, '《中华人民共和国职业病防治法》', '第六十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 监督检查', NULL, '卫生行政部门及其职业卫生监督执法人员履行职责时，不得有下列行为： （一）对不符合法定条件的，发给建设项目有关证明文件、资质证明文件或者予以批准； （二）对已经取得有关证明文件的，不履行监督检查职责； （三）发现用人单位存在职业病危害的，可能造成职业病危害事故，不及时依法采取控制措施； （四）其他违反本法的行为。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358567, '《中华人民共和国职业病防治法》', '第六十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 监督检查', NULL, '职业卫生监督执法人员应当依法经过资格认定。 职业卫生监督管理部门应当加强队伍建设，提高职业卫生监督执法人员的政治、业务素质，依照本法和其他有关法律、法规的规定，建立、健全内部监督制度，对其工作人员执行法律、法规和遵守纪律的情况，进行监督检查。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358568, '《中华人民共和国职业病防治法》', '第六十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 法律责任', NULL, '建设单位违反本法规定，有下列行为之一的，由卫生行政部门给予警告，责令限期改正；逾期不改正的，处十万元以上五十万元以下的罚款；情节严重的，责令停止产生职业病危害的作业，或者提请有关人民政府按照国务院规定的权限责令停建、关闭： （一）未按照规定进行职业病危害预评价的； （二）医疗机构可能产生放射性职业病危害的建设项目未按照规定提交放射性职业病危害预评价报告，或者放射性职业病危害预评价报告未经卫生行政部门审核同意，开工建设的； （三）建设项目的职业病防护设施未按照规定与主体工程同时设计、同时施工、同时投入生产和使用的； （四）建设项目的职业病防护设施设计不符合国家职业卫生标准和卫生要求，或者医疗机构放射性职业病危害严重的建设项目的防护设施设计未经卫生行政部门审查同意擅自施工的； （五）未按照规定对职业病防护设施进行职业病危害控制效果评价的； （六）建设项目竣工投入生产和使用前，职业病防护设施未按照规定验收合格的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358569, '《中华人民共和国职业病防治法》', '第七十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 法律责任', NULL, '违反本法规定，有下列行为之一的，由卫生行政部门给予警告，责令限期改正；逾期不改正的，处十万元以下的罚款： （一）工作场所职业病危害因素检测、评价结果没有存档、上报、公布的； （二）未采取本法第二十条规定的职业病防治管理措施的； （三）未按照规定公布有关职业病防治的规章制度、操作规程、职业病危害事故应急救援措施的； （四）未按照规定组织劳动者进行职业卫生培训，或者未对劳动者个人职业病防护采取指导、督促措施的； （五）国内首次使用或者首次进口与职业病危害有关的化学材料，未按照规定报送毒性鉴定资料以及经有关部门登记注册或者批准进口的文件的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358570, '《中华人民共和国职业病防治法》', '第七十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 法律责任', NULL, '用人单位违反本法规定，有下列行为之一的，由卫生行政部门责令限期改正，给予警告，可以并处五万元以上十万元以下的罚款： （一）未按照规定及时、如实向卫生行政部门申报产生职业病危害的项目的； （二）未实施由专人负责的职业病危害因素日常监测，或者监测系统不能正常监测的； （三）订立或者变更劳动合同时，未告知劳动者职业病危害真实情况的； （四）未按照规定组织职业健康检查、建立职业健康监护档案或者未将检查结果书面告知劳动者的； （五）未依照本法规定在劳动者离开用人单位时提供职业健康监护档案复印件的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358571, '《中华人民共和国职业病防治法》', '第七十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 法律责任', NULL, '用人单位违反本法规定，有下列行为之一的，由卫生行政部门给予警告，责令限期改正，逾期不改正的，处五万元以上二十万元以下的罚款；情节严重的，责令停止产生职业病危害的作业，或者提请有关人民政府按照国务院规定的权限责令关闭： （一）工作场所职业病危害因素的强度或者浓度超过国家职业卫生标准的； （二）未提供职业病防护设施和个人使用的职业病防护用品，或者提供的职业病防护设施和个人使用的职业病防护用品不符合国家职业卫生标准和卫生要求的； （三）对职业病防护设备、应急救援设施和个人使用的职业病防护用品未按照规定进行维护、检修、检测，或者不能保持正常运行、使用状态的； （四）未按照规定对工作场所职业病危害因素进行检测、评价的； （五）工作场所职业病危害因素经治理仍然达不到国家职业卫生标准和卫生要求时，未停止存在职业病危害因素的作业的； （六）未按照规定安排职业病病人、疑似职业病病人进行诊治的； （七）发生或者可能发生急性职业病危害事故时，未立即采取应急救援和控制措施或者未按照规定及时报告的； （八）未按照规定在产生严重职业病危害的作业岗位醒目位置设置警示标识和中文警示说明的； （九）拒绝职业卫生监督管理部门监督检查的； （十）隐瞒、伪造、篡改、毁损职业健康监护档案、工作场所职业病危害因素检测评价结果等相关资料，或者拒不提供职业病诊断、鉴定所需资料的； （十一）未按照规定承担职业病诊断、鉴定费用和职业病病人的医疗、生活保障费用的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358572, '《中华人民共和国职业病防治法》', '第七十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 法律责任', NULL, '向用人单位提供可能产生职业病危害的设备、材料，未按照规定提供中文说明书或者设置警示标识和中文警示说明的，由卫生行政部门责令限期改正，给予警告，并处五万元以上二十万元以下的罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358573, '《中华人民共和国职业病防治法》', '第七十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 法律责任', NULL, '用人单位和医疗卫生机构未按照规定报告职业病、疑似职业病的，由有关主管部门依据职责分工责令限期改正，给予警告，可以并处一万元以下的罚款；弄虚作假的，并处二万元以上五万元以下的罚款；对直接负责的主管人员和其他直接责任人员，可以依法给予降级或者撤职的处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358574, '《中华人民共和国职业病防治法》', '第七十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 法律责任', NULL, '违反本法规定，有下列情形之一的，由卫生行政部门责令限期治理，并处五万元以上三十万元以下的罚款；情节严重的，责令停止产生职业病危害的作业，或者提请有关人民政府按照国务院规定的权限责令关闭： （一）隐瞒技术、工艺、设备、材料所产生的职业病危害而采用的； （二）隐瞒本单位职业卫生真实情况的； （三）可能发生急性职业损伤的有毒、有害工作场所、放射工作场所或者放射性同位素的运输、贮存不符合本法第二十五条规定的； （四）使用国家明令禁止使用的可能产生职业病危害的设备或者材料的； （五）将产生职业病危害的作业转移给没有职业病防护条件的单位和个人，或者没有职业病防护条件的单位和个人接受产生职业病危害的作业的； （六）擅自拆除、停止使用职业病防护设备或者应急救援设施的； （七）安排未经职业健康检查的劳动者、有职业禁忌的劳动者、未成年工或者孕期、哺乳期女职工从事接触职业病危害的作业或者禁忌作业的； （八）违章指挥和强令劳动者进行没有职业病防护措施的作业的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358575, '《中华人民共和国职业病防治法》', '第七十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 法律责任', NULL, '生产、经营或者进口国家明令禁止使用的可能产生职业病危害的设备或者材料的，依照有关法律、行政法规的规定给予处罚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358576, '《中华人民共和国职业病防治法》', '第七十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 法律责任', NULL, '用人单位违反本法规定，已经对劳动者生命健康造成严重损害的，由卫生行政部门责令停止产生职业病危害的作业，或者提请有关人民政府按照国务院规定的权限责令关闭，并处十万元以上五十万元以下的罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358577, '《中华人民共和国职业病防治法》', '第七十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 法律责任', NULL, '用人单位违反本法规定，造成重大职业病危害事故或者其他严重后果，构成犯罪的，对直接负责的主管人员和其他直接责任人员，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358578, '《中华人民共和国职业病防治法》', '第七十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 法律责任', NULL, '未取得职业卫生技术服务资质认可擅自从事职业卫生技术服务的，由卫生行政部门责令立即停止违法行为，没收违法所得；违法所得五千元以上的，并处违法所得二倍以上十倍以下的罚款；没有违法所得或者违法所得不足五千元的，并处五千元以上五万元以下的罚款；情节严重的，对直接负责的主管人员和其他直接责任人员，依法给予降级、撤职或者开除的处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358579, '《中华人民共和国职业病防治法》', '第八十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 法律责任', NULL, '从事职业卫生技术服务的机构和承担职业病诊断的医疗卫生机构违反本法规定，有下列行为之一的，由卫生行政部门责令立即停止违法行为，给予警告，没收违法所得；违法所得五千元以上的，并处违法所得二倍以上五倍以下的罚款；没有违法所得或者违法所得不足五千元的，并处五千元以上二万元以下的罚款；情节严重的，由原认可或者登记机关取消其相应的资格；对直接负责的主管人员和其他直接责任人员，依法给予降级、撤职或者开除的处分；构成犯罪的，依法追究刑事责任： （一）超出资质认可或者诊疗项目登记范围从事职业卫生技术服务或者职业病诊断的； （二）不按照本法规定履行法定职责的； （三）出具虚假证明文件的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358580, '《中华人民共和国职业病防治法》', '第八十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 法律责任', NULL, '职业病诊断鉴定委员会组成人员收受职业病诊断争议当事人的财物或者其他好处的，给予警告，没收收受的财物，可以并处三千元以上五万元以下的罚款，取消其担任职业病诊断鉴定委员会组成人员的资格，并从省、自治区、直辖市人民政府卫生行政部门设立的专家库中予以除名。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358581, '《中华人民共和国职业病防治法》', '第八十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 法律责任', NULL, '卫生行政部门不按照规定报告职业病和职业病危害事故的，由上一级行政部门责令改正，通报批评，给予警告；虚报、瞒报的，对单位负责人、直接负责的主管人员和其他直接责任人员依法给予降级、撤职或者开除的处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358582, '《中华人民共和国职业病防治法》', '第八十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 法律责任', NULL, '县级以上地方人民政府在职业病防治工作中未依照本法履行职责，本行政区域出现重大职业病危害事故、造成严重社会影响的，依法对直接负责的主管人员和其他直接责任人员给予记大过直至开除的处分。 县级以上人民政府职业卫生监督管理部门不履行本法规定的职责，滥用职权、玩忽职守、徇私舞弊，依法对直接负责的主管人员和其他直接责任人员给予记大过或者降级的处分；造成职业病危害事故或者其他严重后果的，依法给予撤职或者开除的处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358583, '《中华人民共和国职业病防治法》', '第八十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 法律责任', NULL, '违反本法规定，构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358584, '《中华人民共和国职业病防治法》', '第八十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第七章 附 则', NULL, '本法下列用语的含义： 职业病危害，是指对从事职业活动的劳动者可能导致职业病的各种危害。职业病危害因素包括：职业活动中存在的各种有害的化学、物理、生物因素以及在作业过程中产生的其他职业有害因素。 职业禁忌，是指劳动者从事特定职业或者接触特定职业病危害因素时，比一般职业人群更易于遭受职业病危害和罹患职业病或者可能导致原有自身疾病病情加重，或者在从事作业过程中诱发可能导致对他人生命健康构成危险的疾病的个人特殊生理或者病理状态。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358585, '《中华人民共和国职业病防治法》', '第八十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第七章 附 则', NULL, '本法第二条规定的用人单位以外的单位，产生职业病危害的，其职业病防治活动可以参照本法执行。 劳务派遣用工单位应当履行本法规定的用人单位的义务。 中国人民解放军参照执行本法的办法，由国务院、中央军事委员会制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358586, '《中华人民共和国职业病防治法》', '第八十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第七章 附 则', NULL, '对医疗机构放射性职业病危害控制的监督管理，由卫生行政部门依照本法的规定实施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1358587, '《中华人民共和国职业病防治法》', '第八十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第七章 附 则', NULL, '本法自2002年5月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360000, '《中华人民共和国社会保险法》', '第一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '为了规范社会保险关系，维护公民参加社会保险和享受社会保险待遇的合法权益，使公民共享发展成果，促进社会和谐稳定，根据宪法，制定本法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360001, '《中华人民共和国社会保险法》', '第二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '国家建立基本养老保险、基本医疗保险、工伤保险、失业保险、生育保险等社会保险制度，保障公民在年老、疾病、工伤、失业、生育等情况下依法从国家和社会获得物质帮助的权利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360002, '《中华人民共和国社会保险法》', '第三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '社会保险制度坚持广覆盖、保基本、多层次、可持续的方针，社会保险水平应当与经济社会发展水平相适应。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360003, '《中华人民共和国社会保险法》', '第四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '中华人民共和国境内的用人单位和个人依法缴纳社会保险费，有权查询缴费记录、个人权益记录，要求社会保险经办机构提供社会保险咨询等相关服务。 个人依法享受社会保险待遇，有权监督本单位为其缴费情况。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360004, '《中华人民共和国社会保险法》', '第五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '县级以上人民政府将社会保险事业纳入国民经济和社会发展规划。 国家多渠道筹集社会保险资金。县级以上人民政府对社会保险事业给予必要的经费支持。 国家通过税收优惠政策支持社会保险事业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360005, '《中华人民共和国社会保险法》', '第六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '国家对社会保险基金实行严格监管。 国务院和省、自治区、直辖市人民政府建立健全社会保险基金监督管理制度，保障社会保险基金安全、有效运行。 县级以上人民政府采取措施，鼓励和支持社会各方面参与社会保险基金的监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360006, '《中华人民共和国社会保险法》', '第七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '国务院社会保险行政部门负责全国的社会保险管理工作，国务院其他有关部门在各自的职责范围内负责有关的社会保险工作。 县级以上地方人民政府社会保险行政部门负责本行政区域的社会保险管理工作，县级以上地方人民政府其他有关部门在各自的职责范围内负责有关的社会保险工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360007, '《中华人民共和国社会保险法》', '第八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '社会保险经办机构提供社会保险服务，负责社会保险登记、个人权益记录、社会保险待遇支付等工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360008, '《中华人民共和国社会保险法》', '第九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '工会依法维护职工的合法权益，有权参与社会保险重大事项的研究，参加社会保险监督委员会，对与职工社会保险权益有关的事项进行监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360009, '《中华人民共和国社会保险法》', '第十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 基本养老保险', NULL, '职工应当参加基本养老保险，由用人单位和职工共同缴纳基本养老保险费。 无雇工的个体工商户、未在用人单位参加基本养老保险的非全日制从业人员以及其他灵活就业人员可以参加基本养老保险，由个人缴纳基本养老保险费。 公务员和参照公务员法管理的工作人员养老保险的办法由国务院规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360010, '《中华人民共和国社会保险法》', '第十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 基本养老保险', NULL, '基本养老保险实行社会统筹与个人账户相结合。 基本养老保险基金由用人单位和个人缴费以及政府补贴等组成。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360011, '《中华人民共和国社会保险法》', '第十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 基本养老保险', NULL, '用人单位应当按照国家规定的本单位职工工资总额的比例缴纳基本养老保险费，记入基本养老保险统筹基金。 职工应当按照国家规定的本人工资的比例缴纳基本养老保险费，记入个人账户。 无雇工的个体工商户、未在用人单位参加基本养老保险的非全日制从业人员以及其他灵活就业人员参加基本养老保险的，应当按照国家规定缴纳基本养老保险费，分别记入基本养老保险统筹基金和个人账户。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360012, '《中华人民共和国社会保险法》', '第十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 基本养老保险', NULL, '国有企业、事业单位职工参加基本养老保险前，视同缴费年限期间应当缴纳的基本养老保险费由政府承担。 基本养老保险基金出现支付不足时，政府给予补贴。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360013, '《中华人民共和国社会保险法》', '第十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 基本养老保险', NULL, '个人账户不得提前支取，记账利率不得低于银行定期存款利率，免征利息税。个人死亡的，个人账户余额可以继承。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360014, '《中华人民共和国社会保险法》', '第十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 基本养老保险', NULL, '基本养老金由统筹养老金和个人账户养老金组成。 基本养老金根据个人累计缴费年限、缴费工资、当地职工平均工资、个人账户金额、城镇人口平均预期寿命等因素确定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360015, '《中华人民共和国社会保险法》', '第十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 基本养老保险', NULL, '参加基本养老保险的个人，达到法定退休年龄时累计缴费满十五年的，按月领取基本养老金。 参加基本养老保险的个人，达到法定退休年龄时累计缴费不足十五年的，可以缴费至满十五年，按月领取基本养老金；也可以转入新型农村社会养老保险或者城镇居民社会养老保险，按照国务院规定享受相应的养老保险待遇。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360016, '《中华人民共和国社会保险法》', '第十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 基本养老保险', NULL, '参加基本养老保险的个人，因病或者非因工死亡的，其遗属可以领取丧葬补助金和抚恤金；在未达到法定退休年龄时因病或者非因工致残完全丧失劳动能力的，可以领取病残津贴。所需资金从基本养老保险基金中支付。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360017, '《中华人民共和国社会保险法》', '第十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 基本养老保险', NULL, '国家建立基本养老金正常调整机制。根据职工平均工资增长、物价上涨情况，适时提高基本养老保险待遇水平。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360018, '《中华人民共和国社会保险法》', '第十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 基本养老保险', NULL, '个人跨统筹地区就业的，其基本养老保险关系随本人转移，缴费年限累计计算。个人达到法定退休年龄时，基本养老金分段计算、统一支付。具体办法由国务院规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360019, '《中华人民共和国社会保险法》', '第二十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 基本养老保险', NULL, '国家建立和完善新型农村社会养老保险制度。 新型农村社会养老保险实行个人缴费、集体补助和政府补贴相结合。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360020, '《中华人民共和国社会保险法》', '第二十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 基本养老保险', NULL, '新型农村社会养老保险待遇由基础养老金和个人账户养老金组成。 参加新型农村社会养老保险的农村居民，符合国家规定条件的，按月领取新型农村社会养老保险待遇。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360021, '《中华人民共和国社会保险法》', '第二十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 基本养老保险', NULL, '国家建立和完善城镇居民社会养老保险制度。 省、自治区、直辖市人民政府根据实际情况，可以将城镇居民社会养老保险和新型农村社会养老保险合并实施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360022, '《中华人民共和国社会保险法》', '第二十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 基本医疗保险', NULL, '职工应当参加职工基本医疗保险，由用人单位和职工按照国家规定共同缴纳基本医疗保险费。 无雇工的个体工商户、未在用人单位参加职工基本医疗保险的非全日制从业人员以及其他灵活就业人员可以参加职工基本医疗保险，由个人按照国家规定缴纳基本医疗保险费。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360023, '《中华人民共和国社会保险法》', '第二十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 基本医疗保险', NULL, '国家建立和完善新型农村合作医疗制度。 新型农村合作医疗的管理办法，由国务院规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360024, '《中华人民共和国社会保险法》', '第二十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 基本医疗保险', NULL, '国家建立和完善城镇居民基本医疗保险制度。 城镇居民基本医疗保险实行个人缴费和政府补贴相结合。 享受最低生活保障的人、丧失劳动能力的残疾人、低收入家庭六十周岁以上的老年人和未成年人等所需个人缴费部分，由政府给予补贴。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360025, '《中华人民共和国社会保险法》', '第二十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 基本医疗保险', NULL, '职工基本医疗保险、新型农村合作医疗和城镇居民基本医疗保险的待遇标准按照国家规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360026, '《中华人民共和国社会保险法》', '第二十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 基本医疗保险', NULL, '参加职工基本医疗保险的个人，达到法定退休年龄时累计缴费达到国家规定年限的，退休后不再缴纳基本医疗保险费，按照国家规定享受基本医疗保险待遇；未达到国家规定年限的，可以缴费至国家规定年限。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360027, '《中华人民共和国社会保险法》', '第二十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 基本医疗保险', NULL, '符合基本医疗保险药品目录、诊疗项目、医疗服务设施标准以及急诊、抢救的医疗费用，按照国家规定从基本医疗保险基金中支付。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360028, '《中华人民共和国社会保险法》', '第二十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 基本医疗保险', NULL, '参保人员医疗费用中应当由基本医疗保险基金支付的部分，由社会保险经办机构与医疗机构、药品经营单位直接结算。 社会保险行政部门和卫生行政部门应当建立异地就医医疗费用结算制度，方便参保人员享受基本医疗保险待遇。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360029, '《中华人民共和国社会保险法》', '第三十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 基本医疗保险', NULL, '下列医疗费用不纳入基本医疗保险基金支付范围： （一）应当从工伤保险基金中支付的； （二）应当由第三人负担的； （三）应当由公共卫生负担的； （四）在境外就医的。 医疗费用依法应当由第三人负担，第三人不支付或者无法确定第三人的，由基本医疗保险基金先行支付。基本医疗保险基金先行支付后，有权向第三人追偿。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360030, '《中华人民共和国社会保险法》', '第三十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 基本医疗保险', NULL, '社会保险经办机构根据管理服务的需要，可以与医疗机构、药品经营单位签订服务协议，规范医疗服务行为。 医疗机构应当为参保人员提供合理、必要的医疗服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360031, '《中华人民共和国社会保险法》', '第三十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 基本医疗保险', NULL, '个人跨统筹地区就业的，其基本医疗保险关系随本人转移，缴费年限累计计算。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360032, '《中华人民共和国社会保险法》', '第三十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 工伤保险', NULL, '职工应当参加工伤保险，由用人单位缴纳工伤保险费，职工不缴纳工伤保险费。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360033, '《中华人民共和国社会保险法》', '第三十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 工伤保险', NULL, '国家根据不同行业的工伤风险程度确定行业的差别费率，并根据使用工伤保险基金、工伤发生率等情况在每个行业内确定费率档次。行业差别费率和行业内费率档次由国务院社会保险行政部门制定，报国务院批准后公布施行。 社会保险经办机构根据用人单位使用工伤保险基金、工伤发生率和所属行业费率档次等情况，确定用人单位缴费费率。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360034, '《中华人民共和国社会保险法》', '第三十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 工伤保险', NULL, '用人单位应当按照本单位职工工资总额，根据社会保险经办机构确定的费率缴纳工伤保险费。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360035, '《中华人民共和国社会保险法》', '第三十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 工伤保险', NULL, '职工因工作原因受到事故伤害或者患职业病，且经工伤认定的，享受工伤保险待遇；其中，经劳动能力鉴定丧失劳动能力的，享受伤残待遇。 工伤认定和劳动能力鉴定应当简捷、方便。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360036, '《中华人民共和国社会保险法》', '第三十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 工伤保险', NULL, '职工因下列情形之一导致本人在工作中伤亡的，不认定为工伤： （一）故意犯罪； （二）醉酒或者吸毒； （三）自残或者自杀； （四）法律、行政法规规定的其他情形。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360037, '《中华人民共和国社会保险法》', '第三十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 工伤保险', NULL, '因工伤发生的下列费用，按照国家规定从工伤保险基金中支付： （一）治疗工伤的医疗费用和康复费用； （二）住院伙食补助费； （三）到统筹地区以外就医的交通食宿费； （四）安装配置伤残辅助器具所需费用； （五）生活不能自理的，经劳动能力鉴定委员会确认的生活护理费； （六）一次性伤残补助金和一至四级伤残职工按月领取的伤残津贴； （七）终止或者解除劳动合同时，应当享受的一次性医疗补助金； （八）因工死亡的，其遗属领取的丧葬补助金、供养亲属抚恤金和因工死亡补助金； （九）劳动能力鉴定费。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360038, '《中华人民共和国社会保险法》', '第三十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 工伤保险', NULL, '因工伤发生的下列费用，按照国家规定由用人单位支付： （一）治疗工伤期间的工资福利； （二）五级、六级伤残职工按月领取的伤残津贴； （三）终止或者解除劳动合同时，应当享受的一次性伤残就业补助金。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360039, '《中华人民共和国社会保险法》', '第四十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 工伤保险', NULL, '工伤职工符合领取基本养老金条件的，停发伤残津贴，享受基本养老保险待遇。基本养老保险待遇低于伤残津贴的，从工伤保险基金中补足差额。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360040, '《中华人民共和国社会保险法》', '第四十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 工伤保险', NULL, '职工所在用人单位未依法缴纳工伤保险费，发生工伤事故的，由用人单位支付工伤保险待遇。用人单位不支付的，从工伤保险基金中先行支付。 从工伤保险基金中先行支付的工伤保险待遇应当由用人单位偿还。用人单位不偿还的，社会保险经办机构可以依照本法第六十三条的规定追偿。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360041, '《中华人民共和国社会保险法》', '第四十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 工伤保险', NULL, '由于第三人的原因造成工伤，第三人不支付工伤医疗费用或者无法确定第三人的，由工伤保险基金先行支付。工伤保险基金先行支付后，有权向第三人追偿。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360042, '《中华人民共和国社会保险法》', '第四十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 工伤保险', NULL, '工伤职工有下列情形之一的，停止享受工伤保险待遇： （一）丧失享受待遇条件的； （二）拒不接受劳动能力鉴定的； （三）拒绝治疗的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360043, '《中华人民共和国社会保险法》', '第四十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 失业保险', NULL, '职工应当参加失业保险，由用人单位和职工按照国家规定共同缴纳失业保险费。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360044, '《中华人民共和国社会保险法》', '第四十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 失业保险', NULL, '失业人员符合下列条件的，从失业保险基金中领取失业保险金： （一）失业前用人单位和本人已经缴纳失业保险费满一年的； （二）非因本人意愿中断就业的； （三）已经进行失业登记，并有求职要求的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360045, '《中华人民共和国社会保险法》', '第四十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 失业保险', NULL, '失业人员失业前用人单位和本人累计缴费满一年不足五年的，领取失业保险金的期限最长为十二个月；累计缴费满五年不足十年的，领取失业保险金的期限最长为十八个月；累计缴费十年以上的，领取失业保险金的期限最长为二十四个月。重新就业后，再次失业的，缴费时间重新计算，领取失业保险金的期限与前次失业应当领取而尚未领取的失业保险金的期限合并计算，最长不超过二十四个月。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360046, '《中华人民共和国社会保险法》', '第四十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 失业保险', NULL, '失业保险金的标准，由省、自治区、直辖市人民政府确定，不得低于城市居民最低生活保障标准。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360047, '《中华人民共和国社会保险法》', '第四十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 失业保险', NULL, '失业人员在领取失业保险金期间，参加职工基本医疗保险，享受基本医疗保险待遇。 失业人员应当缴纳的基本医疗保险费从失业保险基金中支付，个人不缴纳基本医疗保险费。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360048, '《中华人民共和国社会保险法》', '第四十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 失业保险', NULL, '失业人员在领取失业保险金期间死亡的，参照当地对在职职工死亡的规定，向其遗属发给一次性丧葬补助金和抚恤金。所需资金从失业保险基金中支付。 个人死亡同时符合领取基本养老保险丧葬补助金、工伤保险丧葬补助金和失业保险丧葬补助金条件的，其遗属只能选择领取其中的一项。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360049, '《中华人民共和国社会保险法》', '第五十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 失业保险', NULL, '用人单位应当及时为失业人员出具终止或者解除劳动关系的证明，并将失业人员的名单自终止或者解除劳动关系之日起十五日内告知社会保险经办机构。 失业人员应当持本单位为其出具的终止或者解除劳动关系的证明，及时到指定的公共就业服务机构办理失业登记。 失业人员凭失业登记证明和个人身份证明，到社会保险经办机构办理领取失业保险金的手续。失业保险金领取期限自办理失业登记之日起计算。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360050, '《中华人民共和国社会保险法》', '第五十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 失业保险', NULL, '失业人员在领取失业保险金期间有下列情形之一的，停止领取失业保险金，并同时停止享受其他失业保险待遇： （一）重新就业的； （二）应征服兵役的； （三）移居境外的； （四）享受基本养老保险待遇的； （五）无正当理由，拒不接受当地人民政府指定部门或者机构介绍的适当工作或者提供的培训的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360051, '《中华人民共和国社会保险法》', '第五十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 失业保险', NULL, '职工跨统筹地区就业的，其失业保险关系随本人转移，缴费年限累计计算。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360052, '《中华人民共和国社会保险法》', '第五十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 生育保险', NULL, '职工应当参加生育保险，由用人单位按照国家规定缴纳生育保险费，职工不缴纳生育保险费。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360053, '《中华人民共和国社会保险法》', '第五十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 生育保险', NULL, '用人单位已经缴纳生育保险费的，其职工享受生育保险待遇；职工未就业配偶按照国家规定享受生育医疗费用待遇。所需资金从生育保险基金中支付。 生育保险待遇包括生育医疗费用和生育津贴。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360054, '《中华人民共和国社会保险法》', '第五十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 生育保险', NULL, '生育医疗费用包括下列各项： （一）生育的医疗费用； （二）计划生育的医疗费用； （三）法律、法规规定的其他项目费用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360055, '《中华人民共和国社会保险法》', '第五十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 生育保险', NULL, '职工有下列情形之一的，可以按照国家规定享受生育津贴： （一）女职工生育享受产假； （二）享受计划生育手术休假； （三）法律、法规规定的其他情形。 生育津贴按照职工所在用人单位上年度职工月平均工资计发。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360056, '《中华人民共和国社会保险法》', '第五十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第七章 社会保险费征缴', NULL, '用人单位应当自成立之日起三十日内凭营业执照、登记证书或者单位印章，向当地社会保险经办机构申请办理社会保险登记。社会保险经办机构应当自收到申请之日起十五日内予以审核，发给社会保险登记证件。 用人单位的社会保险登记事项发生变更或者用人单位依法终止的，应当自变更或者终止之日起三十日内，到社会保险经办机构办理变更或者注销社会保险登记。 市场监督管理部门、民政部门和机构编制管理机关应当及时向社会保险经办机构通报用人单位的成立、终止情况，公安机关应当及时向社会保险经办机构通报个人的出生、死亡以及户口登记、迁移、注销等情况。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360057, '《中华人民共和国社会保险法》', '第五十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第七章 社会保险费征缴', NULL, '用人单位应当自用工之日起三十日内为其职工向社会保险经办机构申请办理社会保险登记。未办理社会保险登记的，由社会保险经办机构核定其应当缴纳的社会保险费。 自愿参加社会保险的无雇工的个体工商户、未在用人单位参加社会保险的非全日制从业人员以及其他灵活就业人员，应当向社会保险经办机构申请办理社会保险登记。 国家建立全国统一的个人社会保障号码。个人社会保障号码为公民身份号码。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360058, '《中华人民共和国社会保险法》', '第五十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第七章 社会保险费征缴', NULL, '县级以上人民政府加强社会保险费的征收工作。 社会保险费实行统一征收，实施步骤和具体办法由国务院规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360059, '《中华人民共和国社会保险法》', '第六十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第七章 社会保险费征缴', NULL, '用人单位应当自行申报、按时足额缴纳社会保险费，非因不可抗力等法定事由不得缓缴、减免。职工应当缴纳的社会保险费由用人单位代扣代缴，用人单位应当按月将缴纳社会保险费的明细情况告知本人。 无雇工的个体工商户、未在用人单位参加社会保险的非全日制从业人员以及其他灵活就业人员，可以直接向社会保险费征收机构缴纳社会保险费。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360060, '《中华人民共和国社会保险法》', '第六十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第七章 社会保险费征缴', NULL, '社会保险费征收机构应当依法按时足额征收社会保险费，并将缴费情况定期告知用人单位和个人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360061, '《中华人民共和国社会保险法》', '第六十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第七章 社会保险费征缴', NULL, '用人单位未按规定申报应当缴纳的社会保险费数额的，按照该单位上月缴费额的百分之一百一十确定应当缴纳数额；缴费单位补办申报手续后，由社会保险费征收机构按照规定结算。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360062, '《中华人民共和国社会保险法》', '第六十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第七章 社会保险费征缴', NULL, '用人单位未按时足额缴纳社会保险费的，由社会保险费征收机构责令其限期缴纳或者补足。 用人单位逾期仍未缴纳或者补足社会保险费的，社会保险费征收机构可以向银行和其他金融机构查询其存款账户；并可以申请县级以上有关行政部门作出划拨社会保险费的决定，书面通知其开户银行或者其他金融机构划拨社会保险费。用人单位账户余额少于应当缴纳的社会保险费的，社会保险费征收机构可以要求该用人单位提供担保，签订延期缴费协议。 用人单位未足额缴纳社会保险费且未提供担保的，社会保险费征收机构可以申请人民法院扣押、查封、拍卖其价值相当于应当缴纳社会保险费的财产，以拍卖所得抵缴社会保险费。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360063, '《中华人民共和国社会保险法》', '第六十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第八章 社会保险基金', NULL, '社会保险基金包括基本养老保险基金、基本医疗保险基金、工伤保险基金、失业保险基金和生育保险基金。除基本医疗保险基金与生育保险基金合并建账及核算外，其他各项社会保险基金按照社会保险险种分别建账，分账核算。社会保险基金执行国家统一的会计制度。 社会保险基金专款专用，任何组织和个人不得侵占或者挪用。 基本养老保险基金逐步实行全国统筹，其他社会保险基金逐步实行省级统筹，具体时间、步骤由国务院规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360064, '《中华人民共和国社会保险法》', '第六十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第八章 社会保险基金', NULL, '社会保险基金通过预算实现收支平衡。 县级以上人民政府在社会保险基金出现支付不足时，给予补贴。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360065, '《中华人民共和国社会保险法》', '第六十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第八章 社会保险基金', NULL, '社会保险基金按照统筹层次设立预算。除基本医疗保险基金与生育保险基金预算合并编制外，其他社会保险基金预算按照社会保险项目分别编制。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360066, '《中华人民共和国社会保险法》', '第六十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第八章 社会保险基金', NULL, '社会保险基金预算、决算草案的编制、审核和批准，依照法律和国务院规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360067, '《中华人民共和国社会保险法》', '第六十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第八章 社会保险基金', NULL, '社会保险基金存入财政专户，具体管理办法由国务院规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360068, '《中华人民共和国社会保险法》', '第六十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第八章 社会保险基金', NULL, '社会保险基金在保证安全的前提下，按照国务院规定投资运营实现保值增值。 社会保险基金不得违规投资运营，不得用于平衡其他政府预算，不得用于兴建、改建办公场所和支付人员经费、运行费用、管理费用，或者违反法律、行政法规规定挪作其他用途。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360069, '《中华人民共和国社会保险法》', '第七十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第八章 社会保险基金', NULL, '社会保险经办机构应当定期向社会公布参加社会保险情况以及社会保险基金的收入、支出、结余和收益情况。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360070, '《中华人民共和国社会保险法》', '第七十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第八章 社会保险基金', NULL, '国家设立全国社会保障基金，由中央财政预算拨款以及国务院批准的其他方式筹集的资金构成，用于社会保障支出的补充、调剂。全国社会保障基金由全国社会保障基金管理运营机构负责管理运营，在保证安全的前提下实现保值增值。 全国社会保障基金应当定期向社会公布收支、管理和投资运营的情况。国务院财政部门、社会保险行政部门、审计机关对全国社会保障基金的收支、管理和投资运营情况实施监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360071, '《中华人民共和国社会保险法》', '第七十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第九章 社会保险经办', NULL, '统筹地区设立社会保险经办机构。社会保险经办机构根据工作需要，经所在地的社会保险行政部门和机构编制管理机关批准，可以在本统筹地区设立分支机构和服务网点。 社会保险经办机构的人员经费和经办社会保险发生的基本运行费用、管理费用，由同级财政按照国家规定予以保障。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360072, '《中华人民共和国社会保险法》', '第七十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第九章 社会保险经办', NULL, '社会保险经办机构应当建立健全业务、财务、安全和风险管理制度。 社会保险经办机构应当按时足额支付社会保险待遇。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360073, '《中华人民共和国社会保险法》', '第七十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第九章 社会保险经办', NULL, '社会保险经办机构通过业务经办、统计、调查获取社会保险工作所需的数据，有关单位和个人应当及时、如实提供。 社会保险经办机构应当及时为用人单位建立档案，完整、准确地记录参加社会保险的人员、缴费等社会保险数据，妥善保管登记、申报的原始凭证和支付结算的会计凭证。 社会保险经办机构应当及时、完整、准确地记录参加社会保险的个人缴费和用人单位为其缴费，以及享受社会保险待遇等个人权益记录，定期将个人权益记录单免费寄送本人。 用人单位和个人可以免费向社会保险经办机构查询、核对其缴费和享受社会保险待遇记录，要求社会保险经办机构提供社会保险咨询等相关服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360074, '《中华人民共和国社会保险法》', '第七十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第九章 社会保险经办', NULL, '全国社会保险信息系统按照国家统一规划，由县级以上人民政府按照分级负责的原则共同建设。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360075, '《中华人民共和国社会保险法》', '第七十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十章 社会保险监督', NULL, '各级人民代表大会常务委员会听取和审议本级人民政府对社会保险基金的收支、管理、投资运营以及监督检查情况的专项工作报告，组织对本法实施情况的执法检查等，依法行使监督职权。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360076, '《中华人民共和国社会保险法》', '第七十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十章 社会保险监督', NULL, '县级以上人民政府社会保险行政部门应当加强对用人单位和个人遵守社会保险法律、法规情况的监督检查。 社会保险行政部门实施监督检查时，被检查的用人单位和个人应当如实提供与社会保险有关的资料，不得拒绝检查或者谎报、瞒报。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360077, '《中华人民共和国社会保险法》', '第七十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十章 社会保险监督', NULL, '财政部门、审计机关按照各自职责，对社会保险基金的收支、管理和投资运营情况实施监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360078, '《中华人民共和国社会保险法》', '第七十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十章 社会保险监督', NULL, '社会保险行政部门对社会保险基金的收支、管理和投资运营情况进行监督检查，发现存在问题的，应当提出整改建议，依法作出处理决定或者向有关行政部门提出处理建议。社会保险基金检查结果应当定期向社会公布。 社会保险行政部门对社会保险基金实施监督检查，有权采取下列措施： （一）查阅、记录、复制与社会保险基金收支、管理和投资运营相关的资料，对可能被转移、隐匿或者灭失的资料予以封存； （二）询问与调查事项有关的单位和个人，要求其对与调查事项有关的问题作出说明、提供有关证明材料； （三）对隐匿、转移、侵占、挪用社会保险基金的行为予以制止并责令改正。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360079, '《中华人民共和国社会保险法》', '第八十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十章 社会保险监督', NULL, '统筹地区人民政府成立由用人单位代表、参保人员代表，以及工会代表、专家等组成的社会保险监督委员会，掌握、分析社会保险基金的收支、管理和投资运营情况，对社会保险工作提出咨询意见和建议，实施社会监督。 社会保险经办机构应当定期向社会保险监督委员会汇报社会保险基金的收支、管理和投资运营情况。社会保险监督委员会可以聘请会计师事务所对社会保险基金的收支、管理和投资运营情况进行年度审计和专项审计。审计结果应当向社会公开。 社会保险监督委员会发现社会保险基金收支、管理和投资运营中存在问题的，有权提出改正建议；对社会保险经办机构及其工作人员的违法行为，有权向有关部门提出依法处理建议。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360080, '《中华人民共和国社会保险法》', '第八十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十章 社会保险监督', NULL, '社会保险行政部门和其他有关行政部门、社会保险经办机构、社会保险费征收机构及其工作人员，应当依法为用人单位和个人的信息保密，不得以任何形式泄露。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360081, '《中华人民共和国社会保险法》', '第八十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十章 社会保险监督', NULL, '任何组织或者个人有权对违反社会保险法律、法规的行为进行举报、投诉。 社会保险行政部门、卫生行政部门、社会保险经办机构、社会保险费征收机构和财政部门、审计机关对属于本部门、本机构职责范围的举报、投诉，应当依法处理；对不属于本部门、本机构职责范围的，应当书面通知并移交有权处理的部门、机构处理。有权处理的部门、机构应当及时处理，不得推诿。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360082, '《中华人民共和国社会保险法》', '第八十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十章 社会保险监督', NULL, '用人单位或者个人认为社会保险费征收机构的行为侵害自己合法权益的，可以依法申请行政复议或者提起行政诉讼。 用人单位或者个人对社会保险经办机构不依法办理社会保险登记、核定社会保险费、支付社会保险待遇、办理社会保险转移接续手续或者侵害其他社会保险权益的行为，可以依法申请行政复议或者提起行政诉讼。 个人与所在用人单位发生社会保险争议的，可以依法申请调解、仲裁，提起诉讼。用人单位侵害个人社会保险权益的，个人也可以要求社会保险行政部门或者社会保险费征收机构依法处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360083, '《中华人民共和国社会保险法》', '第八十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十一章 法律责任', NULL, '用人单位不办理社会保险登记的，由社会保险行政部门责令限期改正；逾期不改正的，对用人单位处应缴社会保险费数额一倍以上三倍以下的罚款，对其直接负责的主管人员和其他直接责任人员处五百元以上三千元以下的罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360084, '《中华人民共和国社会保险法》', '第八十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十一章 法律责任', NULL, '用人单位拒不出具终止或者解除劳动关系证明的，依照《中华人民共和国劳动合同法》的规定处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360085, '《中华人民共和国社会保险法》', '第八十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十一章 法律责任', NULL, '用人单位未按时足额缴纳社会保险费的，由社会保险费征收机构责令限期缴纳或者补足，并自欠缴之日起，按日加收万分之五的滞纳金；逾期仍不缴纳的，由有关行政部门处欠缴数额一倍以上三倍以下的罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360086, '《中华人民共和国社会保险法》', '第八十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十一章 法律责任', NULL, '社会保险经办机构以及医疗机构、药品经营单位等社会保险服务机构以欺诈、伪造证明材料或者其他手段骗取社会保险基金支出的，由社会保险行政部门责令退回骗取的社会保险金，处骗取金额二倍以上五倍以下的罚款；属于社会保险服务机构的，解除服务协议；直接负责的主管人员和其他直接责任人员有执业资格的，依法吊销其执业资格。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360087, '《中华人民共和国社会保险法》', '第八十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十一章 法律责任', NULL, '以欺诈、伪造证明材料或者其他手段骗取社会保险待遇的，由社会保险行政部门责令退回骗取的社会保险金，处骗取金额二倍以上五倍以下的罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360088, '《中华人民共和国社会保险法》', '第八十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十一章 法律责任', NULL, '社会保险经办机构及其工作人员有下列行为之一的，由社会保险行政部门责令改正；给社会保险基金、用人单位或者个人造成损失的，依法承担赔偿责任；对直接负责的主管人员和其他直接责任人员依法给予处分： （一）未履行社会保险法定职责的； （二）未将社会保险基金存入财政专户的； （三）克扣或者拒不按时支付社会保险待遇的； （四）丢失或者篡改缴费记录、享受社会保险待遇记录等社会保险数据、个人权益记录的； （五）有违反社会保险法律、法规的其他行为的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360089, '《中华人民共和国社会保险法》', '第九十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十一章 法律责任', NULL, '社会保险费征收机构擅自更改社会保险费缴费基数、费率，导致少收或者多收社会保险费的，由有关行政部门责令其追缴应当缴纳的社会保险费或者退还不应当缴纳的社会保险费；对直接负责的主管人员和其他直接责任人员依法给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360090, '《中华人民共和国社会保险法》', '第九十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十一章 法律责任', NULL, '违反本法规定，隐匿、转移、侵占、挪用社会保险基金或者违规投资运营的，由社会保险行政部门、财政部门、审计机关责令追回；有违法所得的，没收违法所得；对直接负责的主管人员和其他直接责任人员依法给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360091, '《中华人民共和国社会保险法》', '第九十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十一章 法律责任', NULL, '社会保险行政部门和其他有关行政部门、社会保险经办机构、社会保险费征收机构及其工作人员泄露用人单位和个人信息的，对直接负责的主管人员和其他直接责任人员依法给予处分；给用人单位或者个人造成损失的，应当承担赔偿责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360092, '《中华人民共和国社会保险法》', '第九十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十一章 法律责任', NULL, '国家工作人员在社会保险管理、监督工作中滥用职权、玩忽职守、徇私舞弊的，依法给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360093, '《中华人民共和国社会保险法》', '第九十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十一章 法律责任', NULL, '违反本法规定，构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360094, '《中华人民共和国社会保险法》', '第九十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十二章 附 则', NULL, '进城务工的农村居民依照本法规定参加社会保险。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360095, '《中华人民共和国社会保险法》', '第九十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十二章 附 则', NULL, '征收农村集体所有的土地，应当足额安排被征地农民的社会保险费，按照国务院规定将被征地农民纳入相应的社会保险制度。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360096, '《中华人民共和国社会保险法》', '第九十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十二章 附 则', NULL, '外国人在中国境内就业的，参照本法规定参加社会保险。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1360097, '《中华人民共和国社会保险法》', '第九十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十二章 附 则', NULL, '本法自2011年7月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363000, '《中华人民共和国劳动法》', '第一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '为了保护劳动者的合法权益，调整劳动关系，建立和维护适应社会主义市场经济的劳动制度，促进经济发展和社会进步，根据宪法，制定本法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363001, '《中华人民共和国劳动法》', '第二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '在中华人民共和国境内的企业、个体经济组织（以下统称用人单位）和与之形成劳动关系的劳动者，适用本法。 国家机关、事业组织、社会团体和与之建立劳动合同关系的劳动者，依照本法执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363002, '《中华人民共和国劳动法》', '第三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '劳动者享有平等就业和选择职业的权利、取得劳动报酬的权利、休息休假的权利、获得劳动安全卫生保护的权利、接受职业技能培训的权利、享受社会保险和福利的权利、提请劳动争议处理的权利以及法律规定的其他劳动权利。 劳动者应当完成劳动任务，提高职业技能，执行劳动安全卫生规程，遵守劳动纪律和职业道德。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363003, '《中华人民共和国劳动法》', '第四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '用人单位应当依法建立和完善规章制度，保障劳动者享有劳动权利和履行劳动义务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363004, '《中华人民共和国劳动法》', '第五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '国家采取各种措施，促进劳动就业，发展职业教育，制定劳动标准，调节社会收入，完善社会保险，协调劳动关系，逐步提高劳动者的生活水平。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363005, '《中华人民共和国劳动法》', '第六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '国家提倡劳动者参加社会义务劳动，开展劳动竞赛和合理化建议活动，鼓励和保护劳动者进行科学研究、技术革新和发明创造，表彰和奖励劳动模范和先进工作者。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363006, '《中华人民共和国劳动法》', '第七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '劳动者有权依法参加和组织工会。 工会代表和维护劳动者的合法权益，依法独立自主地开展活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363007, '《中华人民共和国劳动法》', '第八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '劳动者依照法律规定，通过职工大会、职工代表大会或者其他形式，参与民主管理或者就保护劳动者合法权益与用人单位进行平等协商。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363008, '《中华人民共和国劳动法》', '第九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '国务院劳动行政部门主管全国劳动工作。 县级以上地方人民政府劳动行政部门主管本行政区域内的劳动工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363009, '《中华人民共和国劳动法》', '第十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 促进就业', NULL, '国家通过促进经济和社会发展，创造就业条件，扩大就业机会。 国家鼓励企业、事业组织、社会团体在法律、行政法规规定的范围内兴办产业或者拓展经营，增加就业。 国家支持劳动者自愿组织起来就业和从事个体经营实现就业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363010, '《中华人民共和国劳动法》', '第十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 促进就业', NULL, '地方各级人民政府应当采取措施，发展多种类型的职业介绍机构，提供就业服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363011, '《中华人民共和国劳动法》', '第十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 促进就业', NULL, '劳动者就业，不因民族、种族、性别、宗教信仰不同而受歧视。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363012, '《中华人民共和国劳动法》', '第十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 促进就业', NULL, '妇女享有与男子平等的就业权利。在录用职工时，除国家规定的不适合妇女的工种或者岗位外，不得以性别为由拒绝录用妇女或者提高对妇女的录用标准。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363013, '《中华人民共和国劳动法》', '第十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 促进就业', NULL, '残疾人、少数民族人员、退出现役的军人的就业，法律、法规有特别规定的，从其规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363014, '《中华人民共和国劳动法》', '第十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 促进就业', NULL, '禁止用人单位招用未满十六周岁的未成年人。 文艺、体育和特种工艺单位招用未满十六周岁的未成年人，必须遵守国家有关规定，并保障其接受义务教育的权利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363015, '《中华人民共和国劳动法》', '第十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动合同和集体合同', NULL, '劳动合同是劳动者与用人单位确立劳动关系、明确双方权利和义务的协议。 建立劳动关系应当订立劳动合同。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363016, '《中华人民共和国劳动法》', '第十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动合同和集体合同', NULL, '订立和变更劳动合同，应当遵循平等自愿、协商一致的原则，不得违反法律、行政法规的规定。 劳动合同依法订立即具有法律约束力，当事人必须履行劳动合同规定的义务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363017, '《中华人民共和国劳动法》', '第十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动合同和集体合同', NULL, '下列劳动合同无效： （一）违反法律、行政法规的劳动合同； （二）采取欺诈、威胁等手段订立的劳动合同。 无效的劳动合同，从订立的时候起，就没有法律约束力。确认劳动合同部分无效的，如果不影响其余部分的效力，其余部分仍然有效。 劳动合同的无效，由劳动争议仲裁委员会或者人民法院确认。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363018, '《中华人民共和国劳动法》', '第十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动合同和集体合同', NULL, '劳动合同应当以书面形式订立，并具备以下条款： （一）劳动合同期限； （二）工作内容； （三）劳动保护和劳动条件； （四）劳动报酬； （五）劳动纪律； （六）劳动合同终止的条件； （七）违反劳动合同的责任。 劳动合同除前款规定的必备条款外，当事人可以协商约定其他内容。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363019, '《中华人民共和国劳动法》', '第二十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动合同和集体合同', NULL, '劳动合同的期限分为有固定期限、无固定期限和以完成一定的工作为期限。 劳动者在同一用人单位连续工作满十年以上，当事人双方同意续延劳动合同的，如果劳动者提出订立无固定期限的劳动合同，应当订立无固定期限的劳动合同。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363020, '《中华人民共和国劳动法》', '第二十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动合同和集体合同', NULL, '劳动合同可以约定试用期。试用期最长不得超过六个月。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363021, '《中华人民共和国劳动法》', '第二十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动合同和集体合同', NULL, '劳动合同当事人可以在劳动合同中约定保守用人单位商业秘密的有关事项。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363022, '《中华人民共和国劳动法》', '第二十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动合同和集体合同', NULL, '劳动合同期满或者当事人约定的劳动合同终止条件出现，劳动合同即行终止。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363023, '《中华人民共和国劳动法》', '第二十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动合同和集体合同', NULL, '经劳动合同当事人协商一致，劳动合同可以解除。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363024, '《中华人民共和国劳动法》', '第二十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动合同和集体合同', NULL, '劳动者有下列情形之一的，用人单位可以解除劳动合同： （一）在试用期间被证明不符合录用条件的； （二）严重违反劳动纪律或者用人单位规章制度的； （三）严重失职，营私舞弊，对用人单位利益造成重大损害的； （四）被依法追究刑事责任的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363025, '《中华人民共和国劳动法》', '第二十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动合同和集体合同', NULL, '有下列情形之一的，用人单位可以解除劳动合同，但是应当提前三十日以书面形式通知劳动者本人： （一）劳动者患病或者非因工负伤，医疗期满后，不能从事原工作也不能从事由用人单位另行安排的工作的； （二）劳动者不能胜任工作，经过培训或者调整工作岗位，仍不能胜任工作的； （三）劳动合同订立时所依据的客观情况发生重大变化，致使原劳动合同无法履行，经当事人协商不能就变更劳动合同达成协议的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363026, '《中华人民共和国劳动法》', '第二十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动合同和集体合同', NULL, '用人单位濒临破产进行法定整顿期间或者生产经营状况发生严重困难，确需裁减人员的，应当提前三十日向工会或者全体职工说明情况，听取工会或者职工的意见，经向劳动行政部门报告后，可以裁减人员。 用人单位依据本条规定裁减人员，在六个月内录用人员的，应当优先录用被裁减的人员。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363027, '《中华人民共和国劳动法》', '第二十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动合同和集体合同', NULL, '用人单位依据本法第二十四条、第二十六条、第二十七条的规定解除劳动合同的，应当依照国家有关规定给予经济补偿。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363028, '《中华人民共和国劳动法》', '第二十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动合同和集体合同', NULL, '劳动者有下列情形之一的，用人单位不得依据本法第二十六条、第二十七条的规定解除劳动合同： （一）患职业病或者因工负伤并被确认丧失或者部分丧失劳动能力的； （二）患病或者负伤，在规定的医疗期内的； （三）女职工在孕期、产期、哺乳期内的； （四）法律、行政法规规定的其他情形。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363029, '《中华人民共和国劳动法》', '第三十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动合同和集体合同', NULL, '用人单位解除劳动合同，工会认为不适当的，有权提出意见。如果用人单位违反法律、法规或者劳动合同，工会有权要求重新处理；劳动者申请仲裁或者提起诉讼的，工会应当依法给予支持和帮助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363030, '《中华人民共和国劳动法》', '第三十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动合同和集体合同', NULL, '劳动者解除劳动合同，应当提前三十日以书面形式通知用人单位。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363031, '《中华人民共和国劳动法》', '第三十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动合同和集体合同', NULL, '有下列情形之一的，劳动者可以随时通知用人单位解除劳动合同： （一）在试用期内的； （二）用人单位以暴力、威胁或者非法限制人身自由的手段强迫劳动的； （三）用人单位未按照劳动合同约定支付劳动报酬或者提供劳动条件的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363032, '《中华人民共和国劳动法》', '第三十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动合同和集体合同', NULL, '企业职工一方与企业可以就劳动报酬、工作时间、休息休假、劳动安全卫生、保险福利等事项，签订集体合同。集体合同草案应当提交职工代表大会或者全体职工讨论通过。 集体合同由工会代表职工与企业签订；没有建立工会的企业，由职工推举的代表与企业签订。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363033, '《中华人民共和国劳动法》', '第三十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动合同和集体合同', NULL, '集体合同签订后应当报送劳动行政部门；劳动行政部门自收到集体合同文本之日起十五日内未提出异议的，集体合同即行生效。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363034, '《中华人民共和国劳动法》', '第三十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动合同和集体合同', NULL, '依法签订的集体合同对企业和企业全体职工具有约束力。职工个人与企业订立的劳动合同中劳动条件和劳动报酬等标准不得低于集体合同的规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363035, '《中华人民共和国劳动法》', '第三十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 工作时间和休息休假', NULL, '国家实行劳动者每日工作时间不超过八小时、平均每周工作时间不超过四十四小时的工时制度。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363036, '《中华人民共和国劳动法》', '第三十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 工作时间和休息休假', NULL, '对实行计件工作的劳动者，用人单位应当根据本法第三十六条规定的工时制度合理确定其劳动定额和计件报酬标准。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363037, '《中华人民共和国劳动法》', '第三十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 工作时间和休息休假', NULL, '用人单位应当保证劳动者每周至少休息一日。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363038, '《中华人民共和国劳动法》', '第三十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 工作时间和休息休假', NULL, '企业因生产特点不能实行本法第三十六条、第三十八条规定的，经劳动行政部门批准，可以实行其他工作和休息办法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363039, '《中华人民共和国劳动法》', '第四十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 工作时间和休息休假', NULL, '用人单位在下列节日期间应当依法安排劳动者休假： （一）元旦； （二）春节； （三）国际劳动节； （四）国庆节； （五）法律、法规规定的其他休假节日。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363040, '《中华人民共和国劳动法》', '第四十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 工作时间和休息休假', NULL, '用人单位由于生产经营需要，经与工会和劳动者协商后可以延长工作时间，一般每日不得超过一小时；因特殊原因需要延长工作时间的，在保障劳动者身体健康的条件下延长工作时间每日不得超过三小时，但是每月不得超过三十六小时。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363041, '《中华人民共和国劳动法》', '第四十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 工作时间和休息休假', NULL, '有下列情形之一的，延长工作时间不受本法第四十一条规定的限制： （一）发生自然灾害、事故或者因其他原因，威胁劳动者生命健康和财产安全，需要紧急处理的； （二）生产设备、交通运输线路、公共设施发生故障，影响生产和公众利益，必须及时抢修的； （三）法律、行政法规规定的其他情形。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363042, '《中华人民共和国劳动法》', '第四十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 工作时间和休息休假', NULL, '用人单位不得违反本法规定延长劳动者的工作时间。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363043, '《中华人民共和国劳动法》', '第四十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 工作时间和休息休假', NULL, '有下列情形之一的，用人单位应当按照下列标准支付高于劳动者正常工作时间工资的工资报酬： （一）安排劳动者延长工作时间的，支付不低于工资的百分之一百五十的工资报酬； （二）休息日安排劳动者工作又不能安排补休的，支付不低于工资的百分之二百的工资报酬； （三）法定休假日安排劳动者工作的，支付不低于工资的百分之三百的工资报酬。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363044, '《中华人民共和国劳动法》', '第四十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 工作时间和休息休假', NULL, '国家实行带薪年休假制度。 劳动者连续工作一年以上的，享受带薪年休假。具体办法由国务院规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363045, '《中华人民共和国劳动法》', '第四十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 工 资', NULL, '工资分配应当遵循按劳分配原则，实行同工同酬。 工资水平在经济发展的基础上逐步提高。国家对工资总量实行宏观调控。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363046, '《中华人民共和国劳动法》', '第四十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 工 资', NULL, '用人单位根据本单位的生产经营特点和经济效益，依法自主确定本单位的工资分配方式和工资水平。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363047, '《中华人民共和国劳动法》', '第四十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 工 资', NULL, '国家实行最低工资保障制度。最低工资的具体标准由省、自治区、直辖市人民政府规定，报国务院备案。 用人单位支付劳动者的工资不得低于当地最低工资标准。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363048, '《中华人民共和国劳动法》', '第四十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 工 资', NULL, '确定和调整最低工资标准应当综合参考下列因素： （一）劳动者本人及平均赡养人口的最低生活费用； （二）社会平均工资水平； （三）劳动生产率； （四）就业状况； （五）地区之间经济发展水平的差异。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363049, '《中华人民共和国劳动法》', '第五十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 工 资', NULL, '工资应当以货币形式按月支付给劳动者本人。不得克扣或者无故拖欠劳动者的工资。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363050, '《中华人民共和国劳动法》', '第五十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 工 资', NULL, '劳动者在法定休假日和婚丧假期间以及依法参加社会活动期间，用人单位应当依法支付工资。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363051, '《中华人民共和国劳动法》', '第五十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 劳动安全卫生', NULL, '用人单位必须建立、健全劳动安全卫生制度，严格执行国家劳动安全卫生规程和标准，对劳动者进行劳动安全卫生教育，防止劳动过程中的事故，减少职业危害。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363052, '《中华人民共和国劳动法》', '第五十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 劳动安全卫生', NULL, '劳动安全卫生设施必须符合国家规定的标准。 新建、改建、扩建工程的劳动安全卫生设施必须与主体工程同时设计、同时施工、同时投入生产和使用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363053, '《中华人民共和国劳动法》', '第五十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 劳动安全卫生', NULL, '用人单位必须为劳动者提供符合国家规定的劳动安全卫生条件和必要的劳动防护用品，对从事有职业危害作业的劳动者应当定期进行健康检查。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363054, '《中华人民共和国劳动法》', '第五十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 劳动安全卫生', NULL, '从事特种作业的劳动者必须经过专门培训并取得特种作业资格。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363055, '《中华人民共和国劳动法》', '第五十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 劳动安全卫生', NULL, '劳动者在劳动过程中必须严格遵守安全操作规程。 劳动者对用人单位管理人员违章指挥、强令冒险作业，有权拒绝执行；对危害生命安全和身体健康的行为，有权提出批评、检举和控告。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363056, '《中华人民共和国劳动法》', '第五十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 劳动安全卫生', NULL, '国家建立伤亡事故和职业病统计报告和处理制度。县级以上各级人民政府劳动行政部门、有关部门和用人单位应当依法对劳动者在劳动过程中发生的伤亡事故和劳动者的职业病状况，进行统计、报告和处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363057, '《中华人民共和国劳动法》', '第五十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第七章 女职工和未成年工特殊保护', NULL, '国家对女职工和未成年工实行特殊劳动保护。 未成年工是指年满十六周岁未满十八周岁的劳动者。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363058, '《中华人民共和国劳动法》', '第五十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第七章 女职工和未成年工特殊保护', NULL, '禁止安排女职工从事矿山井下、国家规定的第四级体力劳动强度的劳动和其他禁忌从事的劳动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363059, '《中华人民共和国劳动法》', '第六十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第七章 女职工和未成年工特殊保护', NULL, '不得安排女职工在经期从事高处、低温、冷水作业和国家规定的第三级体力劳动强度的劳动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363060, '《中华人民共和国劳动法》', '第六十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第七章 女职工和未成年工特殊保护', NULL, '不得安排女职工在怀孕期间从事国家规定的第三级体力劳动强度的劳动和孕期禁忌从事的劳动。对怀孕七个月以上的女职工，不得安排其延长工作时间和夜班劳动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363061, '《中华人民共和国劳动法》', '第六十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第七章 女职工和未成年工特殊保护', NULL, '女职工生育享受不少于九十天的产假。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363062, '《中华人民共和国劳动法》', '第六十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第七章 女职工和未成年工特殊保护', NULL, '不得安排女职工在哺乳未满一周岁的婴儿期间从事国家规定的第三级体力劳动强度的劳动和哺乳期禁忌从事的其他劳动，不得安排其延长工作时间和夜班劳动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363063, '《中华人民共和国劳动法》', '第六十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第七章 女职工和未成年工特殊保护', NULL, '不得安排未成年工从事矿山井下、有毒有害、国家规定的第四级体力劳动强度的劳动和其他禁忌从事的劳动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363064, '《中华人民共和国劳动法》', '第六十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第七章 女职工和未成年工特殊保护', NULL, '用人单位应当对未成年工定期进行健康检查。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363065, '《中华人民共和国劳动法》', '第六十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第八章 职业培训', NULL, '国家通过各种途径，采取各种措施，发展职业培训事业，开发劳动者的职业技能，提高劳动者素质，增强劳动者的就业能力和工作能力。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363066, '《中华人民共和国劳动法》', '第六十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第八章 职业培训', NULL, '各级人民政府应当把发展职业培训纳入社会经济发展的规划，鼓励和支持有条件的企业、事业组织、社会团体和个人进行各种形式的职业培训。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363067, '《中华人民共和国劳动法》', '第六十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第八章 职业培训', NULL, '用人单位应当建立职业培训制度，按照国家规定提取和使用职业培训经费，根据本单位实际，有计划地对劳动者进行职业培训。 从事技术工种的劳动者，上岗前必须经过培训。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363068, '《中华人民共和国劳动法》', '第六十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第八章 职业培训', NULL, '国家确定职业分类，对规定的职业制定职业技能标准，实行职业资格证书制度，由经备案的考核鉴定机构负责对劳动者实施职业技能考核鉴定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363069, '《中华人民共和国劳动法》', '第七十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第九章 社会保险和福利', NULL, '国家发展社会保险事业，建立社会保险制度，设立社会保险基金，使劳动者在年老、患病、工伤、失业、生育等情况下获得帮助和补偿。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363070, '《中华人民共和国劳动法》', '第七十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第九章 社会保险和福利', NULL, '社会保险水平应当与社会经济发展水平和社会承受能力相适应。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363071, '《中华人民共和国劳动法》', '第七十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第九章 社会保险和福利', NULL, '社会保险基金按照保险类型确定资金来源，逐步实行社会统筹。用人单位和劳动者必须依法参加社会保险，缴纳社会保险费。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363072, '《中华人民共和国劳动法》', '第七十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第九章 社会保险和福利', NULL, '劳动者在下列情形下，依法享受社会保险待遇： （一）退休； （二）患病、负伤； （三）因工伤残或者患职业病； （四）失业； （五）生育。 劳动者死亡后，其遗属依法享受遗属津贴。 劳动者享受社会保险待遇的条件和标准由法律、法规规定。 劳动者享受的社会保险金必须按时足额支付。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363073, '《中华人民共和国劳动法》', '第七十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第九章 社会保险和福利', NULL, '社会保险基金经办机构依照法律规定收支、管理和运营社会保险基金，并负有使社会保险基金保值增值的责任。 社会保险基金监督机构依照法律规定，对社会保险基金的收支、管理和运营实施监督。 社会保险基金经办机构和社会保险基金监督机构的设立和职能由法律规定。 任何组织和个人不得挪用社会保险基金。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363074, '《中华人民共和国劳动法》', '第七十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第九章 社会保险和福利', NULL, '国家鼓励用人单位根据本单位实际情况为劳动者建立补充保险。 国家提倡劳动者个人进行储蓄性保险。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363075, '《中华人民共和国劳动法》', '第七十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第九章 社会保险和福利', NULL, '国家发展社会福利事业，兴建公共福利设施，为劳动者休息、休养和疗养提供条件。 用人单位应当创造条件，改善集体福利，提高劳动者的福利待遇。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363076, '《中华人民共和国劳动法》', '第七十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十章 劳动争议', NULL, '用人单位与劳动者发生劳动争议，当事人可以依法申请调解、仲裁、提起诉讼，也可以协商解决。 调解原则适用于仲裁和诉讼程序。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363077, '《中华人民共和国劳动法》', '第七十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十章 劳动争议', NULL, '解决劳动争议，应当根据合法、公正、及时处理的原则，依法维护劳动争议当事人的合法权益。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363078, '《中华人民共和国劳动法》', '第七十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十章 劳动争议', NULL, '劳动争议发生后，当事人可以向本单位劳动争议调解委员会申请调解；调解不成，当事人一方要求仲裁的，可以向劳动争议仲裁委员会申请仲裁。当事人一方也可以直接向劳动争议仲裁委员会申请仲裁。对仲裁裁决不服的，可以向人民法院提起诉讼。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363079, '《中华人民共和国劳动法》', '第八十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十章 劳动争议', NULL, '在用人单位内，可以设立劳动争议调解委员会。劳动争议调解委员会由职工代表、用人单位代表和工会代表组成。劳动争议调解委员会主任由工会代表担任。 劳动争议经调解达成协议的，当事人应当履行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363080, '《中华人民共和国劳动法》', '第八十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十章 劳动争议', NULL, '劳动争议仲裁委员会由劳动行政部门代表、同级工会代表、用人单位方面的代表组成。劳动争议仲裁委员会主任由劳动行政部门代表担任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363081, '《中华人民共和国劳动法》', '第八十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十章 劳动争议', NULL, '提出仲裁要求的一方应当自劳动争议发生之日起六十日内向劳动争议仲裁委员会提出书面申请。仲裁裁决一般应在收到仲裁申请的六十日内作出。对仲裁裁决无异议的，当事人必须履行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363082, '《中华人民共和国劳动法》', '第八十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十章 劳动争议', NULL, '劳动争议当事人对仲裁裁决不服的，可以自收到仲裁裁决书之日起十五日内向人民法院提起诉讼。一方当事人在法定期限内不起诉又不履行仲裁裁决的，另一方当事人可以申请人民法院强制执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363083, '《中华人民共和国劳动法》', '第八十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十章 劳动争议', NULL, '因签订集体合同发生争议，当事人协商解决不成的，当地人民政府劳动行政部门可以组织有关各方协调处理。 因履行集体合同发生争议，当事人协商解决不成的，可以向劳动争议仲裁委员会申请仲裁；对仲裁裁决不服的，可以自收到仲裁裁决书之日起十五日内向人民法院提起诉讼。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363084, '《中华人民共和国劳动法》', '第八十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十一章 监督检查', NULL, '县级以上各级人民政府劳动行政部门依法对用人单位遵守劳动法律、法规的情况进行监督检查，对违反劳动法律、法规的行为有权制止，并责令改正。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363085, '《中华人民共和国劳动法》', '第八十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十一章 监督检查', NULL, '县级以上各级人民政府劳动行政部门监督检查人员执行公务，有权进入用人单位了解执行劳动法律、法规的情况，查阅必要的资料，并对劳动场所进行检查。 县级以上各级人民政府劳动行政部门监督检查人员执行公务，必须出示证件，秉公执法并遵守有关规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363086, '《中华人民共和国劳动法》', '第八十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十一章 监督检查', NULL, '县级以上各级人民政府有关部门在各自职责范围内，对用人单位遵守劳动法律、法规的情况进行监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363087, '《中华人民共和国劳动法》', '第八十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十一章 监督检查', NULL, '各级工会依法维护劳动者的合法权益，对用人单位遵守劳动法律、法规的情况进行监督。 任何组织和个人对于违反劳动法律、法规的行为有权检举和控告。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363088, '《中华人民共和国劳动法》', '第八十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十二章 法律责任', NULL, '用人单位制定的劳动规章制度违反法律、法规规定的，由劳动行政部门给予警告，责令改正；对劳动者造成损害的，应当承担赔偿责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363089, '《中华人民共和国劳动法》', '第九十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十二章 法律责任', NULL, '用人单位违反本法规定，延长劳动者工作时间的，由劳动行政部门给予警告，责令改正，并可以处以罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363090, '《中华人民共和国劳动法》', '第九十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十二章 法律责任', NULL, '用人单位有下列侵害劳动者合法权益情形之一的，由劳动行政部门责令支付劳动者的工资报酬、经济补偿，并可以责令支付赔偿金： （一）克扣或者无故拖欠劳动者工资的； （二）拒不支付劳动者延长工作时间工资报酬的； （三）低于当地最低工资标准支付劳动者工资的； （四）解除劳动合同后，未依照本法规定给予劳动者经济补偿的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363091, '《中华人民共和国劳动法》', '第九十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十二章 法律责任', NULL, '用人单位的劳动安全设施和劳动卫生条件不符合国家规定或者未向劳动者提供必要的劳动防护用品和劳动保护设施的，由劳动行政部门或者有关部门责令改正，可以处以罚款；情节严重的，提请县级以上人民政府决定责令停产整顿；对事故隐患不采取措施，致使发生重大事故，造成劳动者生命和财产损失的，对责任人员依照刑法有关规定追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363092, '《中华人民共和国劳动法》', '第九十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十二章 法律责任', NULL, '用人单位强令劳动者违章冒险作业，发生重大伤亡事故，造成严重后果的，对责任人员依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363093, '《中华人民共和国劳动法》', '第九十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十二章 法律责任', NULL, '用人单位非法招用未满十六周岁的未成年人的，由劳动行政部门责令改正，处以罚款；情节严重的，由市场监督管理部门吊销营业执照。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363094, '《中华人民共和国劳动法》', '第九十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十二章 法律责任', NULL, '用人单位违反本法对女职工和未成年工的保护规定，侵害其合法权益的，由劳动行政部门责令改正，处以罚款；对女职工或者未成年工造成损害的，应当承担赔偿责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363095, '《中华人民共和国劳动法》', '第九十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十二章 法律责任', NULL, '用人单位有下列行为之一，由公安机关对责任人员处以十五日以下拘留、罚款或者警告；构成犯罪的，对责任人员依法追究刑事责任： （一）以暴力、威胁或者非法限制人身自由的手段强迫劳动的； （二）侮辱、体罚、殴打、非法搜查和拘禁劳动者的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363096, '《中华人民共和国劳动法》', '第九十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十二章 法律责任', NULL, '由于用人单位的原因订立的无效合同，对劳动者造成损害的，应当承担赔偿责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363097, '《中华人民共和国劳动法》', '第九十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十二章 法律责任', NULL, '用人单位违反本法规定的条件解除劳动合同或者故意拖延不订立劳动合同的，由劳动行政部门责令改正；对劳动者造成损害的，应当承担赔偿责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363098, '《中华人民共和国劳动法》', '第九十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十二章 法律责任', NULL, '用人单位招用尚未解除劳动合同的劳动者，对原用人单位造成经济损失的，该用人单位应当依法承担连带赔偿责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363099, '《中华人民共和国劳动法》', '第一百条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十二章 法律责任', NULL, '用人单位无故不缴纳社会保险费的，由劳动行政部门责令其限期缴纳；逾期不缴的，可以加收滞纳金。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363100, '《中华人民共和国劳动法》', '第一百零一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十二章 法律责任', NULL, '用人单位无理阻挠劳动行政部门、有关部门及其工作人员行使监督检查权，打击报复举报人员的，由劳动行政部门或者有关部门处以罚款；构成犯罪的，对责任人员依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363101, '《中华人民共和国劳动法》', '第一百零二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十二章 法律责任', NULL, '劳动者违反本法规定的条件解除劳动合同或者违反劳动合同中约定的保密事项，对用人单位造成经济损失的，应当依法承担赔偿责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363102, '《中华人民共和国劳动法》', '第一百零三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十二章 法律责任', NULL, '劳动行政部门或者有关部门的工作人员滥用职权、玩忽职守、徇私舞弊，构成犯罪的，依法追究刑事责任；不构成犯罪的，给予行政处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363103, '《中华人民共和国劳动法》', '第一百零四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十二章 法律责任', NULL, '国家工作人员和社会保险基金经办机构的工作人员挪用社会保险基金，构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363104, '《中华人民共和国劳动法》', '第一百零五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十二章 法律责任', NULL, '违反本法规定侵害劳动者合法权益，其他法律、行政法规已规定处罚的，依照该法律、行政法规的规定处罚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363105, '《中华人民共和国劳动法》', '第一百零六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十三章 附 则', NULL, '省、自治区、直辖市人民政府根据本法和本地区的实际情况，规定劳动合同制度的实施步骤，报国务院备案。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1363106, '《中华人民共和国劳动法》', '第一百零七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十三章 附 则', NULL, '本法自1995年1月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372000, '《中华人民共和国就业促进法》', '第一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第一章 总 则', NULL, '为了促进就业，促进经济发展与扩大就业相协调，促进社会和谐稳定，制定本法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372001, '《中华人民共和国就业促进法》', '第二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第一章 总 则', NULL, '国家把扩大就业放在经济社会发展的突出位置，实施积极的就业政策，坚持劳动者自主择业、市场调节就业、政府促进就业的方针，多渠道扩大就业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372002, '《中华人民共和国就业促进法》', '第三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第一章 总 则', NULL, '劳动者依法享有平等就业和自主择业的权利。 劳动者就业，不因民族、种族、性别、宗教信仰等不同而受歧视。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372003, '《中华人民共和国就业促进法》', '第四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第一章 总 则', NULL, '县级以上人民政府把扩大就业作为经济和社会发展的重要目标，纳入国民经济和社会发展规划，并制定促进就业的中长期规划和年度工作计划。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372004, '《中华人民共和国就业促进法》', '第五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第一章 总 则', NULL, '县级以上人民政府通过发展经济和调整产业结构、规范人力资源市场、完善就业服务、加强职业教育和培训、提供就业援助等措施，创造就业条件，扩大就业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372005, '《中华人民共和国就业促进法》', '第六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第一章 总 则', NULL, '国务院建立全国促进就业工作协调机制，研究就业工作中的重大问题，协调推动全国的促进就业工作。国务院劳动行政部门具体负责全国的促进就业工作。 省、自治区、直辖市人民政府根据促进就业工作的需要，建立促进就业工作协调机制，协调解决本行政区域就业工作中的重大问题。 县级以上人民政府有关部门按照各自的职责分工，共同做好促进就业工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372006, '《中华人民共和国就业促进法》', '第七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第一章 总 则', NULL, '国家倡导劳动者树立正确的择业观念，提高就业能力和创业能力；鼓励劳动者自主创业、自谋职业。 各级人民政府和有关部门应当简化程序，提高效率，为劳动者自主创业、自谋职业提供便利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372007, '《中华人民共和国就业促进法》', '第八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第一章 总 则', NULL, '用人单位依法享有自主用人的权利。 用人单位应当依照本法以及其他法律、法规的规定，保障劳动者的合法权益。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372008, '《中华人民共和国就业促进法》', '第九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第一章 总 则', NULL, '工会、共产主义青年团、妇女联合会、残疾人联合会以及其他社会组织，协助人民政府开展促进就业工作，依法维护劳动者的劳动权利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372009, '《中华人民共和国就业促进法》', '第十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第一章 总 则', NULL, '各级人民政府和有关部门对在促进就业工作中作出显著成绩的单位和个人，给予表彰和奖励。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372010, '《中华人民共和国就业促进法》', '第十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第二章 政策支持', NULL, '县级以上人民政府应当把扩大就业作为重要职责，统筹协调产业政策与就业政策。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372011, '《中华人民共和国就业促进法》', '第十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第二章 政策支持', NULL, '国家鼓励各类企业在法律、法规规定的范围内，通过兴办产业或者拓展经营，增加就业岗位。 国家鼓励发展劳动密集型产业、服务业，扶持中小企业，多渠道、多方式增加就业岗位。 国家鼓励、支持、引导非公有制经济发展，扩大就业，增加就业岗位。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372012, '《中华人民共和国就业促进法》', '第十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第二章 政策支持', NULL, '国家发展国内外贸易和国际经济合作，拓宽就业渠道。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372013, '《中华人民共和国就业促进法》', '第十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第二章 政策支持', NULL, '县级以上人民政府在安排政府投资和确定重大建设项目时，应当发挥投资和重大建设项目带动就业的作用，增加就业岗位。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372014, '《中华人民共和国就业促进法》', '第十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第二章 政策支持', NULL, '国家实行有利于促进就业的财政政策，加大资金投入，改善就业环境，扩大就业。 县级以上人民政府应当根据就业状况和就业工作目标，在财政预算中安排就业专项资金用于促进就业工作。 就业专项资金用于职业介绍、职业培训、公益性岗位、职业技能鉴定、特定就业政策和社会保险等的补贴，小额贷款担保基金和微利项目的小额担保贷款贴息，以及扶持公共就业服务等。就业专项资金的使用管理办法由国务院财政部门和劳动行政部门规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372015, '《中华人民共和国就业促进法》', '第十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第二章 政策支持', NULL, '国家建立健全失业保险制度，依法确保失业人员的基本生活，并促进其实现就业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372016, '《中华人民共和国就业促进法》', '第十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第二章 政策支持', NULL, '国家鼓励企业增加就业岗位，扶持失业人员和残疾人就业，对下列企业、人员依法给予税收优惠： （一）吸纳符合国家规定条件的失业人员达到规定要求的企业； （二）失业人员创办的中小企业； （三）安置残疾人员达到规定比例或者集中使用残疾人的企业； （四）从事个体经营的符合国家规定条件的失业人员； （五）从事个体经营的残疾人； （六）国务院规定给予税收优惠的其他企业、人员。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372017, '《中华人民共和国就业促进法》', '第十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第二章 政策支持', NULL, '对本法第十七条第四项、第五项规定的人员，有关部门应当在经营场地等方面给予照顾，免除行政事业性收费。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372018, '《中华人民共和国就业促进法》', '第十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第二章 政策支持', NULL, '国家实行有利于促进就业的金融政策，增加中小企业的融资渠道；鼓励金融机构改进金融服务，加大对中小企业的信贷支持，并对自主创业人员在一定期限内给予小额信贷等扶持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372019, '《中华人民共和国就业促进法》', '第二十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第二章 政策支持', NULL, '国家实行城乡统筹的就业政策，建立健全城乡劳动者平等就业的制度，引导农业富余劳动力有序转移就业。 县级以上地方人民政府推进小城镇建设和加快县域经济发展，引导农业富余劳动力就地就近转移就业；在制定小城镇规划时，将本地区农业富余劳动力转移就业作为重要内容。 县级以上地方人民政府引导农业富余劳动力有序向城市异地转移就业；劳动力输出地和输入地人民政府应当互相配合，改善农村劳动者进城就业的环境和条件。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372020, '《中华人民共和国就业促进法》', '第二十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第二章 政策支持', NULL, '国家支持区域经济发展，鼓励区域协作，统筹协调不同地区就业的均衡增长。 国家支持民族地区发展经济，扩大就业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372021, '《中华人民共和国就业促进法》', '第二十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第二章 政策支持', NULL, '各级人民政府统筹做好城镇新增劳动力就业、农业富余劳动力转移就业和失业人员就业工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372022, '《中华人民共和国就业促进法》', '第二十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第二章 政策支持', NULL, '各级人民政府采取措施，逐步完善和实施与非全日制用工等灵活就业相适应的劳动和社会保险政策，为灵活就业人员提供帮助和服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372023, '《中华人民共和国就业促进法》', '第二十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第二章 政策支持', NULL, '地方各级人民政府和有关部门应当加强对失业人员从事个体经营的指导，提供政策咨询、就业培训和开业指导等服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372024, '《中华人民共和国就业促进法》', '第二十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第三章 公平就业', NULL, '各级人民政府创造公平就业的环境，消除就业歧视，制定政策并采取措施对就业困难人员给予扶持和援助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372025, '《中华人民共和国就业促进法》', '第二十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第三章 公平就业', NULL, '用人单位招用人员、职业中介机构从事职业中介活动，应当向劳动者提供平等的就业机会和公平的就业条件，不得实施就业歧视。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372026, '《中华人民共和国就业促进法》', '第二十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第三章 公平就业', NULL, '国家保障妇女享有与男子平等的劳动权利。 用人单位招用人员，除国家规定的不适合妇女的工种或者岗位外，不得以性别为由拒绝录用妇女或者提高对妇女的录用标准。 用人单位录用女职工，不得在劳动合同中规定限制女职工结婚、生育的内容。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372027, '《中华人民共和国就业促进法》', '第二十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第三章 公平就业', NULL, '各民族劳动者享有平等的劳动权利。 用人单位招用人员，应当依法对少数民族劳动者给予适当照顾。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372028, '《中华人民共和国就业促进法》', '第二十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第三章 公平就业', NULL, '国家保障残疾人的劳动权利。 各级人民政府应当对残疾人就业统筹规划，为残疾人创造就业条件。 用人单位招用人员，不得歧视残疾人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372029, '《中华人民共和国就业促进法》', '第三十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第三章 公平就业', NULL, '用人单位招用人员，不得以是传染病病原携带者为由拒绝录用。但是，经医学鉴定传染病病原携带者在治愈前或者排除传染嫌疑前，不得从事法律、行政法规和国务院卫生行政部门规定禁止从事的易使传染病扩散的工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372030, '《中华人民共和国就业促进法》', '第三十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第三章 公平就业', NULL, '农村劳动者进城就业享有与城镇劳动者平等的劳动权利，不得对农村劳动者进城就业设置歧视性限制。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372031, '《中华人民共和国就业促进法》', '第三十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第四章 就业服务和管理', NULL, '县级以上人民政府培育和完善统一开放、竞争有序的人力资源市场，为劳动者就业提供服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372032, '《中华人民共和国就业促进法》', '第三十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第四章 就业服务和管理', NULL, '县级以上人民政府鼓励社会各方面依法开展就业服务活动，加强对公共就业服务和职业中介服务的指导和监督，逐步完善覆盖城乡的就业服务体系。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372033, '《中华人民共和国就业促进法》', '第三十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第四章 就业服务和管理', NULL, '县级以上人民政府加强人力资源市场信息网络及相关设施建设，建立健全人力资源市场信息服务体系，完善市场信息发布制度。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372034, '《中华人民共和国就业促进法》', '第三十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第四章 就业服务和管理', NULL, '县级以上人民政府建立健全公共就业服务体系，设立公共就业服务机构，为劳动者免费提供下列服务： （一）就业政策法规咨询； （二）职业供求信息、市场工资指导价位信息和职业培训信息发布； （三）职业指导和职业介绍； （四）对就业困难人员实施就业援助； （五）办理就业登记、失业登记等事务； （六）其他公共就业服务。 公共就业服务机构应当不断提高服务的质量和效率，不得从事经营性活动。 公共就业服务经费纳入同级财政预算。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372035, '《中华人民共和国就业促进法》', '第三十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第四章 就业服务和管理', NULL, '县级以上地方人民政府对职业中介机构提供公益性就业服务的，按照规定给予补贴。 国家鼓励社会各界为公益性就业服务提供捐赠、资助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372036, '《中华人民共和国就业促进法》', '第三十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第四章 就业服务和管理', NULL, '地方各级人民政府和有关部门不得举办或者与他人联合举办经营性的职业中介机构。 地方各级人民政府和有关部门、公共就业服务机构举办的招聘会，不得向劳动者收取费用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372037, '《中华人民共和国就业促进法》', '第三十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第四章 就业服务和管理', NULL, '县级以上人民政府和有关部门加强对职业中介机构的管理，鼓励其提高服务质量，发挥其在促进就业中的作用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372038, '《中华人民共和国就业促进法》', '第三十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第四章 就业服务和管理', NULL, '从事职业中介活动，应当遵循合法、诚实信用、公平、公开的原则。 用人单位通过职业中介机构招用人员，应当如实向职业中介机构提供岗位需求信息。 禁止任何组织或者个人利用职业中介活动侵害劳动者的合法权益。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372039, '《中华人民共和国就业促进法》', '第四十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第四章 就业服务和管理', NULL, '设立职业中介机构应当具备下列条件： （一）有明确的章程和管理制度； （二）有开展业务必备的固定场所、办公设施和一定数额的开办资金； （三）有一定数量具备相应职业资格的专职工作人员； （四）法律、法规规定的其他条件。 设立职业中介机构应当在工商行政管理部门办理登记后，向劳动行政部门申请行政许可。 未经依法许可和登记的机构，不得从事职业中介活动。 国家对外商投资职业中介机构和向劳动者提供境外就业服务的职业中介机构另有规定的，依照其规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372040, '《中华人民共和国就业促进法》', '第四十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第四章 就业服务和管理', NULL, '职业中介机构不得有下列行为： （一）提供虚假就业信息； （二）为无合法证照的用人单位提供职业中介服务； （三）伪造、涂改、转让职业中介许可证； （四）扣押劳动者的居民身份证和其他证件，或者向劳动者收取押金； （五）其他违反法律、法规规定的行为。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372041, '《中华人民共和国就业促进法》', '第四十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第四章 就业服务和管理', NULL, '县级以上人民政府建立失业预警制度，对可能出现的较大规模的失业，实施预防、调节和控制。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372042, '《中华人民共和国就业促进法》', '第四十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第四章 就业服务和管理', NULL, '国家建立劳动力调查统计制度和就业登记、失业登记制度，开展劳动力资源和就业、失业状况调查统计，并公布调查统计结果。 统计部门和劳动行政部门进行劳动力调查统计和就业、失业登记时，用人单位和个人应当如实提供调查统计和登记所需要的情况。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372043, '《中华人民共和国就业促进法》', '第四十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第五章 职业教育和培训', NULL, '国家依法发展职业教育，鼓励开展职业培训，促进劳动者提高职业技能，增强就业能力和创业能力。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372044, '《中华人民共和国就业促进法》', '第四十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第五章 职业教育和培训', NULL, '县级以上人民政府根据经济社会发展和市场需求，制定并实施职业能力开发计划。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372045, '《中华人民共和国就业促进法》', '第四十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第五章 职业教育和培训', NULL, '县级以上人民政府加强统筹协调，鼓励和支持各类职业院校、职业技能培训机构和用人单位依法开展就业前培训、在职培训、再就业培训和创业培训；鼓励劳动者参加各种形式的培训。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372046, '《中华人民共和国就业促进法》', '第四十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第五章 职业教育和培训', NULL, '县级以上地方人民政府和有关部门根据市场需求和产业发展方向，鼓励、指导企业加强职业教育和培训。 职业院校、职业技能培训机构与企业应当密切联系，实行产教结合，为经济建设服务，培养实用人才和熟练劳动者。 企业应当按照国家有关规定提取职工教育经费，对劳动者进行职业技能培训和继续教育培训。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372047, '《中华人民共和国就业促进法》', '第四十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第五章 职业教育和培训', NULL, '国家采取措施建立健全劳动预备制度，县级以上地方人民政府对有就业要求的初高中毕业生实行一定期限的职业教育和培训，使其取得相应的职业资格或者掌握一定的职业技能。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372048, '《中华人民共和国就业促进法》', '第四十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第五章 职业教育和培训', NULL, '地方各级人民政府鼓励和支持开展就业培训，帮助失业人员提高职业技能，增强其就业能力和创业能力。失业人员参加就业培训的，按照有关规定享受政府培训补贴。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372049, '《中华人民共和国就业促进法》', '第五十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第五章 职业教育和培训', NULL, '地方各级人民政府采取有效措施，组织和引导进城就业的农村劳动者参加技能培训，鼓励各类培训机构为进城就业的农村劳动者提供技能培训，增强其就业能力和创业能力。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372050, '《中华人民共和国就业促进法》', '第五十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第五章 职业教育和培训', NULL, '国家对从事涉及公共安全、人身健康、生命财产安全等特殊工种的劳动者，实行职业资格证书制度，具体办法由国务院规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372051, '《中华人民共和国就业促进法》', '第五十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第六章 就业援助', NULL, '各级人民政府建立健全就业援助制度，采取税费减免、贷款贴息、社会保险补贴、岗位补贴等办法，通过公益性岗位安置等途径，对就业困难人员实行优先扶持和重点帮助。 就业困难人员是指因身体状况、技能水平、家庭因素、失去土地等原因难以实现就业，以及连续失业一定时间仍未能实现就业的人员。就业困难人员的具体范围，由省、自治区、直辖市人民政府根据本行政区域的实际情况规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372052, '《中华人民共和国就业促进法》', '第五十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第六章 就业援助', NULL, '政府投资开发的公益性岗位，应当优先安排符合岗位要求的就业困难人员。被安排在公益性岗位工作的，按照国家规定给予岗位补贴。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372053, '《中华人民共和国就业促进法》', '第五十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第六章 就业援助', NULL, '地方各级人民政府加强基层就业援助服务工作，对就业困难人员实施重点帮助，提供有针对性的就业服务和公益性岗位援助。 地方各级人民政府鼓励和支持社会各方面为就业困难人员提供技能培训、岗位信息等服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372054, '《中华人民共和国就业促进法》', '第五十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第六章 就业援助', NULL, '各级人民政府采取特别扶助措施，促进残疾人就业。 用人单位应当按照国家规定安排残疾人就业，具体办法由国务院规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372055, '《中华人民共和国就业促进法》', '第五十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第六章 就业援助', NULL, '县级以上地方人民政府采取多种就业形式，拓宽公益性岗位范围，开发就业岗位，确保城市有就业需求的家庭至少有一人实现就业。 法定劳动年龄内的家庭人员均处于失业状况的城市居民家庭，可以向住所地街道、社区公共就业服务机构申请就业援助。街道、社区公共就业服务机构经确认属实的，应当为该家庭中至少一人提供适当的就业岗位。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372056, '《中华人民共和国就业促进法》', '第五十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第六章 就业援助', NULL, '国家鼓励资源开采型城市和独立工矿区发展与市场需求相适应的产业，引导劳动者转移就业。 对因资源枯竭或者经济结构调整等原因造成就业困难人员集中的地区，上级人民政府应当给予必要的扶持和帮助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372057, '《中华人民共和国就业促进法》', '第五十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第七章 监督检查', NULL, '各级人民政府和有关部门应当建立促进就业的目标责任制度。县级以上人民政府按照促进就业目标责任制的要求，对所属的有关部门和下一级人民政府进行考核和监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372058, '《中华人民共和国就业促进法》', '第五十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第七章 监督检查', NULL, '审计机关、财政部门应当依法对就业专项资金的管理和使用情况进行监督检查。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372059, '《中华人民共和国就业促进法》', '第六十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第七章 监督检查', NULL, '劳动行政部门应当对本法实施情况进行监督检查，建立举报制度，受理对违反本法行为的举报，并及时予以核实、处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372060, '《中华人民共和国就业促进法》', '第六十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第八章 法律责任', NULL, '违反本法规定，劳动行政等有关部门及其工作人员滥用职权、玩忽职守、徇私舞弊的，对直接负责的主管人员和其他直接责任人员依法给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372061, '《中华人民共和国就业促进法》', '第六十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第八章 法律责任', NULL, '违反本法规定，实施就业歧视的，劳动者可以向人民法院提起诉讼。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372062, '《中华人民共和国就业促进法》', '第六十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第八章 法律责任', NULL, '违反本法规定，地方各级人民政府和有关部门、公共就业服务机构举办经营性的职业中介机构，从事经营性职业中介活动，向劳动者收取费用的，由上级主管机关责令限期改正，将违法收取的费用退还劳动者，并对直接负责的主管人员和其他直接责任人员依法给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372063, '《中华人民共和国就业促进法》', '第六十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第八章 法律责任', NULL, '违反本法规定，未经许可和登记，擅自从事职业中介活动的，由劳动行政部门或者其他主管部门依法予以关闭；有违法所得的，没收违法所得，并处一万元以上五万元以下的罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372064, '《中华人民共和国就业促进法》', '第六十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第八章 法律责任', NULL, '违反本法规定，职业中介机构提供虚假就业信息，为无合法证照的用人单位提供职业中介服务，伪造、涂改、转让职业中介许可证的，由劳动行政部门或者其他主管部门责令改正；有违法所得的，没收违法所得，并处一万元以上五万元以下的罚款；情节严重的，吊销职业中介许可证。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372065, '《中华人民共和国就业促进法》', '第六十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第八章 法律责任', NULL, '违反本法规定，职业中介机构扣押劳动者居民身份证等证件的，由劳动行政部门责令限期退还劳动者，并依照有关法律规定给予处罚。 违反本法规定，职业中介机构向劳动者收取押金的，由劳动行政部门责令限期退还劳动者，并以每人五百元以上二千元以下的标准处以罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372066, '《中华人民共和国就业促进法》', '第六十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第八章 法律责任', NULL, '违反本法规定，企业未按照国家规定提取职工教育经费，或者挪用职工教育经费的，由劳动行政部门责令改正，并依法给予处罚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372067, '《中华人民共和国就业促进法》', '第六十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第八章 法律责任', NULL, '违反本法规定，侵害劳动者合法权益，造成财产损失或者其他损害的，依法承担民事责任；构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1372068, '《中华人民共和国就业促进法》', '第六十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第九章 附 则', NULL, '本法自2008年1月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375000, '《中华人民共和国劳动合同法》', '第一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第一章 总 则', NULL, '为了完善劳动合同制度，明确劳动合同双方当事人的权利和义务，保护劳动者的合法权益，构建和发展和谐稳定的劳动关系，制定本法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375001, '《中华人民共和国劳动合同法》', '第二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第一章 总 则', NULL, '中华人民共和国境内的企业、个体经济组织、民办非企业单位等组织（以下称用人单位）与劳动者建立劳动关系，订立、履行、变更、解除或者终止劳动合同，适用本法。 国家机关、事业单位、社会团体和与其建立劳动关系的劳动者，订立、履行、变更、解除或者终止劳动合同，依照本法执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375002, '《中华人民共和国劳动合同法》', '第三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第一章 总 则', NULL, '订立劳动合同，应当遵循合法、公平、平等自愿、协商一致、诚实信用的原则。 依法订立的劳动合同具有约束力，用人单位与劳动者应当履行劳动合同约定的义务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375003, '《中华人民共和国劳动合同法》', '第四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第一章 总 则', NULL, '用人单位应当依法建立和完善劳动规章制度，保障劳动者享有劳动权利、履行劳动义务。 用人单位在制定、修改或者决定有关劳动报酬、工作时间、休息休假、劳动安全卫生、保险福利、职工培训、劳动纪律以及劳动定额管理等直接涉及劳动者切身利益的规章制度或者重大事项时，应当经职工代表大会或者全体职工讨论，提出方案和意见，与工会或者职工代表平等协商确定。 在规章制度和重大事项决定实施过程中，工会或者职工认为不适当的，有权向用人单位提出，通过协商予以修改完善。 用人单位应当将直接涉及劳动者切身利益的规章制度和重大事项决定公示，或者告知劳动者。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375004, '《中华人民共和国劳动合同法》', '第五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第一章 总 则', NULL, '县级以上人民政府劳动行政部门会同工会和企业方面代表，建立健全协调劳动关系三方机制，共同研究解决有关劳动关系的重大问题。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375005, '《中华人民共和国劳动合同法》', '第六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第一章 总 则', NULL, '工会应当帮助、指导劳动者与用人单位依法订立和履行劳动合同，并与用人单位建立集体协商机制，维护劳动者的合法权益。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375006, '《中华人民共和国劳动合同法》', '第七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第二章 劳动合同的订立', NULL, '用人单位自用工之日起即与劳动者建立劳动关系。用人单位应当建立职工名册备查。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375007, '《中华人民共和国劳动合同法》', '第八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第二章 劳动合同的订立', NULL, '用人单位招用劳动者时，应当如实告知劳动者工作内容、工作条件、工作地点、职业危害、安全生产状况、劳动报酬，以及劳动者要求了解的其他情况；用人单位有权了解劳动者与劳动合同直接相关的基本情况，劳动者应当如实说明。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375008, '《中华人民共和国劳动合同法》', '第九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第二章 劳动合同的订立', NULL, '用人单位招用劳动者，不得扣押劳动者的居民身份证和其他证件，不得要求劳动者提供担保或者以其他名义向劳动者收取财物。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375009, '《中华人民共和国劳动合同法》', '第十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第二章 劳动合同的订立', NULL, '建立劳动关系，应当订立书面劳动合同。 已建立劳动关系，未同时订立书面劳动合同的，应当自用工之日起一个月内订立书面劳动合同。 用人单位与劳动者在用工前订立劳动合同的，劳动关系自用工之日起建立。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375010, '《中华人民共和国劳动合同法》', '第十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第二章 劳动合同的订立', NULL, '用人单位未在用工的同时订立书面劳动合同，与劳动者约定的劳动报酬不明确的，新招用的劳动者的劳动报酬按照集体合同规定的标准执行；没有集体合同或者集体合同未规定的，实行同工同酬。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375011, '《中华人民共和国劳动合同法》', '第十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第二章 劳动合同的订立', NULL, '劳动合同分为固定期限劳动合同、无固定期限劳动合同和以完成一定工作任务为期限的劳动合同。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375012, '《中华人民共和国劳动合同法》', '第十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第二章 劳动合同的订立', NULL, '固定期限劳动合同，是指用人单位与劳动者约定合同终止时间的劳动合同。 用人单位与劳动者协商一致，可以订立固定期限劳动合同。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375013, '《中华人民共和国劳动合同法》', '第十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第二章 劳动合同的订立', NULL, '无固定期限劳动合同，是指用人单位与劳动者约定无确定终止时间的劳动合同。 用人单位与劳动者协商一致，可以订立无固定期限劳动合同。有下列情形之一，劳动者提出或者同意续订、订立劳动合同的，除劳动者提出订立固定期限劳动合同外，应当订立无固定期限劳动合同： （一）劳动者在该用人单位连续工作满十年的； （二）用人单位初次实行劳动合同制度或者国有企业改制重新订立劳动合同时，劳动者在该用人单位连续工作满十年且距法定退休年龄不足十年的； （三）连续订立二次固定期限劳动合同，且劳动者没有本法第三十九条和第四十条第一项、第二项规定的情形，续订劳动合同的。 用人单位自用工之日起满一年不与劳动者订立书面劳动合同的，视为用人单位与劳动者已订立无固定期限劳动合同。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375014, '《中华人民共和国劳动合同法》', '第十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第二章 劳动合同的订立', NULL, '以完成一定工作任务为期限的劳动合同，是指用人单位与劳动者约定以某项工作的完成为合同期限的劳动合同。 用人单位与劳动者协商一致，可以订立以完成一定工作任务为期限的劳动合同。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375015, '《中华人民共和国劳动合同法》', '第十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第二章 劳动合同的订立', NULL, '劳动合同由用人单位与劳动者协商一致，并经用人单位与劳动者在劳动合同文本上签字或者盖章生效。 劳动合同文本由用人单位和劳动者各执一份。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375016, '《中华人民共和国劳动合同法》', '第十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第二章 劳动合同的订立', NULL, '劳动合同应当具备以下条款： （一）用人单位的名称、住所和法定代表人或者主要负责人； （二）劳动者的姓名、住址和居民身份证或者其他有效身份证件号码； （三）劳动合同期限； （四）工作内容和工作地点； （五）工作时间和休息休假； （六）劳动报酬； （七）社会保险； （八）劳动保护、劳动条件和职业危害防护； （九）法律、法规规定应当纳入劳动合同的其他事项。 劳动合同除前款规定的必备条款外，用人单位与劳动者可以约定试用期、培训、保守秘密、补充保险和福利待遇等其他事项。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375017, '《中华人民共和国劳动合同法》', '第十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第二章 劳动合同的订立', NULL, '劳动合同对劳动报酬和劳动条件等标准约定不明确，引发争议的，用人单位与劳动者可以重新协商；协商不成的，适用集体合同规定；没有集体合同或者集体合同未规定劳动报酬的，实行同工同酬；没有集体合同或者集体合同未规定劳动条件等标准的，适用国家有关规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375018, '《中华人民共和国劳动合同法》', '第十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第二章 劳动合同的订立', NULL, '劳动合同期限三个月以上不满一年的，试用期不得超过一个月；劳动合同期限一年以上不满三年的，试用期不得超过二个月；三年以上固定期限和无固定期限的劳动合同，试用期不得超过六个月。 同一用人单位与同一劳动者只能约定一次试用期。 以完成一定工作任务为期限的劳动合同或者劳动合同期限不满三个月的，不得约定试用期。 试用期包含在劳动合同期限内。劳动合同仅约定试用期的，试用期不成立，该期限为劳动合同期限。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375019, '《中华人民共和国劳动合同法》', '第二十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第二章 劳动合同的订立', NULL, '劳动者在试用期的工资不得低于本单位相同岗位最低档工资或者劳动合同约定工资的百分之八十，并不得低于用人单位所在地的最低工资标准。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375020, '《中华人民共和国劳动合同法》', '第二十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第二章 劳动合同的订立', NULL, '在试用期中，除劳动者有本法第三十九条和第四十条第一项、第二项规定的情形外，用人单位不得解除劳动合同。用人单位在试用期解除劳动合同的，应当向劳动者说明理由。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375021, '《中华人民共和国劳动合同法》', '第二十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第二章 劳动合同的订立', NULL, '用人单位为劳动者提供专项培训费用，对其进行专业技术培训的，可以与该劳动者订立协议，约定服务期。 劳动者违反服务期约定的，应当按照约定向用人单位支付违约金。违约金的数额不得超过用人单位提供的培训费用。用人单位要求劳动者支付的违约金不得超过服务期尚未履行部分所应分摊的培训费用。 用人单位与劳动者约定服务期的，不影响按照正常的工资调整机制提高劳动者在服务期期间的劳动报酬。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375022, '《中华人民共和国劳动合同法》', '第二十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第二章 劳动合同的订立', NULL, '用人单位与劳动者可以在劳动合同中约定保守用人单位的商业秘密和与知识产权相关的保密事项。 对负有保密义务的劳动者，用人单位可以在劳动合同或者保密协议中与劳动者约定竞业限制条款，并约定在解除或者终止劳动合同后，在竞业限制期限内按月给予劳动者经济补偿。劳动者违反竞业限制约定的，应当按照约定向用人单位支付违约金。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375023, '《中华人民共和国劳动合同法》', '第二十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第二章 劳动合同的订立', NULL, '竞业限制的人员限于用人单位的高级管理人员、高级技术人员和其他负有保密义务的人员。竞业限制的范围、地域、期限由用人单位与劳动者约定，竞业限制的约定不得违反法律、法规的规定。 在解除或者终止劳动合同后，前款规定的人员到与本单位生产或者经营同类产品、从事同类业务的有竞争关系的其他用人单位，或者自己开业生产或者经营同类产品、从事同类业务的竞业限制期限，不得超过二年。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375024, '《中华人民共和国劳动合同法》', '第二十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第二章 劳动合同的订立', NULL, '除本法第二十二条和第二十三条规定的情形外，用人单位不得与劳动者约定由劳动者承担违约金。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375025, '《中华人民共和国劳动合同法》', '第二十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第二章 劳动合同的订立', NULL, '下列劳动合同无效或者部分无效： （一）以欺诈、胁迫的手段或者乘人之危，使对方在违背真实意思的情况下订立或者变更劳动合同的； （二）用人单位免除自己的法定责任、排除劳动者权利的； （三）违反法律、行政法规强制性规定的。 对劳动合同的无效或者部分无效有争议的，由劳动争议仲裁机构或者人民法院确认。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375026, '《中华人民共和国劳动合同法》', '第二十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第二章 劳动合同的订立', NULL, '劳动合同部分无效，不影响其他部分效力的，其他部分仍然有效。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375027, '《中华人民共和国劳动合同法》', '第二十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第二章 劳动合同的订立', NULL, '劳动合同被确认无效，劳动者已付出劳动的，用人单位应当向劳动者支付劳动报酬。劳动报酬的数额，参照本单位相同或者相近岗位劳动者的劳动报酬确定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375028, '《中华人民共和国劳动合同法》', '第二十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第三章 劳动合同的履行和变更', NULL, '用人单位与劳动者应当按照劳动合同的约定，全面履行各自的义务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375029, '《中华人民共和国劳动合同法》', '第三十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第三章 劳动合同的履行和变更', NULL, '用人单位应当按照劳动合同约定和国家规定，向劳动者及时足额支付劳动报酬。 用人单位拖欠或者未足额支付劳动报酬的，劳动者可以依法向当地人民法院申请支付令，人民法院应当依法发出支付令。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375030, '《中华人民共和国劳动合同法》', '第三十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第三章 劳动合同的履行和变更', NULL, '用人单位应当严格执行劳动定额标准，不得强迫或者变相强迫劳动者加班。用人单位安排加班的，应当按照国家有关规定向劳动者支付加班费。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375031, '《中华人民共和国劳动合同法》', '第三十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第三章 劳动合同的履行和变更', NULL, '劳动者拒绝用人单位管理人员违章指挥、强令冒险作业的，不视为违反劳动合同。 劳动者对危害生命安全和身体健康的劳动条件，有权对用人单位提出批评、检举和控告。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375032, '《中华人民共和国劳动合同法》', '第三十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第三章 劳动合同的履行和变更', NULL, '用人单位变更名称、法定代表人、主要负责人或者投资人等事项，不影响劳动合同的履行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375033, '《中华人民共和国劳动合同法》', '第三十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第三章 劳动合同的履行和变更', NULL, '用人单位发生合并或者分立等情况，原劳动合同继续有效，劳动合同由承继其权利和义务的用人单位继续履行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375034, '《中华人民共和国劳动合同法》', '第三十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第三章 劳动合同的履行和变更', NULL, '用人单位与劳动者协商一致，可以变更劳动合同约定的内容。变更劳动合同，应当采用书面形式。 变更后的劳动合同文本由用人单位和劳动者各执一份。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375035, '《中华人民共和国劳动合同法》', '第三十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第四章 劳动合同的解除和终止', NULL, '用人单位与劳动者协商一致，可以解除劳动合同。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375036, '《中华人民共和国劳动合同法》', '第三十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第四章 劳动合同的解除和终止', NULL, '劳动者提前三十日以书面形式通知用人单位，可以解除劳动合同。劳动者在试用期内提前三日通知用人单位，可以解除劳动合同。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375037, '《中华人民共和国劳动合同法》', '第三十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第四章 劳动合同的解除和终止', NULL, '用人单位有下列情形之一的，劳动者可以解除劳动合同： （一）未按照劳动合同约定提供劳动保护或者劳动条件的； （二）未及时足额支付劳动报酬的； （三）未依法为劳动者缴纳社会保险费的； （四）用人单位的规章制度违反法律、法规的规定，损害劳动者权益的； （五）因本法第二十六条第一款规定的情形致使劳动合同无效的； （六）法律、行政法规规定劳动者可以解除劳动合同的其他情形。 用人单位以暴力、威胁或者非法限制人身自由的手段强迫劳动者劳动的，或者用人单位违章指挥、强令冒险作业危及劳动者人身安全的，劳动者可以立即解除劳动合同，不需事先告知用人单位。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375038, '《中华人民共和国劳动合同法》', '第三十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第四章 劳动合同的解除和终止', NULL, '劳动者有下列情形之一的，用人单位可以解除劳动合同： （一）在试用期间被证明不符合录用条件的； （二）严重违反用人单位的规章制度的； （三）严重失职，营私舞弊，给用人单位造成重大损害的； （四）劳动者同时与其他用人单位建立劳动关系，对完成本单位的工作任务造成严重影响，或者经用人单位提出，拒不改正的； （五）因本法第二十六条第一款第一项规定的情形致使劳动合同无效的； （六）被依法追究刑事责任的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375039, '《中华人民共和国劳动合同法》', '第四十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第四章 劳动合同的解除和终止', NULL, '有下列情形之一的，用人单位提前三十日以书面形式通知劳动者本人或者额外支付劳动者一个月工资后，可以解除劳动合同： （一）劳动者患病或者非因工负伤，在规定的医疗期满后不能从事原工作，也不能从事由用人单位另行安排的工作的； （二）劳动者不能胜任工作，经过培训或者调整工作岗位，仍不能胜任工作的； （三）劳动合同订立时所依据的客观情况发生重大变化，致使劳动合同无法履行，经用人单位与劳动者协商，未能就变更劳动合同内容达成协议的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375040, '《中华人民共和国劳动合同法》', '第四十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第四章 劳动合同的解除和终止', NULL, '有下列情形之一，需要裁减人员二十人以上或者裁减不足二十人但占企业职工总数百分之十以上的，用人单位提前三十日向工会或者全体职工说明情况，听取工会或者职工的意见后，裁减人员方案经向劳动行政部门报告，可以裁减人员： （一）依照企业破产法规定进行重整的； （二）生产经营发生严重困难的； （三）企业转产、重大技术革新或者经营方式调整，经变更劳动合同后，仍需裁减人员的； （四）其他因劳动合同订立时所依据的客观经济情况发生重大变化，致使劳动合同无法履行的。 裁减人员时，应当优先留用下列人员： （一）与本单位订立较长期限的固定期限劳动合同的； （二）与本单位订立无固定期限劳动合同的； （三）家庭无其他就业人员，有需要扶养的老人或者未成年人的。 用人单位依照本条第一款规定裁减人员，在六个月内重新招用人员的，应当通知被裁减的人员，并在同等条件下优先招用被裁减的人员。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375041, '《中华人民共和国劳动合同法》', '第四十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第四章 劳动合同的解除和终止', NULL, '劳动者有下列情形之一的，用人单位不得依照本法第四十条、第四十一条的规定解除劳动合同： （一）从事接触职业病危害作业的劳动者未进行离岗前职业健康检查，或者疑似职业病病人在诊断或者医学观察期间的； （二）在本单位患职业病或者因工负伤并被确认丧失或者部分丧失劳动能力的； （三）患病或者非因工负伤，在规定的医疗期内的； （四）女职工在孕期、产期、哺乳期的； （五）在本单位连续工作满十五年，且距法定退休年龄不足五年的； （六）法律、行政法规规定的其他情形。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375042, '《中华人民共和国劳动合同法》', '第四十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第四章 劳动合同的解除和终止', NULL, '用人单位单方解除劳动合同，应当事先将理由通知工会。用人单位违反法律、行政法规规定或者劳动合同约定的，工会有权要求用人单位纠正。用人单位应当研究工会的意见，并将处理结果书面通知工会。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375043, '《中华人民共和国劳动合同法》', '第四十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第四章 劳动合同的解除和终止', NULL, '有下列情形之一的，劳动合同终止： （一）劳动合同期满的； （二）劳动者开始依法享受基本养老保险待遇的； （三）劳动者死亡，或者被人民法院宣告死亡或者宣告失踪的； （四）用人单位被依法宣告破产的； （五）用人单位被吊销营业执照、责令关闭、撤销或者用人单位决定提前解散的； （六）法律、行政法规规定的其他情形。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375044, '《中华人民共和国劳动合同法》', '第四十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第四章 劳动合同的解除和终止', NULL, '劳动合同期满，有本法第四十二条规定情形之一的，劳动合同应当续延至相应的情形消失时终止。但是，本法第四十二条第二项规定丧失或者部分丧失劳动能力劳动者的劳动合同的终止，按照国家有关工伤保险的规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375045, '《中华人民共和国劳动合同法》', '第四十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第四章 劳动合同的解除和终止', NULL, '有下列情形之一的，用人单位应当向劳动者支付经济补偿： （一）劳动者依照本法第三十八条规定解除劳动合同的； （二）用人单位依照本法第三十六条规定向劳动者提出解除劳动合同并与劳动者协商一致解除劳动合同的； （三）用人单位依照本法第四十条规定解除劳动合同的； （四）用人单位依照本法第四十一条第一款规定解除劳动合同的； （五）除用人单位维持或者提高劳动合同约定条件续订劳动合同，劳动者不同意续订的情形外，依照本法第四十四条第一项规定终止固定期限劳动合同的； （六）依照本法第四十四条第四项、第五项规定终止劳动合同的； （七）法律、行政法规规定的其他情形。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375046, '《中华人民共和国劳动合同法》', '第四十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第四章 劳动合同的解除和终止', NULL, '经济补偿按劳动者在本单位工作的年限，每满一年支付一个月工资的标准向劳动者支付。六个月以上不满一年的，按一年计算；不满六个月的，向劳动者支付半个月工资的经济补偿。 劳动者月工资高于用人单位所在直辖市、设区的市级人民政府公布的本地区上年度职工月平均工资三倍的，向其支付经济补偿的标准按职工月平均工资三倍的数额支付，向其支付经济补偿的年限最高不超过十二年。 本条所称月工资是指劳动者在劳动合同解除或者终止前十二个月的平均工资。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375047, '《中华人民共和国劳动合同法》', '第四十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第四章 劳动合同的解除和终止', NULL, '用人单位违反本法规定解除或者终止劳动合同，劳动者要求继续履行劳动合同的，用人单位应当继续履行；劳动者不要求继续履行劳动合同或者劳动合同已经不能继续履行的，用人单位应当依照本法第八十七条规定支付赔偿金。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375048, '《中华人民共和国劳动合同法》', '第四十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第四章 劳动合同的解除和终止', NULL, '国家采取措施，建立健全劳动者社会保险关系跨地区转移接续制度。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375049, '《中华人民共和国劳动合同法》', '第五十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第四章 劳动合同的解除和终止', NULL, '用人单位应当在解除或者终止劳动合同时出具解除或者终止劳动合同的证明，并在十五日内为劳动者办理档案和社会保险关系转移手续。 劳动者应当按照双方约定，办理工作交接。用人单位依照本法有关规定应当向劳动者支付经济补偿的，在办结工作交接时支付。 用人单位对已经解除或者终止的劳动合同的文本，至少保存二年备查。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375050, '《中华人民共和国劳动合同法》', '第五十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第五章 特别规定', '第一节 集体合同', '企业职工一方与用人单位通过平等协商，可以就劳动报酬、工作时间、休息休假、劳动安全卫生、保险福利等事项订立集体合同。集体合同草案应当提交职工代表大会或者全体职工讨论通过。 集体合同由工会代表企业职工一方与用人单位订立；尚未建立工会的用人单位，由上级工会指导劳动者推举的代表与用人单位订立。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375051, '《中华人民共和国劳动合同法》', '第五十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第五章 特别规定', '第一节 集体合同', '企业职工一方与用人单位可以订立劳动安全卫生、女职工权益保护、工资调整机制等专项集体合同。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375052, '《中华人民共和国劳动合同法》', '第五十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第五章 特别规定', '第一节 集体合同', '在县级以下区域内，建筑业、采矿业、餐饮服务业等行业可以由工会与企业方面代表订立行业性集体合同，或者订立区域性集体合同。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375053, '《中华人民共和国劳动合同法》', '第五十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第五章 特别规定', '第一节 集体合同', '集体合同订立后，应当报送劳动行政部门；劳动行政部门自收到集体合同文本之日起十五日内未提出异议的，集体合同即行生效。 依法订立的集体合同对用人单位和劳动者具有约束力。行业性、区域性集体合同对当地本行业、本区域的用人单位和劳动者具有约束力。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375054, '《中华人民共和国劳动合同法》', '第五十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第五章 特别规定', '第一节 集体合同', '集体合同中劳动报酬和劳动条件等标准不得低于当地人民政府规定的最低标准；用人单位与劳动者订立的劳动合同中劳动报酬和劳动条件等标准不得低于集体合同规定的标准。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375055, '《中华人民共和国劳动合同法》', '第五十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第五章 特别规定', '第一节 集体合同', '用人单位违反集体合同，侵犯职工劳动权益的，工会可以依法要求用人单位承担责任；因履行集体合同发生争议，经协商解决不成的，工会可以依法申请仲裁、提起诉讼。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375056, '《中华人民共和国劳动合同法》', '第五十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第五章 特别规定', '第二节 劳务派遣', '经营劳务派遣业务应当具备下列条件： （一）注册资本不得少于人民币二百万元； （二）有与开展业务相适应的固定的经营场所和设施； （三）有符合法律、行政法规规定的劳务派遣管理制度； （四）法律、行政法规规定的其他条件。 经营劳务派遣业务，应当向劳动行政部门依法申请行政许可；经许可的，依法办理相应的公司登记。未经许可，任何单位和个人不得经营劳务派遣业务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375057, '《中华人民共和国劳动合同法》', '第五十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第五章 特别规定', '第二节 劳务派遣', '劳务派遣单位是本法所称用人单位，应当履行用人单位对劳动者的义务。劳务派遣单位与被派遣劳动者订立的劳动合同，除应当载明本法第十七条规定的事项外，还应当载明被派遣劳动者的用工单位以及派遣期限、工作岗位等情况。 劳务派遣单位应当与被派遣劳动者订立二年以上的固定期限劳动合同，按月支付劳动报酬；被派遣劳动者在无工作期间，劳务派遣单位应当按照所在地人民政府规定的最低工资标准，向其按月支付报酬。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375058, '《中华人民共和国劳动合同法》', '第五十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第五章 特别规定', '第二节 劳务派遣', '劳务派遣单位派遣劳动者应当与接受以劳务派遣形式用工的单位（以下称用工单位）订立劳务派遣协议。劳务派遣协议应当约定派遣岗位和人员数量、派遣期限、劳动报酬和社会保险费的数额与支付方式以及违反协议的责任。 用工单位应当根据工作岗位的实际需要与劳务派遣单位确定派遣期限，不得将连续用工期限分割订立数个短期劳务派遣协议。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375059, '《中华人民共和国劳动合同法》', '第六十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第五章 特别规定', '第二节 劳务派遣', '劳务派遣单位应当将劳务派遣协议的内容告知被派遣劳动者。 劳务派遣单位不得克扣用工单位按照劳务派遣协议支付给被派遣劳动者的劳动报酬。 劳务派遣单位和用工单位不得向被派遣劳动者收取费用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375060, '《中华人民共和国劳动合同法》', '第六十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第五章 特别规定', '第二节 劳务派遣', '劳务派遣单位跨地区派遣劳动者的，被派遣劳动者享有的劳动报酬和劳动条件，按照用工单位所在地的标准执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375061, '《中华人民共和国劳动合同法》', '第六十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第五章 特别规定', '第二节 劳务派遣', '用工单位应当履行下列义务： （一）执行国家劳动标准，提供相应的劳动条件和劳动保护； （二）告知被派遣劳动者的工作要求和劳动报酬； （三）支付加班费、绩效奖金，提供与工作岗位相关的福利待遇； （四）对在岗被派遣劳动者进行工作岗位所必需的培训； （五）连续用工的，实行正常的工资调整机制。 用工单位不得将被派遣劳动者再派遣到其他用人单位。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375062, '《中华人民共和国劳动合同法》', '第六十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第五章 特别规定', '第二节 劳务派遣', '被派遣劳动者享有与用工单位的劳动者同工同酬的权利。用工单位应当按照同工同酬原则，对被派遣劳动者与本单位同类岗位的劳动者实行相同的劳动报酬分配办法。用工单位无同类岗位劳动者的，参照用工单位所在地相同或者相近岗位劳动者的劳动报酬确定。 劳务派遣单位与被派遣劳动者订立的劳动合同和与用工单位订立的劳务派遣协议，载明或者约定的向被派遣劳动者支付的劳动报酬应当符合前款规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375063, '《中华人民共和国劳动合同法》', '第六十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第五章 特别规定', '第二节 劳务派遣', '被派遣劳动者有权在劳务派遣单位或者用工单位依法参加或者组织工会，维护自身的合法权益。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375064, '《中华人民共和国劳动合同法》', '第六十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第五章 特别规定', '第二节 劳务派遣', '被派遣劳动者可以依照本法第三十六条、第三十八条的规定与劳务派遣单位解除劳动合同。 被派遣劳动者有本法第三十九条和第四十条第一项、第二项规定情形的，用工单位可以将劳动者退回劳务派遣单位，劳务派遣单位依照本法有关规定，可以与劳动者解除劳动合同。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375065, '《中华人民共和国劳动合同法》', '第六十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第五章 特别规定', '第二节 劳务派遣', '劳动合同用工是我国的企业基本用工形式。劳务派遣用工是补充形式，只能在临时性、辅助性或者替代性的工作岗位上实施。 前款规定的临时性工作岗位是指存续时间不超过六个月的岗位；辅助性工作岗位是指为主营业务岗位提供服务的非主营业务岗位；替代性工作岗位是指用工单位的劳动者因脱产学习、休假等原因无法工作的一定期间内，可以由其他劳动者替代工作的岗位。 用工单位应当严格控制劳务派遣用工数量，不得超过其用工总量的一定比例，具体比例由国务院劳动行政部门规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375066, '《中华人民共和国劳动合同法》', '第六十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第五章 特别规定', '第二节 劳务派遣', '用人单位不得设立劳务派遣单位向本单位或者所属单位派遣劳动者。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375067, '《中华人民共和国劳动合同法》', '第六十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第五章 特别规定', '第三节 非全日制用工', '非全日制用工，是指以小时计酬为主，劳动者在同一用人单位一般平均每日工作时间不超过四小时，每周工作时间累计不超过二十四小时的用工形式。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375068, '《中华人民共和国劳动合同法》', '第六十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第五章 特别规定', '第三节 非全日制用工', '非全日制用工双方当事人可以订立口头协议。 从事非全日制用工的劳动者可以与一个或者一个以上用人单位订立劳动合同；但是，后订立的劳动合同不得影响先订立的劳动合同的履行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375069, '《中华人民共和国劳动合同法》', '第七十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第五章 特别规定', '第三节 非全日制用工', '非全日制用工双方当事人不得约定试用期。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375070, '《中华人民共和国劳动合同法》', '第七十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第五章 特别规定', '第三节 非全日制用工', '非全日制用工双方当事人任何一方都可以随时通知对方终止用工。终止用工，用人单位不向劳动者支付经济补偿。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375071, '《中华人民共和国劳动合同法》', '第七十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第五章 特别规定', '第三节 非全日制用工', '非全日制用工小时计酬标准不得低于用人单位所在地人民政府规定的最低小时工资标准。 非全日制用工劳动报酬结算支付周期最长不得超过十五日。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375072, '《中华人民共和国劳动合同法》', '第七十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第六章 监督检查', NULL, '国务院劳动行政部门负责全国劳动合同制度实施的监督管理。 县级以上地方人民政府劳动行政部门负责本行政区域内劳动合同制度实施的监督管理。 县级以上各级人民政府劳动行政部门在劳动合同制度实施的监督管理工作中，应当听取工会、企业方面代表以及有关行业主管部门的意见。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375073, '《中华人民共和国劳动合同法》', '第七十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第六章 监督检查', NULL, '县级以上地方人民政府劳动行政部门依法对下列实施劳动合同制度的情况进行监督检查： （一）用人单位制定直接涉及劳动者切身利益的规章制度及其执行的情况； （二）用人单位与劳动者订立和解除劳动合同的情况； （三）劳务派遣单位和用工单位遵守劳务派遣有关规定的情况； （四）用人单位遵守国家关于劳动者工作时间和休息休假规定的情况； （五）用人单位支付劳动合同约定的劳动报酬和执行最低工资标准的情况； （六）用人单位参加各项社会保险和缴纳社会保险费的情况； （七）法律、法规规定的其他劳动监察事项。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375074, '《中华人民共和国劳动合同法》', '第七十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第六章 监督检查', NULL, '县级以上地方人民政府劳动行政部门实施监督检查时，有权查阅与劳动合同、集体合同有关的材料，有权对劳动场所进行实地检查，用人单位和劳动者都应当如实提供有关情况和材料。 劳动行政部门的工作人员进行监督检查，应当出示证件，依法行使职权，文明执法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375075, '《中华人民共和国劳动合同法》', '第七十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第六章 监督检查', NULL, '县级以上人民政府建设、卫生、安全生产监督管理等有关主管部门在各自职责范围内，对用人单位执行劳动合同制度的情况进行监督管理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375076, '《中华人民共和国劳动合同法》', '第七十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第六章 监督检查', NULL, '劳动者合法权益受到侵害的，有权要求有关部门依法处理，或者依法申请仲裁、提起诉讼。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375077, '《中华人民共和国劳动合同法》', '第七十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第六章 监督检查', NULL, '工会依法维护劳动者的合法权益，对用人单位履行劳动合同、集体合同的情况进行监督。用人单位违反劳动法律、法规和劳动合同、集体合同的，工会有权提出意见或者要求纠正；劳动者申请仲裁、提起诉讼的，工会依法给予支持和帮助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375078, '《中华人民共和国劳动合同法》', '第七十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第六章 监督检查', NULL, '任何组织或者个人对违反本法的行为都有权举报，县级以上人民政府劳动行政部门应当及时核实、处理，并对举报有功人员给予奖励。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375079, '《中华人民共和国劳动合同法》', '第八十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第七章 法律责任', NULL, '用人单位直接涉及劳动者切身利益的规章制度违反法律、法规规定的，由劳动行政部门责令改正，给予警告；给劳动者造成损害的，应当承担赔偿责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375080, '《中华人民共和国劳动合同法》', '第八十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第七章 法律责任', NULL, '用人单位提供的劳动合同文本未载明本法规定的劳动合同必备条款或者用人单位未将劳动合同文本交付劳动者的，由劳动行政部门责令改正；给劳动者造成损害的，应当承担赔偿责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375081, '《中华人民共和国劳动合同法》', '第八十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第七章 法律责任', NULL, '用人单位自用工之日起超过一个月不满一年未与劳动者订立书面劳动合同的，应当向劳动者每月支付二倍的工资。 用人单位违反本法规定不与劳动者订立无固定期限劳动合同的，自应当订立无固定期限劳动合同之日起向劳动者每月支付二倍的工资。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375082, '《中华人民共和国劳动合同法》', '第八十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第七章 法律责任', NULL, '用人单位违反本法规定与劳动者约定试用期的，由劳动行政部门责令改正；违法约定的试用期已经履行的，由用人单位以劳动者试用期满月工资为标准，按已经履行的超过法定试用期的期间向劳动者支付赔偿金。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375083, '《中华人民共和国劳动合同法》', '第八十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第七章 法律责任', NULL, '用人单位违反本法规定，扣押劳动者居民身份证等证件的，由劳动行政部门责令限期退还劳动者本人，并依照有关法律规定给予处罚。 用人单位违反本法规定，以担保或者其他名义向劳动者收取财物的，由劳动行政部门责令限期退还劳动者本人，并以每人五百元以上二千元以下的标准处以罚款；给劳动者造成损害的，应当承担赔偿责任。 劳动者依法解除或者终止劳动合同，用人单位扣押劳动者档案或者其他物品的，依照前款规定处罚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375084, '《中华人民共和国劳动合同法》', '第八十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第七章 法律责任', NULL, '用人单位有下列情形之一的，由劳动行政部门责令限期支付劳动报酬、加班费或者经济补偿；劳动报酬低于当地最低工资标准的，应当支付其差额部分；逾期不支付的，责令用人单位按应付金额百分之五十以上百分之一百以下的标准向劳动者加付赔偿金： （一）未按照劳动合同的约定或者国家规定及时足额支付劳动者劳动报酬的； （二）低于当地最低工资标准支付劳动者工资的； （三）安排加班不支付加班费的； （四）解除或者终止劳动合同，未依照本法规定向劳动者支付经济补偿的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375085, '《中华人民共和国劳动合同法》', '第八十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第七章 法律责任', NULL, '劳动合同依照本法第二十六条规定被确认无效，给对方造成损害的，有过错的一方应当承担赔偿责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375086, '《中华人民共和国劳动合同法》', '第八十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第七章 法律责任', NULL, '用人单位违反本法规定解除或者终止劳动合同的，应当依照本法第四十七条规定的经济补偿标准的二倍向劳动者支付赔偿金。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375087, '《中华人民共和国劳动合同法》', '第八十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第七章 法律责任', NULL, '用人单位有下列情形之一的，依法给予行政处罚；构成犯罪的，依法追究刑事责任；给劳动者造成损害的，应当承担赔偿责任： （一）以暴力、威胁或者非法限制人身自由的手段强迫劳动的； （二）违章指挥或者强令冒险作业危及劳动者人身安全的； （三）侮辱、体罚、殴打、非法搜查或者拘禁劳动者的； （四）劳动条件恶劣、环境污染严重，给劳动者身心健康造成严重损害的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375088, '《中华人民共和国劳动合同法》', '第八十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第七章 法律责任', NULL, '用人单位违反本法规定未向劳动者出具解除或者终止劳动合同的书面证明，由劳动行政部门责令改正；给劳动者造成损害的，应当承担赔偿责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375089, '《中华人民共和国劳动合同法》', '第九十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第七章 法律责任', NULL, '劳动者违反本法规定解除劳动合同，或者违反劳动合同中约定的保密义务或者竞业限制，给用人单位造成损失的，应当承担赔偿责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375090, '《中华人民共和国劳动合同法》', '第九十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第七章 法律责任', NULL, '用人单位招用与其他用人单位尚未解除或者终止劳动合同的劳动者，给其他用人单位造成损失的，应当承担连带赔偿责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375091, '《中华人民共和国劳动合同法》', '第九十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第七章 法律责任', NULL, '违反本法规定，未经许可，擅自经营劳务派遣业务的，由劳动行政部门责令停止违法行为，没收违法所得，并处违法所得一倍以上五倍以下的罚款；没有违法所得的，可以处五万元以下的罚款。 劳务派遣单位、用工单位违反本法有关劳务派遣规定的，由劳动行政部门责令限期改正；逾期不改正的，以每人五千元以上一万元以下的标准处以罚款，对劳务派遣单位，吊销其劳务派遣业务经营许可证。用工单位给被派遣劳动者造成损害的，劳务派遣单位与用工单位承担连带赔偿责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375092, '《中华人民共和国劳动合同法》', '第九十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第七章 法律责任', NULL, '对不具备合法经营资格的用人单位的违法犯罪行为，依法追究法律责任；劳动者已经付出劳动的，该单位或者其出资人应当依照本法有关规定向劳动者支付劳动报酬、经济补偿、赔偿金；给劳动者造成损害的，应当承担赔偿责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375093, '《中华人民共和国劳动合同法》', '第九十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第七章 法律责任', NULL, '个人承包经营违反本法规定招用劳动者，给劳动者造成损害的，发包的组织与个人承包经营者承担连带赔偿责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375094, '《中华人民共和国劳动合同法》', '第九十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第七章 法律责任', NULL, '劳动行政部门和其他有关主管部门及其工作人员玩忽职守、不履行法定职责，或者违法行使职权，给劳动者或者用人单位造成损害的，应当承担赔偿责任；对直接负责的主管人员和其他直接责任人员，依法给予行政处分；构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375095, '《中华人民共和国劳动合同法》', '第九十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第八章 附 则', NULL, '事业单位与实行聘用制的工作人员订立、履行、变更、解除或者终止劳动合同，法律、行政法规或者国务院另有规定的，依照其规定；未作规定的，依照本法有关规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375096, '《中华人民共和国劳动合同法》', '第九十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第八章 附 则', NULL, '本法施行前已依法订立且在本法施行之日存续的劳动合同，继续履行；本法第十四条第二款第三项规定连续订立固定期限劳动合同的次数，自本法施行后续订固定期限劳动合同时开始计算。 本法施行前已建立劳动关系，尚未订立书面劳动合同的，应当自本法施行之日起一个月内订立。 本法施行之日存续的劳动合同在本法施行后解除或者终止，依照本法第四十六条规定应当支付经济补偿的，经济补偿年限自本法施行之日起计算；本法施行前按照当时有关规定，用人单位应当向劳动者支付经济补偿的，按照当时有关规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1375097, '《中华人民共和国劳动合同法》', '第九十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-12-28', '第八章 附 则', NULL, '本法自2008年1月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447000, '《中华人民共和国劳动争议调解仲裁法》', '第一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第一章 总 则', NULL, '为了公正及时解决劳动争议，保护当事人合法权益，促进劳动关系和谐稳定，制定本法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447001, '《中华人民共和国劳动争议调解仲裁法》', '第二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第一章 总 则', NULL, '中华人民共和国境内的用人单位与劳动者发生的下列劳动争议，适用本法： （一）因确认劳动关系发生的争议； （二）因订立、履行、变更、解除和终止劳动合同发生的争议； （三）因除名、辞退和辞职、离职发生的争议； （四）因工作时间、休息休假、社会保险、福利、培训以及劳动保护发生的争议； （五）因劳动报酬、工伤医疗费、经济补偿或者赔偿金等发生的争议； （六）法律、法规规定的其他劳动争议。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447002, '《中华人民共和国劳动争议调解仲裁法》', '第三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第一章 总 则', NULL, '解决劳动争议，应当根据事实，遵循合法、公正、及时、着重调解的原则，依法保护当事人的合法权益。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447003, '《中华人民共和国劳动争议调解仲裁法》', '第四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第一章 总 则', NULL, '发生劳动争议，劳动者可以与用人单位协商，也可以请工会或者第三方共同与用人单位协商，达成和解协议。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447004, '《中华人民共和国劳动争议调解仲裁法》', '第五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第一章 总 则', NULL, '发生劳动争议，当事人不愿协商、协商不成或者达成和解协议后不履行的，可以向调解组织申请调解；不愿调解、调解不成或者达成调解协议后不履行的，可以向劳动争议仲裁委员会申请仲裁；对仲裁裁决不服的，除本法另有规定的外，可以向人民法院提起诉讼。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447005, '《中华人民共和国劳动争议调解仲裁法》', '第六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第一章 总 则', NULL, '发生劳动争议，当事人对自己提出的主张，有责任提供证据。与争议事项有关的证据属于用人单位掌握管理的，用人单位应当提供；用人单位不提供的，应当承担不利后果。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447006, '《中华人民共和国劳动争议调解仲裁法》', '第七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第一章 总 则', NULL, '发生劳动争议的劳动者一方在十人以上，并有共同请求的，可以推举代表参加调解、仲裁或者诉讼活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447007, '《中华人民共和国劳动争议调解仲裁法》', '第八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第一章 总 则', NULL, '县级以上人民政府劳动行政部门会同工会和企业方面代表建立协调劳动关系三方机制，共同研究解决劳动争议的重大问题。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447008, '《中华人民共和国劳动争议调解仲裁法》', '第九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第一章 总 则', NULL, '用人单位违反国家规定，拖欠或者未足额支付劳动报酬，或者拖欠工伤医疗费、经济补偿或者赔偿金的，劳动者可以向劳动行政部门投诉，劳动行政部门应当依法处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447009, '《中华人民共和国劳动争议调解仲裁法》', '第十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第二章 调 解', NULL, '发生劳动争议，当事人可以到下列调解组织申请调解： （一）企业劳动争议调解委员会； （二）依法设立的基层人民调解组织； （三）在乡镇、街道设立的具有劳动争议调解职能的组织。 企业劳动争议调解委员会由职工代表和企业代表组成。职工代表由工会成员担任或者由全体职工推举产生，企业代表由企业负责人指定。企业劳动争议调解委员会主任由工会成员或者双方推举的人员担任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447010, '《中华人民共和国劳动争议调解仲裁法》', '第十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第二章 调 解', NULL, '劳动争议调解组织的调解员应当由公道正派、联系群众、热心调解工作，并具有一定法律知识、政策水平和文化水平的成年公民担任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447011, '《中华人民共和国劳动争议调解仲裁法》', '第十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第二章 调 解', NULL, '当事人申请劳动争议调解可以书面申请，也可以口头申请。口头申请的，调解组织应当当场记录申请人基本情况、申请调解的争议事项、理由和时间。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447012, '《中华人民共和国劳动争议调解仲裁法》', '第十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第二章 调 解', NULL, '调解劳动争议，应当充分听取双方当事人对事实和理由的陈述，耐心疏导，帮助其达成协议。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447013, '《中华人民共和国劳动争议调解仲裁法》', '第十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第二章 调 解', NULL, '经调解达成协议的，应当制作调解协议书。 调解协议书由双方当事人签名或者盖章，经调解员签名并加盖调解组织印章后生效，对双方当事人具有约束力，当事人应当履行。 自劳动争议调解组织收到调解申请之日起十五日内未达成调解协议的，当事人可以依法申请仲裁。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447014, '《中华人民共和国劳动争议调解仲裁法》', '第十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第二章 调 解', NULL, '达成调解协议后，一方当事人在协议约定期限内不履行调解协议的，另一方当事人可以依法申请仲裁。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447015, '《中华人民共和国劳动争议调解仲裁法》', '第十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第二章 调 解', NULL, '因支付拖欠劳动报酬、工伤医疗费、经济补偿或者赔偿金事项达成调解协议，用人单位在协议约定期限内不履行的，劳动者可以持调解协议书依法向人民法院申请支付令。人民法院应当依法发出支付令。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447016, '《中华人民共和国劳动争议调解仲裁法》', '第十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第三章 仲 裁', '第一节 一般规定', '劳动争议仲裁委员会按照统筹规划、合理布局和适应实际需要的原则设立。省、自治区人民政府可以决定在市、县设立；直辖市人民政府可以决定在区、县设立。直辖市、设区的市也可以设立一个或者若干个劳动争议仲裁委员会。劳动争议仲裁委员会不按行政区划层层设立。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447017, '《中华人民共和国劳动争议调解仲裁法》', '第十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第三章 仲 裁', '第一节 一般规定', '国务院劳动行政部门依照本法有关规定制定仲裁规则。省、自治区、直辖市人民政府劳动行政部门对本行政区域的劳动争议仲裁工作进行指导。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447018, '《中华人民共和国劳动争议调解仲裁法》', '第十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第三章 仲 裁', '第一节 一般规定', '劳动争议仲裁委员会由劳动行政部门代表、工会代表和企业方面代表组成。劳动争议仲裁委员会组成人员应当是单数。 劳动争议仲裁委员会依法履行下列职责： （一）聘任、解聘专职或者兼职仲裁员； （二）受理劳动争议案件； （三）讨论重大或者疑难的劳动争议案件； （四）对仲裁活动进行监督。 劳动争议仲裁委员会下设办事机构，负责办理劳动争议仲裁委员会的日常工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447019, '《中华人民共和国劳动争议调解仲裁法》', '第二十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第三章 仲 裁', '第一节 一般规定', '劳动争议仲裁委员会应当设仲裁员名册。 仲裁员应当公道正派并符合下列条件之一： （一）曾任审判员的； （二）从事法律研究、教学工作并具有中级以上职称的； （三）具有法律知识、从事人力资源管理或者工会等专业工作满五年的； （四）律师执业满三年的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447020, '《中华人民共和国劳动争议调解仲裁法》', '第二十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第三章 仲 裁', '第一节 一般规定', '劳动争议仲裁委员会负责管辖本区域内发生的劳动争议。 劳动争议由劳动合同履行地或者用人单位所在地的劳动争议仲裁委员会管辖。双方当事人分别向劳动合同履行地和用人单位所在地的劳动争议仲裁委员会申请仲裁的，由劳动合同履行地的劳动争议仲裁委员会管辖。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447021, '《中华人民共和国劳动争议调解仲裁法》', '第二十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第三章 仲 裁', '第一节 一般规定', '发生劳动争议的劳动者和用人单位为劳动争议仲裁案件的双方当事人。 劳务派遣单位或者用工单位与劳动者发生劳动争议的，劳务派遣单位和用工单位为共同当事人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447022, '《中华人民共和国劳动争议调解仲裁法》', '第二十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第三章 仲 裁', '第一节 一般规定', '与劳动争议案件的处理结果有利害关系的第三人，可以申请参加仲裁活动或者由劳动争议仲裁委员会通知其参加仲裁活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447023, '《中华人民共和国劳动争议调解仲裁法》', '第二十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第三章 仲 裁', '第一节 一般规定', '当事人可以委托代理人参加仲裁活动。委托他人参加仲裁活动，应当向劳动争议仲裁委员会提交有委托人签名或者盖章的委托书，委托书应当载明委托事项和权限。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447024, '《中华人民共和国劳动争议调解仲裁法》', '第二十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第三章 仲 裁', '第一节 一般规定', '丧失或者部分丧失民事行为能力的劳动者，由其法定代理人代为参加仲裁活动；无法定代理人的，由劳动争议仲裁委员会为其指定代理人。劳动者死亡的，由其近亲属或者代理人参加仲裁活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447025, '《中华人民共和国劳动争议调解仲裁法》', '第二十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第三章 仲 裁', '第一节 一般规定', '劳动争议仲裁公开进行，但当事人协议不公开进行或者涉及国家秘密、商业秘密和个人隐私的除外。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447026, '《中华人民共和国劳动争议调解仲裁法》', '第二十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第三章 仲 裁', '第二节 申请和受理', '劳动争议申请仲裁的时效期间为一年。仲裁时效期间从当事人知道或者应当知道其权利被侵害之日起计算。 前款规定的仲裁时效，因当事人一方向对方当事人主张权利，或者向有关部门请求权利救济，或者对方当事人同意履行义务而中断。从中断时起，仲裁时效期间重新计算。 因不可抗力或者有其他正当理由，当事人不能在本条第一款规定的仲裁时效期间申请仲裁的，仲裁时效中止。从中止时效的原因消除之日起，仲裁时效期间继续计算。 劳动关系存续期间因拖欠劳动报酬发生争议的，劳动者申请仲裁不受本条第一款规定的仲裁时效期间的限制；但是，劳动关系终止的，应当自劳动关系终止之日起一年内提出。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447027, '《中华人民共和国劳动争议调解仲裁法》', '第二十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第三章 仲 裁', '第二节 申请和受理', '申请人申请仲裁应当提交书面仲裁申请，并按照被申请人人数提交副本。 仲裁申请书应当载明下列事项： （一）劳动者的姓名、性别、年龄、职业、工作单位和住所，用人单位的名称、住所和法定代表人或者主要负责人的姓名、职务； （二）仲裁请求和所根据的事实、理由； （三）证据和证据来源、证人姓名和住所。 书写仲裁申请确有困难的，可以口头申请，由劳动争议仲裁委员会记入笔录，并告知对方当事人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447028, '《中华人民共和国劳动争议调解仲裁法》', '第二十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第三章 仲 裁', '第二节 申请和受理', '劳动争议仲裁委员会收到仲裁申请之日起五日内，认为符合受理条件的，应当受理，并通知申请人；认为不符合受理条件的，应当书面通知申请人不予受理，并说明理由。对劳动争议仲裁委员会不予受理或者逾期未作出决定的，申请人可以就该劳动争议事项向人民法院提起诉讼。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447029, '《中华人民共和国劳动争议调解仲裁法》', '第三十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第三章 仲 裁', '第二节 申请和受理', '劳动争议仲裁委员会受理仲裁申请后，应当在五日内将仲裁申请书副本送达被申请人。 被申请人收到仲裁申请书副本后，应当在十日内向劳动争议仲裁委员会提交答辩书。劳动争议仲裁委员会收到答辩书后，应当在五日内将答辩书副本送达申请人。被申请人未提交答辩书的，不影响仲裁程序的进行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447030, '《中华人民共和国劳动争议调解仲裁法》', '第三十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第三章 仲 裁', '第三节 开庭和裁决', '劳动争议仲裁委员会裁决劳动争议案件实行仲裁庭制。仲裁庭由三名仲裁员组成，设首席仲裁员。简单劳动争议案件可以由一名仲裁员独任仲裁。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447031, '《中华人民共和国劳动争议调解仲裁法》', '第三十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第三章 仲 裁', '第三节 开庭和裁决', '劳动争议仲裁委员会应当在受理仲裁申请之日起五日内将仲裁庭的组成情况书面通知当事人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447032, '《中华人民共和国劳动争议调解仲裁法》', '第三十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第三章 仲 裁', '第三节 开庭和裁决', '仲裁员有下列情形之一，应当回避，当事人也有权以口头或者书面方式提出回避申请： （一）是本案当事人或者当事人、代理人的近亲属的； （二）与本案有利害关系的； （三）与本案当事人、代理人有其他关系，可能影响公正裁决的； （四）私自会见当事人、代理人，或者接受当事人、代理人的请客送礼的。 劳动争议仲裁委员会对回避申请应当及时作出决定，并以口头或者书面方式通知当事人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447033, '《中华人民共和国劳动争议调解仲裁法》', '第三十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第三章 仲 裁', '第三节 开庭和裁决', '仲裁员有本法第三十三条第四项规定情形，或者有索贿受贿、徇私舞弊、枉法裁决行为的，应当依法承担法律责任。劳动争议仲裁委员会应当将其解聘。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447034, '《中华人民共和国劳动争议调解仲裁法》', '第三十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第三章 仲 裁', '第三节 开庭和裁决', '仲裁庭应当在开庭五日前，将开庭日期、地点书面通知双方当事人。当事人有正当理由的，可以在开庭三日前请求延期开庭。是否延期，由劳动争议仲裁委员会决定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447035, '《中华人民共和国劳动争议调解仲裁法》', '第三十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第三章 仲 裁', '第三节 开庭和裁决', '申请人收到书面通知，无正当理由拒不到庭或者未经仲裁庭同意中途退庭的，可以视为撤回仲裁申请。 被申请人收到书面通知，无正当理由拒不到庭或者未经仲裁庭同意中途退庭的，可以缺席裁决。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447036, '《中华人民共和国劳动争议调解仲裁法》', '第三十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第三章 仲 裁', '第三节 开庭和裁决', '仲裁庭对专门性问题认为需要鉴定的，可以交由当事人约定的鉴定机构鉴定；当事人没有约定或者无法达成约定的，由仲裁庭指定的鉴定机构鉴定。 根据当事人的请求或者仲裁庭的要求，鉴定机构应当派鉴定人参加开庭。当事人经仲裁庭许可，可以向鉴定人提问。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447037, '《中华人民共和国劳动争议调解仲裁法》', '第三十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第三章 仲 裁', '第三节 开庭和裁决', '当事人在仲裁过程中有权进行质证和辩论。质证和辩论终结时，首席仲裁员或者独任仲裁员应当征询当事人的最后意见。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447038, '《中华人民共和国劳动争议调解仲裁法》', '第三十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第三章 仲 裁', '第三节 开庭和裁决', '当事人提供的证据经查证属实的，仲裁庭应当将其作为认定事实的根据。 劳动者无法提供由用人单位掌握管理的与仲裁请求有关的证据，仲裁庭可以要求用人单位在指定期限内提供。用人单位在指定期限内不提供的，应当承担不利后果。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447039, '《中华人民共和国劳动争议调解仲裁法》', '第四十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第三章 仲 裁', '第三节 开庭和裁决', '仲裁庭应当将开庭情况记入笔录。当事人和其他仲裁参加人认为对自己陈述的记录有遗漏或者差错的，有权申请补正。如果不予补正，应当记录该申请。 笔录由仲裁员、记录人员、当事人和其他仲裁参加人签名或者盖章。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447040, '《中华人民共和国劳动争议调解仲裁法》', '第四十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第三章 仲 裁', '第三节 开庭和裁决', '当事人申请劳动争议仲裁后，可以自行和解。达成和解协议的，可以撤回仲裁申请。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447041, '《中华人民共和国劳动争议调解仲裁法》', '第四十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第三章 仲 裁', '第三节 开庭和裁决', '仲裁庭在作出裁决前，应当先行调解。 调解达成协议的，仲裁庭应当制作调解书。 调解书应当写明仲裁请求和当事人协议的结果。调解书由仲裁员签名，加盖劳动争议仲裁委员会印章，送达双方当事人。调解书经双方当事人签收后，发生法律效力。 调解不成或者调解书送达前，一方当事人反悔的，仲裁庭应当及时作出裁决。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447042, '《中华人民共和国劳动争议调解仲裁法》', '第四十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第三章 仲 裁', '第三节 开庭和裁决', '仲裁庭裁决劳动争议案件，应当自劳动争议仲裁委员会受理仲裁申请之日起四十五日内结束。案情复杂需要延期的，经劳动争议仲裁委员会主任批准，可以延期并书面通知当事人，但是延长期限不得超过十五日。逾期未作出仲裁裁决的，当事人可以就该劳动争议事项向人民法院提起诉讼。 仲裁庭裁决劳动争议案件时，其中一部分事实已经清楚，可以就该部分先行裁决。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447043, '《中华人民共和国劳动争议调解仲裁法》', '第四十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第三章 仲 裁', '第三节 开庭和裁决', '仲裁庭对追索劳动报酬、工伤医疗费、经济补偿或者赔偿金的案件，根据当事人的申请，可以裁决先予执行，移送人民法院执行。 仲裁庭裁决先予执行的，应当符合下列条件： （一）当事人之间权利义务关系明确； （二）不先予执行将严重影响申请人的生活。 劳动者申请先予执行的，可以不提供担保。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447044, '《中华人民共和国劳动争议调解仲裁法》', '第四十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第三章 仲 裁', '第三节 开庭和裁决', '裁决应当按照多数仲裁员的意见作出，少数仲裁员的不同意见应当记入笔录。仲裁庭不能形成多数意见时，裁决应当按照首席仲裁员的意见作出。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447045, '《中华人民共和国劳动争议调解仲裁法》', '第四十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第三章 仲 裁', '第三节 开庭和裁决', '裁决书应当载明仲裁请求、争议事实、裁决理由、裁决结果和裁决日期。裁决书由仲裁员签名，加盖劳动争议仲裁委员会印章。对裁决持不同意见的仲裁员，可以签名，也可以不签名。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447046, '《中华人民共和国劳动争议调解仲裁法》', '第四十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第三章 仲 裁', '第三节 开庭和裁决', '下列劳动争议，除本法另有规定的外，仲裁裁决为终局裁决，裁决书自作出之日起发生法律效力： （一）追索劳动报酬、工伤医疗费、经济补偿或者赔偿金，不超过当地月最低工资标准十二个月金额的争议； （二）因执行国家的劳动标准在工作时间、休息休假、社会保险等方面发生的争议。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447047, '《中华人民共和国劳动争议调解仲裁法》', '第四十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第三章 仲 裁', '第三节 开庭和裁决', '劳动者对本法第四十七条规定的仲裁裁决不服的，可以自收到仲裁裁决书之日起十五日内向人民法院提起诉讼。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447048, '《中华人民共和国劳动争议调解仲裁法》', '第四十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第三章 仲 裁', '第三节 开庭和裁决', '用人单位有证据证明本法第四十七条规定的仲裁裁决有下列情形之一，可以自收到仲裁裁决书之日起三十日内向劳动争议仲裁委员会所在地的中级人民法院申请撤销裁决： （一）适用法律、法规确有错误的； （二）劳动争议仲裁委员会无管辖权的； （三）违反法定程序的； （四）裁决所根据的证据是伪造的； （五）对方当事人隐瞒了足以影响公正裁决的证据的； （六）仲裁员在仲裁该案时有索贿受贿、徇私舞弊、枉法裁决行为的。 人民法院经组成合议庭审查核实裁决有前款规定情形之一的，应当裁定撤销。 仲裁裁决被人民法院裁定撤销的，当事人可以自收到裁定书之日起十五日内就该劳动争议事项向人民法院提起诉讼。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447049, '《中华人民共和国劳动争议调解仲裁法》', '第五十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第三章 仲 裁', '第三节 开庭和裁决', '当事人对本法第四十七条规定以外的其他劳动争议案件的仲裁裁决不服的，可以自收到仲裁裁决书之日起十五日内向人民法院提起诉讼；期满不起诉的，裁决书发生法律效力。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447050, '《中华人民共和国劳动争议调解仲裁法》', '第五十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第三章 仲 裁', '第三节 开庭和裁决', '当事人对发生法律效力的调解书、裁决书，应当依照规定的期限履行。一方当事人逾期不履行的，另一方当事人可以依照民事诉讼法的有关规定向人民法院申请执行。受理申请的人民法院应当依法执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447051, '《中华人民共和国劳动争议调解仲裁法》', '第五十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第四章 附 则', NULL, '事业单位实行聘用制的工作人员与本单位发生劳动争议的，依照本法执行；法律、行政法规或者国务院另有规定的，依照其规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447052, '《中华人民共和国劳动争议调解仲裁法》', '第五十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第四章 附 则', NULL, '劳动争议仲裁不收费。劳动争议仲裁委员会的经费由财政予以保障。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1447053, '《中华人民共和国劳动争议调解仲裁法》', '第五十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2007-12-29', '第四章 附 则', NULL, '本法自2008年5月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021000, '《退役军人就业创业促进条例》', '第一条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第一章 总 则', NULL, '为了促进退役军人就业创业，发挥退役军人人力资源作用，维护退役军人合法权益，让军人成为全社会尊崇的职业，根据《中华人民共和国退役军人保障法》、《中华人民共和国就业促进法》等有关法律，制定本条例。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021001, '《退役军人就业创业促进条例》', '第二条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第一章 总 则', NULL, '退役军人就业创业工作坚持中国共产党的领导，坚持普惠与优待叠加的原则，采取政府推动、市场引导、社会支持相结合的方式，鼓励和扶持退役军人就业创业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021002, '《退役军人就业创业促进条例》', '第三条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第一章 总 则', NULL, '引导退役军人树立正确的择业观念，通过教育培训、就业支持、创业扶持等措施，促进退役军人高质量充分就业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021003, '《退役军人就业创业促进条例》', '第四条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第一章 总 则', NULL, '国家将退役军人就业创业工作纳入有关规划。 各级人民政府应当加强对退役军人就业创业的指导和服务，推动机关、群团组织、企业事业单位等各负其责、密切配合，形成支持退役军人就业创业的合力。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021004, '《退役军人就业创业促进条例》', '第五条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第一章 总 则', NULL, '国务院退役军人工作主管部门、人力资源社会保障部门以及中央和国家机关其他有关部门按照职责分工做好退役军人就业创业工作。 县级以上地方人民政府退役军人工作主管部门应当加强对退役军人就业创业的宣传、组织、协调等工作。地方各级有关机关应当在各自职责范围内做好退役军人就业创业工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021005, '《退役军人就业创业促进条例》', '第六条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第一章 总 则', NULL, '尊重、关爱退役军人是全社会的共同责任。国家鼓励和引导企业、社会组织、个人等社会力量依法为退役军人就业创业提供支持和帮助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021006, '《退役军人就业创业促进条例》', '第七条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第一章 总 则', NULL, '退役军人在就业创业活动中应当模范遵守宪法和法律法规，保守军事秘密，践行社会主义核心价值观，积极参加社会主义现代化建设。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021007, '《退役军人就业创业促进条例》', '第八条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第一章 总 则', NULL, '国家依法对退役军人就业创业给予经费支持，标准应当与经济社会发展水平和财力状况相适应。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021008, '《退役军人就业创业促进条例》', '第九条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第二章 教育培训', NULL, '国家采取措施加强对退役军人的教育培训，帮助退役军人完善知识结构，提高思想政治水平、职业技能水平和综合职业素养，提升就业创业能力。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021009, '《退役军人就业创业促进条例》', '第十条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第二章 教育培训', NULL, '国家鼓励退役军人接受学历教育，提升学历层次，增强就业创业发展潜力。 国家鼓励退役军人接受职业学校教育，提升技术技能，增强职业综合素质和行动能力。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021010, '《退役军人就业创业促进条例》', '第十一条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第二章 教育培训', NULL, '军人入伍前已被普通高等学校录取或者是正在普通高等学校就学的学生，服现役期间保留入学资格或者学籍，退役后2年内允许入学或者复学，可以按照国家有关规定转入本校其他专业学习。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021011, '《退役军人就业创业促进条例》', '第十二条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第二章 教育培训', NULL, '退役军人参加国家教育考试的，按照国家有关规定享受优待政策。 退役军人在接受学历教育时，按照国家有关规定享受学费和助学金资助等国家教育资助政策。 县级以上地方人民政府兵役机关、退役军人工作主管部门按照职责分工负责对退役军人考生和复学学生的政策宣传、身份审核工作，教育行政部门负责资助资格审核工作。 鼓励各地出台政策支持退役军人参加高等教育自学考试和各类高等学校举办的高等学历继续教育。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021012, '《退役军人就业创业促进条例》', '第十三条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第二章 教育培训', NULL, '鼓励普通高等学校、职业院校（含技工院校）等针对退役军人特点，优化人才培养方案。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021013, '《退役军人就业创业促进条例》', '第十四条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第二章 教育培训', NULL, '退役军人培训工作应当以提高就业质量为导向，紧密围绕社会需求，适应科技创新和产业发展趋势，为退役军人提供有特色、精细化、针对性强的培训服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021014, '《退役军人就业创业促进条例》', '第十五条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第二章 教育培训', NULL, '县级以上地方人民政府退役军人工作主管部门根据驻地部队需要，协助开展职业技能储备培训和离队前教育。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021015, '《退役军人就业创业促进条例》', '第十六条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第二章 教育培训', NULL, '军人退出现役后，退役军人工作主管部门和其他负责退役军人安置工作的部门应当区分不同安置方式的退役军人，组织适应性培训。培训应当使用适合退役军人特点的教材，培训时长不得少于国家规定的时长。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021016, '《退役军人就业创业促进条例》', '第十七条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第二章 教育培训', NULL, '符合条件的退役军人参加职业技能培训的，按照规定享受职业技能培训补贴等相应扶持政策。 安置地人民政府退役军人工作主管部门应当根据未达到法定退休年龄的自主就业退役军士和义务兵的就业需求，组织其免费参加职业技能培训，或者在其参加职业技能培训后在安置地标准内给予培训补贴。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021017, '《退役军人就业创业促进条例》', '第十八条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第二章 教育培训', NULL, '自主就业的退役军士和义务兵原则上在安置地参加职业技能培训。经安置地人民政府退役军人工作主管部门批准，在安置地以外地区参加职业技能培训的，培训结束并经安置地人民政府退役军人工作主管部门审核同意后，在安置地标准内给予培训补贴。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021018, '《退役军人就业创业促进条例》', '第十九条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第二章 教育培训', NULL, '省级人民政府退役军人工作主管部门负责统筹本行政区域内退役军人职业技能培训工作，明确总体计划、管理机制、发展方向等，可以根据实际情况会同有关部门制定公布职业技能培训项目参考目录，结合实际组织实施示范培训。 设区的市级人民政府退役军人工作主管部门及其授权的县级人民政府退役军人工作主管部门负责本行政区域内退役军人职业技能培训的具体组织实施，结合本地区产业发展和急需紧缺职业需要，综合考虑自主就业的退役军士和义务兵就业需求，会同有关部门制定公布职业技能培训项目参考目录。 组织实施职业技能培训的地方人民政府退役军人工作主管部门按照规定从普通高等学校、职业院校（含技工院校）、专业培训机构中确定承训机构，签订承训合同，公告承训机构信息，并动态更新。涉及政府采购的，应当严格执行政府采购有关规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021019, '《退役军人就业创业促进条例》', '第二十条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第二章 教育培训', NULL, '承训机构应当建立健全教学管理制度、学员管理制度、安全管理制度，组织学员参加职业能力评价，推荐就业岗位。 鼓励承训机构共享优质培训资源。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021020, '《退役军人就业创业促进条例》', '第二十一条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第二章 教育培训', NULL, '省级人民政府退役军人工作主管部门会同有关部门对承训机构加强动态管理，建立以学员满意度、职业技能评价、培训后就业情况等为主要指标的培训质量评价标准，定期对培训质量进行检查，提高职业技能培训质量和水平。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021021, '《退役军人就业创业促进条例》', '第二十二条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第二章 教育培训', NULL, '鼓励公共实训基地主动承接退役军人职业技能培训项目，面向退役军人就业需求和市场需求设置有针对性的培训课程。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021022, '《退役军人就业创业促进条例》', '第二十三条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第二章 教育培训', NULL, '国家推行终身职业技能培训制度，将退役军人职业技能培训纳入终身职业技能培训政策和组织实施体系。 国务院退役军人工作主管部门完善网络课程体系，为退役军人提供便捷化网络学习服务。 鼓励用人单位定期组织招用的退役军人参加岗位技能提升和知识更新培训。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021023, '《退役军人就业创业促进条例》', '第二十四条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第二章 教育培训', NULL, '发挥普通高等学校、职业院校（含技工院校）等教学资源优势，加强校内培训服务，支持退役军人学生在获得学历证书的同时，经考试考核合格取得相应的职业资格证书或者职业技能等级证书。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021024, '《退役军人就业创业促进条例》', '第二十五条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第二章 教育培训', NULL, '退役军人服现役期间取得的技能人员职业资格证书，作为其退出现役后从事相应职业（工种）的合法凭证，在全国范围内通用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021025, '《退役军人就业创业促进条例》', '第二十六条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第三章 就业支持', NULL, '国家支持退役军人多渠道就业，引导退役军人发挥自身优势投身社会主义现代化建设。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021026, '《退役军人就业创业促进条例》', '第二十七条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第三章 就业支持', NULL, '自主就业的退役军士和义务兵入伍前是机关、群团组织、事业单位或者国有企业人员的，退出现役后可以选择复职复工，其工资、福利待遇不得低于本单位同等条件人员的平均水平。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021027, '《退役军人就业创业促进条例》', '第二十八条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第三章 就业支持', NULL, '机关、群团组织、事业单位和国有企业在招录或者招聘人员时，对退役军人的年龄和学历条件可以适当放宽，同等条件下优先招录、招聘退役军人。国有企业招聘人员时，可以根据需要设置一定比例的岗位招聘退役军人。 鼓励和引导前款规定以外的其他用人单位在招用人员时，同等条件下优先招用退役军人。 用人单位招用退役军人符合国家规定的，依法享受税收优惠等政策。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021028, '《退役军人就业创业促进条例》', '第二十九条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第三章 就业支持', NULL, '各地应当设置一定数量的基层公务员职位，面向服现役满5年的高校毕业生退役军人招考。 服现役满5年的高校毕业生退役军人可以报考面向服务基层项目人员定向考录的职位，同服务基层项目人员共享公务员定向考录计划。 各级有关机关在组织开展选调生工作时，应当注重选调有服役经历的符合条件的优秀大学生。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021029, '《退役军人就业创业促进条例》', '第三十条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第三章 就业支持', NULL, '艰苦边远地区县乡事业单位可以按照有关规定对退役军人进行专项招聘，并增加工作实绩在组织考察中的权重。 促进符合条件的优秀退役军人到中小学任教。各地在制定中小学教师招聘计划时，可以面向退役军人单列计划。 各地应当注重从优秀退役军人中选聘党的基层组织、社区和村专职工作人员。 各级退役军人工作主管部门直属事业单位、乡镇（街道）退役军人服务站应当优先招聘符合条件的退役军人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021030, '《退役军人就业创业促进条例》', '第三十一条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第三章 就业支持', NULL, '国家综合性消防救援队伍招录消防员时，应当设置一定比例的计划专项招录退役军士和义务兵。 招聘警务辅助人员时，同等条件下应当优先招聘退役军人。 军队文职人员岗位、国防教育机构岗位等应当优先选用符合条件的退役军人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021031, '《退役军人就业创业促进条例》', '第三十二条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第三章 就业支持', NULL, '退役军官在军队团和相当于团以下单位工作的经历，退役军士和义务兵服现役的经历，视为基层工作经历。 退役军人服现役年限计算为工龄，退役后与所在单位工作年限累计计算，享受国家和所在单位规定的与工龄有关的相应待遇。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021032, '《退役军人就业创业促进条例》', '第三十三条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第三章 就业支持', NULL, '县级以上地方人民政府退役军人工作主管部门应当会同有关部门开展退役军人就业推荐、职业指导，定期组织退役军人招聘活动，开展形式多样的岗位推介，为退役军人就业搭建平台。 公共人力资源服务机构应当免费为退役军人提供职业介绍、职业指导等服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021033, '《退役军人就业创业促进条例》', '第三十四条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第三章 就业支持', NULL, '地方各级人民政府应当将符合就业困难人员认定条件的退役军人纳入就业援助范围，优先提供帮扶。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021034, '《退役军人就业创业促进条例》', '第三十五条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第四章 创业扶持', NULL, '鼓励和支持有条件、有意愿的退役军人创业，带动更多就业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021035, '《退役军人就业创业促进条例》', '第三十六条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第四章 创业扶持', NULL, '退役军人从事个体经营，依法享受税收优惠等政策。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021036, '《退役军人就业创业促进条例》', '第三十七条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第四章 创业扶持', NULL, '退役军人创业，可以按照国家有关规定申请创业担保贷款，并享受贷款贴息等融资优惠政策。 金融机构应当按照市场化原则，依法依规提供符合退役军人创业需求的金融产品和服务，扩大退役军人信贷服务覆盖面。 鼓励社会资本设立退役军人创业基金，拓宽退役军人融资渠道。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021037, '《退役军人就业创业促进条例》', '第三十八条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第四章 创业扶持', NULL, '县级以上地方人民政府投资建设或者与社会共建的创业基地（园区）等可以通过开辟专区等形式，优先为退役军人创业提供服务。 有条件的地区可以建立退役军人创业载体，为退役军人创业提供经营场地、投资融资、项目对接等方面的优先、优惠服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021038, '《退役军人就业创业促进条例》', '第三十九条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第四章 创业扶持', NULL, '县级以上地方人民政府应当支持引导有创业意愿和培训需求的退役军人参加创业培训。 鼓励县级以上地方人民政府退役军人工作主管部门建立退役军人创业服务团队，发挥创业指导、吸纳退役军人就业、企业互助发展等方面作用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021039, '《退役军人就业创业促进条例》', '第四十条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第四章 创业扶持', NULL, '国务院部门、县级以上地方人民政府及其部门设立的政务服务机构、公共服务机构等应当设置退役军人窗口或者绿色通道，为退役军人创业提供登记注册、税费办理、补贴申领等服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021040, '《退役军人就业创业促进条例》', '第四十一条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第四章 创业扶持', NULL, '鼓励退役军人围绕新技术、新产业、新业态以及国家重点扶持领域创业创新。支持退役军人创办的符合条件的中小企业参与科技型中小企业评价。 县级以上人民政府退役军人工作主管部门应当采取多种举措促进退役军人创业创新赛事活动优秀项目成果转化。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021041, '《退役军人就业创业促进条例》', '第四十二条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第四章 创业扶持', NULL, '县级以上人民政府退役军人工作主管部门应当引导退役军人用好各项创业扶持优惠政策。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021042, '《退役军人就业创业促进条例》', '第四十三条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第五章 法律责任', NULL, '退役军人工作主管部门及其工作人员有下列行为之一的，由其上级主管部门责令改正；对负有责任的领导人员和直接责任人员依法给予处分： （一）在退役军人就业创业工作中出具虚假文件的； （二）挪用、截留、私分退役军人就业创业工作等经费的； （三）在退役军人就业创业工作中利用职务之便为自己或者他人谋取私利的； （四）在退役军人就业创业工作中失职渎职的； （五）有其他违反法律法规行为的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021043, '《退役军人就业创业促进条例》', '第四十四条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第五章 法律责任', NULL, '其他负责退役军人就业创业有关工作的部门及其工作人员违反本条例规定的，由其上级主管部门责令改正；对负有责任的领导人员和直接责任人员依法给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021044, '《退役军人就业创业促进条例》', '第四十五条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第五章 法律责任', NULL, '退役军人弄虚作假骗取相关待遇的，由有关主管部门取消待遇，追缴非法所得，并由其所在单位或者有关部门依法给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021045, '《退役军人就业创业促进条例》', '第四十六条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第五章 法律责任', NULL, '违反本条例规定，构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021046, '《退役军人就业创业促进条例》', '第四十七条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第六章 附 则', NULL, '中国人民武装警察部队依法退出现役的警官、警士和义务兵等人员，适用本条例。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021047, '《退役军人就业创业促进条例》', '第四十八条', '劳动', '行政法规', NULL, '国务院 2026-06-26', '第六章 附 则', NULL, '本条例自2026年8月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103500, '《使用有毒物品作业场所劳动保护条例》', '第一条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第一章 总 则', NULL, '为了保证作业场所安全使用有毒物品，预防、控制和消除职业中毒危害，保护劳动者的生命安全、身体健康及其相关权益，根据职业病防治法和其他有关法律、行政法规的规定，制定本条例。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103501, '《使用有毒物品作业场所劳动保护条例》', '第二条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第一章 总 则', NULL, '作业场所使用有毒物品可能产生职业中毒危害的劳动保护，适用本条例。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103502, '《使用有毒物品作业场所劳动保护条例》', '第三条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第一章 总 则', NULL, '按照有毒物品产生的职业中毒危害程度，有毒物品分为一般有毒物品和高毒物品。国家对作业场所使用高毒物品实行特殊管理。 一般有毒物品目录、高毒物品目录由国务院卫生行政部门会同有关部门依据国家标准制定、调整并公布。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103503, '《使用有毒物品作业场所劳动保护条例》', '第四条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第一章 总 则', NULL, '从事使用有毒物品作业的用人单位（以下简称用人单位）应当使用符合国家标准的有毒物品，不得在作业场所使用国家明令禁止使用的有毒物品或者使用不符合国家标准的有毒物品。 用人单位应当尽可能使用无毒物品；需要使用有毒物品的，应当优先选择使用低毒物品。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103504, '《使用有毒物品作业场所劳动保护条例》', '第五条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第一章 总 则', NULL, '用人单位应当依照本条例和其他有关法律、行政法规的规定，采取有效的防护措施，预防职业中毒事故的发生，依法参加工伤保险，保障劳动者的生命安全和身体健康。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103505, '《使用有毒物品作业场所劳动保护条例》', '第六条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第一章 总 则', NULL, '国家鼓励研制、开发、推广、应用有利于预防、控制、消除职业中毒危害和保护劳动者健康的新技术、新工艺、新材料；限制使用或者淘汰有关职业中毒危害严重的技术、工艺、材料；加强对有关职业病的机理和发生规律的基础研究，提高有关职业病防治科学技术水平。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103506, '《使用有毒物品作业场所劳动保护条例》', '第七条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第一章 总 则', NULL, '禁止使用童工。 用人单位不得安排未成年人和孕期、哺乳期的女职工从事使用有毒物品的作业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103507, '《使用有毒物品作业场所劳动保护条例》', '第八条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第一章 总 则', NULL, '工会组织应当督促并协助用人单位开展职业卫生宣传教育和培训，对用人单位的职业卫生工作提出意见和建议，与用人单位就劳动者反映的职业病防治问题进行协调并督促解决。 工会组织对用人单位违反法律、法规，侵犯劳动者合法权益的行为，有权要求纠正；产生严重职业中毒危害时，有权要求用人单位采取防护措施，或者向政府有关部门建议采取强制性措施；发生职业中毒事故时，有权参与事故调查处理；发现危及劳动者生命、健康的情形时，有权建议用人单位组织劳动者撤离危险现场，用人单位应当立即作出处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103508, '《使用有毒物品作业场所劳动保护条例》', '第九条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第一章 总 则', NULL, '县级以上人民政府卫生行政、疾病预防控制部门及其他有关行政部门应当依据各自的职责，监督用人单位严格遵守本条例和其他有关法律、法规的规定，加强作业场所使用有毒物品的劳动保护，防止职业中毒事故发生，确保劳动者依法享有的权利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103509, '《使用有毒物品作业场所劳动保护条例》', '第十条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第一章 总 则', NULL, '各级人民政府应当加强对使用有毒物品作业场所职业卫生安全及相关劳动保护工作的领导，督促、支持卫生行政、疾病预防控制部门及其他有关行政部门依法履行监督检查职责，及时协调、解决有关重大问题；在发生职业中毒事故时，应当采取有效措施，控制事故危害的蔓延并消除事故危害，并妥善处理有关善后工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103510, '《使用有毒物品作业场所劳动保护条例》', '第十一条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第二章 作业场所的预防措施', NULL, '用人单位的设立，应当符合有关法律、行政法规规定的设立条件，并依法办理有关手续，取得营业执照。 用人单位的使用有毒物品作业场所，除应当符合职业病防治法规定的职业卫生要求外，还必须符合下列要求： （一）作业场所与生活场所分开，作业场所不得住人； （二）有害作业与无害作业分开，高毒作业场所与其他作业场所隔离； （三）设置有效的通风装置；可能突然泄漏大量有毒物品或者易造成急性中毒的作业场所，设置自动报警装置和事故通风设施； （四）高毒作业场所设置应急撤离通道和必要的泄险区。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103511, '《使用有毒物品作业场所劳动保护条例》', '第十二条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第二章 作业场所的预防措施', NULL, '使用有毒物品作业场所应当设置黄色区域警示线、警示标识和中文警示说明。警示说明应当载明产生职业中毒危害的种类、后果、预防以及应急救治措施等内容。 高毒作业场所应当设置红色区域警示线、警示标识和中文警示说明，并设置通讯报警设备。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103512, '《使用有毒物品作业场所劳动保护条例》', '第十三条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第二章 作业场所的预防措施', NULL, '新建、扩建、改建的建设项目和技术改造、技术引进项目（以下统称建设项目），可能产生职业中毒危害的，应当依照职业病防治法的规定进行职业中毒危害预评价；可能产生职业中毒危害的建设项目的职业中毒危害防护设施应当与主体工程同时设计，同时施工，同时投入生产和使用；建设项目竣工验收前，应当进行职业中毒危害控制效果评价；建设项目的职业中毒危害防护设施经依法组织验收合格后，方可投入生产和使用。 可能产生职业中毒危害的建设项目的职业中毒危害防护设施设计应当符合国家职业卫生标准和卫生要求。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103513, '《使用有毒物品作业场所劳动保护条例》', '第十四条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第二章 作业场所的预防措施', NULL, '用人单位应当按照国务院卫生行政部门的规定，向卫生行政部门及时、如实申报存在职业中毒危害项目。 从事使用高毒物品作业的用人单位，在申报使用高毒物品作业项目时，应当向卫生行政部门提交下列有关资料： （一）职业中毒危害控制效果评价报告； （二）职业卫生管理制度和操作规程等材料； （三）职业中毒事故应急救援预案。 从事使用高毒物品作业的用人单位变更所使用的高毒物品品种的，应当依照前款规定向原受理申报的卫生行政部门重新申报。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103514, '《使用有毒物品作业场所劳动保护条例》', '第十五条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第二章 作业场所的预防措施', NULL, '用人单位变更名称、法定代表人或者负责人的，应当向原受理申报的卫生行政部门备案。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103515, '《使用有毒物品作业场所劳动保护条例》', '第十六条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第二章 作业场所的预防措施', NULL, '从事使用高毒物品作业的用人单位，应当配备应急救援人员和必要的应急救援器材、设备，制定事故应急救援预案，并根据实际情况变化对应急救援预案适时进行修订，定期组织演练。事故应急救援预案和演练记录应当报当地卫生行政部门、应急管理部门和公安部门备案。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103516, '《使用有毒物品作业场所劳动保护条例》', '第十七条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第三章 劳动过程的防护', NULL, '用人单位应当依照职业病防治法的有关规定，采取有效的职业卫生防护管理措施，加强劳动过程中的防护与管理。 从事使用高毒物品作业的用人单位，应当配备专职的或者兼职的职业卫生医师和护士；不具备配备专职的或者兼职的职业卫生医师和护士条件的，应当与依法取得资质认证的职业卫生技术服务机构签订合同，由其提供职业卫生服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103517, '《使用有毒物品作业场所劳动保护条例》', '第十八条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第三章 劳动过程的防护', NULL, '用人单位应当与劳动者订立劳动合同，将工作过程中可能产生的职业中毒危害及其后果、职业中毒危害防护措施和待遇等如实告知劳动者，并在劳动合同中写明，不得隐瞒或者欺骗。 劳动者在已订立劳动合同期间因工作岗位或者工作内容变更，从事劳动合同中未告知的存在职业中毒危害的作业时，用人单位应当依照前款规定，如实告知劳动者，并协商变更原劳动合同有关条款。 用人单位违反前两款规定的，劳动者有权拒绝从事存在职业中毒危害的作业，用人单位不得因此单方面解除或者终止与劳动者所订立的劳动合同。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103518, '《使用有毒物品作业场所劳动保护条例》', '第十九条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第三章 劳动过程的防护', NULL, '用人单位有关管理人员应当熟悉有关职业病防治的法律、法规以及确保劳动者安全使用有毒物品作业的知识。 用人单位应当对劳动者进行上岗前的职业卫生培训和在岗期间的定期职业卫生培训，普及有关职业卫生知识，督促劳动者遵守有关法律、法规和操作规程，指导劳动者正确使用职业中毒危害防护设备和个人使用的职业中毒危害防护用品。 劳动者经培训考核合格，方可上岗作业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103519, '《使用有毒物品作业场所劳动保护条例》', '第二十条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第三章 劳动过程的防护', NULL, '用人单位应当确保职业中毒危害防护设备、应急救援设施、通讯报警装置处于正常适用状态，不得擅自拆除或者停止运行。 用人单位应当对前款所列设施进行经常性的维护、检修，定期检测其性能和效果，确保其处于良好运行状态。 职业中毒危害防护设备、应急救援设施和通讯报警装置处于不正常状态时，用人单位应当立即停止使用有毒物品作业；恢复正常状态后，方可重新作业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103520, '《使用有毒物品作业场所劳动保护条例》', '第二十一条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第三章 劳动过程的防护', NULL, '用人单位应当为从事使用有毒物品作业的劳动者提供符合国家职业卫生标准的防护用品，并确保劳动者正确使用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103521, '《使用有毒物品作业场所劳动保护条例》', '第二十二条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第三章 劳动过程的防护', NULL, '有毒物品必须附具说明书，如实载明产品特性、主要成分、存在的职业中毒危害因素、可能产生的危害后果、安全使用注意事项、职业中毒危害防护以及应急救治措施等内容；没有说明书或者说明书不符合要求的，不得向用人单位销售。 用人单位有权向生产、经营有毒物品的单位索取说明书。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103522, '《使用有毒物品作业场所劳动保护条例》', '第二十三条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第三章 劳动过程的防护', NULL, '有毒物品的包装应当符合国家标准，并以易于劳动者理解的方式加贴或者拴挂有毒物品安全标签。有毒物品的包装必须有醒目的警示标识和中文警示说明。 经营、使用有毒物品的单位，不得经营、使用没有安全标签、警示标识和中文警示说明的有毒物品。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103523, '《使用有毒物品作业场所劳动保护条例》', '第二十四条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第三章 劳动过程的防护', NULL, '用人单位维护、检修存在高毒物品的生产装置，必须事先制订维护、检修方案，明确职业中毒危害防护措施，确保维护、检修人员的生命安全和身体健康。 维护、检修存在高毒物品的生产装置，必须严格按照维护、检修方案和操作规程进行。维护、检修现场应当有专人监护，并设置警示标志。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103524, '《使用有毒物品作业场所劳动保护条例》', '第二十五条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第三章 劳动过程的防护', NULL, '需要进入存在高毒物品的设备、容器或者狭窄封闭场所作业时，用人单位应当事先采取下列措施： （一）保持作业场所良好的通风状态，确保作业场所职业中毒危害因素浓度符合国家职业卫生标准； （二）为劳动者配备符合国家职业卫生标准的防护用品； （三）设置现场监护人员和现场救援设备。 未采取前款规定措施或者采取的措施不符合要求的，用人单位不得安排劳动者进入存在高毒物品的设备、容器或者狭窄封闭场所作业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103525, '《使用有毒物品作业场所劳动保护条例》', '第二十六条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第三章 劳动过程的防护', NULL, '用人单位应当按照国务院卫生行政部门的规定，定期对使用有毒物品作业场所职业中毒危害因素进行检测、评价。检测、评价结果存入用人单位职业卫生档案，定期向所在地卫生行政部门报告并向劳动者公布。 从事使用高毒物品作业的用人单位应当至少每一个月对高毒作业场所进行一次职业中毒危害因素检测；至少每半年进行一次职业中毒危害控制效果评价。 高毒作业场所职业中毒危害因素不符合国家职业卫生标准和卫生要求时，用人单位必须立即停止高毒作业，并采取相应的治理措施；经治理，职业中毒危害因素符合国家职业卫生标准和卫生要求的，方可重新作业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103526, '《使用有毒物品作业场所劳动保护条例》', '第二十七条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第三章 劳动过程的防护', NULL, '从事使用高毒物品作业的用人单位应当设置淋浴间和更衣室，并设置清洗、存放或者处理从事使用高毒物品作业劳动者的工作服、工作鞋帽等物品的专用间。 劳动者结束作业时，其使用的工作服、工作鞋帽等物品必须存放在高毒作业区域内，不得穿戴到非高毒作业区域。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103527, '《使用有毒物品作业场所劳动保护条例》', '第二十八条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第三章 劳动过程的防护', NULL, '用人单位应当按照规定对从事使用高毒物品作业的劳动者进行岗位轮换。 用人单位应当为从事使用高毒物品作业的劳动者提供岗位津贴。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103528, '《使用有毒物品作业场所劳动保护条例》', '第二十九条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第三章 劳动过程的防护', NULL, '用人单位转产、停产、停业或者解散、破产的，应当采取有效措施，妥善处理留存或者残留有毒物品的设备、包装物和容器。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103529, '《使用有毒物品作业场所劳动保护条例》', '第三十条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第三章 劳动过程的防护', NULL, '用人单位应当对本单位执行本条例规定的情况进行经常性的监督检查；发现问题，应当及时依照本条例规定的要求进行处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103530, '《使用有毒物品作业场所劳动保护条例》', '第三十一条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第四章 职业健康监护', NULL, '用人单位应当组织从事使用有毒物品作业的劳动者进行上岗前职业健康检查。 用人单位不得安排未经上岗前职业健康检查的劳动者从事使用有毒物品的作业，不得安排有职业禁忌的劳动者从事其所禁忌的作业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103531, '《使用有毒物品作业场所劳动保护条例》', '第三十二条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第四章 职业健康监护', NULL, '用人单位应当对从事使用有毒物品作业的劳动者进行定期职业健康检查。 用人单位发现有职业禁忌或者有与所从事职业相关的健康损害的劳动者，应当将其及时调离原工作岗位，并妥善安置。 用人单位对需要复查和医学观察的劳动者，应当按照体检机构的要求安排其复查和医学观察。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103532, '《使用有毒物品作业场所劳动保护条例》', '第三十三条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第四章 职业健康监护', NULL, '用人单位应当对从事使用有毒物品作业的劳动者进行离岗时的职业健康检查；对离岗时未进行职业健康检查的劳动者，不得解除或者终止与其订立的劳动合同。 用人单位发生分立、合并、解散、破产等情形的，应当对从事使用有毒物品作业的劳动者进行健康检查，并按照国家有关规定妥善安置职业病病人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103533, '《使用有毒物品作业场所劳动保护条例》', '第三十四条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第四章 职业健康监护', NULL, '用人单位对受到或者可能受到急性职业中毒危害的劳动者，应当及时组织进行健康检查和医学观察。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103534, '《使用有毒物品作业场所劳动保护条例》', '第三十五条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第四章 职业健康监护', NULL, '劳动者职业健康检查和医学观察的费用，由用人单位承担。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103535, '《使用有毒物品作业场所劳动保护条例》', '第三十六条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第四章 职业健康监护', NULL, '用人单位应当建立职业健康监护档案。 职业健康监护档案应当包括下列内容： （一）劳动者的职业史和职业中毒危害接触史； （二）相应作业场所职业中毒危害因素监测结果； （三）职业健康检查结果及处理情况； （四）职业病诊疗等劳动者健康资料。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103536, '《使用有毒物品作业场所劳动保护条例》', '第三十七条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第五章 劳动者的权利与义务', NULL, '从事使用有毒物品作业的劳动者在存在威胁生命安全或者身体健康危险的情况下，有权通知用人单位并从使用有毒物品造成的危险现场撤离。 用人单位不得因劳动者依据前款规定行使权利，而取消或者减少劳动者在正常工作时享有的工资、福利待遇。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103537, '《使用有毒物品作业场所劳动保护条例》', '第三十八条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第五章 劳动者的权利与义务', NULL, '劳动者享有下列职业卫生保护权利： （一）获得职业卫生教育、培训； （二）获得职业健康检查、职业病诊疗、康复等职业病防治服务； （三）了解工作场所产生或者可能产生的职业中毒危害因素、危害后果和应当采取的职业中毒危害防护措施； （四）要求用人单位提供符合防治职业病要求的职业中毒危害防护设施和个人使用的职业中毒危害防护用品，改善工作条件； （五）对违反职业病防治法律、法规，危及生命、健康的行为提出批评、检举和控告； （六）拒绝违章指挥和强令进行没有职业中毒危害防护措施的作业； （七）参与用人单位职业卫生工作的民主管理，对职业病防治工作提出意见和建议。 用人单位应当保障劳动者行使前款所列权利。禁止因劳动者依法行使正当权利而降低其工资、福利等待遇或者解除、终止与其订立的劳动合同。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103538, '《使用有毒物品作业场所劳动保护条例》', '第三十九条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第五章 劳动者的权利与义务', NULL, '劳动者有权在正式上岗前从用人单位获得下列资料： （一）作业场所使用的有毒物品的特性、有害成分、预防措施、教育和培训资料； （二）有毒物品的标签、标识及有关资料； （三）有毒物品安全使用说明书； （四）可能影响安全使用有毒物品的其他有关资料。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103539, '《使用有毒物品作业场所劳动保护条例》', '第四十条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第五章 劳动者的权利与义务', NULL, '劳动者有权查阅、复印其本人职业健康监护档案。 劳动者离开用人单位时，有权索取本人健康监护档案复印件；用人单位应当如实、无偿提供，并在所提供的复印件上签章。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103540, '《使用有毒物品作业场所劳动保护条例》', '第四十一条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第五章 劳动者的权利与义务', NULL, '用人单位按照国家规定参加工伤保险的，患职业病的劳动者有权按照国家有关工伤保险的规定，享受下列工伤保险待遇： （一）医疗费：因患职业病进行诊疗所需费用，由工伤保险基金按照规定标准支付； （二）住院伙食补助费：由用人单位按照当地因公出差伙食标准的一定比例支付； （三）康复费：由工伤保险基金按照规定标准支付； （四）残疾用具费：因残疾需要配置辅助器具的，所需费用由工伤保险基金按照普及型辅助器具标准支付； （五）停工留薪期待遇：原工资、福利待遇不变，由用人单位支付； （六）生活护理补助费：经评残并确认需要生活护理的，生活护理补助费由工伤保险基金按照规定标准支付； （七）一次性伤残补助金：经鉴定为十级至一级伤残的，按照伤残等级享受相当于6个月至24个月的本人工资的一次性伤残补助金，由工伤保险基金支付； （八）伤残津贴：经鉴定为四级至一级伤残的，按照规定享受相当于本人工资75%至90%的伤残津贴，由工伤保险基金支付； （九）死亡补助金：因职业中毒死亡的，由工伤保险基金按照不低于48个月的统筹地区上年度职工月平均工资的标准一次支付； （十）丧葬补助金：因职业中毒死亡的，由工伤保险基金按照6个月的统筹地区上年度职工月平均工资的标准一次支付； （十一）供养亲属抚恤金：因职业中毒死亡的，对由死者生前提供主要生活来源的亲属由工伤保险基金支付抚恤金：对其配偶每月按照统筹地区上年度职工月平均工资的40%发给，对其生前供养的直系亲属每人每月按照统筹地区上年度职工月平均工资的30%发给； （十二）国家规定的其他工伤保险待遇。 本条例施行后，国家对工伤保险待遇的项目和标准作出调整时，从其规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103541, '《使用有毒物品作业场所劳动保护条例》', '第四十二条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第五章 劳动者的权利与义务', NULL, '用人单位未参加工伤保险的，其劳动者从事有毒物品作业患职业病的，用人单位应当按照国家有关工伤保险规定的项目和标准，保证劳动者享受工伤待遇。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103542, '《使用有毒物品作业场所劳动保护条例》', '第四十三条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第五章 劳动者的权利与义务', NULL, '用人单位无营业执照以及被依法吊销营业执照，其劳动者从事使用有毒物品作业患职业病的，应当按照国家有关工伤保险规定的项目和标准，给予劳动者一次性赔偿。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103543, '《使用有毒物品作业场所劳动保护条例》', '第四十四条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第五章 劳动者的权利与义务', NULL, '用人单位分立、合并的，承继单位应当承担由原用人单位对患职业病的劳动者承担的补偿责任。 用人单位解散、破产的，应当依法从其清算财产中优先支付患职业病的劳动者的补偿费用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103544, '《使用有毒物品作业场所劳动保护条例》', '第四十五条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第五章 劳动者的权利与义务', NULL, '劳动者除依法享有工伤保险外，依照有关民事法律的规定，尚有获得赔偿的权利的，有权向用人单位提出赔偿要求。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103545, '《使用有毒物品作业场所劳动保护条例》', '第四十六条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第五章 劳动者的权利与义务', NULL, '劳动者应当学习和掌握相关职业卫生知识，遵守有关劳动保护的法律、法规和操作规程，正确使用和维护职业中毒危害防护设施及其用品；发现职业中毒事故隐患时，应当及时报告。 作业场所出现使用有毒物品产生的危险时，劳动者应当采取必要措施，按照规定正确使用防护设施，将危险加以消除或者减少到最低限度。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103546, '《使用有毒物品作业场所劳动保护条例》', '第四十七条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第六章 监督管理', NULL, '县级以上人民政府卫生行政、疾病预防控制部门应当依照本条例的规定和国家有关职业卫生要求，依据职责划分，对作业场所使用有毒物品作业及职业中毒危害检测、评价活动进行监督检查。 卫生行政、疾病预防控制部门实施监督检查，不得收取费用，不得接受用人单位的财物或者其他利益。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103547, '《使用有毒物品作业场所劳动保护条例》', '第四十八条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第六章 监督管理', NULL, '卫生行政、疾病预防控制部门应当建立、健全监督制度，核查反映用人单位有关劳动保护的材料，履行监督责任。 用人单位应当向卫生行政、疾病预防控制部门如实、具体提供反映有关劳动保护的材料；必要时，卫生行政、疾病预防控制部门可以查阅或者要求用人单位报送有关材料。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103548, '《使用有毒物品作业场所劳动保护条例》', '第四十九条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第六章 监督管理', NULL, '卫生行政、疾病预防控制部门应当监督用人单位严格执行有关职业卫生规范。 卫生行政、疾病预防控制部门应当依照本条例的规定对使用有毒物品作业场所的职业卫生防护设备、设施的防护性能进行定期检验和不定期的抽查；发现职业卫生防护设备、设施存在隐患时，应当责令用人单位立即消除隐患；消除隐患期间，应当责令其停止作业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103549, '《使用有毒物品作业场所劳动保护条例》', '第五十条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第六章 监督管理', NULL, '卫生行政、疾病预防控制部门应当采取措施，鼓励对用人单位的违法行为进行举报、投诉、检举和控告。 卫生行政、疾病预防控制部门对举报、投诉、检举和控告应当及时核实，依法作出处理，并将处理结果予以公布。 卫生行政、疾病预防控制部门对举报人、投诉人、检举人和控告人负有保密的义务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103550, '《使用有毒物品作业场所劳动保护条例》', '第五十一条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第六章 监督管理', NULL, '职业卫生监督执法人员依法执行职务时，应当出示执法证件。 职业卫生监督执法人员应当忠于职守，秉公执法；涉及用人单位秘密的，应当为其保密。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103551, '《使用有毒物品作业场所劳动保护条例》', '第五十二条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第六章 监督管理', NULL, '疾病预防控制部门依法实施罚款的行政处罚，应当依照有关法律、行政法规的规定，实施罚款决定与罚款收缴分离；收缴的罚款以及依法没收的经营所得，必须全部上缴国库。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103552, '《使用有毒物品作业场所劳动保护条例》', '第五十三条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第六章 监督管理', NULL, '卫生行政、疾病预防控制部门履行监督检查职责时，有权采取下列措施： （一）进入用人单位和使用有毒物品作业场所现场，了解情况，调查取证，进行抽样检查、检测、检验，进行实地检查； （二）查阅或者复制与违反本条例行为有关的资料，采集样品； （三）责令违反本条例规定的单位和个人停止违法行为。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103553, '《使用有毒物品作业场所劳动保护条例》', '第五十四条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第六章 监督管理', NULL, '发生职业中毒事故或者有证据证明职业中毒危害状态可能导致事故发生时，卫生行政、疾病预防控制部门有权采取下列临时控制措施： （一）责令暂停导致职业中毒事故的作业； （二）封存造成职业中毒事故或者可能导致事故发生的物品； （三）组织控制职业中毒事故现场。 在职业中毒事故或者危害状态得到有效控制后，卫生行政、疾病预防控制部门应当及时解除控制措施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103554, '《使用有毒物品作业场所劳动保护条例》', '第五十五条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第六章 监督管理', NULL, '职业卫生监督执法人员依法执行职务时，被检查单位应当接受检查并予以支持、配合，不得拒绝和阻碍。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103555, '《使用有毒物品作业场所劳动保护条例》', '第五十六条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第六章 监督管理', NULL, '疾病预防控制部门应当加强队伍建设，提高职业卫生监督执法人员的政治、业务素质，依照本条例的规定，建立、健全内部监督制度，对职业卫生监督执法人员执行法律、法规和遵守纪律的情况进行监督检查。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103556, '《使用有毒物品作业场所劳动保护条例》', '第五十七条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第七章 罚 则', NULL, '卫生行政、疾病预防控制部门的工作人员有下列行为之一，导致职业中毒事故发生的，依照刑法关于滥用职权罪、玩忽职守罪或者其他罪的规定，依法追究刑事责任；造成职业中毒危害但尚未导致职业中毒事故发生，不够刑事处罚的，根据不同情节，依法给予降级、撤职或者开除的处分： （一）对用人单位不履行监督检查职责，或者发现用人单位存在违反本条例的行为不予查处的； （二）发现用人单位存在职业中毒危害，可能造成职业中毒事故，不及时依法采取控制措施的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103557, '《使用有毒物品作业场所劳动保护条例》', '第五十八条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第七章 罚 则', NULL, '用人单位违反本条例的规定，有下列情形之一的，由疾病预防控制部门给予警告，责令限期改正；逾期不改正的，处10万元以上50万元以下的罚款；情节严重的，提请有关人民政府按照国务院规定的权限责令停建、予以关闭；造成严重职业中毒危害或者导致职业中毒事故发生的，对负有责任的主管人员和其他直接责任人员依照刑法关于重大劳动安全事故罪或者其他罪的规定，依法追究刑事责任： （一）可能产生职业中毒危害的建设项目，未依照职业病防治法的规定进行职业中毒危害预评价的； （二）职业中毒危害防护设施未与主体工程同时设计，同时施工，同时投入生产和使用的； （三）建设项目竣工验收前，未进行职业中毒危害控制效果评价，或者职业中毒危害防护设施未经依法组织验收合格，擅自投入生产和使用的； （四）可能产生职业中毒危害的建设项目，其职业中毒危害防护设施设计不符合国家职业卫生标准和卫生要求的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103558, '《使用有毒物品作业场所劳动保护条例》', '第五十九条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第七章 罚 则', NULL, '用人单位违反本条例的规定，有下列情形之一的，由疾病预防控制部门给予警告，责令限期改正；逾期不改正的，处5万元以上20万元以下的罚款；情节严重的，提请有关人民政府按照国务院规定的权限予以关闭；造成严重职业中毒危害或者导致职业中毒事故发生的，对负有责任的主管人员和其他直接责任人员依照刑法关于重大劳动安全事故罪或者其他罪的规定，依法追究刑事责任： （一）使用有毒物品作业场所未按照规定设置警示标识和中文警示说明的； （二）未对职业卫生防护设备、应急救援设施、通讯报警装置进行维护、检修和定期检测，导致上述设施处于不正常状态的； （三）未依照本条例的规定进行职业中毒危害因素检测和职业中毒危害控制效果评价的； （四）未向从事使用有毒物品作业的劳动者提供符合国家职业卫生标准的防护用品，或者未保证劳动者正确使用的。 用人单位违反本条例的规定，有下列情形之一的，由疾病预防控制部门给予警告，责令限期改正，处5万元以上20万元以下的罚款；逾期不改正的，提请有关人民政府按照国务院规定的权限予以关闭；造成严重职业中毒危害或者导致职业中毒事故发生的，对负有责任的主管人员和其他直接责任人员依照刑法关于重大劳动安全事故罪或者其他罪的规定，依法追究刑事责任： （一）高毒作业场所未按照规定设置撤离通道和泄险区的； （二）高毒作业场所未按照规定设置警示线的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103559, '《使用有毒物品作业场所劳动保护条例》', '第六十条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第七章 罚 则', NULL, '用人单位违反本条例的规定，有下列情形之一的，由疾病预防控制部门给予警告，责令限期改正，处5万元以上30万元以下的罚款；逾期不改正的，提请有关人民政府按照国务院规定的权限予以关闭；造成严重职业中毒危害或者导致职业中毒事故发生的，对负有责任的主管人员和其他直接责任人员依照刑法关于重大责任事故罪、重大劳动安全事故罪或者其他罪的规定，依法追究刑事责任： （一）使用有毒物品作业场所未设置有效通风装置的，或者可能突然泄漏大量有毒物品或者易造成急性中毒的作业场所未设置自动报警装置或者事故通风设施的； （二）职业卫生防护设备、应急救援设施、通讯报警装置处于不正常状态而不停止作业，或者擅自拆除或者停止运行职业卫生防护设备、应急救援设施、通讯报警装置的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103560, '《使用有毒物品作业场所劳动保护条例》', '第六十一条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第七章 罚 则', NULL, '从事使用高毒物品作业的用人单位违反本条例的规定，有下列行为之一的，由疾病预防控制部门给予警告，责令限期改正，处5万元以上20万元以下的罚款；逾期不改正的，提请有关人民政府按照国务院规定的权限予以关闭；造成严重职业中毒危害或者导致职业中毒事故发生的，对负有责任的主管人员和其他直接责任人员依照刑法关于重大责任事故罪或者其他罪的规定，依法追究刑事责任： （一）作业场所职业中毒危害因素不符合国家职业卫生标准和卫生要求而不立即停止高毒作业并采取相应的治理措施的，或者职业中毒危害因素治理不符合国家职业卫生标准和卫生要求重新作业的； （二）未依照本条例的规定维护、检修存在高毒物品的生产装置的； （三）未采取本条例规定的措施，安排劳动者进入存在高毒物品的设备、容器或者狭窄封闭场所作业的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103561, '《使用有毒物品作业场所劳动保护条例》', '第六十二条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第七章 罚 则', NULL, '在作业场所使用国家明令禁止使用的有毒物品或者使用不符合国家标准的有毒物品的，由疾病预防控制部门责令立即停止使用，处5万元以上30万元以下的罚款；情节严重的，责令停止使用有毒物品作业，或者提请有关人民政府按照国务院规定的权限予以关闭；造成严重职业中毒危害或者导致职业中毒事故发生的，对负有责任的主管人员和其他直接责任人员依照刑法关于危险物品肇事罪、重大责任事故罪或者其他罪的规定，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103562, '《使用有毒物品作业场所劳动保护条例》', '第六十三条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第七章 罚 则', NULL, '用人单位违反本条例的规定，有下列行为之一的，由疾病预防控制部门责令限期改正，处5万元以上30万元以下的罚款；情节严重的，责令停止使用有毒物品作业，或者提请有关人民政府按照国务院规定的权限予以关闭；造成严重职业中毒危害或者导致职业中毒事故发生的，对负有责任的主管人员和其他直接责任人员依照刑法关于重大责任事故罪或者其他罪的规定，依法追究刑事责任： （一）未组织从事使用有毒物品作业的劳动者进行上岗前职业健康检查，安排未经上岗前职业健康检查的劳动者从事使用有毒物品作业的； （二）使用未经培训考核合格的劳动者从事高毒作业的； （三）安排有职业禁忌的劳动者从事所禁忌的作业的； （四）发现有职业禁忌或者有与所从事职业相关的健康损害的劳动者，未及时调离原工作岗位，并妥善安置的； （五）安排未成年人或者孕期、哺乳期的女职工从事使用有毒物品作业的； （六）使用童工的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103563, '《使用有毒物品作业场所劳动保护条例》', '第六十四条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第七章 罚 则', NULL, '从事使用有毒物品作业的用人单位违反本条例的规定，在转产、停产、停业或者解散、破产时未采取有效措施，妥善处理留存或者残留高毒物品的设备、包装物和容器的，由疾病预防控制部门责令改正，处2万元以上10万元以下的罚款；触犯刑律的，对负有责任的主管人员和其他直接责任人员依照刑法关于污染环境罪、危险物品肇事罪或者其他罪的规定，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103564, '《使用有毒物品作业场所劳动保护条例》', '第六十五条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第七章 罚 则', NULL, '用人单位违反本条例的规定，有下列情形之一的，由疾病预防控制部门给予警告，责令限期改正，处5000元以上2万元以下的罚款；逾期不改正的，责令停止使用有毒物品作业，或者提请有关人民政府按照国务院规定的权限予以关闭；造成严重职业中毒危害或者导致职业中毒事故发生的，对负有责任的主管人员和其他直接责任人员依照刑法关于重大劳动安全事故罪、危险物品肇事罪或者其他罪的规定，依法追究刑事责任： （一）使用有毒物品作业场所未与生活场所分开或者在作业场所住人的； （二）未将有害作业与无害作业分开的； （三）高毒作业场所未与其他作业场所有效隔离的； （四）从事高毒作业未按照规定配备应急救援设施或者制定事故应急救援预案的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103565, '《使用有毒物品作业场所劳动保护条例》', '第六十六条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第七章 罚 则', NULL, '用人单位违反本条例的规定，有下列情形之一的，由疾病预防控制部门给予警告，责令限期改正，处2万元以上5万元以下的罚款；逾期不改正的，提请有关人民政府按照国务院规定的权限予以关闭： （一）未按照规定向卫生行政部门申报高毒作业项目的； （二）变更使用高毒物品品种，未按照规定向原受理申报的卫生行政部门重新申报，或者申报不及时、有虚假的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103566, '《使用有毒物品作业场所劳动保护条例》', '第六十七条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第七章 罚 则', NULL, '用人单位违反本条例的规定，有下列行为之一的，由疾病预防控制部门给予警告，责令限期改正，可以并处5万元以上10万元以下的罚款；逾期不改正的，责令停止使用有毒物品作业，或者提请有关人民政府按照国务院规定的权限予以关闭： （一）未组织从事使用有毒物品作业的劳动者进行定期职业健康检查的； （二）未组织从事使用有毒物品作业的劳动者进行离岗职业健康检查的； （三）对未进行离岗职业健康检查的劳动者，解除或者终止与其订立的劳动合同的； （四）发生分立、合并、解散、破产情形，未对从事使用有毒物品作业的劳动者进行健康检查，并按照国家有关规定妥善安置职业病病人的； （五）对受到或者可能受到急性职业中毒危害的劳动者，未及时组织进行健康检查和医学观察的； （六）未建立职业健康监护档案的； （七）劳动者离开用人单位时，用人单位未如实、无偿提供职业健康监护档案的； （八）未依照职业病防治法和本条例的规定将工作过程中可能产生的职业中毒危害及其后果、有关职业卫生防护措施和待遇等如实告知劳动者并在劳动合同中写明的； （九）劳动者在存在威胁生命、健康危险的情况下，从危险现场中撤离，而被取消或者减少应当享有的待遇的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103567, '《使用有毒物品作业场所劳动保护条例》', '第六十八条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第七章 罚 则', NULL, '用人单位违反本条例的规定，有下列行为之一的，由疾病预防控制部门给予警告，责令限期改正，处5000元以上2万元以下的罚款；逾期不改正的，责令停止使用有毒物品作业，或者提请有关人民政府按照国务院规定的权限予以关闭： （一）未按照规定配备或者聘请职业卫生医师和护士的； （二）未为从事使用高毒物品作业的劳动者设置淋浴间、更衣室或者未设置清洗、存放和处理工作服、工作鞋帽等物品的专用间，或者不能正常使用的； （三）未安排从事使用高毒物品作业一定年限的劳动者进行岗位轮换的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103568, '《使用有毒物品作业场所劳动保护条例》', '第六十九条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第八章 附 则', NULL, '涉及作业场所使用有毒物品可能产生职业中毒危害的劳动保护的有关事项，本条例未作规定的，依照职业病防治法和其他有关法律、行政法规的规定执行。 有毒物品的生产、经营、储存、运输、使用和废弃处置的安全管理，依照危险化学品安全管理条例执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2103569, '《使用有毒物品作业场所劳动保护条例》', '第七十条', '劳动', '行政法规', NULL, '国务院 2024-12-06', '第八章 附 则', NULL, '本条例自公布之日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172500, '《社会保险经办条例》', '第一条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第一章 总 则', NULL, '为了规范社会保险经办，优化社会保险服务，保障社会保险基金安全，维护用人单位和个人的合法权益，促进社会公平，根据《中华人民共和国社会保险法》，制定本条例。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172501, '《社会保险经办条例》', '第二条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第一章 总 则', NULL, '经办基本养老保险、基本医疗保险、工伤保险、失业保险、生育保险等国家规定的社会保险，适用本条例。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172502, '《社会保险经办条例》', '第三条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第一章 总 则', NULL, '社会保险经办工作坚持中国共产党的领导，坚持以人民为中心，遵循合法、便民、及时、公开、安全的原则。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172503, '《社会保险经办条例》', '第四条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第一章 总 则', NULL, '国务院人力资源社会保障行政部门主管全国基本养老保险、工伤保险、失业保险等社会保险经办工作。国务院医疗保障行政部门主管全国基本医疗保险、生育保险等社会保险经办工作。 县级以上地方人民政府人力资源社会保障行政部门按照统筹层次主管基本养老保险、工伤保险、失业保险等社会保险经办工作。县级以上地方人民政府医疗保障行政部门按照统筹层次主管基本医疗保险、生育保险等社会保险经办工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172504, '《社会保险经办条例》', '第五条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第一章 总 则', NULL, '国务院人力资源社会保障行政部门、医疗保障行政部门以及其他有关部门按照各自职责，密切配合、相互协作，共同做好社会保险经办工作。 县级以上地方人民政府应当加强对本行政区域社会保险经办工作的领导，加强社会保险经办能力建设，为社会保险经办工作提供保障。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172505, '《社会保险经办条例》', '第六条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第二章 社会保险登记和关系转移', NULL, '用人单位在登记管理机关办理登记时同步办理社会保险登记。 个人申请办理社会保险登记，以公民身份号码作为社会保障号码，取得社会保障卡和医保电子凭证。社会保险经办机构应当自收到申请之日起10个工作日内办理完毕。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172506, '《社会保险经办条例》', '第七条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第二章 社会保险登记和关系转移', NULL, '社会保障卡是个人参加基本养老保险、基本医疗保险、工伤保险、失业保险、生育保险等社会保险和享受各项社会保险待遇的凭证，包括实体社会保障卡和电子社会保障卡。 医保电子凭证是个人参加基本医疗保险、生育保险等社会保险和享受基本医疗保险、生育保险等社会保险待遇的凭证。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172507, '《社会保险经办条例》', '第八条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第二章 社会保险登记和关系转移', NULL, '登记管理机关应当将用人单位设立、变更、注销登记的信息与社会保险经办机构共享，公安、民政、卫生健康、司法行政等部门应当将个人的出生、死亡以及户口登记、迁移、注销等信息与社会保险经办机构共享。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172508, '《社会保险经办条例》', '第九条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第二章 社会保险登记和关系转移', NULL, '用人单位的性质、银行账户、用工等参保信息发生变化，以及个人参保信息发生变化的，用人单位和个人应当及时告知社会保险经办机构。社会保险经办机构应当对用人单位和个人提供的参保信息与共享信息进行比对核实。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172509, '《社会保险经办条例》', '第十条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第二章 社会保险登记和关系转移', NULL, '用人单位和个人申请变更、注销社会保险登记，社会保险经办机构应当自收到申请之日起10个工作日内办理完毕。用人单位注销社会保险登记的，应当先结清欠缴的社会保险费、滞纳金、罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172510, '《社会保险经办条例》', '第十一条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第二章 社会保险登记和关系转移', NULL, '社会保险经办机构应当及时、完整、准确记录下列信息： （一）社会保险登记情况； （二）社会保险费缴纳情况； （三）社会保险待遇享受情况； （四）个人账户情况； （五）与社会保险经办相关的其他情况。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172511, '《社会保险经办条例》', '第十二条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第二章 社会保险登记和关系转移', NULL, '参加职工基本养老保险的个人跨统筹地区就业，其职工基本养老保险关系随同转移。 参加职工基本养老保险的个人在机关事业单位与企业等不同性质用人单位之间流动就业，其职工基本养老保险关系随同转移。 参加城乡居民基本养老保险且未享受待遇的个人跨统筹地区迁移户籍，其城乡居民基本养老保险关系可以随同转移。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172512, '《社会保险经办条例》', '第十三条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第二章 社会保险登记和关系转移', NULL, '参加职工基本医疗保险的个人跨统筹地区就业，其职工基本医疗保险关系随同转移。 参加城乡居民基本医疗保险的个人跨统筹地区迁移户籍或者变动经常居住地，其城乡居民基本医疗保险关系可以按照规定随同转移。 职工基本医疗保险与城乡居民基本医疗保险之间的关系转移，按照规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172513, '《社会保险经办条例》', '第十四条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第二章 社会保险登记和关系转移', NULL, '参加失业保险的个人跨统筹地区就业，其失业保险关系随同转移。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172514, '《社会保险经办条例》', '第十五条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第二章 社会保险登记和关系转移', NULL, '参加工伤保险、生育保险的个人跨统筹地区就业，在新就业地参加工伤保险、生育保险。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172515, '《社会保险经办条例》', '第十六条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第二章 社会保险登记和关系转移', NULL, '用人单位和个人办理社会保险关系转移接续手续的，社会保险经办机构应当在规定时限内办理完毕，并将结果告知用人单位和个人，或者提供办理情况查询服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172516, '《社会保险经办条例》', '第十七条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第二章 社会保险登记和关系转移', NULL, '军事机关和社会保险经办机构，按照各自职责办理军人保险与社会保险关系转移接续手续。 社会保险经办机构应当为军人保险与社会保险关系转移接续手续办理优先提供服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172517, '《社会保险经办条例》', '第十八条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第三章 社会保险待遇核定和支付', NULL, '用人单位和个人应当按照国家规定，向社会保险经办机构提出领取基本养老金的申请。社会保险经办机构应当自收到申请之日起20个工作日内办理完毕。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172518, '《社会保险经办条例》', '第十九条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第三章 社会保险待遇核定和支付', NULL, '参加职工基本养老保险的个人死亡或者失业人员在领取失业保险金期间死亡，其遗属可以依法向社会保险经办机构申领丧葬补助金和抚恤金。社会保险经办机构应当及时核实有关情况，按照规定核定并发放丧葬补助金和抚恤金。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172519, '《社会保险经办条例》', '第二十条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第三章 社会保险待遇核定和支付', NULL, '个人医疗费用、生育医疗费用中应当由基本医疗保险（含生育保险）基金支付的部分，由社会保险经办机构审核后与医疗机构、药品经营单位直接结算。 因特殊情况个人申请手工报销，应当向社会保险经办机构提供医疗机构、药品经营单位的收费票据、费用清单、诊断证明、病历资料。社会保险经办机构应当对收费票据、费用清单、诊断证明、病历资料进行审核，并自收到申请之日起30个工作日内办理完毕。 参加生育保险的个人申领生育津贴，应当向社会保险经办机构提供病历资料。社会保险经办机构应当对病历资料进行审核，并自收到申请之日起10个工作日内办理完毕。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172520, '《社会保险经办条例》', '第二十一条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第三章 社会保险待遇核定和支付', NULL, '工伤职工及其用人单位依法申请劳动能力鉴定、辅助器具配置确认、停工留薪期延长确认、工伤旧伤复发确认，应当向社会保险经办机构提供诊断证明、病历资料。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172521, '《社会保险经办条例》', '第二十二条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第三章 社会保险待遇核定和支付', NULL, '个人治疗工伤的医疗费用、康复费用、安装配置辅助器具费用中应当由工伤保险基金支付的部分，由社会保险经办机构审核后与医疗机构、辅助器具配置机构直接结算。 因特殊情况用人单位或者个人申请手工报销，应当向社会保险经办机构提供医疗机构、辅助器具配置机构的收费票据、费用清单、诊断证明、病历资料。社会保险经办机构应当对收费票据、费用清单、诊断证明、病历资料进行审核，并自收到申请之日起20个工作日内办理完毕。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172522, '《社会保险经办条例》', '第二十三条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第三章 社会保险待遇核定和支付', NULL, '人力资源社会保障行政部门、医疗保障行政部门应当按照各自职责建立健全异地就医医疗费用结算制度。社会保险经办机构应当做好异地就医医疗费用结算工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172523, '《社会保险经办条例》', '第二十四条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第三章 社会保险待遇核定和支付', NULL, '个人申领失业保险金，社会保险经办机构应当自收到申请之日起10个工作日内办理完毕。 个人在领取失业保险金期间，社会保险经办机构应当从失业保险基金中支付其应当缴纳的基本医疗保险（含生育保险）费。 个人申领职业培训等补贴，应当提供职业资格证书或者职业技能等级证书。社会保险经办机构应当对职业资格证书或者职业技能等级证书进行审核，并自收到申请之日起10个工作日内办理完毕。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172524, '《社会保险经办条例》', '第二十五条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第三章 社会保险待遇核定和支付', NULL, '个人出现国家规定的停止享受社会保险待遇的情形，用人单位、待遇享受人员或者其亲属应当自相关情形发生之日起20个工作日内告知社会保险经办机构。社会保险经办机构核实后应当停止发放相应的社会保险待遇。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172525, '《社会保险经办条例》', '第二十六条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第三章 社会保险待遇核定和支付', NULL, '社会保险经办机构应当通过信息比对、自助认证等方式，核验社会保险待遇享受资格。通过信息比对、自助认证等方式无法确认社会保险待遇享受资格的，社会保险经办机构可以委托用人单位或者第三方机构进行核实。 对涉嫌丧失社会保险待遇享受资格后继续享受待遇的，社会保险经办机构应当调查核实。经调查确认不符合社会保险待遇享受资格的，停止发放待遇。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172526, '《社会保险经办条例》', '第二十七条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第四章 社会保险经办服务和管理', NULL, '社会保险经办机构应当依托社会保险公共服务平台、医疗保障信息平台等实现跨部门、跨统筹地区社会保险经办。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172527, '《社会保险经办条例》', '第二十八条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第四章 社会保险经办服务和管理', NULL, '社会保险经办机构应当推动社会保险经办事项与相关政务服务事项协同办理。社会保险经办窗口应当进驻政务服务中心，为用人单位和个人提供一站式服务。 人力资源社会保障行政部门、医疗保障行政部门应当强化社会保险经办服务能力，实现省、市、县、乡镇（街道）、村（社区）全覆盖。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172528, '《社会保险经办条例》', '第二十九条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第四章 社会保险经办服务和管理', NULL, '用人单位和个人办理社会保险事务，可以通过政府网站、移动终端、自助终端等服务渠道办理，也可以到社会保险经办窗口现场办理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172529, '《社会保险经办条例》', '第三十条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第四章 社会保险经办服务和管理', NULL, '社会保险经办机构应当加强无障碍环境建设，提供无障碍信息交流，完善无障碍服务设施设备，采用授权代办、上门服务等方式，为老年人、残疾人等特殊群体提供便利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172530, '《社会保险经办条例》', '第三十一条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第四章 社会保险经办服务和管理', NULL, '用人单位和个人办理社会保险事务，社会保险经办机构要求其提供身份证件以外的其他证明材料的，应当有法律、法规和国务院决定依据。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172531, '《社会保险经办条例》', '第三十二条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第四章 社会保险经办服务和管理', NULL, '社会保险经办机构免费向用人单位和个人提供查询核对社会保险缴费和享受社会保险待遇记录、社会保险咨询等相关服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172532, '《社会保险经办条例》', '第三十三条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第四章 社会保险经办服务和管理', NULL, '社会保险经办机构应当根据经办工作需要，与符合条件的机构协商签订服务协议，规范社会保险服务行为。人力资源社会保障行政部门、医疗保障行政部门应当加强对服务协议订立、履行等情况的监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172533, '《社会保险经办条例》', '第三十四条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第四章 社会保险经办服务和管理', NULL, '医疗保障行政部门所属的社会保险经办机构应当改进基金支付和结算服务，加强服务协议管理，建立健全集体协商谈判机制。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172534, '《社会保险经办条例》', '第三十五条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第四章 社会保险经办服务和管理', NULL, '社会保险经办机构应当妥善保管社会保险经办信息，确保信息完整、准确和安全。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172535, '《社会保险经办条例》', '第三十六条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第四章 社会保险经办服务和管理', NULL, '社会保险经办机构应当建立健全业务、财务、安全和风险管理等内部控制制度。 社会保险经办机构应当定期对内部控制制度的制定、执行情况进行检查、评估，对发现的问题进行整改。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172536, '《社会保险经办条例》', '第三十七条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第四章 社会保险经办服务和管理', NULL, '社会保险经办机构应当明确岗位权责，对重点业务、高风险业务分级审核。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172537, '《社会保险经办条例》', '第三十八条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第四章 社会保险经办服务和管理', NULL, '社会保险经办机构应当加强信息系统应用管理，健全信息核验机制，记录业务经办过程。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172538, '《社会保险经办条例》', '第三十九条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第四章 社会保险经办服务和管理', NULL, '社会保险经办机构具体编制下一年度社会保险基金预算草案，报本级人力资源社会保障行政部门、医疗保障行政部门审核汇总。社会保险基金收入预算草案由社会保险经办机构会同社会保险费征收机构具体编制。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172539, '《社会保险经办条例》', '第四十条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第四章 社会保险经办服务和管理', NULL, '社会保险经办机构设立社会保险基金支出户，用于接受财政专户拨入基金、支付基金支出款项、上解上级经办机构基金、下拨下级经办机构基金等。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172540, '《社会保险经办条例》', '第四十一条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第四章 社会保险经办服务和管理', NULL, '社会保险经办机构应当按照国家统一的会计制度对社会保险基金进行会计核算、对账。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172541, '《社会保险经办条例》', '第四十二条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第四章 社会保险经办服务和管理', NULL, '社会保险经办机构应当核查下列事项： （一）社会保险登记和待遇享受等情况； （二）社会保险服务机构履行服务协议、执行费用结算项目和标准情况； （三）法律、法规规定的其他事项。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172542, '《社会保险经办条例》', '第四十三条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第四章 社会保险经办服务和管理', NULL, '社会保险经办机构发现社会保险服务机构违反服务协议的，可以督促其履行服务协议，按照服务协议约定暂停或者不予拨付费用、追回违规费用、中止相关责任人员或者所在部门涉及社会保险基金使用的社会保险服务，直至解除服务协议；社会保险服务机构及其相关责任人员有权进行陈述、申辩。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172543, '《社会保险经办条例》', '第四十四条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第四章 社会保险经办服务和管理', NULL, '社会保险经办机构发现用人单位、个人、社会保险服务机构违反社会保险法律、法规、规章的，应当责令改正。对拒不改正或者依法应当由人力资源社会保障行政部门、医疗保障行政部门处理的，及时移交人力资源社会保障行政部门、医疗保障行政部门处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172544, '《社会保险经办条例》', '第四十五条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第四章 社会保险经办服务和管理', NULL, '国务院人力资源社会保障行政部门、医疗保障行政部门会同有关部门建立社会保险信用管理制度，明确社会保险领域严重失信主体名单认定标准。 社会保险经办机构应当如实记录用人单位、个人和社会保险服务机构及其工作人员违反社会保险法律、法规行为等失信行为。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172545, '《社会保险经办条例》', '第四十六条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第四章 社会保险经办服务和管理', NULL, '个人多享受社会保险待遇的，由社会保险经办机构责令退回；难以一次性退回的，可以签订还款协议分期退回，也可以从其后续享受的社会保险待遇或者个人账户余额中抵扣。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172546, '《社会保险经办条例》', '第四十七条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第五章 社会保险经办监督', NULL, '人力资源社会保障行政部门、医疗保障行政部门按照各自职责对社会保险经办机构下列事项进行监督检查： （一）社会保险法律、法规、规章执行情况； （二）社会保险登记、待遇支付等经办情况； （三）社会保险基金管理情况； （四）与社会保险服务机构签订服务协议和服务协议履行情况； （五）法律、法规规定的其他事项。 财政部门、审计机关按照各自职责，依法对社会保险经办机构的相关工作实施监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172547, '《社会保险经办条例》', '第四十八条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第五章 社会保险经办监督', NULL, '人力资源社会保障行政部门、医疗保障行政部门应当按照各自职责加强对社会保险服务机构、用人单位和个人遵守社会保险法律、法规、规章情况的监督检查。社会保险服务机构、用人单位和个人应当配合，如实提供与社会保险有关的资料，不得拒绝检查或者谎报、瞒报。 人力资源社会保障行政部门、医疗保障行政部门发现社会保险服务机构、用人单位违反社会保险法律、法规、规章的，应当按照各自职责提出处理意见，督促整改，并可以约谈相关负责人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172548, '《社会保险经办条例》', '第四十九条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第五章 社会保险经办监督', NULL, '人力资源社会保障行政部门、医疗保障行政部门、社会保险经办机构及其工作人员依法保护用人单位和个人的信息，不得以任何形式泄露。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172549, '《社会保险经办条例》', '第五十条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第五章 社会保险经办监督', NULL, '人力资源社会保障行政部门、医疗保障行政部门应当畅通监督渠道，鼓励和支持社会各方面对社会保险经办进行监督。 社会保险经办机构应当定期向社会公布参加社会保险情况以及社会保险基金的收入、支出、结余和收益情况，听取用人单位和个人的意见建议，接受社会监督。 工会、企业代表组织应当及时反映用人单位和个人对社会保险经办的意见建议。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172550, '《社会保险经办条例》', '第五十一条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第五章 社会保险经办监督', NULL, '任何组织和个人有权对违反社会保险法律、法规、规章的行为进行举报、投诉。 人力资源社会保障行政部门、医疗保障行政部门对收到的有关社会保险的举报、投诉，应当依法进行处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172551, '《社会保险经办条例》', '第五十二条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第五章 社会保险经办监督', NULL, '用人单位和个人认为社会保险经办机构在社会保险经办工作中侵害其社会保险权益的，可以依法申请行政复议或者提起行政诉讼。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172552, '《社会保险经办条例》', '第五十三条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第六章 法律责任', NULL, '社会保险经办机构及其工作人员有下列行为之一的，由人力资源社会保障行政部门、医疗保障行政部门按照各自职责责令改正；给社会保险基金、用人单位或者个人造成损失的，依法承担赔偿责任；对负有责任的领导人员和直接责任人员依法给予处分： （一）未履行社会保险法定职责的； （二）违反规定要求提供证明材料的； （三）克扣或者拒不按时支付社会保险待遇的； （四）丢失或者篡改缴费记录、享受社会保险待遇记录等社会保险数据、个人权益记录的； （五）违反社会保险经办内部控制制度的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172553, '《社会保险经办条例》', '第五十四条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第六章 法律责任', NULL, '人力资源社会保障行政部门、医疗保障行政部门、社会保险经办机构及其工作人员泄露用人单位和个人信息的，对负有责任的领导人员和直接责任人员依法给予处分；给用人单位或者个人造成损失的，依法承担赔偿责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172554, '《社会保险经办条例》', '第五十五条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第六章 法律责任', NULL, '以欺诈、伪造证明材料或者其他手段骗取社会保险基金支出的，由人力资源社会保障行政部门、医疗保障行政部门按照各自职责责令退回，处骗取金额2倍以上5倍以下的罚款；属于定点医药机构的，责令其暂停相关责任部门6个月以上1年以下涉及社会保险基金使用的社会保险服务，直至由社会保险经办机构解除服务协议；属于其他社会保险服务机构的，由社会保险经办机构解除服务协议。对负有责任的领导人员和直接责任人员，有执业资格的，由有关主管部门依法吊销其执业资格。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172555, '《社会保险经办条例》', '第五十六条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第六章 法律责任', NULL, '隐匿、转移、侵占、挪用社会保险基金或者违规投资运营的，由人力资源社会保障行政部门、医疗保障行政部门、财政部门、审计机关按照各自职责责令追回；有违法所得的，没收违法所得；对负有责任的领导人员和直接责任人员依法给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172556, '《社会保险经办条例》', '第五十七条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第六章 法律责任', NULL, '社会保险服务机构拒绝人力资源社会保障行政部门、医疗保障行政部门监督检查或者谎报、瞒报有关情况的，由人力资源社会保障行政部门、医疗保障行政部门按照各自职责责令改正，并可以约谈有关负责人；拒不改正的，处1万元以上5万元以下的罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172557, '《社会保险经办条例》', '第五十八条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第六章 法律责任', NULL, '公职人员在社会保险经办工作中滥用职权、玩忽职守、徇私舞弊的，依法给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172558, '《社会保险经办条例》', '第五十九条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第六章 法律责任', NULL, '违反本条例规定，构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172559, '《社会保险经办条例》', '第六十条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第七章 附 则', NULL, '本条例所称社会保险经办机构，是指人力资源社会保障行政部门所属的经办基本养老保险、工伤保险、失业保险等社会保险的机构和医疗保障行政部门所属的经办基本医疗保险、生育保险等社会保险的机构。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172560, '《社会保险经办条例》', '第六十一条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第七章 附 则', NULL, '本条例所称社会保险服务机构，是指与社会保险经办机构签订服务协议，提供社会保险服务的医疗机构、药品经营单位、辅助器具配置机构、失业保险委托培训机构等机构。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172561, '《社会保险经办条例》', '第六十二条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第七章 附 则', NULL, '社会保障卡加载金融功能，有条件的地方可以扩大社会保障卡的应用范围，提升民生服务效能。医保电子凭证可以根据需要，加载相关服务功能。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2172562, '《社会保险经办条例》', '第六十三条', '劳动', '行政法规', NULL, '国务院 2023-08-16', '第七章 附 则', NULL, '本条例自2023年12月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274500, '《保障农民工工资支付条例》', '第一条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第一章 总则', NULL, '为了规范农民工工资支付行为，保障农民工按时足额获得工资，根据《中华人民共和国劳动法》及有关法律规定，制定本条例。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274501, '《保障农民工工资支付条例》', '第二条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第一章 总则', NULL, '保障农民工工资支付，适用本条例。 本条例所称农民工，是指为用人单位提供劳动的农村居民。 本条例所称工资，是指农民工为用人单位提供劳动后应当获得的劳动报酬。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274502, '《保障农民工工资支付条例》', '第三条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第一章 总则', NULL, '农民工有按时足额获得工资的权利。任何单位和个人不得拖欠农民工工资。 农民工应当遵守劳动纪律和职业道德，执行劳动安全卫生规程，完成劳动任务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274503, '《保障农民工工资支付条例》', '第四条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第一章 总则', NULL, '县级以上地方人民政府对本行政区域内保障农民工工资支付工作负责，建立保障农民工工资支付工作协调机制，加强监管能力建设，健全保障农民工工资支付工作目标责任制，并纳入对本级人民政府有关部门和下级人民政府进行考核和监督的内容。 乡镇人民政府、街道办事处应当加强对拖欠农民工工资矛盾的排查和调处工作，防范和化解矛盾，及时调解纠纷。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274504, '《保障农民工工资支付条例》', '第五条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第一章 总则', NULL, '保障农民工工资支付，应当坚持市场主体负责、政府依法监管、社会协同监督，按照源头治理、预防为主、防治结合、标本兼治的要求，依法根治拖欠农民工工资问题。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274505, '《保障农民工工资支付条例》', '第六条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第一章 总则', NULL, '用人单位实行农民工劳动用工实名制管理，与招用的农民工书面约定或者通过依法制定的规章制度规定工资支付标准、支付时间、支付方式等内容。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274506, '《保障农民工工资支付条例》', '第七条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第一章 总则', NULL, '人力资源社会保障行政部门负责保障农民工工资支付工作的组织协调、管理指导和农民工工资支付情况的监督检查,查处有关拖欠农民工工资案件。 住房城乡建设、交通运输、水利等相关行业工程建设主管部门按照职责履行行业监管责任，督办因违法发包、转包、违法分包、挂靠、拖欠工程款等导致的拖欠农民工工资案件。 发展改革等部门按照职责负责政府投资项目的审批管理，依法审查政府投资项目的资金来源和筹措方式，按规定及时安排政府投资，加强社会信用体系建设，组织对拖欠农民工工资失信联合惩戒对象依法依规予以限制和惩戒。 财政部门负责政府投资资金的预算管理，根据经批准的预算按规定及时足额拨付政府投资资金。 公安机关负责及时受理、侦办涉嫌拒不支付劳动报酬刑事案件，依法处置因农民工工资拖欠引发的社会治安案件。 司法行政、自然资源、人民银行、审计、国有资产管理、税务、市场监管、金融监管等部门，按照职责做好与保障农民工工资支付相关的工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274507, '《保障农民工工资支付条例》', '第八条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第一章 总则', NULL, '工会、共产主义青年团、妇女联合会、残疾人联合会等组织按照职责依法维护农民工获得工资的权利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274508, '《保障农民工工资支付条例》', '第九条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第一章 总则', NULL, '新闻媒体应当开展保障农民工工资支付法律法规政策的公益宣传和先进典型的报道，依法加强对拖欠农民工工资违法行为的舆论监督，引导用人单位增强依法用工、按时足额支付工资的法律意识，引导农民工依法维权。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274509, '《保障农民工工资支付条例》', '第十条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第一章 总则', NULL, '被拖欠工资的农民工有权依法投诉，或者申请劳动争议调解仲裁和提起诉讼。 任何单位和个人对拖欠农民工工资的行为，有权向人力资源社会保障行政部门或者其他有关部门举报。 人力资源社会保障行政部门和其他有关部门应当公开举报投诉电话、网站等渠道，依法接受对拖欠农民工工资行为的举报、投诉。对于举报、投诉的处理实行首问负责制，属于本部门受理的，应当依法及时处理；不属于本部门受理的，应当及时转送相关部门，相关部门应当依法及时处理，并将处理结果告知举报、投诉人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274510, '《保障农民工工资支付条例》', '第十一条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第二章 工资支付形式与周期', NULL, '农民工工资应当以货币形式，通过银行转账或者现金支付给农民工本人，不得以实物或者有价证券等其他形式替代。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274511, '《保障农民工工资支付条例》', '第十二条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第二章 工资支付形式与周期', NULL, '用人单位应当按照与农民工书面约定或者依法制定的规章制度规定的工资支付周期和具体支付日期足额支付工资。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274512, '《保障农民工工资支付条例》', '第十三条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第二章 工资支付形式与周期', NULL, '实行月、周、日、小时工资制的，按照月、周、日、小时为周期支付工资；实行计件工资制的，工资支付周期由双方依法约定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274513, '《保障农民工工资支付条例》', '第十四条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第二章 工资支付形式与周期', NULL, '用人单位与农民工书面约定或者依法制定的规章制度规定的具体支付日期，可以在农民工提供劳动的当期或者次期。具体支付日期遇法定节假日或者休息日的，应当在法定节假日或者休息日前支付。 用人单位因不可抗力未能在支付日期支付工资的，应当在不可抗力消除后及时支付。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274514, '《保障农民工工资支付条例》', '第十五条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第二章 工资支付形式与周期', NULL, '用人单位应当按照工资支付周期编制书面工资支付台账，并至少保存3年。 书面工资支付台账应当包括用人单位名称，支付周期，支付日期，支付对象姓名、身份证号码、联系方式，工作时间，应发工资项目及数额，代扣、代缴、扣除项目和数额，实发工资数额，银行代发工资凭证或者农民工签字等内容。 用人单位向农民工支付工资时，应当提供农民工本人的工资清单。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274515, '《保障农民工工资支付条例》', '第十六条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第三章 工资清偿', NULL, '用人单位拖欠农民工工资的，应当依法予以清偿。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274516, '《保障农民工工资支付条例》', '第十七条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第三章 工资清偿', NULL, '不具备合法经营资格的单位招用农民工，农民工已经付出劳动而未获得工资的，依照有关法律规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274517, '《保障农民工工资支付条例》', '第十八条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第三章 工资清偿', NULL, '用工单位使用个人、不具备合法经营资格的单位或者未依法取得劳务派遣许可证的单位派遣的农民工，拖欠农民工工资的，由用工单位清偿，并可以依法进行追偿。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274518, '《保障农民工工资支付条例》', '第十九条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第三章 工资清偿', NULL, '用人单位将工作任务发包给个人或者不具备合法经营资格的单位，导致拖欠所招用农民工工资的，依照有关法律规定执行。 用人单位允许个人、不具备合法经营资格或者未取得相应资质的单位以用人单位的名义对外经营，导致拖欠所招用农民工工资的，由用人单位清偿，并可以依法进行追偿。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274519, '《保障农民工工资支付条例》', '第二十条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第三章 工资清偿', NULL, '合伙企业、个人独资企业、个体经济组织等用人单位拖欠农民工工资的，应当依法予以清偿；不清偿的，由出资人依法清偿。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274520, '《保障农民工工资支付条例》', '第二十一条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第三章 工资清偿', NULL, '用人单位合并或者分立时，应当在实施合并或者分立前依法清偿拖欠的农民工工资；经与农民工书面协商一致的，可以由合并或者分立后承继其权利和义务的用人单位清偿。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274521, '《保障农民工工资支付条例》', '第二十二条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第三章 工资清偿', NULL, '用人单位被依法吊销营业执照或者登记证书、被责令关闭、被撤销或者依法解散的，应当在申请注销登记前依法清偿拖欠的农民工工资。 未依据前款规定清偿农民工工资的用人单位主要出资人，应当在注册新用人单位前清偿拖欠的农民工工资。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274522, '《保障农民工工资支付条例》', '第二十三条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第四章 工程建设领域特别规定', NULL, '建设单位应当有满足施工所需要的资金安排。没有满足施工所需要的资金安排的，工程建设项目不得开工建设；依法需要办理施工许可证的，相关行业工程建设主管部门不予颁发施工许可证。 政府投资项目所需资金，应当按照国家有关规定落实到位，不得由施工单位垫资建设。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274523, '《保障农民工工资支付条例》', '第二十四条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第四章 工程建设领域特别规定', NULL, '建设单位应当向施工单位提供工程款支付担保。 建设单位与施工总承包单位依法订立书面工程施工合同，应当约定工程款计量周期、工程款进度结算办法以及人工费用拨付周期，并按照保障农民工工资按时足额支付的要求约定人工费用。人工费用拨付周期不得超过1个月。 建设单位与施工总承包单位应当将工程施工合同保存备查。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274524, '《保障农民工工资支付条例》', '第二十五条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第四章 工程建设领域特别规定', NULL, '施工总承包单位与分包单位依法订立书面分包合同，应当约定工程款计量周期、工程款进度结算办法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274525, '《保障农民工工资支付条例》', '第二十六条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第四章 工程建设领域特别规定', NULL, '施工总承包单位应当按照有关规定开设农民工工资专用账户，专项用于支付该工程建设项目农民工工资。 开设、使用农民工工资专用账户有关资料应当由施工总承包单位妥善保存备查。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274526, '《保障农民工工资支付条例》', '第二十七条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第四章 工程建设领域特别规定', NULL, '金融机构应当优化农民工工资专用账户开设服务流程，做好农民工工资专用账户的日常管理工作；发现资金未按约定拨付等情况的，及时通知施工总承包单位，由施工总承包单位报告人力资源社会保障行政部门和相关行业工程建设主管部门，并纳入欠薪预警系统。 工程完工且未拖欠农民工工资的，施工总承包单位公示30日后，可以申请注销农民工工资专用账户，账户内余额归施工总承包单位所有。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274527, '《保障农民工工资支付条例》', '第二十八条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第四章 工程建设领域特别规定', NULL, '施工总承包单位或者分包单位应当依法与所招用的农民工订立劳动合同并进行用工实名登记，具备条件的行业应当通过相应的管理服务信息平台进行用工实名登记、管理。未与施工总承包单位或者分包单位订立劳动合同并进行用工实名登记的人员，不得进入项目现场施工。 施工总承包单位应当在工程项目部配备劳资专管员，对分包单位劳动用工实施监督管理，掌握施工现场用工、考勤、工资支付等情况，审核分包单位编制的农民工工资支付表，分包单位应当予以配合。 施工总承包单位、分包单位应当建立用工管理台账，并保存至工程完工且工资全部结清后至少3年。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274528, '《保障农民工工资支付条例》', '第二十九条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第四章 工程建设领域特别规定', NULL, '建设单位应当按照合同约定及时拨付工程款，并将人工费用及时足额拨付至农民工工资专用账户，加强对施工总承包单位按时足额支付农民工工资的监督。 因建设单位未按照合同约定及时拨付工程款导致农民工工资拖欠的，建设单位应当以未结清的工程款为限先行垫付被拖欠的农民工工资。 建设单位应当以项目为单位建立保障农民工工资支付协调机制和工资拖欠预防机制，督促施工总承包单位加强劳动用工管理，妥善处理与农民工工资支付相关的矛盾纠纷。发生农民工集体讨薪事件的，建设单位应当会同施工总承包单位及时处理，并向项目所在地人力资源社会保障行政部门和相关行业工程建设主管部门报告有关情况。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274529, '《保障农民工工资支付条例》', '第三十条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第四章 工程建设领域特别规定', NULL, '分包单位对所招用农民工的实名制管理和工资支付负直接责任。 施工总承包单位对分包单位劳动用工和工资发放等情况进行监督。 分包单位拖欠农民工工资的，由施工总承包单位先行清偿，再依法进行追偿。 工程建设项目转包，拖欠农民工工资的，由施工总承包单位先行清偿，再依法进行追偿。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274530, '《保障农民工工资支付条例》', '第三十一条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第四章 工程建设领域特别规定', NULL, '工程建设领域推行分包单位农民工工资委托施工总承包单位代发制度。 分包单位应当按月考核农民工工作量并编制工资支付表，经农民工本人签字确认后，与当月工程进度等情况一并交施工总承包单位。 施工总承包单位根据分包单位编制的工资支付表，通过农民工工资专用账户直接将工资支付到农民工本人的银行账户，并向分包单位提供代发工资凭证。 用于支付农民工工资的银行账户所绑定的农民工本人社会保障卡或者银行卡，用人单位或者其他人员不得以任何理由扣押或者变相扣押。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274531, '《保障农民工工资支付条例》', '第三十二条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第四章 工程建设领域特别规定', NULL, '施工总承包单位应当按照有关规定存储工资保证金，专项用于支付为所承包工程提供劳动的农民工被拖欠的工资。 工资保证金实行差异化存储办法，对一定时期内未发生工资拖欠的单位实行减免措施，对发生工资拖欠的单位适当提高存储比例。工资保证金可以用金融机构保函替代。 工资保证金的存储比例、存储形式、减免措施等具体办法，由国务院人力资源社会保障行政部门会同有关部门制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274532, '《保障农民工工资支付条例》', '第三十三条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第四章 工程建设领域特别规定', NULL, '除法律另有规定外，农民工工资专用账户资金和工资保证金不得因支付为本项目提供劳动的农民工工资之外的原因被查封、冻结或者划拨。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274533, '《保障农民工工资支付条例》', '第三十四条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第四章 工程建设领域特别规定', NULL, '施工总承包单位应当在施工现场醒目位置设立维权信息告示牌，明示下列事项： （一）建设单位、施工总承包单位及所在项目部、分包单位、相关行业工程建设主管部门、劳资专管员等基本信息； （二）当地最低工资标准、工资支付日期等基本信息； （三）相关行业工程建设主管部门和劳动保障监察投诉举报电话、劳动争议调解仲裁申请渠道、法律援助申请渠道、公共法律服务热线等信息。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274534, '《保障农民工工资支付条例》', '第三十五条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第四章 工程建设领域特别规定', NULL, '建设单位与施工总承包单位或者承包单位与分包单位因工程数量、质量、造价等产生争议的，建设单位不得因争议不按照本条例第二十四条的规定拨付工程款中的人工费用，施工总承包单位也不得因争议不按照规定代发工资。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274535, '《保障农民工工资支付条例》', '第三十六条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第四章 工程建设领域特别规定', NULL, '建设单位或者施工总承包单位将建设工程发包或者分包给个人或者不具备合法经营资格的单位，导致拖欠农民工工资的，由建设单位或者施工总承包单位清偿。 施工单位允许其他单位和个人以施工单位的名义对外承揽建设工程，导致拖欠农民工工资的，由施工单位清偿。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274536, '《保障农民工工资支付条例》', '第三十七条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第四章 工程建设领域特别规定', NULL, '工程建设项目违反国土空间规划、工程建设等法律法规，导致拖欠农民工工资的，由建设单位清偿。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274537, '《保障农民工工资支付条例》', '第三十八条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第五章 监督检查', NULL, '县级以上地方人民政府应当建立农民工工资支付监控预警平台,实现人力资源社会保障、发展改革、司法行政、财政、住房城乡建设、交通运输、水利等部门的工程项目审批、资金落实、施工许可、劳动用工、工资支付等信息及时共享。 人力资源社会保障行政部门根据水电燃气供应、物业管理、信贷、税收等反映企业生产经营相关指标的变化情况，及时监控和预警工资支付隐患并做好防范工作，市场监管、金融监管、税务等部门应当予以配合。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274538, '《保障农民工工资支付条例》', '第三十九条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第五章 监督检查', NULL, '人力资源社会保障行政部门、相关行业工程建设主管部门和其他有关部门应当按照职责，加强对用人单位与农民工签订劳动合同、工资支付以及工程建设项目实行农民工实名制管理、农民工工资专用账户管理、施工总承包单位代发工资、工资保证金存储、维权信息公示等情况的监督检查，预防和减少拖欠农民工工资行为的发生。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274539, '《保障农民工工资支付条例》', '第四十条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第五章 监督检查', NULL, '人力资源社会保障行政部门在查处拖欠农民工工资案件时，需要依法查询相关单位金融账户和相关当事人拥有房产、车辆等情况的，应当经设区的市级以上地方人民政府人力资源社会保障行政部门负责人批准，有关金融机构和登记部门应当予以配合。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274540, '《保障农民工工资支付条例》', '第四十一条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第五章 监督检查', NULL, '人力资源社会保障行政部门在查处拖欠农民工工资案件时，发生用人单位拒不配合调查、清偿责任主体及相关当事人无法联系等情形的，可以请求公安机关和其他有关部门协助处理。 人力资源社会保障行政部门发现拖欠农民工工资的违法行为涉嫌构成拒不支付劳动报酬罪的，应当按照有关规定及时移送公安机关审查并作出决定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274541, '《保障农民工工资支付条例》', '第四十二条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第五章 监督检查', NULL, '人力资源社会保障行政部门作出责令支付被拖欠的农民工工资的决定，相关单位不支付的，可以依法申请人民法院强制执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274542, '《保障农民工工资支付条例》', '第四十三条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第五章 监督检查', NULL, '相关行业工程建设主管部门应当依法规范本领域建设市场秩序，对违法发包、转包、违法分包、挂靠等行为进行查处，并对导致拖欠农民工工资的违法行为及时予以制止、纠正。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274543, '《保障农民工工资支付条例》', '第四十四条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第五章 监督检查', NULL, '财政部门、审计机关和相关行业工程建设主管部门按照职责，依法对政府投资项目建设单位按照工程施工合同约定向农民工工资专用账户拨付资金情况进行监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274544, '《保障农民工工资支付条例》', '第四十五条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第五章 监督检查', NULL, '司法行政部门和法律援助机构应当将农民工列为法律援助的重点对象，并依法为请求支付工资的农民工提供便捷的法律援助。 公共法律服务相关机构应当积极参与相关诉讼、咨询、调解等活动，帮助解决拖欠农民工工资问题。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274545, '《保障农民工工资支付条例》', '第四十六条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第五章 监督检查', NULL, '人力资源社会保障行政部门、相关行业工程建设主管部门和其他有关部门应当按照“谁执法谁普法”普法责任制的要求，通过以案释法等多种形式，加大对保障农民工工资支付相关法律法规的普及宣传。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274546, '《保障农民工工资支付条例》', '第四十七条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第五章 监督检查', NULL, '人力资源社会保障行政部门应当建立用人单位及相关责任人劳动保障守法诚信档案，对用人单位开展守法诚信等级评价。 用人单位有严重拖欠农民工工资违法行为的，由人力资源社会保障行政部门向社会公布，必要时可以通过召开新闻发布会等形式向媒体公开曝光。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274547, '《保障农民工工资支付条例》', '第四十八条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第五章 监督检查', NULL, '用人单位拖欠农民工工资，情节严重或者造成严重不良社会影响的，有关部门应当将该用人单位及其法定代表人或者主要负责人、直接负责的主管人员和其他直接责任人员列入拖欠农民工工资失信联合惩戒对象名单，在政府资金支持、政府采购、招投标、融资贷款、市场准入、税收优惠、评优评先、交通出行等方面依法依规予以限制。 拖欠农民工工资需要列入失信联合惩戒名单的具体情形，由国务院人力资源社会保障行政部门规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274548, '《保障农民工工资支付条例》', '第四十九条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第五章 监督检查', NULL, '建设单位未依法提供工程款支付担保或者政府投资项目拖欠工程款，导致拖欠农民工工资的，县级以上地方人民政府应当限制其新建项目，并记入信用记录，纳入国家信用信息系统进行公示。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274549, '《保障农民工工资支付条例》', '第五十条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第五章 监督检查', NULL, '农民工与用人单位就拖欠工资存在争议，用人单位应当提供依法由其保存的劳动合同、职工名册、工资支付台账和清单等材料；不提供的，依法承担不利后果。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274550, '《保障农民工工资支付条例》', '第五十一条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第五章 监督检查', NULL, '工会依法维护农民工工资权益，对用人单位工资支付情况进行监督；发现拖欠农民工工资的，可以要求用人单位改正，拒不改正的，可以请求人力资源社会保障行政部门和其他有关部门依法处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274551, '《保障农民工工资支付条例》', '第五十二条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第五章 监督检查', NULL, '单位或者个人编造虚假事实或者采取非法手段讨要农民工工资，或者以拖欠农民工工资为名讨要工程款的，依法予以处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274552, '《保障农民工工资支付条例》', '第五十三条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第六章 法律责任', NULL, '违反本条例规定拖欠农民工工资的，依照有关法律规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274553, '《保障农民工工资支付条例》', '第五十四条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第六章 法律责任', NULL, '有下列情形之一的，由人力资源社会保障行政部门责令限期改正；逾期不改正的，对单位处2万元以上5万元以下的罚款，对法定代表人或者主要负责人、直接负责的主管人员和其他直接责任人员处1万元以上3万元以下的罚款： （一）以实物、有价证券等形式代替货币支付农民工工资； （二）未编制工资支付台账并依法保存，或者未向农民工提供工资清单； （三）扣押或者变相扣押用于支付农民工工资的银行账户所绑定的农民工本人社会保障卡或者银行卡。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274554, '《保障农民工工资支付条例》', '第五十五条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第六章 法律责任', NULL, '有下列情形之一的，由人力资源社会保障行政部门、相关行业工程建设主管部门按照职责责令限期改正；逾期不改正的，责令项目停工，并处5万元以上10万元以下的罚款；情节严重的，给予施工单位限制承接新工程、降低资质等级、吊销资质证书等处罚： （一）施工总承包单位未按规定开设或者使用农民工工资专用账户； （二）施工总承包单位未按规定存储工资保证金或者未提供金融机构保函； （三）施工总承包单位、分包单位未实行劳动用工实名制管理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274555, '《保障农民工工资支付条例》', '第五十六条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第六章 法律责任', NULL, '有下列情形之一的，由人力资源社会保障行政部门、相关行业工程建设主管部门按照职责责令限期改正；逾期不改正的，处5万元以上10万元以下的罚款： （一）分包单位未按月考核农民工工作量、编制工资支付表并经农民工本人签字确认； （二）施工总承包单位未对分包单位劳动用工实施监督管理； （三）分包单位未配合施工总承包单位对其劳动用工进行监督管理； （四）施工总承包单位未实行施工现场维权信息公示制度。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274556, '《保障农民工工资支付条例》', '第五十七条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第六章 法律责任', NULL, '有下列情形之一的，由人力资源社会保障行政部门、相关行业工程建设主管部门按照职责责令限期改正；逾期不改正的，责令项目停工，并处5万元以上10万元以下的罚款： （一）建设单位未依法提供工程款支付担保； （二）建设单位未按约定及时足额向农民工工资专用账户拨付工程款中的人工费用； （三）建设单位或者施工总承包单位拒不提供或者无法提供工程施工合同、农民工工资专用账户有关资料。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274557, '《保障农民工工资支付条例》', '第五十八条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第六章 法律责任', NULL, '不依法配合人力资源社会保障行政部门查询相关单位金融账户的，由金融监管部门责令改正；拒不改正的，处2万元以上5万元以下的罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274558, '《保障农民工工资支付条例》', '第五十九条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第六章 法律责任', NULL, '政府投资项目政府投资资金不到位拖欠农民工工资的，由人力资源社会保障行政部门报本级人民政府批准，责令限期足额拨付所拖欠的资金；逾期不拨付的，由上一级人民政府人力资源社会保障行政部门约谈直接责任部门和相关监管部门负责人，必要时进行通报，约谈地方人民政府负责人。情节严重的，对地方人民政府及其有关部门负责人、直接负责的主管人员和其他直接责任人员依法依规给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274559, '《保障农民工工资支付条例》', '第六十条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第六章 法律责任', NULL, '政府投资项目建设单位未经批准立项建设、擅自扩大建设规模、擅自增加投资概算、未及时拨付工程款等导致拖欠农民工工资的，除依法承担责任外，由人力资源社会保障行政部门、其他有关部门按照职责约谈建设单位负责人，并作为其业绩考核、薪酬分配、评优评先、职务晋升等的重要依据。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274560, '《保障农民工工资支付条例》', '第六十一条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第六章 法律责任', NULL, '对于建设资金不到位、违法违规开工建设的社会投资工程建设项目拖欠农民工工资的，由人力资源社会保障行政部门、其他有关部门按照职责依法对建设单位进行处罚；对建设单位负责人依法依规给予处分。相关部门工作人员未依法履行职责的，由有关机关依法依规给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274561, '《保障农民工工资支付条例》', '第六十二条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第六章 法律责任', NULL, '县级以上地方人民政府人力资源社会保障、发展改革、财政、公安等部门和相关行业工程建设主管部门工作人员，在履行农民工工资支付监督管理职责过程中滥用职权、玩忽职守、徇私舞弊的，依法依规给予处分；构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274562, '《保障农民工工资支付条例》', '第六十三条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第七章 附则', NULL, '用人单位一时难以支付拖欠的农民工工资或者拖欠农民工工资逃匿的，县级以上地方人民政府可以动用应急周转金，先行垫付用人单位拖欠的农民工部分工资或者基本生活费。对已经垫付的应急周转金，应当依法向拖欠农民工工资的用人单位进行追偿。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2274563, '《保障农民工工资支付条例》', '第六十四条', '劳动', '行政法规', NULL, '国务院 2019-12-30', '第七章 附则', NULL, '本条例自2020年5月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2294000, '《社会保险费征缴暂行条例》', '第一条', '劳动', '行政法规', NULL, '国务院 2019-03-24', '第一章 总则', NULL, '为了加强和规范社会保险费征缴工作，保障社会保险金的发放，制定本条例。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2294001, '《社会保险费征缴暂行条例》', '第二条', '劳动', '行政法规', NULL, '国务院 2019-03-24', '第一章 总则', NULL, '基本养老保险费、基本医疗保险费、失业保险费(以下统称社会保险费)的征收、缴纳，适用本条例。 本条例所称缴费单位、缴费个人，是指依照有关法律、行政法规和国务院的规定，应当缴纳社会保险费的单位和个人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2294002, '《社会保险费征缴暂行条例》', '第三条', '劳动', '行政法规', NULL, '国务院 2019-03-24', '第一章 总则', NULL, '基本养老保险费的征缴范围：国有企业、城镇集体企业、外商投资企业、城镇私营企业和其他城镇企业及其职工，实行企业化管理的事业单位及其职工。 基本医疗保险费的征缴范围：国有企业、城镇集体企业、外商投资企业、城镇私营企业和其他城镇企业及其职工，国家机关及其工作人员，事业单位及其职工，民办非企业单位及其职工，社会团体及其专职人员。 失业保险费的征缴范围：国有企业、城镇集体企业、外商投资企业、城镇私营企业和其他城镇企业及其职工，事业单位及其职工。 省、自治区、直辖市人民政府根据当地实际情况，可以规定将城镇个体工商户纳入基本养老保险、基本医疗保险的范围，并可以规定将社会团体及其专职人员、民办非企业单位及其职工以及有雇工的城镇个体工商户及其雇工纳入失业保险的范围。 社会保险费的费基、费率依照有关法律、行政法规和国务院的规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2294003, '《社会保险费征缴暂行条例》', '第四条', '劳动', '行政法规', NULL, '国务院 2019-03-24', '第一章 总则', NULL, '缴费单位、缴费个人应当按时足额缴纳社会保险费。 征缴的社会保险费纳入社会保险基金，专款专用，任何单位和个人不得挪用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2294004, '《社会保险费征缴暂行条例》', '第五条', '劳动', '行政法规', NULL, '国务院 2019-03-24', '第一章 总则', NULL, '国务院劳动保障行政部门负责全国的社会保险费征缴管理和监督检查工作。县级以上地方各级人民政府劳动保障行政部门负责本行政区域内的社会保险费征缴管理和监督检查工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2294005, '《社会保险费征缴暂行条例》', '第六条', '劳动', '行政法规', NULL, '国务院 2019-03-24', '第一章 总则', NULL, '社会保险费实行三项社会保险费集中、统一征收。社会保险费的征收机构由省、自治区、直辖市人民政府规定，可以由税务机关征收，也可以由劳动保障行政部门按照国务院规定设立的社会保险经办机构(以下简称社会保险经办机构)征收。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2294006, '《社会保险费征缴暂行条例》', '第七条', '劳动', '行政法规', NULL, '国务院 2019-03-24', '第二章 征缴管理', NULL, '缴费单位必须向当地社会保险经办机构办理社会保险登记，参加社会保险。 登记事项包括：单位名称、住所、经营地点、单位类型、法定代表人或者负责人、开户银行账号以及国务院劳动保障行政部门规定的其他事项。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2294007, '《社会保险费征缴暂行条例》', '第八条', '劳动', '行政法规', NULL, '国务院 2019-03-24', '第二章 征缴管理', NULL, '企业在办理登记注册时，同步办理社会保险登记。 前款规定以外的缴费单位应当自成立之日起30日内，向当地社会保险经办机构申请办理社会保险登记。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2294008, '《社会保险费征缴暂行条例》', '第九条', '劳动', '行政法规', NULL, '国务院 2019-03-24', '第二章 征缴管理', NULL, '缴费单位的社会保险登记事项发生变更或者缴费单位依法终止的，应当自变更或者终止之日起30日内，到社会保险经办机构办理变更或者注销社会保险登记手续。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2294009, '《社会保险费征缴暂行条例》', '第十条', '劳动', '行政法规', NULL, '国务院 2019-03-24', '第二章 征缴管理', NULL, '缴费单位必须按月向社会保险经办机构申报应缴纳的社会保险费数额，经社会保险经办机构核定后，在规定的期限内缴纳社会保险费。 缴费单位不按规定申报应缴纳的社会保险费数额的，由社会保险经办机构暂按该单位上月缴费数额的110%确定应缴数额；没有上月缴费数额的，由社会保险经办机构暂按该单位的经营状况、职工人数等有关情况确定应缴数额。缴费单位补办申报手续并按核定数额缴纳社会保险费后，由社会保险经办机构按照规定结算。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2294010, '《社会保险费征缴暂行条例》', '第十一条', '劳动', '行政法规', NULL, '国务院 2019-03-24', '第二章 征缴管理', NULL, '省、自治区、直辖市人民政府规定由税务机关征收社会保险费的，社会保险经办机构应当及时向税务机关提供缴费单位社会保险登记、变更登记、注销登记以及缴费申报的情况。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2294011, '《社会保险费征缴暂行条例》', '第十二条', '劳动', '行政法规', NULL, '国务院 2019-03-24', '第二章 征缴管理', NULL, '缴费单位和缴费个人应当以货币形式全额缴纳社会保险费。 缴费个人应当缴纳的社会保险费，由所在单位从其本人工资中代扣代缴。 社会保险费不得减免。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2294012, '《社会保险费征缴暂行条例》', '第十三条', '劳动', '行政法规', NULL, '国务院 2019-03-24', '第二章 征缴管理', NULL, '缴费单位未按规定缴纳和代扣代缴社会保险费的，由劳动保障行政部门或者税务机关责令限期缴纳；逾期仍不缴纳的，除补缴欠缴数额外，从欠缴之日起，按日加收2‰的滞纳金。滞纳金并入社会保险基金。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2294013, '《社会保险费征缴暂行条例》', '第十四条', '劳动', '行政法规', NULL, '国务院 2019-03-24', '第二章 征缴管理', NULL, '征收的社会保险费存入财政部门在国有商业银行开设的社会保障基金财政专户。 社会保险基金按照不同险种的统筹范围，分别建立基本养老保险基金、基本医疗保险基金、失业保险基金。各项社会保险基金分别单独核算。 社会保险基金不计征税、费。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2294014, '《社会保险费征缴暂行条例》', '第十五条', '劳动', '行政法规', NULL, '国务院 2019-03-24', '第二章 征缴管理', NULL, '省、自治区、直辖市人民政府规定由税务机关征收社会保险费的，税务机关应当及时向社会保险经办机构提供缴费单位和缴费个人的缴费情况；社会保险经办机构应当将有关情况汇总，报劳动保障行政部门。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2294015, '《社会保险费征缴暂行条例》', '第十六条', '劳动', '行政法规', NULL, '国务院 2019-03-24', '第二章 征缴管理', NULL, '社会保险经办机构应当建立缴费记录，其中基本养老保险、基本医疗保险并应当按照规定记录个人账户。社会保险经办机构负责保存缴费记录，并保证其完整、安全。社会保险经办机构应当至少每年向缴费个人发送一次基本养老保险、基本医疗保险个人账户通知单。 缴费单位、缴费个人有权按照规定查询缴费记录。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2294016, '《社会保险费征缴暂行条例》', '第十七条', '劳动', '行政法规', NULL, '国务院 2019-03-24', '第三章 监督检查', NULL, '缴费单位应当每年向本单位职工公布本单位全年社会保险费缴纳情况，接受职工监督。 社会保险经办机构应当定期向社会公告社会保险费征收情况，接受社会监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2294017, '《社会保险费征缴暂行条例》', '第十八条', '劳动', '行政法规', NULL, '国务院 2019-03-24', '第三章 监督检查', NULL, '按照省、自治区、直辖市人民政府关于社会保险费征缴机构的规定，劳动保障行政部门或者税务机关依法对单位缴费情况进行检查时，被检查的单位应当提供与缴纳社会保险费有关的用人情况、工资表、财务报表等资料，如实反映情况，不得拒绝检查，不得谎报、瞒报。劳动保障行政部门或者税务机关可以记录、录音、录像、照相和复制有关资料；但是，应当为缴费单位保密。 劳动保障行政部门、税务机关的工作人员在行使前款所列职权时，应当出示执行公务证件。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2294018, '《社会保险费征缴暂行条例》', '第十九条', '劳动', '行政法规', NULL, '国务院 2019-03-24', '第三章 监督检查', NULL, '劳动保障行政部门或者税务机关调查社会保险费征缴违法案件时，有关部门、单位应当给予支持、协助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2294019, '《社会保险费征缴暂行条例》', '第二十条', '劳动', '行政法规', NULL, '国务院 2019-03-24', '第三章 监督检查', NULL, '社会保险经办机构受劳动保障行政部门的委托，可以进行与社会保险费征缴有关的检查、调查工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2294020, '《社会保险费征缴暂行条例》', '第二十一条', '劳动', '行政法规', NULL, '国务院 2019-03-24', '第三章 监督检查', NULL, '任何组织和个人对有关社会保险费征缴的违法行为，有权举报。劳动保障行政部门或者税务机关对举报应当及时调查，按照规定处理，并为举报人保密。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2294021, '《社会保险费征缴暂行条例》', '第二十二条', '劳动', '行政法规', NULL, '国务院 2019-03-24', '第三章 监督检查', NULL, '社会保险基金实行收支两条线管理，由财政部门依法进行监督。 审计部门依法对社会保险基金的收支情况进行监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2294022, '《社会保险费征缴暂行条例》', '第二十三条', '劳动', '行政法规', NULL, '国务院 2019-03-24', '第四章 罚则', NULL, '缴费单位未按照规定办理社会保险登记、变更登记或者注销登记，或者未按照规定申报应缴纳的社会保险费数额的，由劳动保障行政部门责令限期改正；情节严重的，对直接负责的主管人员和其他直接责任人员可以处1000元以上5000元以下的罚款；情节特别严重的，对直接负责的主管人员和其他直接责任人员可以处5000元以上10000元以下的罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2294023, '《社会保险费征缴暂行条例》', '第二十四条', '劳动', '行政法规', NULL, '国务院 2019-03-24', '第四章 罚则', NULL, '缴费单位违反有关财务、会计、统计的法律、行政法规和国家有关规定，伪造、变造、故意毁灭有关账册、材料，或者不设账册，致使社会保险费缴费基数无法确定的，除依照有关法律、行政法规的规定给予行政处罚、纪律处分、刑事处罚外，依照本条例第十条的规定征缴；迟延缴纳的，由劳动保障行政部门或者税务机关依照本条例第十三条的规定决定加收滞纳金，并对直接负责的主管人员和其他直接责任人员处5000元以上20000元以下的罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2294024, '《社会保险费征缴暂行条例》', '第二十五条', '劳动', '行政法规', NULL, '国务院 2019-03-24', '第四章 罚则', NULL, '缴费单位和缴费个人对劳动保障行政部门或者税务机关的处罚决定不服的，可以依法申请复议；对复议决定不服的，可以依法提起诉讼。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2294025, '《社会保险费征缴暂行条例》', '第二十六条', '劳动', '行政法规', NULL, '国务院 2019-03-24', '第四章 罚则', NULL, '缴费单位逾期拒不缴纳社会保险费、滞纳金的，由劳动保障行政部门或者税务机关申请人民法院依法强制征缴。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2294026, '《社会保险费征缴暂行条例》', '第二十七条', '劳动', '行政法规', NULL, '国务院 2019-03-24', '第四章 罚则', NULL, '劳动保障行政部门、社会保险经办机构或者税务机关的工作人员滥用职权、徇私舞弊、玩忽职守，致使社会保险费流失的，由劳动保障行政部门或者税务机关追回流失的社会保险费；构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2294027, '《社会保险费征缴暂行条例》', '第二十八条', '劳动', '行政法规', NULL, '国务院 2019-03-24', '第四章 罚则', NULL, '任何单位、个人挪用社会保险基金的，追回被挪用的社会保险基金；有违法所得的，没收违法所得，并入社会保险基金；构成犯罪的，依法追究刑事责任；尚不构成犯罪的，对直接负责的主管人员和其他直接责任人员依法给予行政处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2294028, '《社会保险费征缴暂行条例》', '第二十九条', '劳动', '行政法规', NULL, '国务院 2019-03-24', '第五章 附则', NULL, '省、自治区、直辖市人民政府根据本地实际情况，可以决定本条例适用于本行政区域内工伤保险费和生育保险费的征收、缴纳。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2294029, '《社会保险费征缴暂行条例》', '第三十条', '劳动', '行政法规', NULL, '国务院 2019-03-24', '第五章 附则', NULL, '税务机关、社会保险经办机构征收社会保险费，不得从社会保险基金中提取任何费用，所需经费列入预算，由财政拨付。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2294030, '《社会保险费征缴暂行条例》', '第三十一条', '劳动', '行政法规', NULL, '国务院 2019-03-24', '第五章 附则', NULL, '本条例自发布之日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486000, '《事业单位人事管理条例》', '第一条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第一章 总则', NULL, '为了规范事业单位的人事管理，保障事业单位工作人员的合法权益，建设高素质的事业单位工作人员队伍，促进公共服务发展，制定本条例。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486001, '《事业单位人事管理条例》', '第二条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第一章 总则', NULL, '事业单位人事管理，坚持党管干部、党管人才原则，全面准确贯彻民主、公开、竞争、择优方针。 国家对事业单位工作人员实行分级分类管理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486002, '《事业单位人事管理条例》', '第三条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第一章 总则', NULL, '中央事业单位人事综合管理部门负责全国事业单位人事综合管理工作。 县级以上地方各级事业单位人事综合管理部门负责本辖区事业单位人事综合管理工作。 事业单位主管部门具体负责所属事业单位人事管理工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486003, '《事业单位人事管理条例》', '第四条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第一章 总则', NULL, '事业单位应当建立健全人事管理制度。 事业单位制定或者修改人事管理制度，应当通过职工代表大会或者其他形式听取工作人员意见。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486004, '《事业单位人事管理条例》', '第五条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第二章 岗位设置', NULL, '国家建立事业单位岗位管理制度，明确岗位类别和等级。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486005, '《事业单位人事管理条例》', '第六条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第二章 岗位设置', NULL, '事业单位根据职责任务和工作需要，按照国家有关规定设置岗位。 岗位应当具有明确的名称、职责任务、工作标准和任职条件。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486006, '《事业单位人事管理条例》', '第七条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第二章 岗位设置', NULL, '事业单位拟订岗位设置方案，应当报人事综合管理部门备案。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486007, '《事业单位人事管理条例》', '第八条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第三章 公开招聘和竞聘上岗', NULL, '事业单位新聘用工作人员，应当面向社会公开招聘。但是，国家政策性安置、按照人事管理权限由上级任命、涉密岗位等人员除外。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486008, '《事业单位人事管理条例》', '第九条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第三章 公开招聘和竞聘上岗', NULL, '事业单位公开招聘工作人员按照下列程序进行： (一)制定公开招聘方案； (二)公布招聘岗位、资格条件等招聘信息； (三)审查应聘人员资格条件； (四)考试、考察； (五)体检； (六)公示拟聘人员名单； (七)订立聘用合同，办理聘用手续。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486009, '《事业单位人事管理条例》', '第十条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第三章 公开招聘和竞聘上岗', NULL, '事业单位内部产生岗位人选，需要竞聘上岗的，按照下列程序进行： (一)制定竞聘上岗方案； (二)在本单位公布竞聘岗位、资格条件、聘期等信息； (三)审查竞聘人员资格条件； (四)考评； (五)在本单位公示拟聘人员名单； (六)办理聘任手续。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486010, '《事业单位人事管理条例》', '第十一条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第三章 公开招聘和竞聘上岗', NULL, '事业单位工作人员可以按照国家有关规定进行交流。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486011, '《事业单位人事管理条例》', '第十二条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第四章 聘用合同', NULL, '事业单位与工作人员订立的聘用合同，期限一般不低于3年。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486012, '《事业单位人事管理条例》', '第十三条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第四章 聘用合同', NULL, '初次就业的工作人员与事业单位订立的聘用合同期限3年以上的，试用期为12个月。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486013, '《事业单位人事管理条例》', '第十四条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第四章 聘用合同', NULL, '事业单位工作人员在本单位连续工作满10年且距法定退休年龄不足10年，提出订立聘用至退休的合同的，事业单位应当与其订立聘用至退休的合同。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486014, '《事业单位人事管理条例》', '第十五条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第四章 聘用合同', NULL, '事业单位工作人员连续旷工超过15个工作日，或者1年内累计旷工超过30个工作日的，事业单位可以解除聘用合同。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486015, '《事业单位人事管理条例》', '第十六条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第四章 聘用合同', NULL, '事业单位工作人员年度考核不合格且不同意调整工作岗位，或者连续两年年度考核不合格的，事业单位提前30日书面通知，可以解除聘用合同。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486016, '《事业单位人事管理条例》', '第十七条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第四章 聘用合同', NULL, '事业单位工作人员提前30日书面通知事业单位，可以解除聘用合同。但是，双方对解除聘用合同另有约定的除外。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486017, '《事业单位人事管理条例》', '第十八条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第四章 聘用合同', NULL, '事业单位工作人员受到开除处分的，解除聘用合同。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486018, '《事业单位人事管理条例》', '第十九条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第四章 聘用合同', NULL, '自聘用合同依法解除、终止之日起，事业单位与被解除、终止聘用合同人员的人事关系终止。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486019, '《事业单位人事管理条例》', '第二十条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第五章 考核和培训', NULL, '事业单位应当根据聘用合同规定的岗位职责任务，全面考核工作人员的表现，重点考核工作绩效。考核应当听取服务对象的意见和评价。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486020, '《事业单位人事管理条例》', '第二十一条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第五章 考核和培训', NULL, '考核分为平时考核、年度考核和聘期考核。 年度考核的结果可以分为优秀、合格、基本合格和不合格等档次，聘期考核的结果可以分为合格和不合格等档次。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486021, '《事业单位人事管理条例》', '第二十二条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第五章 考核和培训', NULL, '考核结果作为调整事业单位工作人员岗位、工资以及续订聘用合同的依据。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486022, '《事业单位人事管理条例》', '第二十三条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第五章 考核和培训', NULL, '事业单位应当根据不同岗位的要求，编制工作人员培训计划，对工作人员进行分级分类培训。 工作人员应当按照所在单位的要求，参加岗前培训、在岗培训、转岗培训和为完成特定任务的专项培训。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486023, '《事业单位人事管理条例》', '第二十四条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第五章 考核和培训', NULL, '培训经费按照国家有关规定列支。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486024, '《事业单位人事管理条例》', '第二十五条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第六章 奖励和处分', NULL, '事业单位工作人员或者集体有下列情形之一的，给予奖励： (一)长期服务基层，爱岗敬业，表现突出的； (二)在执行国家重要任务、应对重大突发事件中表现突出的； (三)在工作中有重大发明创造、技术革新的； (四)在培养人才、传播先进文化中作出突出贡献的； (五)有其他突出贡献的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486025, '《事业单位人事管理条例》', '第二十六条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第六章 奖励和处分', NULL, '奖励坚持精神奖励与物质奖励相结合、以精神奖励为主的原则。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486026, '《事业单位人事管理条例》', '第二十七条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第六章 奖励和处分', NULL, '奖励分为嘉奖、记功、记大功、授予荣誉称号。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486027, '《事业单位人事管理条例》', '第二十八条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第六章 奖励和处分', NULL, '事业单位工作人员有下列行为之一的，给予处分： (一)损害国家声誉和利益的； (二)失职渎职的； (三)利用工作之便谋取不正当利益的； (四)挥霍、浪费国家资财的； (五)严重违反职业道德、社会公德的； (六)其他严重违反纪律的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486028, '《事业单位人事管理条例》', '第二十九条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第六章 奖励和处分', NULL, '处分分为警告、记过、降低岗位等级或者撤职、开除。 受处分的期间为：警告，6个月；记过，12个月；降低岗位等级或者撤职，24个月。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486029, '《事业单位人事管理条例》', '第三十条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第六章 奖励和处分', NULL, '给予工作人员处分，应当事实清楚、证据确凿、定性准确、处理恰当、程序合法、手续完备。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486030, '《事业单位人事管理条例》', '第三十一条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第六章 奖励和处分', NULL, '工作人员受开除以外的处分，在受处分期间没有再发生违纪行为的，处分期满后，由处分决定单位解除处分并以书面形式通知本人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486031, '《事业单位人事管理条例》', '第三十二条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第七章 工资福利和社会保险', NULL, '国家建立激励与约束相结合的事业单位工资制度。 事业单位工作人员工资包括基本工资、绩效工资和津贴补贴。 事业单位工资分配应当结合不同行业事业单位特点，体现岗位职责、工作业绩、实际贡献等因素。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486032, '《事业单位人事管理条例》', '第三十三条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第七章 工资福利和社会保险', NULL, '国家建立事业单位工作人员工资的正常增长机制。 事业单位工作人员的工资水平应当与国民经济发展相协调、与社会进步相适应。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486033, '《事业单位人事管理条例》', '第三十四条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第七章 工资福利和社会保险', NULL, '事业单位工作人员享受国家规定的福利待遇。 事业单位执行国家规定的工时制度和休假制度。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486034, '《事业单位人事管理条例》', '第三十五条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第七章 工资福利和社会保险', NULL, '事业单位及其工作人员依法参加社会保险，工作人员依法享受社会保险待遇。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486035, '《事业单位人事管理条例》', '第三十六条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第七章 工资福利和社会保险', NULL, '事业单位工作人员符合国家规定退休条件的，应当退休。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486036, '《事业单位人事管理条例》', '第三十七条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第八章 人事争议处理', NULL, '事业单位工作人员与所在单位发生人事争议的，依照《中华人民共和国劳动争议调解仲裁法》等有关规定处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486037, '《事业单位人事管理条例》', '第三十八条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第八章 人事争议处理', NULL, '事业单位工作人员对涉及本人的考核结果、处分决定等不服的，可以按照国家有关规定申请复核、提出申诉。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486038, '《事业单位人事管理条例》', '第三十九条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第八章 人事争议处理', NULL, '负有事业单位聘用、考核、奖励、处分、人事争议处理等职责的人员履行职责，有下列情形之一的，应当回避： (一)与本人有利害关系的； (二)与本人近亲属有利害关系的； (三)其他可能影响公正履行职责的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486039, '《事业单位人事管理条例》', '第四十条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第八章 人事争议处理', NULL, '对事业单位人事管理工作中的违法违纪行为，任何单位或者个人可以向事业单位人事综合管理部门、主管部门或者监察机关投诉、举报，有关部门和机关应当及时调查处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486040, '《事业单位人事管理条例》', '第四十一条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第九章 法律责任', NULL, '事业单位违反本条例规定的，由县级以上事业单位人事综合管理部门或者主管部门责令限期改正；逾期不改正的，对直接负责的主管人员和其他直接责任人员依法给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486041, '《事业单位人事管理条例》', '第四十二条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第九章 法律责任', NULL, '对事业单位工作人员的人事处理违反本条例规定给当事人造成名誉损害的，应当赔礼道歉、恢复名誉、消除影响；造成经济损失的，依法给予赔偿。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486042, '《事业单位人事管理条例》', '第四十三条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第九章 法律责任', NULL, '事业单位人事综合管理部门和主管部门的工作人员在事业单位人事管理工作中滥用职权、玩忽职守、徇私舞弊的，依法给予处分；构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2486043, '《事业单位人事管理条例》', '第四十四条', '劳动', '行政法规', NULL, '国务院 2014-04-25', '第十章 附则', NULL, '本条例自2014年7月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2517500, '《女职工劳动保护特别规定》', '第一条', '劳动', '行政法规', NULL, '国务院 2012-04-28', NULL, NULL, '为了减少和解决女职工在劳动中因生理特点造成的特殊困难，保护女职工健康，制定本规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2517501, '《女职工劳动保护特别规定》', '第二条', '劳动', '行政法规', NULL, '国务院 2012-04-28', NULL, NULL, '中华人民共和国境内的国家机关、企业、事业单位、社会团体、个体经济组织以及其他社会组织等用人单位及其女职工，适用本规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2517502, '《女职工劳动保护特别规定》', '第三条', '劳动', '行政法规', NULL, '国务院 2012-04-28', NULL, NULL, '用人单位应当加强女职工劳动保护，采取措施改善女职工劳动安全卫生条件，对女职工进行劳动安全卫生知识培训。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2517503, '《女职工劳动保护特别规定》', '第四条', '劳动', '行政法规', NULL, '国务院 2012-04-28', NULL, NULL, '用人单位应当遵守女职工禁忌从事的劳动范围的规定。用人单位应当将本单位属于女职工禁忌从事的劳动范围的岗位书面告知女职工。 女职工禁忌从事的劳动范围由本规定附录列示。国务院安全生产监督管理部门会同国务院人力资源社会保障行政部门、国务院卫生行政部门根据经济社会发展情况，对女职工禁忌从事的劳动范围进行调整。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2517504, '《女职工劳动保护特别规定》', '第五条', '劳动', '行政法规', NULL, '国务院 2012-04-28', NULL, NULL, '用人单位不得因女职工怀孕、生育、哺乳降低其工资、予以辞退、与其解除劳动或者聘用合同。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2517505, '《女职工劳动保护特别规定》', '第六条', '劳动', '行政法规', NULL, '国务院 2012-04-28', NULL, NULL, '女职工在孕期不能适应原劳动的，用人单位应当根据医疗机构的证明，予以减轻劳动量或者安排其他能够适应的劳动。 对怀孕7个月以上的女职工，用人单位不得延长劳动时间或者安排夜班劳动，并应当在劳动时间内安排一定的休息时间。 怀孕女职工在劳动时间内进行产前检查，所需时间计入劳动时间。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2517506, '《女职工劳动保护特别规定》', '第七条', '劳动', '行政法规', NULL, '国务院 2012-04-28', NULL, NULL, '女职工生育享受98天产假，其中产前可以休假15天；难产的，增加产假15天；生育多胞胎的，每多生育1个婴儿，增加产假15天。 女职工怀孕未满4个月流产的，享受15天产假；怀孕满4个月流产的，享受42天产假。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2517507, '《女职工劳动保护特别规定》', '第八条', '劳动', '行政法规', NULL, '国务院 2012-04-28', NULL, NULL, '女职工产假期间的生育津贴，对已经参加生育保险的，按照用人单位上年度职工月平均工资的标准由生育保险基金支付；对未参加生育保险的，按照女职工产假前工资的标准由用人单位支付。 女职工生育或者流产的医疗费用，按照生育保险规定的项目和标准，对已经参加生育保险的，由生育保险基金支付；对未参加生育保险的，由用人单位支付。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2517508, '《女职工劳动保护特别规定》', '第九条', '劳动', '行政法规', NULL, '国务院 2012-04-28', NULL, NULL, '对哺乳未满1周岁婴儿的女职工，用人单位不得延长劳动时间或者安排夜班劳动。 用人单位应当在每天的劳动时间内为哺乳期女职工安排1小时哺乳时间；女职工生育多胞胎的，每多哺乳1个婴儿每天增加1小时哺乳时间。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2517509, '《女职工劳动保护特别规定》', '第十条', '劳动', '行政法规', NULL, '国务院 2012-04-28', NULL, NULL, '女职工比较多的用人单位应当根据女职工的需要，建立女职工卫生室、孕妇休息室、哺乳室等设施，妥善解决女职工在生理卫生、哺乳方面的困难。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2517510, '《女职工劳动保护特别规定》', '第十一条', '劳动', '行政法规', NULL, '国务院 2012-04-28', NULL, NULL, '在劳动场所，用人单位应当预防和制止对女职工的性骚扰。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2517511, '《女职工劳动保护特别规定》', '第十二条', '劳动', '行政法规', NULL, '国务院 2012-04-28', NULL, NULL, '县级以上人民政府人力资源社会保障行政部门、安全生产监督管理部门按照各自职责负责对用人单位遵守本规定的情况进行监督检查。 工会、妇女组织依法对用人单位遵守本规定的情况进行监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2517512, '《女职工劳动保护特别规定》', '第十三条', '劳动', '行政法规', NULL, '国务院 2012-04-28', NULL, NULL, '用人单位违反本规定第六条第二款、第七条、第九条第一款规定的，由县级以上人民政府人力资源社会保障行政部门责令限期改正，按照受侵害女职工每人1000元以上5000元以下的标准计算，处以罚款。 用人单位违反本规定附录第一条、第二条规定的，由县级以上人民政府安全生产监督管理部门责令限期改正，按照受侵害女职工每人1000元以上5000元以下的标准计算，处以罚款。用人单位违反本规定附录第三条、第四条规定的，由县级以上人民政府安全生产监督管理部门责令限期治理，处5万元以上30万元以下的罚款；情节严重的，责令停止有关作业，或者提请有关人民政府按照国务院规定的权限责令关闭。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2517513, '《女职工劳动保护特别规定》', '第十四条', '劳动', '行政法规', NULL, '国务院 2012-04-28', NULL, NULL, '用人单位违反本规定，侵害女职工合法权益的，女职工可以依法投诉、举报、申诉，依法向劳动人事争议调解仲裁机构申请调解仲裁，对仲裁裁决不服的，依法向人民法院提起诉讼。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2517514, '《女职工劳动保护特别规定》', '第十五条', '劳动', '行政法规', NULL, '国务院 2012-04-28', NULL, NULL, '用人单位违反本规定，侵害女职工合法权益，造成女职工损害的，依法给予赔偿；用人单位及其直接负责的主管人员和其他直接责任人员构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2517515, '《女职工劳动保护特别规定》', '第十六条', '劳动', '行政法规', NULL, '国务院 2012-04-28', NULL, NULL, '本规定自公布之日起施行。1988年7月21日国务院发布的《女职工劳动保护规定》同时废止。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2517516, '《女职工劳动保护特别规定》', '附录', '劳动', '行政法规', '女职工禁忌从事的劳动范围', '国务院 2012-04-28', NULL, NULL, '一、女职工禁忌从事的劳动范围： (一)矿山井下作业； (二)体力劳动强度分级标准中规定的第四级体力劳动强度的作业； (三)每小时负重6次以上、每次负重超过20公斤的作业，或者间断负重、每次负重超过25公斤的作业。 二、女职工在经期禁忌从事的劳动范围： (一)冷水作业分级标准中规定的第二级、第三级、第四级冷水作业； (二)低温作业分级标准中规定的第二级、第三级、第四级低温作业； (三)体力劳动强度分级标准中规定的第三级、第四级体力劳动强度的作业； (四)高处作业分级标准中规定的第三级、第四级高处作业。 三、女职工在孕期禁忌从事的劳动范围： (一)作业场所空气中铅及其化合物、汞及其化合物、苯、镉、铍、砷、氰化物、氮氧化物、一氧化碳、二硫化碳、氯、己内酰胺、氯丁二烯、氯乙烯、环氧乙烷、苯胺、甲醛等有毒物质浓度超过国家职业卫生标准的作业； (二)从事抗癌药物、己烯雌酚生产，接触麻醉剂气体等的作业； (三)非密封源放射性物质的操作，核事故与放射事故的应急处置； (四)高处作业分级标准中规定的高处作业； (五)冷水作业分级标准中规定的冷水作业； (六)低温作业分级标准中规定的低温作业； (七)高温作业分级标准中规定的第三级、第四级的作业； (八)噪声作业分级标准中规定的第三级、第四级的作业； (九)体力劳动强度分级标准中规定的第三级、第四级体力劳动强度的作业； (十)在密闭空间、高压室作业或者潜水作业，伴有强烈振动的作业，或者需要频繁弯腰、攀高、下蹲的作业。 四、女职工在哺乳期禁忌从事的劳动范围： (一)孕期禁忌从事的劳动范围的第一项、第三项、第九项； (二)作业场所空气中锰、氟、溴、甲醇、有机磷化合物、有机氯化合物等有毒物质浓度超过国家职业卫生标准的作业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598500, '《工伤保险条例》', '第一条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第一章 总则', NULL, '为了保障因工作遭受事故伤害或者患职业病的职工获得医疗救治和经济补偿，促进工伤预防和职业康复，分散用人单位的工伤风险，制定本条例。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598501, '《工伤保险条例》', '第二条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第一章 总则', NULL, '中华人民共和国境内的企业、事业单位、社会团体、民办非企业单位、基金会、律师事务所、会计师事务所等组织和有雇工的个体工商户(以下称用人单位)应当依照本条例规定参加工伤保险，为本单位全部职工或者雇工(以下称职工)缴纳工伤保险费。 中华人民共和国境内的企业、事业单位、社会团体、民办非企业单位、基金会、律师事务所、会计师事务所等组织的职工和个体工商户的雇工，均有依照本条例的规定享受工伤保险待遇的权利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598502, '《工伤保险条例》', '第三条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第一章 总则', NULL, '工伤保险费的征缴按照《社会保险费征缴暂行条例》关于基本养老保险费、基本医疗保险费、失业保险费的征缴规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598503, '《工伤保险条例》', '第四条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第一章 总则', NULL, '用人单位应当将参加工伤保险的有关情况在本单位内公示。 用人单位和职工应当遵守有关安全生产和职业病防治的法律法规，执行安全卫生规程和标准，预防工伤事故发生，避免和减少职业病危害。 职工发生工伤时，用人单位应当采取措施使工伤职工得到及时救治。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598504, '《工伤保险条例》', '第五条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第一章 总则', NULL, '国务院社会保险行政部门负责全国的工伤保险工作。 县级以上地方各级人民政府社会保险行政部门负责本行政区域内的工伤保险工作。 社会保险行政部门按照国务院有关规定设立的社会保险经办机构(以下称经办机构)具体承办工伤保险事务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598505, '《工伤保险条例》', '第六条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第一章 总则', NULL, '社会保险行政部门等部门制定工伤保险的政策、标准，应当征求工会组织、用人单位代表的意见。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598506, '《工伤保险条例》', '第七条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第二章 工伤保险基金', NULL, '工伤保险基金由用人单位缴纳的工伤保险费、工伤保险基金的利息和依法纳入工伤保险基金的其他资金构成。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598507, '《工伤保险条例》', '第八条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第二章 工伤保险基金', NULL, '工伤保险费根据以支定收、收支平衡的原则，确定费率。 国家根据不同行业的工伤风险程度确定行业的差别费率，并根据工伤保险费使用、工伤发生率等情况在每个行业内确定若干费率档次。行业差别费率及行业内费率档次由国务院社会保险行政部门制定，报国务院批准后公布施行。 统筹地区经办机构根据用人单位工伤保险费使用、工伤发生率等情况，适用所属行业内相应的费率档次确定单位缴费费率。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598508, '《工伤保险条例》', '第九条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第二章 工伤保险基金', NULL, '国务院社会保险行政部门应当定期了解全国各统筹地区工伤保险基金收支情况，及时提出调整行业差别费率及行业内费率档次的方案，报国务院批准后公布施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598509, '《工伤保险条例》', '第十条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第二章 工伤保险基金', NULL, '用人单位应当按时缴纳工伤保险费。职工个人不缴纳工伤保险费。 用人单位缴纳工伤保险费的数额为本单位职工工资总额乘以单位缴费费率之积。 对难以按照工资总额缴纳工伤保险费的行业，其缴纳工伤保险费的具体方式，由国务院社会保险行政部门规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598510, '《工伤保险条例》', '第十一条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第二章 工伤保险基金', NULL, '工伤保险基金逐步实行省级统筹。 跨地区、生产流动性较大的行业，可以采取相对集中的方式异地参加统筹地区的工伤保险。具体办法由国务院社会保险行政部门会同有关行业的主管部门制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598511, '《工伤保险条例》', '第十二条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第二章 工伤保险基金', NULL, '工伤保险基金存入社会保障基金财政专户，用于本条例规定的工伤保险待遇，劳动能力鉴定，工伤预防的宣传、培训等费用，以及法律、法规规定的用于工伤保险的其他费用的支付。 工伤预防费用的提取比例、使用和管理的具体办法，由国务院社会保险行政部门会同国务院财政、卫生行政、安全生产监督管理等部门规定。 任何单位或者个人不得将工伤保险基金用于投资运营、兴建或者改建办公场所、发放奖金，或者挪作其他用途。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598512, '《工伤保险条例》', '第十三条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第二章 工伤保险基金', NULL, '工伤保险基金应当留有一定比例的储备金，用于统筹地区重大事故的工伤保险待遇支付；储备金不足支付的，由统筹地区的人民政府垫付。储备金占基金总额的具体比例和储备金的使用办法，由省、自治区、直辖市人民政府规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598513, '《工伤保险条例》', '第十四条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第三章 工伤认定', NULL, '职工有下列情形之一的，应当认定为工伤： (一)在工作时间和工作场所内，因工作原因受到事故伤害的； (二)工作时间前后在工作场所内，从事与工作有关的预备性或者收尾性工作受到事故伤害的； (三)在工作时间和工作场所内，因履行工作职责受到暴力等意外伤害的； (四)患职业病的； (五)因工外出期间，由于工作原因受到伤害或者发生事故下落不明的； (六)在上下班途中，受到非本人主要责任的交通事故或者城市轨道交通、客运轮渡、火车事故伤害的； (七)法律、行政法规规定应当认定为工伤的其他情形。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598514, '《工伤保险条例》', '第十五条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第三章 工伤认定', NULL, '职工有下列情形之一的，视同工伤： (一)在工作时间和工作岗位，突发疾病死亡或者在48小时之内经抢救无效死亡的； (二)在抢险救灾等维护国家利益、公共利益活动中受到伤害的； (三)职工原在军队服役，因战、因公负伤致残，已取得革命伤残军人证，到用人单位后旧伤复发的。 职工有前款第(一)项、第(二)项情形的，按照本条例的有关规定享受工伤保险待遇；职工有前款第(三)项情形的，按照本条例的有关规定享受除一次性伤残补助金以外的工伤保险待遇。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598515, '《工伤保险条例》', '第十六条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第三章 工伤认定', NULL, '职工符合本条例第十四条、第十五条的规定，但是有下列情形之一的，不得认定为工伤或者视同工伤： (一)故意犯罪的； (二)醉酒或者吸毒的； (三)自残或者自杀的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598516, '《工伤保险条例》', '第十七条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第三章 工伤认定', NULL, '职工发生事故伤害或者按照职业病防治法规定被诊断、鉴定为职业病，所在单位应当自事故伤害发生之日或者被诊断、鉴定为职业病之日起30日内，向统筹地区社会保险行政部门提出工伤认定申请。遇有特殊情况，经报社会保险行政部门同意，申请时限可以适当延长。 用人单位未按前款规定提出工伤认定申请的，工伤职工或者其近亲属、工会组织在事故伤害发生之日或者被诊断、鉴定为职业病之日起1年内，可以直接向用人单位所在地统筹地区社会保险行政部门提出工伤认定申请。 按照本条第一款规定应当由省级社会保险行政部门进行工伤认定的事项，根据属地原则由用人单位所在地的设区的市级社会保险行政部门办理。 用人单位未在本条第一款规定的时限内提交工伤认定申请，在此期间发生符合本条例规定的工伤待遇等有关费用由该用人单位负担。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598517, '《工伤保险条例》', '第十八条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第三章 工伤认定', NULL, '提出工伤认定申请应当提交下列材料： (一)工伤认定申请表； (二)与用人单位存在劳动关系(包括事实劳动关系)的证明材料； (三)医疗诊断证明或者职业病诊断证明书(或者职业病诊断鉴定书)。 工伤认定申请表应当包括事故发生的时间、地点、原因以及职工伤害程度等基本情况。 工伤认定申请人提供材料不完整的，社会保险行政部门应当一次性书面告知工伤认定申请人需要补正的全部材料。申请人按照书面告知要求补正材料后，社会保险行政部门应当受理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598518, '《工伤保险条例》', '第十九条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第三章 工伤认定', NULL, '社会保险行政部门受理工伤认定申请后，根据审核需要可以对事故伤害进行调查核实，用人单位、职工、工会组织、医疗机构以及有关部门应当予以协助。职业病诊断和诊断争议的鉴定，依照职业病防治法的有关规定执行。对依法取得职业病诊断证明书或者职业病诊断鉴定书的，社会保险行政部门不再进行调查核实。 职工或者其近亲属认为是工伤，用人单位不认为是工伤的，由用人单位承担举证责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598519, '《工伤保险条例》', '第二十条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第三章 工伤认定', NULL, '社会保险行政部门应当自受理工伤认定申请之日起60日内作出工伤认定的决定，并书面通知申请工伤认定的职工或者其近亲属和该职工所在单位。 社会保险行政部门对受理的事实清楚、权利义务明确的工伤认定申请，应当在15日内作出工伤认定的决定。 作出工伤认定决定需要以司法机关或者有关行政主管部门的结论为依据的，在司法机关或者有关行政主管部门尚未作出结论期间，作出工伤认定决定的时限中止。 社会保险行政部门工作人员与工伤认定申请人有利害关系的，应当回避。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598520, '《工伤保险条例》', '第二十一条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第四章 劳动能力鉴定', NULL, '职工发生工伤，经治疗伤情相对稳定后存在残疾、影响劳动能力的，应当进行劳动能力鉴定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598521, '《工伤保险条例》', '第二十二条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第四章 劳动能力鉴定', NULL, '劳动能力鉴定是指劳动功能障碍程度和生活自理障碍程度的等级鉴定。 劳动功能障碍分为十个伤残等级，最重的为一级，最轻的为十级。 生活自理障碍分为三个等级：生活完全不能自理、生活大部分不能自理和生活部分不能自理。 劳动能力鉴定标准由国务院社会保险行政部门会同国务院卫生行政部门等部门制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598522, '《工伤保险条例》', '第二十三条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第四章 劳动能力鉴定', NULL, '劳动能力鉴定由用人单位、工伤职工或者其近亲属向设区的市级劳动能力鉴定委员会提出申请，并提供工伤认定决定和职工工伤医疗的有关资料。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598523, '《工伤保险条例》', '第二十四条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第四章 劳动能力鉴定', NULL, '省、自治区、直辖市劳动能力鉴定委员会和设区的市级劳动能力鉴定委员会分别由省、自治区、直辖市和设区的市级社会保险行政部门、卫生行政部门、工会组织、经办机构代表以及用人单位代表组成。 劳动能力鉴定委员会建立医疗卫生专家库。列入专家库的医疗卫生专业技术人员应当具备下列条件： (一)具有医疗卫生高级专业技术职务任职资格； (二)掌握劳动能力鉴定的相关知识； (三)具有良好的职业品德。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598524, '《工伤保险条例》', '第二十五条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第四章 劳动能力鉴定', NULL, '设区的市级劳动能力鉴定委员会收到劳动能力鉴定申请后，应当从其建立的医疗卫生专家库中随机抽取3名或者5名相关专家组成专家组，由专家组提出鉴定意见。设区的市级劳动能力鉴定委员会根据专家组的鉴定意见作出工伤职工劳动能力鉴定结论；必要时，可以委托具备资格的医疗机构协助进行有关的诊断。 设区的市级劳动能力鉴定委员会应当自收到劳动能力鉴定申请之日起60日内作出劳动能力鉴定结论，必要时，作出劳动能力鉴定结论的期限可以延长30日。劳动能力鉴定结论应当及时送达申请鉴定的单位和个人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598525, '《工伤保险条例》', '第二十六条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第四章 劳动能力鉴定', NULL, '申请鉴定的单位或者个人对设区的市级劳动能力鉴定委员会作出的鉴定结论不服的，可以在收到该鉴定结论之日起15日内向省、自治区、直辖市劳动能力鉴定委员会提出再次鉴定申请。省、自治区、直辖市劳动能力鉴定委员会作出的劳动能力鉴定结论为最终结论。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598526, '《工伤保险条例》', '第二十七条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第四章 劳动能力鉴定', NULL, '劳动能力鉴定工作应当客观、公正。劳动能力鉴定委员会组成人员或者参加鉴定的专家与当事人有利害关系的，应当回避。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598527, '《工伤保险条例》', '第二十八条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第四章 劳动能力鉴定', NULL, '自劳动能力鉴定结论作出之日起1年后，工伤职工或者其近亲属、所在单位或者经办机构认为伤残情况发生变化的，可以申请劳动能力复查鉴定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598528, '《工伤保险条例》', '第二十九条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第四章 劳动能力鉴定', NULL, '劳动能力鉴定委员会依照本条例第二十六条和第二十八条的规定进行再次鉴定和复查鉴定的期限，依照本条例第二十五条第二款的规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598529, '《工伤保险条例》', '第三十条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第五章 工伤保险待遇', NULL, '职工因工作遭受事故伤害或者患职业病进行治疗，享受工伤医疗待遇。 职工治疗工伤应当在签订服务协议的医疗机构就医，情况紧急时可以先到就近的医疗机构急救。 治疗工伤所需费用符合工伤保险诊疗项目目录、工伤保险药品目录、工伤保险住院服务标准的，从工伤保险基金支付。工伤保险诊疗项目目录、工伤保险药品目录、工伤保险住院服务标准，由国务院社会保险行政部门会同国务院卫生行政部门、食品药品监督管理部门等部门规定。 职工住院治疗工伤的伙食补助费，以及经医疗机构出具证明，报经办机构同意，工伤职工到统筹地区以外就医所需的交通、食宿费用从工伤保险基金支付，基金支付的具体标准由统筹地区人民政府规定。 工伤职工治疗非工伤引发的疾病，不享受工伤医疗待遇，按照基本医疗保险办法处理。 工伤职工到签订服务协议的医疗机构进行工伤康复的费用，符合规定的，从工伤保险基金支付。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598530, '《工伤保险条例》', '第三十一条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第五章 工伤保险待遇', NULL, '社会保险行政部门作出认定为工伤的决定后发生行政复议、行政诉讼的，行政复议和行政诉讼期间不停止支付工伤职工治疗工伤的医疗费用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598531, '《工伤保险条例》', '第三十二条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第五章 工伤保险待遇', NULL, '工伤职工因日常生活或者就业需要，经劳动能力鉴定委员会确认，可以安装假肢、矫形器、假眼、假牙和配置轮椅等辅助器具，所需费用按照国家规定的标准从工伤保险基金支付。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598532, '《工伤保险条例》', '第三十三条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第五章 工伤保险待遇', NULL, '职工因工作遭受事故伤害或者患职业病需要暂停工作接受工伤医疗的，在停工留薪期内，原工资福利待遇不变，由所在单位按月支付。 停工留薪期一般不超过12个月。伤情严重或者情况特殊，经设区的市级劳动能力鉴定委员会确认，可以适当延长，但延长不得超过12个月。工伤职工评定伤残等级后，停发原待遇，按照本章的有关规定享受伤残待遇。工伤职工在停工留薪期满后仍需治疗的，继续享受工伤医疗待遇。 生活不能自理的工伤职工在停工留薪期需要护理的，由所在单位负责。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598533, '《工伤保险条例》', '第三十四条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第五章 工伤保险待遇', NULL, '工伤职工已经评定伤残等级并经劳动能力鉴定委员会确认需要生活护理的，从工伤保险基金按月支付生活护理费。 生活护理费按照生活完全不能自理、生活大部分不能自理或者生活部分不能自理3个不同等级支付，其标准分别为统筹地区上年度职工月平均工资的50%、40%或者30%。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598534, '《工伤保险条例》', '第三十五条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第五章 工伤保险待遇', NULL, '职工因工致残被鉴定为一级至四级伤残的，保留劳动关系，退出工作岗位，享受以下待遇： (一)从工伤保险基金按伤残等级支付一次性伤残补助金，标准为：一级伤残为27个月的本人工资，二级伤残为25个月的本人工资，三级伤残为23个月的本人工资，四级伤残为21个月的本人工资； (二)从工伤保险基金按月支付伤残津贴，标准为：一级伤残为本人工资的90%，二级伤残为本人工资的85%，三级伤残为本人工资的80%，四级伤残为本人工资的75%。伤残津贴实际金额低于当地最低工资标准的，由工伤保险基金补足差额； (三)工伤职工达到退休年龄并办理退休手续后，停发伤残津贴，按照国家有关规定享受基本养老保险待遇。基本养老保险待遇低于伤残津贴的，由工伤保险基金补足差额。 职工因工致残被鉴定为一级至四级伤残的，由用人单位和职工个人以伤残津贴为基数，缴纳基本医疗保险费。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598535, '《工伤保险条例》', '第三十六条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第五章 工伤保险待遇', NULL, '职工因工致残被鉴定为五级、六级伤残的，享受以下待遇： (一)从工伤保险基金按伤残等级支付一次性伤残补助金，标准为：五级伤残为18个月的本人工资，六级伤残为16个月的本人工资； (二)保留与用人单位的劳动关系，由用人单位安排适当工作。难以安排工作的，由用人单位按月发给伤残津贴，标准为：五级伤残为本人工资的70%，六级伤残为本人工资的60%，并由用人单位按照规定为其缴纳应缴纳的各项社会保险费。伤残津贴实际金额低于当地最低工资标准的，由用人单位补足差额。 经工伤职工本人提出，该职工可以与用人单位解除或者终止劳动关系，由工伤保险基金支付一次性工伤医疗补助金，由用人单位支付一次性伤残就业补助金。一次性工伤医疗补助金和一次性伤残就业补助金的具体标准由省、自治区、直辖市人民政府规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598536, '《工伤保险条例》', '第三十七条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第五章 工伤保险待遇', NULL, '职工因工致残被鉴定为七级至十级伤残的，享受以下待遇： (一)从工伤保险基金按伤残等级支付一次性伤残补助金，标准为：七级伤残为13个月的本人工资，八级伤残为11个月的本人工资，九级伤残为9个月的本人工资，十级伤残为7个月的本人工资； (二)劳动、聘用合同期满终止，或者职工本人提出解除劳动、聘用合同的，由工伤保险基金支付一次性工伤医疗补助金，由用人单位支付一次性伤残就业补助金。一次性工伤医疗补助金和一次性伤残就业补助金的具体标准由省、自治区、直辖市人民政府规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598537, '《工伤保险条例》', '第三十八条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第五章 工伤保险待遇', NULL, '工伤职工工伤复发，确认需要治疗的，享受本条例第三十条、第三十二条和第三十三条规定的工伤待遇。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598538, '《工伤保险条例》', '第三十九条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第五章 工伤保险待遇', NULL, '职工因工死亡，其近亲属按照下列规定从工伤保险基金领取丧葬补助金、供养亲属抚恤金和一次性工亡补助金： (一)丧葬补助金为6个月的统筹地区上年度职工月平均工资； (二)供养亲属抚恤金按照职工本人工资的一定比例发给由因工死亡职工生前提供主要生活来源、无劳动能力的亲属。标准为：配偶每月40%，其他亲属每人每月30%，孤寡老人或者孤儿每人每月在上述标准的基础上增加10%。核定的各供养亲属的抚恤金之和不应高于因工死亡职工生前的工资。供养亲属的具体范围由国务院社会保险行政部门规定； (三)一次性工亡补助金标准为上一年度全国城镇居民人均可支配收入的20倍。 伤残职工在停工留薪期内因工伤导致死亡的，其近亲属享受本条第一款规定的待遇。 一级至四级伤残职工在停工留薪期满后死亡的，其近亲属可以享受本条第一款第(一)项、第(二)项规定的待遇。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598539, '《工伤保险条例》', '第四十条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第五章 工伤保险待遇', NULL, '伤残津贴、供养亲属抚恤金、生活护理费由统筹地区社会保险行政部门根据职工平均工资和生活费用变化等情况适时调整。调整办法由省、自治区、直辖市人民政府规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598540, '《工伤保险条例》', '第四十一条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第五章 工伤保险待遇', NULL, '职工因工外出期间发生事故或者在抢险救灾中下落不明的，从事故发生当月起3个月内照发工资，从第4个月起停发工资，由工伤保险基金向其供养亲属按月支付供养亲属抚恤金。生活有困难的，可以预支一次性工亡补助金的50%。职工被人民法院宣告死亡的，按照本条例第三十九条职工因工死亡的规定处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598541, '《工伤保险条例》', '第四十二条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第五章 工伤保险待遇', NULL, '工伤职工有下列情形之一的，停止享受工伤保险待遇： (一)丧失享受待遇条件的； (二)拒不接受劳动能力鉴定的； (三)拒绝治疗的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598542, '《工伤保险条例》', '第四十三条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第五章 工伤保险待遇', NULL, '用人单位分立、合并、转让的，承继单位应当承担原用人单位的工伤保险责任；原用人单位已经参加工伤保险的，承继单位应当到当地经办机构办理工伤保险变更登记。 用人单位实行承包经营的，工伤保险责任由职工劳动关系所在单位承担。 职工被借调期间受到工伤事故伤害的，由原用人单位承担工伤保险责任，但原用人单位与借调单位可以约定补偿办法。 企业破产的，在破产清算时依法拨付应当由单位支付的工伤保险待遇费用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598543, '《工伤保险条例》', '第四十四条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第五章 工伤保险待遇', NULL, '职工被派遣出境工作，依据前往国家或者地区的法律应当参加当地工伤保险的，参加当地工伤保险，其国内工伤保险关系中止；不能参加当地工伤保险的，其国内工伤保险关系不中止。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598544, '《工伤保险条例》', '第四十五条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第五章 工伤保险待遇', NULL, '职工再次发生工伤，根据规定应当享受伤残津贴的，按照新认定的伤残等级享受伤残津贴待遇。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598545, '《工伤保险条例》', '第四十六条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第六章 监督管理', NULL, '经办机构具体承办工伤保险事务，履行下列职责： (一)根据省、自治区、直辖市人民政府规定，征收工伤保险费； (二)核查用人单位的工资总额和职工人数，办理工伤保险登记，并负责保存用人单位缴费和职工享受工伤保险待遇情况的记录； (三)进行工伤保险的调查、统计； (四)按照规定管理工伤保险基金的支出； (五)按照规定核定工伤保险待遇； (六)为工伤职工或者其近亲属免费提供咨询服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598546, '《工伤保险条例》', '第四十七条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第六章 监督管理', NULL, '经办机构与医疗机构、辅助器具配置机构在平等协商的基础上签订服务协议，并公布签订服务协议的医疗机构、辅助器具配置机构的名单。具体办法由国务院社会保险行政部门分别会同国务院卫生行政部门、民政部门等部门制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598547, '《工伤保险条例》', '第四十八条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第六章 监督管理', NULL, '经办机构按照协议和国家有关目录、标准对工伤职工医疗费用、康复费用、辅助器具费用的使用情况进行核查，并按时足额结算费用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598548, '《工伤保险条例》', '第四十九条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第六章 监督管理', NULL, '经办机构应当定期公布工伤保险基金的收支情况，及时向社会保险行政部门提出调整费率的建议。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598549, '《工伤保险条例》', '第五十条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第六章 监督管理', NULL, '社会保险行政部门、经办机构应当定期听取工伤职工、医疗机构、辅助器具配置机构以及社会各界对改进工伤保险工作的意见。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598550, '《工伤保险条例》', '第五十一条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第六章 监督管理', NULL, '社会保险行政部门依法对工伤保险费的征缴和工伤保险基金的支付情况进行监督检查。 财政部门和审计机关依法对工伤保险基金的收支、管理情况进行监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598551, '《工伤保险条例》', '第五十二条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第六章 监督管理', NULL, '任何组织和个人对有关工伤保险的违法行为，有权举报。社会保险行政部门对举报应当及时调查，按照规定处理，并为举报人保密。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598552, '《工伤保险条例》', '第五十三条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第六章 监督管理', NULL, '工会组织依法维护工伤职工的合法权益，对用人单位的工伤保险工作实行监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598553, '《工伤保险条例》', '第五十四条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第六章 监督管理', NULL, '职工与用人单位发生工伤待遇方面的争议，按照处理劳动争议的有关规定处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598554, '《工伤保险条例》', '第五十五条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第六章 监督管理', NULL, '有下列情形之一的，有关单位或者个人可以依法申请行政复议，也可以依法向人民法院提起行政诉讼： (一)申请工伤认定的职工或者其近亲属、该职工所在单位对工伤认定申请不予受理的决定不服的； (二)申请工伤认定的职工或者其近亲属、该职工所在单位对工伤认定结论不服的； (三)用人单位对经办机构确定的单位缴费费率不服的； (四)签订服务协议的医疗机构、辅助器具配置机构认为经办机构未履行有关协议或者规定的； (五)工伤职工或者其近亲属对经办机构核定的工伤保险待遇有异议的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598555, '《工伤保险条例》', '第五十六条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第七章 法律责任', NULL, '单位或者个人违反本条例第十二条规定挪用工伤保险基金，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予处分或者纪律处分。被挪用的基金由社会保险行政部门追回，并入工伤保险基金；没收的违法所得依法上缴国库。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598556, '《工伤保险条例》', '第五十七条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第七章 法律责任', NULL, '社会保险行政部门工作人员有下列情形之一的，依法给予处分；情节严重，构成犯罪的，依法追究刑事责任： (一)无正当理由不受理工伤认定申请，或者弄虚作假将不符合工伤条件的人员认定为工伤职工的； (二)未妥善保管申请工伤认定的证据材料，致使有关证据灭失的； (三)收受当事人财物的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598557, '《工伤保险条例》', '第五十八条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第七章 法律责任', NULL, '经办机构有下列行为之一的，由社会保险行政部门责令改正，对直接负责的主管人员和其他责任人员依法给予纪律处分；情节严重，构成犯罪的，依法追究刑事责任；造成当事人经济损失的，由经办机构依法承担赔偿责任： (一)未按规定保存用人单位缴费和职工享受工伤保险待遇情况记录的； (二)不按规定核定工伤保险待遇的； (三)收受当事人财物的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598558, '《工伤保险条例》', '第五十九条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第七章 法律责任', NULL, '医疗机构、辅助器具配置机构不按服务协议提供服务的，经办机构可以解除服务协议。 经办机构不按时足额结算费用的，由社会保险行政部门责令改正；医疗机构、辅助器具配置机构可以解除服务协议。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598559, '《工伤保险条例》', '第六十条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第七章 法律责任', NULL, '用人单位、工伤职工或者其近亲属骗取工伤保险待遇，医疗机构、辅助器具配置机构骗取工伤保险基金支出的，由社会保险行政部门责令退还，处骗取金额2倍以上5倍以下的罚款；情节严重，构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598560, '《工伤保险条例》', '第六十一条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第七章 法律责任', NULL, '从事劳动能力鉴定的组织或者个人有下列情形之一的，由社会保险行政部门责令改正，处2000元以上1万元以下的罚款；情节严重，构成犯罪的，依法追究刑事责任： (一)提供虚假鉴定意见的； (二)提供虚假诊断证明的； (三)收受当事人财物的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598561, '《工伤保险条例》', '第六十二条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第七章 法律责任', NULL, '用人单位依照本条例规定应当参加工伤保险而未参加的，由社会保险行政部门责令限期参加，补缴应当缴纳的工伤保险费，并自欠缴之日起，按日加收万分之五的滞纳金；逾期仍不缴纳的，处欠缴数额1倍以上3倍以下的罚款。 依照本条例规定应当参加工伤保险而未参加工伤保险的用人单位职工发生工伤的，由该用人单位按照本条例规定的工伤保险待遇项目和标准支付费用。 用人单位参加工伤保险并补缴应当缴纳的工伤保险费、滞纳金后，由工伤保险基金和用人单位依照本条例的规定支付新发生的费用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598562, '《工伤保险条例》', '第六十三条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第七章 法律责任', NULL, '用人单位违反本条例第十九条的规定，拒不协助社会保险行政部门对事故进行调查核实的，由社会保险行政部门责令改正，处2000元以上2万元以下的罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598563, '《工伤保险条例》', '第六十四条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第八章 附则', NULL, '本条例所称工资总额，是指用人单位直接支付给本单位全部职工的劳动报酬总额。 本条例所称本人工资，是指工伤职工因工作遭受事故伤害或者患职业病前12个月平均月缴费工资。本人工资高于统筹地区职工平均工资300%的，按照统筹地区职工平均工资的300%计算；本人工资低于统筹地区职工平均工资60%的，按照统筹地区职工平均工资的60%计算。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598564, '《工伤保险条例》', '第六十五条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第八章 附则', NULL, '公务员和参照公务员法管理的事业单位、社会团体的工作人员因工作遭受事故伤害或者患职业病的，由所在单位支付费用。具体办法由国务院社会保险行政部门会同国务院财政部门规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598565, '《工伤保险条例》', '第六十六条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第八章 附则', NULL, '无营业执照或者未经依法登记、备案的单位以及被依法吊销营业执照或者撤销登记、备案的单位的职工受到事故伤害或者患职业病的，由该单位向伤残职工或者死亡职工的近亲属给予一次性赔偿，赔偿标准不得低于本条例规定的工伤保险待遇；用人单位不得使用童工，用人单位使用童工造成童工伤残、死亡的，由该单位向童工或者童工的近亲属给予一次性赔偿，赔偿标准不得低于本条例规定的工伤保险待遇。具体办法由国务院社会保险行政部门规定。 前款规定的伤残职工或者死亡职工的近亲属就赔偿数额与单位发生争议的，以及前款规定的童工或者童工的近亲属就赔偿数额与单位发生争议的，按照处理劳动争议的有关规定处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2598566, '《工伤保险条例》', '第六十七条', '劳动', '行政法规', NULL, '国务院 2010-12-20', '第八章 附则', NULL, '本条例自2004年1月1日起施行。本条例施行前已受到事故伤害或者患职业病的职工尚未完成工伤认定的，按照本条例的规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2627000, '《中华人民共和国劳动合同法实施条例》', '第一条', '劳动', '行政法规', NULL, '国务院 2008-09-18', '第一章 总则', NULL, '为了贯彻实施《中华人民共和国劳动合同法》(以下简称劳动合同法)，制定本条例。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2627001, '《中华人民共和国劳动合同法实施条例》', '第二条', '劳动', '行政法规', NULL, '国务院 2008-09-18', '第一章 总则', NULL, '各级人民政府和县级以上人民政府劳动行政等有关部门以及工会等组织，应当采取措施，推动劳动合同法的贯彻实施，促进劳动关系的和谐。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2627002, '《中华人民共和国劳动合同法实施条例》', '第三条', '劳动', '行政法规', NULL, '国务院 2008-09-18', '第一章 总则', NULL, '依法成立的会计师事务所、律师事务所等合伙组织和基金会，属于劳动合同法规定的用人单位。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2627003, '《中华人民共和国劳动合同法实施条例》', '第四条', '劳动', '行政法规', NULL, '国务院 2008-09-18', '第二章 劳动合同的订立', NULL, '劳动合同法规定的用人单位设立的分支机构，依法取得营业执照或者登记证书的，可以作为用人单位与劳动者订立劳动合同；未依法取得营业执照或者登记证书的，受用人单位委托可以与劳动者订立劳动合同。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2627004, '《中华人民共和国劳动合同法实施条例》', '第五条', '劳动', '行政法规', NULL, '国务院 2008-09-18', '第二章 劳动合同的订立', NULL, '自用工之日起一个月内，经用人单位书面通知后，劳动者不与用人单位订立书面劳动合同的，用人单位应当书面通知劳动者终止劳动关系，无需向劳动者支付经济补偿，但是应当依法向劳动者支付其实际工作时间的劳动报酬。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2627005, '《中华人民共和国劳动合同法实施条例》', '第六条', '劳动', '行政法规', NULL, '国务院 2008-09-18', '第二章 劳动合同的订立', NULL, '用人单位自用工之日起超过一个月不满一年未与劳动者订立书面劳动合同的，应当依照劳动合同法第八十二条的规定向劳动者每月支付两倍的工资，并与劳动者补订书面劳动合同；劳动者不与用人单位订立书面劳动合同的，用人单位应当书面通知劳动者终止劳动关系，并依照劳动合同法第四十七条的规定支付经济补偿。 前款规定的用人单位向劳动者每月支付两倍工资的起算时间为用工之日起满一个月的次日，截止时间为补订书面劳动合同的前一日。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2627006, '《中华人民共和国劳动合同法实施条例》', '第七条', '劳动', '行政法规', NULL, '国务院 2008-09-18', '第二章 劳动合同的订立', NULL, '用人单位自用工之日起满一年未与劳动者订立书面劳动合同的，自用工之日起满一个月的次日至满一年的前一日应当依照劳动合同法第八十二条的规定向劳动者每月支付两倍的工资，并视为自用工之日起满一年的当日已经与劳动者订立无固定期限劳动合同，应当立即与劳动者补订书面劳动合同。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2627007, '《中华人民共和国劳动合同法实施条例》', '第八条', '劳动', '行政法规', NULL, '国务院 2008-09-18', '第二章 劳动合同的订立', NULL, '劳动合同法第七条规定的职工名册，应当包括劳动者姓名、性别、公民身份号码、户籍地址及现住址、联系方式、用工形式、用工起始时间、劳动合同期限等内容。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2627008, '《中华人民共和国劳动合同法实施条例》', '第九条', '劳动', '行政法规', NULL, '国务院 2008-09-18', '第二章 劳动合同的订立', NULL, '劳动合同法第十四条第二款规定的连续工作满10年的起始时间，应当自用人单位用工之日起计算，包括劳动合同法施行前的工作年限。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2627009, '《中华人民共和国劳动合同法实施条例》', '第十条', '劳动', '行政法规', NULL, '国务院 2008-09-18', '第二章 劳动合同的订立', NULL, '劳动者非因本人原因从原用人单位被安排到新用人单位工作的，劳动者在原用人单位的工作年限合并计算为新用人单位的工作年限。原用人单位已经向劳动者支付经济补偿的，新用人单位在依法解除、终止劳动合同计算支付经济补偿的工作年限时，不再计算劳动者在原用人单位的工作年限。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2627010, '《中华人民共和国劳动合同法实施条例》', '第十一条', '劳动', '行政法规', NULL, '国务院 2008-09-18', '第二章 劳动合同的订立', NULL, '除劳动者与用人单位协商一致的情形外，劳动者依照劳动合同法第十四条第二款的规定，提出订立无固定期限劳动合同的，用人单位应当与其订立无固定期限劳动合同。对劳动合同的内容，双方应当按照合法、公平、平等自愿、协商一致、诚实信用的原则协商确定；对协商不一致的内容，依照劳动合同法第十八条的规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2627011, '《中华人民共和国劳动合同法实施条例》', '第十二条', '劳动', '行政法规', NULL, '国务院 2008-09-18', '第二章 劳动合同的订立', NULL, '地方各级人民政府及县级以上地方人民政府有关部门为安置就业困难人员提供的给予岗位补贴和社会保险补贴的公益性岗位，其劳动合同不适用劳动合同法有关无固定期限劳动合同的规定以及支付经济补偿的规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2627012, '《中华人民共和国劳动合同法实施条例》', '第十三条', '劳动', '行政法规', NULL, '国务院 2008-09-18', '第二章 劳动合同的订立', NULL, '用人单位与劳动者不得在劳动合同法第四十四条规定的劳动合同终止情形之外约定其他的劳动合同终止条件。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2627013, '《中华人民共和国劳动合同法实施条例》', '第十四条', '劳动', '行政法规', NULL, '国务院 2008-09-18', '第二章 劳动合同的订立', NULL, '劳动合同履行地与用人单位注册地不一致的，有关劳动者的最低工资标准、劳动保护、劳动条件、职业危害防护和本地区上年度职工月平均工资标准等事项，按照劳动合同履行地的有关规定执行；用人单位注册地的有关标准高于劳动合同履行地的有关标准，且用人单位与劳动者约定按照用人单位注册地的有关规定执行的，从其约定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2627014, '《中华人民共和国劳动合同法实施条例》', '第十五条', '劳动', '行政法规', NULL, '国务院 2008-09-18', '第二章 劳动合同的订立', NULL, '劳动者在试用期的工资不得低于本单位相同岗位最低档工资的80%或者不得低于劳动合同约定工资的80%，并不得低于用人单位所在地的最低工资标准。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2627015, '《中华人民共和国劳动合同法实施条例》', '第十六条', '劳动', '行政法规', NULL, '国务院 2008-09-18', '第二章 劳动合同的订立', NULL, '劳动合同法第二十二条第二款规定的培训费用，包括用人单位为了对劳动者进行专业技术培训而支付的有凭证的培训费用、培训期间的差旅费用以及因培训产生的用于该劳动者的其他直接费用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2627016, '《中华人民共和国劳动合同法实施条例》', '第十七条', '劳动', '行政法规', NULL, '国务院 2008-09-18', '第二章 劳动合同的订立', NULL, '劳动合同期满，但是用人单位与劳动者依照劳动合同法第二十二条的规定约定的服务期尚未到期的，劳动合同应当续延至服务期满；双方另有约定的，从其约定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2627017, '《中华人民共和国劳动合同法实施条例》', '第十八条', '劳动', '行政法规', NULL, '国务院 2008-09-18', '第三章 劳动合同的解除和终止', NULL, '有下列情形之一的，依照劳动合同法规定的条件、程序，劳动者可以与用人单位解除固定期限劳动合同、无固定期限劳动合同或者以完成一定工作任务为期限的劳动合同： (一)劳动者与用人单位协商一致的； (二)劳动者提前30日以书面形式通知用人单位的； (三)劳动者在试用期内提前3日通知用人单位的； (四)用人单位未按照劳动合同约定提供劳动保护或者劳动条件的； (五)用人单位未及时足额支付劳动报酬的； (六)用人单位未依法为劳动者缴纳社会保险费的； (七)用人单位的规章制度违反法律、法规的规定，损害劳动者权益的； (八)用人单位以欺诈、胁迫的手段或者乘人之危，使劳动者在违背真实意思的情况下订立或者变更劳动合同的； (九)用人单位在劳动合同中免除自己的法定责任、排除劳动者权利的； (十)用人单位违反法律、行政法规强制性规定的； (十一)用人单位以暴力、威胁或者非法限制人身自由的手段强迫劳动者劳动的； (十二)用人单位违章指挥、强令冒险作业危及劳动者人身安全的； (十三)法律、行政法规规定劳动者可以解除劳动合同的其他情形。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2627018, '《中华人民共和国劳动合同法实施条例》', '第十九条', '劳动', '行政法规', NULL, '国务院 2008-09-18', '第三章 劳动合同的解除和终止', NULL, '有下列情形之一的，依照劳动合同法规定的条件、程序，用人单位可以与劳动者解除固定期限劳动合同、无固定期限劳动合同或者以完成一定工作任务为期限的劳动合同： (一)用人单位与劳动者协商一致的； (二)劳动者在试用期间被证明不符合录用条件的； (三)劳动者严重违反用人单位的规章制度的； (四)劳动者严重失职，营私舞弊，给用人单位造成重大损害的； (五)劳动者同时与其他用人单位建立劳动关系，对完成本单位的工作任务造成严重影响，或者经用人单位提出，拒不改正的； (六)劳动者以欺诈、胁迫的手段或者乘人之危，使用人单位在违背真实意思的情况下订立或者变更劳动合同的； (七)劳动者被依法追究刑事责任的； (八)劳动者患病或者非因工负伤，在规定的医疗期满后不能从事原工作，也不能从事由用人单位另行安排的工作的； (九)劳动者不能胜任工作，经过培训或者调整工作岗位，仍不能胜任工作的； (十)劳动合同订立时所依据的客观情况发生重大变化，致使劳动合同无法履行，经用人单位与劳动者协商，未能就变更劳动合同内容达成协议的； (十一)用人单位依照企业破产法规定进行重整的； (十二)用人单位生产经营发生严重困难的； (十三)企业转产、重大技术革新或者经营方式调整，经变更劳动合同后，仍需裁减人员的； (十四)其他因劳动合同订立时所依据的客观经济情况发生重大变化，致使劳动合同无法履行的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2627019, '《中华人民共和国劳动合同法实施条例》', '第二十条', '劳动', '行政法规', NULL, '国务院 2008-09-18', '第三章 劳动合同的解除和终止', NULL, '用人单位依照劳动合同法第四十条的规定，选择额外支付劳动者一个月工资解除劳动合同的，其额外支付的工资应当按照该劳动者上一个月的工资标准确定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2627020, '《中华人民共和国劳动合同法实施条例》', '第二十一条', '劳动', '行政法规', NULL, '国务院 2008-09-18', '第三章 劳动合同的解除和终止', NULL, '劳动者达到法定退休年龄的，劳动合同终止。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2627021, '《中华人民共和国劳动合同法实施条例》', '第二十二条', '劳动', '行政法规', NULL, '国务院 2008-09-18', '第三章 劳动合同的解除和终止', NULL, '以完成一定工作任务为期限的劳动合同因任务完成而终止的，用人单位应当依照劳动合同法第四十七条的规定向劳动者支付经济补偿。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2627022, '《中华人民共和国劳动合同法实施条例》', '第二十三条', '劳动', '行政法规', NULL, '国务院 2008-09-18', '第三章 劳动合同的解除和终止', NULL, '用人单位依法终止工伤职工的劳动合同的，除依照劳动合同法第四十七条的规定支付经济补偿外，还应当依照国家有关工伤保险的规定支付一次性工伤医疗补助金和伤残就业补助金。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2627023, '《中华人民共和国劳动合同法实施条例》', '第二十四条', '劳动', '行政法规', NULL, '国务院 2008-09-18', '第三章 劳动合同的解除和终止', NULL, '用人单位出具的解除、终止劳动合同的证明，应当写明劳动合同期限、解除或者终止劳动合同的日期、工作岗位、在本单位的工作年限。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2627024, '《中华人民共和国劳动合同法实施条例》', '第二十五条', '劳动', '行政法规', NULL, '国务院 2008-09-18', '第三章 劳动合同的解除和终止', NULL, '用人单位违反劳动合同法的规定解除或者终止劳动合同，依照劳动合同法第八十七条的规定支付了赔偿金的，不再支付经济补偿。赔偿金的计算年限自用工之日起计算。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2627025, '《中华人民共和国劳动合同法实施条例》', '第二十六条', '劳动', '行政法规', NULL, '国务院 2008-09-18', '第三章 劳动合同的解除和终止', NULL, '用人单位与劳动者约定了服务期，劳动者依照劳动合同法第三十八条的规定解除劳动合同的，不属于违反服务期的约定，用人单位不得要求劳动者支付违约金。 有下列情形之一，用人单位与劳动者解除约定服务期的劳动合同的，劳动者应当按照劳动合同的约定向用人单位支付违约金： (一)劳动者严重违反用人单位的规章制度的； (二)劳动者严重失职，营私舞弊，给用人单位造成重大损害的； (三)劳动者同时与其他用人单位建立劳动关系，对完成本单位的工作任务造成严重影响，或者经用人单位提出，拒不改正的； (四)劳动者以欺诈、胁迫的手段或者乘人之危，使用人单位在违背真实意思的情况下订立或者变更劳动合同的； (五)劳动者被依法追究刑事责任的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2627026, '《中华人民共和国劳动合同法实施条例》', '第二十七条', '劳动', '行政法规', NULL, '国务院 2008-09-18', '第三章 劳动合同的解除和终止', NULL, '劳动合同法第四十七条规定的经济补偿的月工资按照劳动者应得工资计算，包括计时工资或者计件工资以及奖金、津贴和补贴等货币性收入。劳动者在劳动合同解除或者终止前12个月的平均工资低于当地最低工资标准的，按照当地最低工资标准计算。劳动者工作不满12个月的，按照实际工作的月数计算平均工资。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2627027, '《中华人民共和国劳动合同法实施条例》', '第二十八条', '劳动', '行政法规', NULL, '国务院 2008-09-18', '第四章 劳务派遣特别规定', NULL, '用人单位或者其所属单位出资或者合伙设立的劳务派遣单位，向本单位或者所属单位派遣劳动者的，属于劳动合同法第六十七条规定的不得设立的劳务派遣单位。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2627028, '《中华人民共和国劳动合同法实施条例》', '第二十九条', '劳动', '行政法规', NULL, '国务院 2008-09-18', '第四章 劳务派遣特别规定', NULL, '用工单位应当履行劳动合同法第六十二条规定的义务，维护被派遣劳动者的合法权益。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2627029, '《中华人民共和国劳动合同法实施条例》', '第三十条', '劳动', '行政法规', NULL, '国务院 2008-09-18', '第四章 劳务派遣特别规定', NULL, '劳务派遣单位不得以非全日制用工形式招用被派遣劳动者。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2627030, '《中华人民共和国劳动合同法实施条例》', '第三十一条', '劳动', '行政法规', NULL, '国务院 2008-09-18', '第四章 劳务派遣特别规定', NULL, '劳务派遣单位或者被派遣劳动者依法解除、终止劳动合同的经济补偿，依照劳动合同法第四十六条、第四十七条的规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2627031, '《中华人民共和国劳动合同法实施条例》', '第三十二条', '劳动', '行政法规', NULL, '国务院 2008-09-18', '第四章 劳务派遣特别规定', NULL, '劳务派遣单位违法解除或者终止被派遣劳动者的劳动合同的，依照劳动合同法第四十八条的规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2627032, '《中华人民共和国劳动合同法实施条例》', '第三十三条', '劳动', '行政法规', NULL, '国务院 2008-09-18', '第五章 法律责任', NULL, '用人单位违反劳动合同法有关建立职工名册规定的，由劳动行政部门责令限期改正；逾期不改正的，由劳动行政部门处2000元以上2万元以下的罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2627033, '《中华人民共和国劳动合同法实施条例》', '第三十四条', '劳动', '行政法规', NULL, '国务院 2008-09-18', '第五章 法律责任', NULL, '用人单位依照劳动合同法的规定应当向劳动者每月支付两倍的工资或者应当向劳动者支付赔偿金而未支付的，劳动行政部门应当责令用人单位支付。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2627034, '《中华人民共和国劳动合同法实施条例》', '第三十五条', '劳动', '行政法规', NULL, '国务院 2008-09-18', '第五章 法律责任', NULL, '用工单位违反劳动合同法和本条例有关劳务派遣规定的，由劳动行政部门和其他有关主管部门责令改正；情节严重的，以每位被派遣劳动者1000元以上5000元以下的标准处以罚款；给被派遣劳动者造成损害的，劳务派遣单位和用工单位承担连带赔偿责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2627035, '《中华人民共和国劳动合同法实施条例》', '第三十六条', '劳动', '行政法规', NULL, '国务院 2008-09-18', '第六章 附则', NULL, '对违反劳动合同法和本条例的行为的投诉、举报，县级以上地方人民政府劳动行政部门依照《劳动保障监察条例》的规定处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2627036, '《中华人民共和国劳动合同法实施条例》', '第三十七条', '劳动', '行政法规', NULL, '国务院 2008-09-18', '第六章 附则', NULL, '劳动者与用人单位因订立、履行、变更、解除或者终止劳动合同发生争议的，依照《中华人民共和国劳动争议调解仲裁法》的规定处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2627037, '《中华人民共和国劳动合同法实施条例》', '第三十八条', '劳动', '行政法规', NULL, '国务院 2008-09-18', '第六章 附则', NULL, '本条例自公布之日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2634500, '《职工带薪年休假条例》', '第一条', '劳动', '行政法规', NULL, '国务院 2007-12-14', NULL, NULL, '为了维护职工休息休假权利，调动职工工作积极性，根据劳动法和公务员法，制定本条例。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2634501, '《职工带薪年休假条例》', '第二条', '劳动', '行政法规', NULL, '国务院 2007-12-14', NULL, NULL, '机关、团体、企业、事业单位、民办非企业单位、有雇工的个体工商户等单位的职工连续工作1年以上的，享受带薪年休假(以下简称年休假)。单位应当保证职工享受年休假。 职工在年休假期间享受与正常工作期间相同的工资收入。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2634502, '《职工带薪年休假条例》', '第三条', '劳动', '行政法规', NULL, '国务院 2007-12-14', NULL, NULL, '职工累计工作已满1年不满10年的，年休假5天；已满10年不满20年的，年休假10天；已满20年的，年休假15天。 国家法定休假日、休息日不计入年休假的假期。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2634503, '《职工带薪年休假条例》', '第四条', '劳动', '行政法规', NULL, '国务院 2007-12-14', NULL, NULL, '职工有下列情形之一的，不享受当年的年休假： (一)职工依法享受寒暑假，其休假天数多于年休假天数的； (二)职工请事假累计20天以上且单位按照规定不扣工资的； (三)累计工作满1年不满10年的职工，请病假累计2个月以上的； (四)累计工作满10年不满20年的职工，请病假累计3个月以上的； (五)累计工作满20年以上的职工，请病假累计4个月以上的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2634504, '《职工带薪年休假条例》', '第五条', '劳动', '行政法规', NULL, '国务院 2007-12-14', NULL, NULL, '单位根据生产、工作的具体情况，并考虑职工本人意愿，统筹安排职工年休假。 年休假在1个年度内可以集中安排，也可以分段安排，一般不跨年度安排。单位因生产、工作特点确有必要跨年度安排职工年休假的，可以跨1个年度安排。 单位确因工作需要不能安排职工休年休假的，经职工本人同意，可以不安排职工休年休假。对职工应休未休的年休假天数，单位应当按照该职工日工资收入的300%支付年休假工资报酬。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2634505, '《职工带薪年休假条例》', '第六条', '劳动', '行政法规', NULL, '国务院 2007-12-14', NULL, NULL, '县级以上地方人民政府人事部门、劳动保障部门应当依据职权对单位执行本条例的情况主动进行监督检查。 工会组织依法维护职工的年休假权利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2634506, '《职工带薪年休假条例》', '第七条', '劳动', '行政法规', NULL, '国务院 2007-12-14', NULL, NULL, '单位不安排职工休年休假又不依照本条例规定给予年休假工资报酬的，由县级以上地方人民政府人事部门或者劳动保障部门依据职权责令限期改正；对逾期不改正的，除责令该单位支付年休假工资报酬外，单位还应当按照年休假工资报酬的数额向职工加付赔偿金；对拒不支付年休假工资报酬、赔偿金的，属于公务员和参照公务员法管理的人员所在单位的，对直接负责的主管人员以及其他直接责任人员依法给予处分；属于其他单位的，由劳动保障部门、人事部门或者职工申请人民法院强制执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2634507, '《职工带薪年休假条例》', '第八条', '劳动', '行政法规', NULL, '国务院 2007-12-14', NULL, NULL, '职工与单位因年休假发生的争议，依照国家有关法律、行政法规的规定处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2634508, '《职工带薪年休假条例》', '第九条', '劳动', '行政法规', NULL, '国务院 2007-12-14', NULL, NULL, '国务院人事部门、国务院劳动保障部门依据职权，分别制定本条例的实施办法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2634509, '《职工带薪年休假条例》', '第十条', '劳动', '行政法规', NULL, '国务院 2007-12-14', NULL, NULL, '本条例自2008年1月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2645000, '《残疾人就业条例》', '第一条', '劳动', '行政法规', NULL, '国务院 2007-02-25', '第一章 总则', NULL, '为了促进残疾人就业，保障残疾人的劳动权利，根据《中华人民共和国残疾人保障法》和其他有关法律，制定本条例。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2645001, '《残疾人就业条例》', '第二条', '劳动', '行政法规', NULL, '国务院 2007-02-25', '第一章 总则', NULL, '国家对残疾人就业实行集中就业与分散就业相结合的方针，促进残疾人就业。 县级以上人民政府应当将残疾人就业纳入国民经济和社会发展规划，并制定优惠政策和具体扶持保护措施，为残疾人就业创造条件。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2645002, '《残疾人就业条例》', '第三条', '劳动', '行政法规', NULL, '国务院 2007-02-25', '第一章 总则', NULL, '机关、团体、企业、事业单位和民办非企业单位(以下统称用人单位)应当依照有关法律、本条例和其他有关行政法规的规定，履行扶持残疾人就业的责任和义务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2645003, '《残疾人就业条例》', '第四条', '劳动', '行政法规', NULL, '国务院 2007-02-25', '第一章 总则', NULL, '国家鼓励社会组织和个人通过多种渠道、多种形式，帮助、支持残疾人就业，鼓励残疾人通过应聘等多种形式就业。禁止在就业中歧视残疾人。 残疾人应当提高自身素质，增强就业能力。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2645004, '《残疾人就业条例》', '第五条', '劳动', '行政法规', NULL, '国务院 2007-02-25', '第一章 总则', NULL, '各级人民政府应当加强对残疾人就业工作的统筹规划，综合协调。县级以上人民政府负责残疾人工作的机构，负责组织、协调、指导、督促有关部门做好残疾人就业工作。 县级以上人民政府劳动保障、民政等有关部门在各自的职责范围内，做好残疾人就业工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2645005, '《残疾人就业条例》', '第六条', '劳动', '行政法规', NULL, '国务院 2007-02-25', '第一章 总则', NULL, '中国残疾人联合会及其地方组织依照法律、法规或者接受政府委托，负责残疾人就业工作的具体组织实施与监督。 工会、共产主义青年团、妇女联合会，应当在各自的工作范围内，做好残疾人就业工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2645006, '《残疾人就业条例》', '第七条', '劳动', '行政法规', NULL, '国务院 2007-02-25', '第一章 总则', NULL, '各级人民政府对在残疾人就业工作中做出显著成绩的单位和个人，给予表彰和奖励。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2645007, '《残疾人就业条例》', '第八条', '劳动', '行政法规', NULL, '国务院 2007-02-25', '第二章 用人单位的责任', NULL, '用人单位应当按照一定比例安排残疾人就业，并为其提供适当的工种、岗位。 用人单位安排残疾人就业的比例不得低于本单位在职职工总数的1.5%。具体比例由省、自治区、直辖市人民政府根据本地区的实际情况规定。 用人单位跨地区招用残疾人的，应当计入所安排的残疾人职工人数之内。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2645008, '《残疾人就业条例》', '第九条', '劳动', '行政法规', NULL, '国务院 2007-02-25', '第二章 用人单位的责任', NULL, '用人单位安排残疾人就业达不到其所在地省、自治区、直辖市人民政府规定比例的，应当缴纳残疾人就业保障金。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2645009, '《残疾人就业条例》', '第十条', '劳动', '行政法规', NULL, '国务院 2007-02-25', '第二章 用人单位的责任', NULL, '政府和社会依法兴办的残疾人福利企业、盲人按摩机构和其他福利性单位(以下统称集中使用残疾人的用人单位)，应当集中安排残疾人就业。 集中使用残疾人的用人单位的资格认定，按照国家有关规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2645010, '《残疾人就业条例》', '第十一条', '劳动', '行政法规', NULL, '国务院 2007-02-25', '第二章 用人单位的责任', NULL, '集中使用残疾人的用人单位中从事全日制工作的残疾人职工，应当占本单位在职职工总数的25%以上。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2645011, '《残疾人就业条例》', '第十二条', '劳动', '行政法规', NULL, '国务院 2007-02-25', '第二章 用人单位的责任', NULL, '用人单位招用残疾人职工，应当依法与其签订劳动合同或者服务协议。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2645012, '《残疾人就业条例》', '第十三条', '劳动', '行政法规', NULL, '国务院 2007-02-25', '第二章 用人单位的责任', NULL, '用人单位应当为残疾人职工提供适合其身体状况的劳动条件和劳动保护，不得在晋职、晋级、评定职称、报酬、社会保险、生活福利等方面歧视残疾人职工。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2645013, '《残疾人就业条例》', '第十四条', '劳动', '行政法规', NULL, '国务院 2007-02-25', '第二章 用人单位的责任', NULL, '用人单位应当根据本单位残疾人职工的实际情况，对残疾人职工进行上岗、在岗、转岗等培训。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2645014, '《残疾人就业条例》', '第十五条', '劳动', '行政法规', NULL, '国务院 2007-02-25', '第三章 保障措施', NULL, '县级以上人民政府应当采取措施，拓宽残疾人就业渠道，开发适合残疾人就业的公益性岗位，保障残疾人就业。 县级以上地方人民政府发展社区服务事业，应当优先考虑残疾人就业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2645015, '《残疾人就业条例》', '第十六条', '劳动', '行政法规', NULL, '国务院 2007-02-25', '第三章 保障措施', NULL, '依法征收的残疾人就业保障金应当纳入财政预算，专项用于残疾人职业培训以及为残疾人提供就业服务和就业援助，任何组织或者个人不得贪污、挪用、截留或者私分。残疾人就业保障金征收、使用、管理的具体办法，由国务院财政部门会同国务院有关部门规定。 财政部门和审计机关应当依法加强对残疾人就业保障金使用情况的监督检查。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2645016, '《残疾人就业条例》', '第十七条', '劳动', '行政法规', NULL, '国务院 2007-02-25', '第三章 保障措施', NULL, '国家对集中使用残疾人的用人单位依法给予税收优惠，并在生产、经营、技术、资金、物资、场地使用等方面给予扶持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2645017, '《残疾人就业条例》', '第十八条', '劳动', '行政法规', NULL, '国务院 2007-02-25', '第三章 保障措施', NULL, '县级以上地方人民政府及其有关部门应当确定适合残疾人生产、经营的产品、项目，优先安排集中使用残疾人的用人单位生产或者经营，并根据集中使用残疾人的用人单位的生产特点确定某些产品由其专产。 政府采购，在同等条件下，应当优先购买集中使用残疾人的用人单位的产品或者服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2645018, '《残疾人就业条例》', '第十九条', '劳动', '行政法规', NULL, '国务院 2007-02-25', '第三章 保障措施', NULL, '国家鼓励扶持残疾人自主择业、自主创业。对残疾人从事个体经营的，应当依法给予税收优惠，有关部门应当在经营场地等方面给予照顾，并按照规定免收管理类、登记类和证照类的行政事业性收费。 国家对自主择业、自主创业的残疾人在一定期限内给予小额信贷等扶持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2645019, '《残疾人就业条例》', '第二十条', '劳动', '行政法规', NULL, '国务院 2007-02-25', '第三章 保障措施', NULL, '地方各级人民政府应当多方面筹集资金，组织和扶持农村残疾人从事种植业、养殖业、手工业和其他形式的生产劳动。 有关部门对从事农业生产劳动的农村残疾人，应当在生产服务、技术指导、农用物资供应、农副产品收购和信贷等方面给予帮助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2645020, '《残疾人就业条例》', '第二十一条', '劳动', '行政法规', NULL, '国务院 2007-02-25', '第四章 就业服务', NULL, '各级人民政府和有关部门应当为就业困难的残疾人提供有针对性的就业援助服务，鼓励和扶持职业培训机构为残疾人提供职业培训，并组织残疾人定期开展职业技能竞赛。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2645021, '《残疾人就业条例》', '第二十二条', '劳动', '行政法规', NULL, '国务院 2007-02-25', '第四章 就业服务', NULL, '中国残疾人联合会及其地方组织所属的残疾人就业服务机构应当免费为残疾人就业提供下列服务： (一)发布残疾人就业信息； (二)组织开展残疾人职业培训； (三)为残疾人提供职业心理咨询、职业适应评估、职业康复训练、求职定向指导、职业介绍等服务； (四)为残疾人自主择业提供必要的帮助； (五)为用人单位安排残疾人就业提供必要的支持。 国家鼓励其他就业服务机构为残疾人就业提供免费服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2645022, '《残疾人就业条例》', '第二十三条', '劳动', '行政法规', NULL, '国务院 2007-02-25', '第四章 就业服务', NULL, '受劳动保障部门的委托，残疾人就业服务机构可以进行残疾人失业登记、残疾人就业与失业统计；经所在地劳动保障部门批准，残疾人就业服务机构还可以进行残疾人职业技能鉴定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2645023, '《残疾人就业条例》', '第二十四条', '劳动', '行政法规', NULL, '国务院 2007-02-25', '第四章 就业服务', NULL, '残疾人职工与用人单位发生争议的，当地法律援助机构应当依法为其提供法律援助，各级残疾人联合会应当给予支持和帮助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2645024, '《残疾人就业条例》', '第二十五条', '劳动', '行政法规', NULL, '国务院 2007-02-25', '第五章 法律责任', NULL, '违反本条例规定，有关行政主管部门及其工作人员滥用职权、玩忽职守、徇私舞弊，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2645025, '《残疾人就业条例》', '第二十六条', '劳动', '行政法规', NULL, '国务院 2007-02-25', '第五章 法律责任', NULL, '违反本条例规定，贪污、挪用、截留、私分残疾人就业保障金，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，对有关责任单位、直接负责的主管人员和其他直接责任人员依法给予处分或者处罚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2645026, '《残疾人就业条例》', '第二十七条', '劳动', '行政法规', NULL, '国务院 2007-02-25', '第五章 法律责任', NULL, '违反本条例规定，用人单位未按照规定缴纳残疾人就业保障金的，由财政部门给予警告，责令限期缴纳；逾期仍不缴纳的，除补缴欠缴数额外，还应当自欠缴之日起，按日加收5‰的滞纳金。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2645027, '《残疾人就业条例》', '第二十八条', '劳动', '行政法规', NULL, '国务院 2007-02-25', '第五章 法律责任', NULL, '违反本条例规定，用人单位弄虚作假，虚报安排残疾人就业人数，骗取集中使用残疾人的用人单位享受的税收优惠待遇的，由税务机关依法处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2645028, '《残疾人就业条例》', '第二十九条', '劳动', '行政法规', NULL, '国务院 2007-02-25', '第六章 附则', NULL, '本条例所称残疾人就业，是指符合法定就业年龄有就业要求的残疾人从事有报酬的劳动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2645029, '《残疾人就业条例》', '第三十条', '劳动', '行政法规', NULL, '国务院 2007-02-25', '第六章 附则', NULL, '本条例自2007年5月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2666000, '《劳动保障监察条例》', '第一条', '劳动', '行政法规', NULL, '国务院 2004-11-01', '第一章 总则', NULL, '为了贯彻实施劳动和社会保障(以下称劳动保障)法律、法规和规章，规范劳动保障监察工作，维护劳动者的合法权益，根据劳动法和有关法律，制定本条例。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2666001, '《劳动保障监察条例》', '第二条', '劳动', '行政法规', NULL, '国务院 2004-11-01', '第一章 总则', NULL, '对企业和个体工商户(以下称用人单位)进行劳动保障监察，适用本条例。 对职业介绍机构、职业技能培训机构和职业技能考核鉴定机构进行劳动保障监察，依照本条例执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2666002, '《劳动保障监察条例》', '第三条', '劳动', '行政法规', NULL, '国务院 2004-11-01', '第一章 总则', NULL, '国务院劳动保障行政部门主管全国的劳动保障监察工作。县级以上地方各级人民政府劳动保障行政部门主管本行政区域内的劳动保障监察工作。 县级以上各级人民政府有关部门根据各自职责，支持、协助劳动保障行政部门的劳动保障监察工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2666003, '《劳动保障监察条例》', '第四条', '劳动', '行政法规', NULL, '国务院 2004-11-01', '第一章 总则', NULL, '县级、设区的市级人民政府劳动保障行政部门可以委托符合监察执法条件的组织实施劳动保障监察。 劳动保障行政部门和受委托实施劳动保障监察的组织中的劳动保障监察员应当经过相应的考核或者考试录用。 劳动保障监察证件由国务院劳动保障行政部门监制。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2666004, '《劳动保障监察条例》', '第五条', '劳动', '行政法规', NULL, '国务院 2004-11-01', '第一章 总则', NULL, '县级以上地方各级人民政府应当加强劳动保障监察工作。劳动保障监察所需经费列入本级财政预算。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2666005, '《劳动保障监察条例》', '第六条', '劳动', '行政法规', NULL, '国务院 2004-11-01', '第一章 总则', NULL, '用人单位应当遵守劳动保障法律、法规和规章，接受并配合劳动保障监察。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2666006, '《劳动保障监察条例》', '第七条', '劳动', '行政法规', NULL, '国务院 2004-11-01', '第一章 总则', NULL, '各级工会依法维护劳动者的合法权益，对用人单位遵守劳动保障法律、法规和规章的情况进行监督。 劳动保障行政部门在劳动保障监察工作中应当注意听取工会组织的意见和建议。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2666007, '《劳动保障监察条例》', '第八条', '劳动', '行政法规', NULL, '国务院 2004-11-01', '第一章 总则', NULL, '劳动保障监察遵循公正、公开、高效、便民的原则。 实施劳动保障监察，坚持教育与处罚相结合，接受社会监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2666008, '《劳动保障监察条例》', '第九条', '劳动', '行政法规', NULL, '国务院 2004-11-01', '第一章 总则', NULL, '任何组织或者个人对违反劳动保障法律、法规或者规章的行为，有权向劳动保障行政部门举报。 劳动者认为用人单位侵犯其劳动保障合法权益的，有权向劳动保障行政部门投诉。 劳动保障行政部门应当为举报人保密；对举报属实，为查处重大违反劳动保障法律、法规或者规章的行为提供主要线索和证据的举报人，给予奖励。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2666009, '《劳动保障监察条例》', '第十条', '劳动', '行政法规', NULL, '国务院 2004-11-01', '第二章 劳动保障监察职责', NULL, '劳动保障行政部门实施劳动保障监察，履行下列职责： (一)宣传劳动保障法律、法规和规章，督促用人单位贯彻执行； (二)检查用人单位遵守劳动保障法律、法规和规章的情况； (三)受理对违反劳动保障法律、法规或者规章的行为的举报、投诉； (四)依法纠正和查处违反劳动保障法律、法规或者规章的行为。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2666010, '《劳动保障监察条例》', '第十一条', '劳动', '行政法规', NULL, '国务院 2004-11-01', '第二章 劳动保障监察职责', NULL, '劳动保障行政部门对下列事项实施劳动保障监察： (一)用人单位制定内部劳动保障规章制度的情况； (二)用人单位与劳动者订立劳动合同的情况； (三)用人单位遵守禁止使用童工规定的情况； (四)用人单位遵守女职工和未成年工特殊劳动保护规定的情况； (五)用人单位遵守工作时间和休息休假规定的情况； (六)用人单位支付劳动者工资和执行最低工资标准的情况； (七)用人单位参加各项社会保险和缴纳社会保险费的情况； (八)职业介绍机构、职业技能培训机构和职业技能考核鉴定机构遵守国家有关职业介绍、职业技能培训和职业技能考核鉴定的规定的情况； (九)法律、法规规定的其他劳动保障监察事项。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2666011, '《劳动保障监察条例》', '第十二条', '劳动', '行政法规', NULL, '国务院 2004-11-01', '第二章 劳动保障监察职责', NULL, '劳动保障监察员依法履行劳动保障监察职责，受法律保护。 劳动保障监察员应当忠于职守，秉公执法，勤政廉洁，保守秘密。 任何组织或者个人对劳动保障监察员的违法违纪行为，有权向劳动保障行政部门或者有关机关检举、控告。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2666012, '《劳动保障监察条例》', '第十三条', '劳动', '行政法规', NULL, '国务院 2004-11-01', '第三章 劳动保障监察的实施', NULL, '对用人单位的劳动保障监察，由用人单位用工所在地的县级或者设区的市级劳动保障行政部门管辖。 上级劳动保障行政部门根据工作需要，可以调查处理下级劳动保障行政部门管辖的案件。劳动保障行政部门对劳动保障监察管辖发生争议的，报请共同的上一级劳动保障行政部门指定管辖。 省、自治区、直辖市人民政府可以对劳动保障监察的管辖制定具体办法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2666013, '《劳动保障监察条例》', '第十四条', '劳动', '行政法规', NULL, '国务院 2004-11-01', '第三章 劳动保障监察的实施', NULL, '劳动保障监察以日常巡视检查、审查用人单位按照要求报送的书面材料以及接受举报投诉等形式进行。 劳动保障行政部门认为用人单位有违反劳动保障法律、法规或者规章的行为，需要进行调查处理的，应当及时立案。 劳动保障行政部门或者受委托实施劳动保障监察的组织应当设立举报、投诉信箱和电话。 对因违反劳动保障法律、法规或者规章的行为引起的群体性事件，劳动保障行政部门应当根据应急预案，迅速会同有关部门处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2666014, '《劳动保障监察条例》', '第十五条', '劳动', '行政法规', NULL, '国务院 2004-11-01', '第三章 劳动保障监察的实施', NULL, '劳动保障行政部门实施劳动保障监察，有权采取下列调查、检查措施： (一)进入用人单位的劳动场所进行检查； (二)就调查、检查事项询问有关人员； (三)要求用人单位提供与调查、检查事项相关的文件资料，并作出解释和说明，必要时可以发出调查询问书； (四)采取记录、录音、录像、照像或者复制等方式收集有关情况和资料； (五)委托会计师事务所对用人单位工资支付、缴纳社会保险费的情况进行审计； (六)法律、法规规定可以由劳动保障行政部门采取的其他调查、检查措施。 劳动保障行政部门对事实清楚、证据确凿、可以当场处理的违反劳动保障法律、法规或者规章的行为有权当场予以纠正。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2666015, '《劳动保障监察条例》', '第十六条', '劳动', '行政法规', NULL, '国务院 2004-11-01', '第三章 劳动保障监察的实施', NULL, '劳动保障监察员进行调查、检查，不得少于2人，并应当佩戴劳动保障监察标志、出示劳动保障监察证件。 劳动保障监察员办理的劳动保障监察事项与本人或者其近亲属有直接利害关系的，应当回避。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2666016, '《劳动保障监察条例》', '第十七条', '劳动', '行政法规', NULL, '国务院 2004-11-01', '第三章 劳动保障监察的实施', NULL, '劳动保障行政部门对违反劳动保障法律、法规或者规章的行为的调查，应当自立案之日起60个工作日内完成；对情况复杂的，经劳动保障行政部门负责人批准，可以延长30个工作日。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2666017, '《劳动保障监察条例》', '第十八条', '劳动', '行政法规', NULL, '国务院 2004-11-01', '第三章 劳动保障监察的实施', NULL, '劳动保障行政部门对违反劳动保障法律、法规或者规章的行为，根据调查、检查的结果，作出以下处理： (一)对依法应当受到行政处罚的，依法作出行政处罚决定； (二)对应当改正未改正的，依法责令改正或者作出相应的行政处理决定； (三)对情节轻微且已改正的，撤销立案。 发现违法案件不属于劳动保障监察事项的，应当及时移送有关部门处理；涉嫌犯罪的，应当依法移送司法机关。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2666018, '《劳动保障监察条例》', '第十九条', '劳动', '行政法规', NULL, '国务院 2004-11-01', '第三章 劳动保障监察的实施', NULL, '劳动保障行政部门对违反劳动保障法律、法规或者规章的行为作出行政处罚或者行政处理决定前，应当听取用人单位的陈述、申辩；作出行政处罚或者行政处理决定，应当告知用人单位依法享有申请行政复议或者提起行政诉讼的权利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2666019, '《劳动保障监察条例》', '第二十条', '劳动', '行政法规', NULL, '国务院 2004-11-01', '第三章 劳动保障监察的实施', NULL, '违反劳动保障法律、法规或者规章的行为在2年内未被劳动保障行政部门发现，也未被举报、投诉的，劳动保障行政部门不再查处。 前款规定的期限，自违反劳动保障法律、法规或者规章的行为发生之日起计算；违反劳动保障法律、法规或者规章的行为有连续或者继续状态的，自行为终了之日起计算。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2666020, '《劳动保障监察条例》', '第二十一条', '劳动', '行政法规', NULL, '国务院 2004-11-01', '第三章 劳动保障监察的实施', NULL, '用人单位违反劳动保障法律、法规或者规章，对劳动者造成损害的，依法承担赔偿责任。劳动者与用人单位就赔偿发生争议的，依照国家有关劳动争议处理的规定处理。 对应当通过劳动争议处理程序解决的事项或者已经按照劳动争议处理程序申请调解、仲裁或者已经提起诉讼的事项，劳动保障行政部门应当告知投诉人依照劳动争议处理或者诉讼的程序办理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2666021, '《劳动保障监察条例》', '第二十二条', '劳动', '行政法规', NULL, '国务院 2004-11-01', '第三章 劳动保障监察的实施', NULL, '劳动保障行政部门应当建立用人单位劳动保障守法诚信档案。用人单位有重大违反劳动保障法律、法规或者规章的行为的，由有关的劳动保障行政部门向社会公布。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2666022, '《劳动保障监察条例》', '第二十三条', '劳动', '行政法规', NULL, '国务院 2004-11-01', '第四章 法律责任', NULL, '用人单位有下列行为之一的，由劳动保障行政部门责令改正，按照受侵害的劳动者每人1000元以上5000元以下的标准计算，处以罚款： (一)安排女职工从事矿山井下劳动、国家规定的第四级体力劳动强度的劳动或者其他禁忌从事的劳动的； (二)安排女职工在经期从事高处、低温、冷水作业或者国家规定的第三级体力劳动强度的劳动的； (三)安排女职工在怀孕期间从事国家规定的第三级体力劳动强度的劳动或者孕期禁忌从事的劳动的； (四)安排怀孕7个月以上的女职工夜班劳动或者延长其工作时间的； (五)女职工生育享受产假少于90天的； (六)安排女职工在哺乳未满1周岁的婴儿期间从事国家规定的第三级体力劳动强度的劳动或者哺乳期禁忌从事的其他劳动，以及延长其工作时间或者安排其夜班劳动的； (七)安排未成年工从事矿山井下、有毒有害、国家规定的第四级体力劳动强度的劳动或者其他禁忌从事的劳动的； (八)未对未成年工定期进行健康检查的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2666023, '《劳动保障监察条例》', '第二十四条', '劳动', '行政法规', NULL, '国务院 2004-11-01', '第四章 法律责任', NULL, '用人单位与劳动者建立劳动关系不依法订立劳动合同的，由劳动保障行政部门责令改正。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2666024, '《劳动保障监察条例》', '第二十五条', '劳动', '行政法规', NULL, '国务院 2004-11-01', '第四章 法律责任', NULL, '用人单位违反劳动保障法律、法规或者规章延长劳动者工作时间的，由劳动保障行政部门给予警告，责令限期改正，并可以按照受侵害的劳动者每人100元以上500元以下的标准计算，处以罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2666025, '《劳动保障监察条例》', '第二十六条', '劳动', '行政法规', NULL, '国务院 2004-11-01', '第四章 法律责任', NULL, '用人单位有下列行为之一的，由劳动保障行政部门分别责令限期支付劳动者的工资报酬、劳动者工资低于当地最低工资标准的差额或者解除劳动合同的经济补偿；逾期不支付的，责令用人单位按照应付金额50%以上1倍以下的标准计算，向劳动者加付赔偿金： (一)克扣或者无故拖欠劳动者工资报酬的； (二)支付劳动者的工资低于当地最低工资标准的； (三)解除劳动合同未依法给予劳动者经济补偿的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2666026, '《劳动保障监察条例》', '第二十七条', '劳动', '行政法规', NULL, '国务院 2004-11-01', '第四章 法律责任', NULL, '用人单位向社会保险经办机构申报应缴纳的社会保险费数额时，瞒报工资总额或者职工人数的，由劳动保障行政部门责令改正，并处瞒报工资数额1倍以上3倍以下的罚款。 骗取社会保险待遇或者骗取社会保险基金支出的，由劳动保障行政部门责令退还，并处骗取金额1倍以上3倍以下的罚款；构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2666027, '《劳动保障监察条例》', '第二十八条', '劳动', '行政法规', NULL, '国务院 2004-11-01', '第四章 法律责任', NULL, '职业介绍机构、职业技能培训机构或者职业技能考核鉴定机构违反国家有关职业介绍、职业技能培训或者职业技能考核鉴定的规定的，由劳动保障行政部门责令改正，没收违法所得，并处1万元以上5万元以下的罚款；情节严重的，吊销许可证。 未经劳动保障行政部门许可，从事职业介绍、职业技能培训或者职业技能考核鉴定的组织或者个人，由劳动保障行政部门、工商行政管理部门依照国家有关无照经营查处取缔的规定查处取缔。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2666028, '《劳动保障监察条例》', '第二十九条', '劳动', '行政法规', NULL, '国务院 2004-11-01', '第四章 法律责任', NULL, '用人单位违反《中华人民共和国工会法》，有下列行为之一的，由劳动保障行政部门责令改正： (一)阻挠劳动者依法参加和组织工会，或者阻挠上级工会帮助、指导劳动者筹建工会的； (二)无正当理由调动依法履行职责的工会工作人员的工作岗位，进行打击报复的； (三)劳动者因参加工会活动而被解除劳动合同的； (四)工会工作人员因依法履行职责被解除劳动合同的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2666029, '《劳动保障监察条例》', '第三十条', '劳动', '行政法规', NULL, '国务院 2004-11-01', '第四章 法律责任', NULL, '有下列行为之一的，由劳动保障行政部门责令改正；对有第(一)项、第(二)项或者第(三)项规定的行为的，处2000元以上2万元以下的罚款： (一)无理抗拒、阻挠劳动保障行政部门依照本条例的规定实施劳动保障监察的； (二)不按照劳动保障行政部门的要求报送书面材料，隐瞒事实真相，出具伪证或者隐匿、毁灭证据的； (三)经劳动保障行政部门责令改正拒不改正，或者拒不履行劳动保障行政部门的行政处理决定的； (四)打击报复举报人、投诉人的。 违反前款规定，构成违反治安管理行为的，由公安机关依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2666030, '《劳动保障监察条例》', '第三十一条', '劳动', '行政法规', NULL, '国务院 2004-11-01', '第四章 法律责任', NULL, '劳动保障监察员滥用职权、玩忽职守、徇私舞弊或者泄露在履行职责过程中知悉的商业秘密的，依法给予行政处分；构成犯罪的，依法追究刑事责任。 劳动保障行政部门和劳动保障监察员违法行使职权，侵犯用人单位或者劳动者的合法权益的，依法承担赔偿责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2666031, '《劳动保障监察条例》', '第三十二条', '劳动', '行政法规', NULL, '国务院 2004-11-01', '第四章 法律责任', NULL, '属于本条例规定的劳动保障监察事项，法律、其他行政法规对处罚另有规定的，从其规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2666032, '《劳动保障监察条例》', '第三十三条', '劳动', '行政法规', NULL, '国务院 2004-11-01', '第五章 附则', NULL, '对无营业执照或者已被依法吊销营业执照，有劳动用工行为的，由劳动保障行政部门依照本条例实施劳动保障监察，并及时通报工商行政管理部门予以查处取缔。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2666033, '《劳动保障监察条例》', '第三十四条', '劳动', '行政法规', NULL, '国务院 2004-11-01', '第五章 附则', NULL, '国家机关、事业单位、社会团体执行劳动保障法律、法规和规章的情况，由劳动保障行政部门根据其职责，依照本条例实施劳动保障监察。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2666034, '《劳动保障监察条例》', '第三十五条', '劳动', '行政法规', NULL, '国务院 2004-11-01', '第五章 附则', NULL, '劳动安全卫生的监督检查，由卫生部门、安全生产监督管理部门、特种设备安全监督管理部门等有关部门依照有关法律、行政法规的规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2666035, '《劳动保障监察条例》', '第三十六条', '劳动', '行政法规', NULL, '国务院 2004-11-01', '第五章 附则', NULL, '本条例自2004年12月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2697500, '《禁止使用童工规定》', '第一条', '劳动', '行政法规', NULL, '国务院 2002-10-01', NULL, NULL, '为保护未成年人的身心健康，促进义务教育制度的实施，维护未成年人的合法权益，根据宪法和劳动法、未成年人保护法，制定本规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2697501, '《禁止使用童工规定》', '第二条', '劳动', '行政法规', NULL, '国务院 2002-10-01', NULL, NULL, '国家机关、社会团体、企业事业单位、民办非企业单位或者个体工商户(以下统称用人单位)均不得招用不满16周岁的未成年人(招用不满16周岁的未成年人，以下统称使用童工)。 禁止任何单位或者个人为不满16周岁的未成年人介绍就业。 禁止不满16周岁的未成年人开业从事个体经营活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2697502, '《禁止使用童工规定》', '第三条', '劳动', '行政法规', NULL, '国务院 2002-10-01', NULL, NULL, '不满16周岁的未成年人的父母或者其他监护人应当保护其身心健康，保障其接受义务教育的权利，不得允许其被用人单位非法招用。 不满16周岁的未成年人的父母或者其他监护人允许其被用人单位非法招用的，所在地的乡(镇)人民政府、城市街道办事处以及村民委员会、居民委员会应当给予批评教育。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2697503, '《禁止使用童工规定》', '第四条', '劳动', '行政法规', NULL, '国务院 2002-10-01', NULL, NULL, '用人单位招用人员时，必须核查被招用人员的身份证；对不满16周岁的未成年人，一律不得录用。用人单位录用人员的录用登记、核查材料应当妥善保管。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2697504, '《禁止使用童工规定》', '第五条', '劳动', '行政法规', NULL, '国务院 2002-10-01', NULL, NULL, '县级以上各级人民政府劳动保障行政部门负责本规定执行情况的监督检查。 县级以上各级人民政府公安、工商行政管理、教育、卫生等行政部门在各自职责范围内对本规定的执行情况进行监督检查，并对劳动保障行政部门的监督检查给予配合。 工会、共青团、妇联等群众组织应当依法维护未成年人的合法权益。 任何单位或者个人发现使用童工的，均有权向县级以上人民政府劳动保障行政部门举报。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2697505, '《禁止使用童工规定》', '第六条', '劳动', '行政法规', NULL, '国务院 2002-10-01', NULL, NULL, '用人单位使用童工的，由劳动保障行政部门按照每使用一名童工每月处5000元罚款的标准给予处罚；在使用有毒物品的作业场所使用童工的，按照《使用有毒物品作业场所劳动保护条例》规定的罚款幅度，或者按照每使用一名童工每月处5000元罚款的标准，从重处罚。劳动保障行政部门并应当责令用人单位限期将童工送回原居住地交其父母或者其他监护人，所需交通和食宿费用全部由用人单位承担。 用人单位经劳动保障行政部门依照前款规定责令限期改正，逾期仍不将童工送交其父母或者其他监护人的，从责令限期改正之日起，由劳动保障行政部门按照每使用一名童工每月处1万元罚款的标准处罚，并由工商行政管理部门吊销其营业执照或者由民政部门撤销民办非企业单位登记；用人单位是国家机关、事业单位的，由有关单位依法对直接负责的主管人员和其他直接责任人员给予降级或者撤职的行政处分或者纪律处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2697506, '《禁止使用童工规定》', '第七条', '劳动', '行政法规', NULL, '国务院 2002-10-01', NULL, NULL, '单位或者个人为不满16周岁的未成年人介绍就业的，由劳动保障行政部门按照每介绍一人处5000元罚款的标准给予处罚；职业中介机构为不满16周岁的未成年人介绍就业的，并由劳动保障行政部门吊销其职业介绍许可证。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2697507, '《禁止使用童工规定》', '第八条', '劳动', '行政法规', NULL, '国务院 2002-10-01', NULL, NULL, '用人单位未按照本规定第四条的规定保存录用登记材料，或者伪造录用登记材料的，由劳动保障行政部门处1万元的罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2697508, '《禁止使用童工规定》', '第九条', '劳动', '行政法规', NULL, '国务院 2002-10-01', NULL, NULL, '无营业执照、被依法吊销营业执照的单位以及未依法登记、备案的单位使用童工或者介绍童工就业的，依照本规定第六条、第七条、第八条规定的标准加一倍罚款，该非法单位由有关的行政主管部门予以取缔。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2697509, '《禁止使用童工规定》', '第十条', '劳动', '行政法规', NULL, '国务院 2002-10-01', NULL, NULL, '童工患病或者受伤的，用人单位应当负责送到医疗机构治疗，并负担治疗期间的全部医疗和生活费用。 童工伤残或者死亡的，用人单位由工商行政管理部门吊销营业执照或者由民政部门撤销民办非企业单位登记；用人单位是国家机关、事业单位的，由有关单位依法对直接负责的主管人员和其他直接责任人员给予降级或者撤职的行政处分或者纪律处分；用人单位还应当一次性地对伤残的童工、死亡童工的直系亲属给予赔偿，赔偿金额按照国家工伤保险的有关规定计算。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2697510, '《禁止使用童工规定》', '第十一条', '劳动', '行政法规', NULL, '国务院 2002-10-01', NULL, NULL, '拐骗童工，强迫童工劳动，使用童工从事高空、井下、放射性、高毒、易燃易爆以及国家规定的第四级体力劳动强度的劳动，使用不满14周岁的童工，或者造成童工死亡或者严重伤残的，依照刑法关于拐卖儿童罪、强迫劳动罪或者其他罪的规定，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2697511, '《禁止使用童工规定》', '第十二条', '劳动', '行政法规', NULL, '国务院 2002-10-01', NULL, NULL, '国家行政机关工作人员有下列行为之一的，依法给予记大过或者降级的行政处分；情节严重的，依法给予撤职或者开除的行政处分；构成犯罪的，依照刑法关于滥用职权罪、玩忽职守罪或者其他罪的规定，依法追究刑事责任： (一)劳动保障等有关部门工作人员在禁止使用童工的监督检查工作中发现使用童工的情况，不予制止、纠正、查处的； (二)公安机关的人民警察违反规定发放身份证或者在身份证上登录虚假出生年月的； (三)工商行政管理部门工作人员发现申请人是不满16周岁的未成年人，仍然为其从事个体经营发放营业执照的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2697512, '《禁止使用童工规定》', '第十三条', '劳动', '行政法规', NULL, '国务院 2002-10-01', NULL, NULL, '文艺、体育单位经未成年人的父母或者其他监护人同意，可以招用不满16周岁的专业文艺工作者、运动员。用人单位应当保障被招用的不满16周岁的未成年人的身心健康，保障其接受义务教育的权利。文艺、体育单位招用不满16周岁的专业文艺工作者、运动员的办法，由国务院劳动保障行政部门会同国务院文化、体育行政部门制定。 学校、其他教育机构以及职业培训机构按照国家有关规定组织不满16周岁的未成年人进行不影响其人身安全和身心健康的教育实践劳动、职业技能培训劳动，不属于使用童工。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2697513, '《禁止使用童工规定》', '第十四条', '劳动', '行政法规', NULL, '国务院 2002-10-01', NULL, NULL, '本规定自2002年12月1日起施行。1991年4月15日国务院发布的《禁止使用童工规定》同时废止。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2772500, '《国务院关于职工工作时间的规定》', '第一条', '劳动', '行政法规', NULL, '国务院 1995-03-25', NULL, NULL, '为了合理安排职工的工作和休息时间，维护职工的休息权利，调动职工的积极性，促进社会主义现代化建设事业的发展，根据宪法有关规定，制定本规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2772501, '《国务院关于职工工作时间的规定》', '第二条', '劳动', '行政法规', NULL, '国务院 1995-03-25', NULL, NULL, '本规定适用于在中华人民共和国境内的国家机关、社会团体、企业事业单位以及其他组织的职工。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2772502, '《国务院关于职工工作时间的规定》', '第三条', '劳动', '行政法规', NULL, '国务院 1995-03-25', NULL, NULL, '职工每日工作8小时，每周工作40小时。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2772503, '《国务院关于职工工作时间的规定》', '第四条', '劳动', '行政法规', NULL, '国务院 1995-03-25', NULL, NULL, '在特殊条件下从事劳动和有特殊情况，需要适当缩短工作时间的，按照国家有关规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2772504, '《国务院关于职工工作时间的规定》', '第五条', '劳动', '行政法规', NULL, '国务院 1995-03-25', NULL, NULL, '因工作性质或者生产特点的限制，不能实行每日工作8小时、每周工作40小时标准工时制度的，按照国家有关规定，可以实行其他工作和休息办法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2772505, '《国务院关于职工工作时间的规定》', '第六条', '劳动', '行政法规', NULL, '国务院 1995-03-25', NULL, NULL, '任何单位和个人不得擅自延长职工工作时间。因特殊情况和紧急任务确需延长工作时间的，按照国家有关规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2772506, '《国务院关于职工工作时间的规定》', '第七条', '劳动', '行政法规', NULL, '国务院 1995-03-25', NULL, NULL, '国家机关、事业单位实行统一的工作时间，星期六和星期日为周休息日。 企业和不能实行前款规定的统一工作时间的事业单位，可以根据实际情况灵活安排周休息日。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2772507, '《国务院关于职工工作时间的规定》', '第八条', '劳动', '行政法规', NULL, '国务院 1995-03-25', NULL, NULL, '本规定由劳动部、人事部负责解释；实施办法由劳动部、人事部制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2772508, '《国务院关于职工工作时间的规定》', '第九条', '劳动', '行政法规', NULL, '国务院 1995-03-25', NULL, NULL, '本规定自1995年5月1日起施行。1995年5月1日施行有困难的企业、事业单位，可以适当延期；但是，事业单位最迟应当自1996年1月1日起施行，企业最迟应当自1997年5月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2789000, '《国有企业富余职工安置规定》', '第一条', '劳动', '行政法规', NULL, '国务院 1993-04-20', NULL, NULL, '为了妥善安置国有企业富余职工，增强企业活力，提高企业经济效益，制定本规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2789001, '《国有企业富余职工安置规定》', '第二条', '劳动', '行政法规', NULL, '国务院 1993-04-20', NULL, NULL, '安置国有企业(以下简称企业)中的富余职工，应当遵循企业自行安置为主、社会帮助安置为辅，保障富余职工基本生活的原则。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2789002, '《国有企业富余职工安置规定》', '第三条', '劳动', '行政法规', NULL, '国务院 1993-04-20', NULL, NULL, '企业安置富余职工应当依照本规定采取拓展多种经营、组织劳务活动、发展第三产业、综合利用资源和其它措施。 企业行政主管部门、劳动行政主管部门和工会组织应当指导、帮助和支持企业做好富余职工安置工作，积极创造条件，培育和完善劳务市场，开辟社会安置渠道。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2789003, '《国有企业富余职工安置规定》', '第四条', '劳动', '行政法规', NULL, '国务院 1993-04-20', NULL, NULL, '企业为安置富余职工而兴办的从事第三产业的独立核算企业，自开业之日起两年免征、三年减半征收企业所得税。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2789004, '《国有企业富余职工安置规定》', '第五条', '劳动', '行政法规', NULL, '国务院 1993-04-20', NULL, NULL, '企业开办的劳动就业服务企业，应当承担安置本企业富余职工的任务。企业应当按照国家有关国有资产管理的规定，在资金、场地、原材料和设备等方面给予扶持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2789005, '《国有企业富余职工安置规定》', '第六条', '劳动', '行政法规', NULL, '国务院 1993-04-20', NULL, NULL, '企业组织本企业富余职工依法兴办的独立核算企业，可以承担本企业中原由外单位承包的技术改造或者劳务项目。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2789006, '《国有企业富余职工安置规定》', '第七条', '劳动', '行政法规', NULL, '国务院 1993-04-20', NULL, NULL, '企业可以对富余职工实行待岗和转业培训，培训期间的工资待遇由企业自行确定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2789007, '《国有企业富余职工安置规定》', '第八条', '劳动', '行政法规', NULL, '国务院 1993-04-20', NULL, NULL, '经企业职工代表大会讨论同意并报企业行政主管部门备案，企业可以对职工实行有限期的放假。职工放假期间，由企业发给生活费。 孕期或者哺乳期的女职工，经本人申请，企业可以给予不超过二年的假期，放假期间发给生活费。假期内含产假的，产假期间按照国家规定发给工资。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2789008, '《国有企业富余职工安置规定》', '第九条', '劳动', '行政法规', NULL, '国务院 1993-04-20', NULL, NULL, '职工距退休年龄不到五年的，经本人申请，企业领导批准，可以退出工作岗位休养。职工退出工作岗位休养期间，由企业发给生活费。已经实行退休费用统筹的地方，企业和退出工作岗位休养的职工应当按照有关规定缴纳基本养老保险费。职工退出工作岗位休养期间达到国家规定的退休年龄时，按照规定办理退休手续。职工退出工作岗位休养期间视为工龄，与其以前的工龄合并计算。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2789009, '《国有企业富余职工安置规定》', '第十条', '劳动', '行政法规', NULL, '国务院 1993-04-20', NULL, NULL, '职工可以申请辞职。经企业批准辞职的职工，在办理辞职手续时，企业应当按照国家有关规定发给一次性生活补助费。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2789010, '《国有企业富余职工安置规定》', '第十一条', '劳动', '行政法规', NULL, '国务院 1993-04-20', NULL, NULL, '按照本规定第八条、第九条规定发放的生活费在企业工资基金中列支，生活费标准由企业自主确定，但是不得低于省、自治区、直辖市人民政府规定的最低标准。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2789011, '《国有企业富余职工安置规定》', '第十二条', '劳动', '行政法规', NULL, '国务院 1993-04-20', NULL, NULL, '企业因生产经营发生重大变化，必须裁减职工的，对劳动合同制职工，经企业职工代表大会讨论同意，可以提前解除劳动合同，但是应当按照合同约定履行义务；合同没有约定的，企业对被提前解除劳动合同的职工，按照其在本企业工作的年限，工龄每满一年，发给相当于本人一个月标准工资的补偿费。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2789012, '《国有企业富余职工安置规定》', '第十三条', '劳动', '行政法规', NULL, '国务院 1993-04-20', NULL, NULL, '各级劳动行政主管部门和企业行政主管部门应当做好富余职工的社会安置和调剂工作，鼓励和帮助富余职工组织起来就业和自谋职业。企业之间调剂职工，可以正式调动，也可以临时借调；临时借调的，借调期间的工资和福利待遇由双方企业在协议中商定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2789013, '《国有企业富余职工安置规定》', '第十四条', '劳动', '行政法规', NULL, '国务院 1993-04-20', NULL, NULL, '富余职工由企业自行安置有困难到社会待业的，在待业期间，依法享受待业保险待遇。劳动行政主管部门和有关行政主管部门应当创造条件，帮助职工再就业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2789014, '《国有企业富余职工安置规定》', '第十五条', '劳动', '行政法规', NULL, '国务院 1993-04-20', NULL, NULL, '企业依照本规定兴办的独立核算企业安置的职工，按照国家有关规定纳入新办企业的职工人数和经济指标的统计范围。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2789015, '《国有企业富余职工安置规定》', '第十六条', '劳动', '行政法规', NULL, '国务院 1993-04-20', NULL, NULL, '省、自治区、直辖市人民政府可以根据本规定制定实施办法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2789016, '《国有企业富余职工安置规定》', '第十七条', '劳动', '行政法规', NULL, '国务院 1993-04-20', NULL, NULL, '本规定由国务院劳动行政主管部门负责解释。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2789017, '《国有企业富余职工安置规定》', '第十八条', '劳动', '行政法规', NULL, '国务院 1993-04-20', NULL, NULL, '本规定自发布之日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2802500, '《劳动就业服务企业管理规定》', '第一条', '劳动', '行政法规', NULL, '国务院 1990-11-22', '第一章 总则', NULL, '为巩固和发展劳动就业服务企业，保障其合法权益，加强管理，促进城镇劳动就业工作的开展，制定本规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2802501, '《劳动就业服务企业管理规定》', '第二条', '劳动', '行政法规', NULL, '国务院 1990-11-22', '第一章 总则', NULL, '劳动就业服务企业是承担安置城镇待业人员任务、由国家和社会扶持、进行生产经营自救的集体所有制经济组织。 前款所称承担安置城镇待业人员任务，是指： (一)劳动就业服务企业开办时，从业人员中百分之六十以上(含百分之六十)为城镇待业人员； (二)劳动就业服务企业存续期间，根据当地就业安置任务和企业常年生产经营情况按一定比例安置城镇待业人员。 本规定所称城镇待业人员，是指城镇居民中持有待业证明的未就过业的人员和曾就过业又失业的人员。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2802502, '《劳动就业服务企业管理规定》', '第三条', '劳动', '行政法规', NULL, '国务院 1990-11-22', '第一章 总则', NULL, '国家对劳动就业服务企业实行扶持政策，鼓励社会各方面依法扶持兴办各种形式的劳动就业服务企业。 各级人民政府及其行业主管部门应当重视和加强对劳动就业服务企业的领导，把巩固和发展劳动就业服务企业作为解决城镇就业问题的重要途径，将其纳入国民经济和社会发展计划，促进城镇劳动就业工作的开展。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2802503, '《劳动就业服务企业管理规定》', '第四条', '劳动', '行政法规', NULL, '国务院 1990-11-22', '第一章 总则', NULL, '国家对劳动就业服务企业给予下列税收优惠： (一)新开办的劳动就业服务企业免征所得税二至三年； (二)免税期满后，继续承担安置城镇待业人员任务并达到一定比例的，享受相应的减免税优惠； (三)适当调低劳动就业服务企业所得税的税率。 上述税收优惠的具体实施办法，由国家税务局商劳动部等有关部门制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2802504, '《劳动就业服务企业管理规定》', '第五条', '劳动', '行政法规', NULL, '国务院 1990-11-22', '第一章 总则', NULL, '国家在开办条件、物资供应、固定资产和流动资金贷款等方面对劳动就业服务企业予以支持和照顾。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2802505, '《劳动就业服务企业管理规定》', '第六条', '劳动', '行政法规', NULL, '国务院 1990-11-22', '第一章 总则', NULL, '国家保护劳动就业服务企业的合法权益。禁止任何机关和单位非法改变劳动就业服务企业的集体所有制性质、干预企业自主权和向企业平调或者摊派人力、物力和财力。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2802506, '《劳动就业服务企业管理规定》', '第七条', '劳动', '行政法规', NULL, '国务院 1990-11-22', '第一章 总则', NULL, '劳动就业服务企业必须贯彻执行国家的方针、政策和法律、法规，坚持社会主义方向，坚持以安置待业人员为主、安置效益和经济效益相结合的原则。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2802507, '《劳动就业服务企业管理规定》', '第八条', '劳动', '行政法规', NULL, '国务院 1990-11-22', '第二章 政府对劳动就业服务企业的管理', NULL, '开办劳动就业服务企业，须经审批机关批准，并经同级工商行政管理机关核准登记，领取《企业法人营业执照》或者《营业执照》后始得经营。 前款所称审批机关批准是指： (一)有主办或者扶持单位的劳动就业服务企业，经主办或者扶持单位的主管部门审查同意，由同级劳动部门认定其劳动就业服务企业的性质； (二)待业人员自筹资金开办的劳动就业服务企业，由当地县(区)以上劳动部门批准。 劳动就业服务企业应当在核准登记的经营范围内从事生产经营活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2802508, '《劳动就业服务企业管理规定》', '第九条', '劳动', '行政法规', NULL, '国务院 1990-11-22', '第二章 政府对劳动就业服务企业的管理', NULL, '各级人民政府的劳动部门对本地区劳动就业服务企业的职责是： (一)指导和监督劳动就业服务企业贯彻执行国家有关方针、政策和法律、法规； (二)制定劳动就业服务企业的地区发展规划； (三)根据国家有关规定，运用就业经费和生产扶持基金，推动劳动就业服务企业的发展，扩大其安置待业人员的能力； (四)开展技术培训，开辟物资渠道，组织技术咨询和信息交流，为劳动就业服务企业提供服务； (五)指导劳动部门所属的劳动就业服务企业的管理活动及其干部的管理和培养工作，开展评选先进集体和个人的活动； (六)省、自治区、直辖市(含计划单列市，下同)人民政府的劳动部门组织本地区的劳动就业服务企业开展产品评优、企业升级的工作。 各级劳动部门的就业服务机构，按照国务院和省、自治区、直辖市人民政府的规定，可以承担上款各项的有关具体工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2802509, '《劳动就业服务企业管理规定》', '第十条', '劳动', '行政法规', NULL, '国务院 1990-11-22', '第二章 政府对劳动就业服务企业的管理', NULL, '各行业主管部门对本部门劳动就业服务企业的职责是： (一)指导和监督劳动就业服务企业贯彻执行国家有关方针、政策和法律、法规； (二)制定劳动就业服务企业的部门发展规划，协助企业筹措发展资金； (三)协调劳动就业服务企业与部门内各有关方面的关系； (四)开展技术培训，为劳动就业服务企业提供咨询，组织物资、生产、技术等信息交流； (五)帮助劳动就业服务企业进行新产品鉴定和科研成果鉴定； (六)指导本部门所属的劳动就业服务企业的干部管理和培养工作，开展评选先进集体和个人的活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2802510, '《劳动就业服务企业管理规定》', '第十一条', '劳动', '行政法规', NULL, '国务院 1990-11-22', '第三章 主办或者扶持单位与劳动就业服务企业的关系', NULL, '企业、事业单位、机关、团体、部队等主办或者扶持单位(简称主办或者扶持单位，下同)对所主办或者扶持开办的劳动就业服务企业的职责是： (一)劳动就业服务企业开办时，为企业筹措开办资金，帮助企业办理审批和工商登记手续； (二)为劳动就业服务企业安置待业人员提供一定的生产经营条件； (三)协调劳动就业服务企业与各方面的关系； (四)在劳动就业服务企业兴办初期，指导企业制定管理制度，任用、招聘或者组织民主选举企业的厂长(经理)； (五)尊重并维护劳动就业服务企业在人财物、产供销等方面的管理自主权； (六)在平等互利、等价交换的原则基础上，同劳动就业服务企业开展生产经营和服务等方面的合作活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2802511, '《劳动就业服务企业管理规定》', '第十二条', '劳动', '行政法规', NULL, '国务院 1990-11-22', '第三章 主办或者扶持单位与劳动就业服务企业的关系', NULL, '主办或者扶持单位应当按照国家有关规定积极支持本单位职工到劳动就业服务企业担任生产经营和技术等方面的管理职务。 主办或者扶持单位的职工到劳动就业服务企业任职，应当逐步实行聘任制，由主办或者扶持单位、任职人员和劳动就业服务企业三方签订聘用合同。聘用合同应当以书面形式订立，其主要内容应当包括： (一)聘用人员的职责； (二)聘用人员的待遇； (三)聘用期限； (四)违约责任及其处理办法； (五)三方认为应当规定的其他内容。 聘用合同一经依法订立即具法律约束力，三方均应当认真履行，不得擅自改变。 聘任期满后可以续聘。 聘用合同书应当报劳动就业服务企业主管部门和劳动部门备案。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2802512, '《劳动就业服务企业管理规定》', '第十三条', '劳动', '行政法规', NULL, '国务院 1990-11-22', '第三章 主办或者扶持单位与劳动就业服务企业的关系', NULL, '全民所有制的主办或者扶持单位的职工被劳动就业服务企业聘用后，仍保留其在原单位的全民所有制职工的身份和待遇。 聘用人员退休后回原单位领取退休金并享受退休人员的一切待遇。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2802513, '《劳动就业服务企业管理规定》', '第十四条', '劳动', '行政法规', NULL, '国务院 1990-11-22', '第三章 主办或者扶持单位与劳动就业服务企业的关系', NULL, '主办或者扶持单位对支持劳动就业服务企业的资金、设备等，应当坚持有偿使用原则： (一)扶持资金(限于主办或者扶持单位的自有资金)可以作为借用款由劳动就业服务企业按双方约定分期归还，也可以依法作为投资参与劳动就业服务企业的利润分配； (二)设备、工具等生产资料和厂房可以在合理作价的基础上由劳动就业服务企业一次或分期付清；主办或者扶持单位也可以采用出租形式，收取相当于折旧费的租金。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2802514, '《劳动就业服务企业管理规定》', '第十五条', '劳动', '行政法规', NULL, '国务院 1990-11-22', '第四章 劳动就业服务企业的内部管理', NULL, '劳动就业服务企业实行民主管理。除下列情况外，劳动就业服务企业的内部管理按国家有关城镇集体所有制企业的法律、法规的规定执行： (一)本规定第十一条(四)所规定的情况； (二)以全民所有制企业为主办单位的劳动就业服务企业，其厂长(经理)人选可以由主办单位提出，由主办单位和劳动就业服务企业共同确定。厂长(经理)实行任期制。在厂长(经理)任期内，无法定理由，主办单位和劳动就业服务企业均不得擅自对厂长(经理)予以罢免或调动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2802515, '《劳动就业服务企业管理规定》', '第十六条', '劳动', '行政法规', NULL, '国务院 1990-11-22', '第四章 劳动就业服务企业的内部管理', NULL, '劳动就业服务企业可以实行多种形式的生产经营责任制，但任何一种生产经营责任制均应当以安置待业人员作为责任制的一项重要内容。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2802516, '《劳动就业服务企业管理规定》', '第十七条', '劳动', '行政法规', NULL, '国务院 1990-11-22', '第四章 劳动就业服务企业的内部管理', NULL, '劳动就业服务企业应当按照灵活方便、合同管理、骨干稳定、合理流动的原则，自主选择用工形式。 从业人员在劳动就业服务企业工作期间应当计算工龄。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2802517, '《劳动就业服务企业管理规定》', '第十八条', '劳动', '行政法规', NULL, '国务院 1990-11-22', '第四章 劳动就业服务企业的内部管理', NULL, '劳动就业服务企业根据自身情况可以有条件地适当安排全民所有制主办单位的富余人员在本企业就业。安置富余人员应当由劳动就业服务企业同全民所有制主办单位双方签订安置合同，合同内容由双方商定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2802518, '《劳动就业服务企业管理规定》', '第十九条', '劳动', '行政法规', NULL, '国务院 1990-11-22', '第四章 劳动就业服务企业的内部管理', NULL, '劳动就业服务企业可以根据国家有关规定和企业经济效益，自主地确定适合本企业具体情况的工资和奖金的分配形式和办法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2802519, '《劳动就业服务企业管理规定》', '第二十条', '劳动', '行政法规', NULL, '国务院 1990-11-22', '第四章 劳动就业服务企业的内部管理', NULL, '劳动就业服务企业对职工个人出资可以实行付息或者分红的办法。企业盈利，按一定比例付息或者分红；企业亏损，在弥补亏损之前，不得付息或者分红。付息或者分红的比例不得超过国家规定的最高限额。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2802520, '《劳动就业服务企业管理规定》', '第二十一条', '劳动', '行政法规', NULL, '国务院 1990-11-22', '第四章 劳动就业服务企业的内部管理', NULL, '由待业人员自筹资金开办的劳动就业服务企业，在企业具备偿还能力时，可以逐步偿还个人出资。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2802521, '《劳动就业服务企业管理规定》', '第二十二条', '劳动', '行政法规', NULL, '国务院 1990-11-22', '第四章 劳动就业服务企业的内部管理', NULL, '劳动就业服务企业应当建立养老保险制度并逐步建立待业保险制度。保险基金提取办法和保险项目按国家有关规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2802522, '《劳动就业服务企业管理规定》', '第二十三条', '劳动', '行政法规', NULL, '国务院 1990-11-22', '第四章 劳动就业服务企业的内部管理', NULL, '劳动就业服务企业应当执行国家有关财务制度和财经纪律，健全财务管理，接受国家有关主管部门的指导和监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2802523, '《劳动就业服务企业管理规定》', '第二十四条', '劳动', '行政法规', NULL, '国务院 1990-11-22', '第五章 法律责任', NULL, '违反本规定第八条的规定，以劳动就业服务企业名义进行活动的，由工商行政管理机关根据国家有关规定给予行政处罚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2802524, '《劳动就业服务企业管理规定》', '第二十五条', '劳动', '行政法规', NULL, '国务院 1990-11-22', '第五章 法律责任', NULL, '任何机关和单位违反本规定第六条的规定，非法改变劳动就业服务企业的集体所有制性质，干预企业自主权的，其上级主管部门应当予以纠正；向劳动就业服务企业平调或者摊派人力、物力、财力的，必须予以赔偿。对负有直接责任的主管人员和其他直接责任人员，由其主管部门根据情节轻重，给予行政处分；构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2802525, '《劳动就业服务企业管理规定》', '第二十六条', '劳动', '行政法规', NULL, '国务院 1990-11-22', '第五章 法律责任', NULL, '劳动就业服务企业违反本规定有关企业领导人员的产生、罢免程序规定的，其主管部门应当予以纠正，并追究直接责任人员的行政责任。 劳动就业服务企业的主管部门或者主办、扶持单位违反本规定有关劳动就业服务企业领导人员产生、罢免程序规定的，其上一级主管部门或者主办、扶持单位的主管部门应当予以纠正，并追究直接责任人员的行政责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2802526, '《劳动就业服务企业管理规定》', '第二十七条', '劳动', '行政法规', NULL, '国务院 1990-11-22', '第六章 附则', NULL, '除本规定有明文规定者外，劳动就业服务企业均应当执行国家有关城镇集体所有制企业的政策和法规。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2802527, '《劳动就业服务企业管理规定》', '第二十八条', '劳动', '行政法规', NULL, '国务院 1990-11-22', '第六章 附则', NULL, '省、自治区、直辖市人民政府和国务院各行业主管部门可以根据本规定并结合本地区、本部门的具体情况制定实施办法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2802528, '《劳动就业服务企业管理规定》', '第二十九条', '劳动', '行政法规', NULL, '国务院 1990-11-22', '第六章 附则', NULL, '本规定由劳动部负责解释。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2802529, '《劳动就业服务企业管理规定》', '第三十条', '劳动', '行政法规', NULL, '国务院 1990-11-22', '第六章 附则', NULL, '本规定从发布之日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2814500, '《关于工资总额组成的规定》', '第一条', '劳动', '行政法规', NULL, '国务院 1990-01-01', '第一章 总则', NULL, '为了统一工资总额的计算范围，保证国家对工资进行统一的统计核算和会计核算，有利于编制、检查计划和进行工资管理以及正确地反映职工的工资收入，制定本规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2814501, '《关于工资总额组成的规定》', '第二条', '劳动', '行政法规', NULL, '国务院 1990-01-01', '第一章 总则', NULL, '全民所有制和集体所有制企业、事业单位，各种合营单位，各级国家机关、政党机关和社会团体，在计划、统计、会计上有关工资总额范围的计算，均应遵守本规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2814502, '《关于工资总额组成的规定》', '第三条', '劳动', '行政法规', NULL, '国务院 1990-01-01', '第一章 总则', NULL, '工资总额是指各单位在一定时期内直接支付给本单位全部职工的劳动报酬总额。 工资总额的计算应以直接支付给职工的全部劳动报酬为根据。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2814503, '《关于工资总额组成的规定》', '第四条', '劳动', '行政法规', NULL, '国务院 1990-01-01', '第二章 工资总额的组成', NULL, '工资总额由下列6个部分组成： (一)计时工资； (二)计件工资； (三)奖金； (四)津贴和补贴； (五)加班加点工资； (六)特殊情况下支付的工资。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2814504, '《关于工资总额组成的规定》', '第五条', '劳动', '行政法规', NULL, '国务院 1990-01-01', '第二章 工资总额的组成', NULL, '计时工资是指按计时工资标准(包括地区生活费补贴)和工作时间支付给个人的劳动报酬。包括： (一)对已做工作按计时工资标准支付的工资； (二)实行结构工资制的单位支付给职工的基础工资和职务(岗位)工资； (三)新参加工作职工的见习工资(学徒的生活费)； (四)运动员体育津贴。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2814505, '《关于工资总额组成的规定》', '第六条', '劳动', '行政法规', NULL, '国务院 1990-01-01', '第二章 工资总额的组成', NULL, '计件工资是指对已做工作按计件单价支付的劳动报酬。包括： (一)实行超额累进计件、直接无限计件、限额计件、超定额计件等工资制，按劳动部门或主管部门批准的定额和计件单价支付给个人的工资； (二)按工作任务包干方法支付给个人的工资； (三)按营业额提成或利润提成办法支付给个人的工资。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2814506, '《关于工资总额组成的规定》', '第七条', '劳动', '行政法规', NULL, '国务院 1990-01-01', '第二章 工资总额的组成', NULL, '奖金是指支付给职工的超额劳动报酬和增收节支的劳动报酬。包括： (一)生产奖； (二)节约奖； (三)劳动竞赛奖； (四)机关、事业单位的奖励工资； (五)其他奖金。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2814507, '《关于工资总额组成的规定》', '第八条', '劳动', '行政法规', NULL, '国务院 1990-01-01', '第二章 工资总额的组成', NULL, '津贴和补贴是指为了补偿职工特殊或额外的劳动消耗和因其他特殊原因支付给职工的津贴，以及为了保证职工工资水平不受物价影响支付给职工的物价补贴。 (一)津贴。包括：补偿职工特殊或额外劳动消耗的津贴，保健性津贴，技术性津贴，年功性津贴及其他津贴。 (二)物价补贴。包括：为保证职工工资水平不受物价上涨或变动影响而支付的各种补贴。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2814508, '《关于工资总额组成的规定》', '第九条', '劳动', '行政法规', NULL, '国务院 1990-01-01', '第二章 工资总额的组成', NULL, '加班加点工资是指按规定支付的加班工资和加点工资。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2814509, '《关于工资总额组成的规定》', '第十条', '劳动', '行政法规', NULL, '国务院 1990-01-01', '第二章 工资总额的组成', NULL, '特殊情况下支付的工资。包括： (一)根据国家法律、法规和政策规定，因病、工伤、产假、计划生育假、婚丧假、事假、探亲假、定期休假、停工学习、执行国家或社会义务等原因按计时工资标准或计时工资标准的一定比例支付的工资； (二)附加工资、保留工资。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2814510, '《关于工资总额组成的规定》', '第十一条', '劳动', '行政法规', NULL, '国务院 1990-01-01', '第三章 工资总额不包括的项目', NULL, '下列各项不列入工资总额的范围： (一)根据国务院发布的有关规定颁发的创造发明奖、自然科学奖、科学技术进步奖和支付的合理化建议和技术改进奖以及支付给运动员、教练员的奖金； (二)有关劳动保险和职工福利方面的各项费用； (三)有关离休、退休、退职人员待遇的各项支出； (四)劳动保护的各项支出； (五)稿费、讲课费及其他专门工作报酬； (六)出差伙食补助费、误餐补助、调动工作的旅费和安家费； (七)对自带工具、牲畜来企业工作职工所支付的工具、牲畜等的补偿费用； (八)实行租赁经营单位的承租人的风险性补偿收入； (九)对购买本企业股票和债券的职工所支付的股息(包括股金分红)和利息； (十)劳动合同制职工解除劳动合同时由企业支付的医疗补助费、生活补助费等； (十一)因录用临时工而在工资以外向提供劳动力单位支付的手续费或管理费； (十二)支付给家庭工人的加工费和按加工订货办法支付给承包单位的发包费用； (十三)支付给参加企业劳动的在校学生的补贴； (十四)计划生育独生子女补贴。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2814511, '《关于工资总额组成的规定》', '第十二条', '劳动', '行政法规', NULL, '国务院 1990-01-01', '第三章 工资总额不包括的项目', NULL, '前条所列各项按照国家规定另行统计。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2814512, '《关于工资总额组成的规定》', '第十三条', '劳动', '行政法规', NULL, '国务院 1990-01-01', '第四章 附则', NULL, '中华人民共和国境内的私营单位、华侨及港、澳、台工商业者经营单位和外商经营单位有关工资总额范围的计算，参照本规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2814513, '《关于工资总额组成的规定》', '第十四条', '劳动', '行政法规', NULL, '国务院 1990-01-01', '第四章 附则', NULL, '本规定由国家统计局负责解释。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2814514, '《关于工资总额组成的规定》', '第十五条', '劳动', '行政法规', NULL, '国务院 1990-01-01', '第四章 附则', NULL, '各地区、各部门可依据本规定制定有关工资总额组成的具体范围的规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2814515, '《关于工资总额组成的规定》', '第十六条', '劳动', '行政法规', NULL, '国务院 1990-01-01', '第四章 附则', NULL, '本规定自发布之日起施行。国务院1955年5月21日批准颁发的《关于工资总额组成的暂行规定》同时废止。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2868500, '《国务院关于高级专家离休退休若干问题的暂行规定》', '第一条', '劳动', '行政法规', NULL, '国务院 1983-09-12', NULL, NULL, '本规定所称高级专家，系指：正副教授、正副研究员、高级工程师、高级农艺师、正副主任医师、正副编审、正副译审、正副研究馆员、高级经济师、高级统计师、高级会计师、特级记者、高级记者、高级工艺美术师，以及文艺六级以上的专家。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2868501, '《国务院关于高级专家离休退休若干问题的暂行规定》', '第二条', '劳动', '行政法规', NULL, '国务院 1983-09-12', NULL, NULL, '高级专家离休退休年龄，一般应按国家统一规定执行。对其中少数高级专家，确因工作需要，身体能够坚持正常工作，征得本人同意，经下述机关批准，其离休退休年龄可以适当延长： 副教授、副研究员以及相当这一级职称的高级专家，经所在单位报请上一级主管机关批准，可以适当延长离休退休年龄，但最长不超过六十五周岁； 教授、研究员以及相当这一级职称的高级专家，经所在单位报请省、市、自治区人民政府或中央、国家机关的部委批准，可以延长离休退休年龄，但最长不超过七十周岁； 学术上造诣高深、在国内外有重大影响的杰出高级专家，经国务院批准，可以暂缓离休退休，继续从事研究或著述工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2868502, '《国务院关于高级专家离休退休若干问题的暂行规定》', '第三条', '劳动', '行政法规', NULL, '国务院 1983-09-12', NULL, NULL, '延长离休退休年龄的高级专家中，担任行政领导职务或管理职务的，在达到国家统一规定的离休退休年龄时，应当免去其行政领导职务或管理职务，使他们集中精力继续从事科学技术或文化艺术等工作。特殊情况经过任免机关批准的除外。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2868503, '《国务院关于高级专家离休退休若干问题的暂行规定》', '第四条', '劳动', '行政法规', NULL, '国务院 1983-09-12', NULL, NULL, '高级专家离休退休的待遇，按国家统一规定办理。符合以下情况的，退休费标准可以适当提高： (一)有重大贡献的高级专家，经省、市、自治区人民政府或中央、国家机关的部委批准，其退休费标准可以酌情提高5%—15%。提高标准后的退休费，不得超过本人原标准工资。 (二)建国后从国外或者从香港、澳门、台湾回来定居工作的高级专家，其退休费均按建国后参加革命工作退休干部的最高标准发给。其中有重大贡献的，再按本条(一)项规定提高退休费。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2868504, '《国务院关于高级专家离休退休若干问题的暂行规定》', '第五条', '劳动', '行政法规', NULL, '国务院 1983-09-12', NULL, NULL, '高级专家离休退休后，如身体尚好，可以接受部门或单位的聘请，担任科学技术或文化艺术顾问，也可以直接承担业务工作。聘请离休退休高级专家应签订聘请合同，聘请条件和受聘人员待遇按国家有关规定办理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2868505, '《国务院关于高级专家离休退休若干问题的暂行规定》', '第六条', '劳动', '行政法规', NULL, '国务院 1983-09-12', NULL, NULL, '各单位和各部门要认真执行国务院关于干部离休退休后政治、生活待遇的有关规定，对离休退休的高级专家应体贴关怀，热情爱护；要积极主动地帮助他们继续进行科学研究、资料整理、著书立说等工作，为他们的业务活动提供必要的方便。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2868506, '《国务院关于高级专家离休退休若干问题的暂行规定》', '第七条', '劳动', '行政法规', NULL, '国务院 1983-09-12', NULL, NULL, '本规定自发布之日起施行。本规定发布以前，已经离休退休的高级专家，不再复职。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2868507, '《国务院关于高级专家离休退休若干问题的暂行规定》', '第八条', '劳动', '行政法规', NULL, '国务院 1983-09-12', NULL, NULL, '本规定由劳动人事部负责解释。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (3012000, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第一条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '具备合法经营资格的承包人将承包业务转包或者分包给不具备合法经营资格的组织或者个人，该组织或者个人招用的劳动者请求确认承包人为承担用工主体责任单位，承担支付劳动报酬、认定工伤后的工伤保险待遇等责任的，人民法院依法予以支持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (3012001, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第二条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '不具备合法经营资格的组织或者个人挂靠具备合法经营资格的单位对外经营，该组织或者个人招用的劳动者请求确认被挂靠单位为承担用工主体责任单位，承担支付劳动报酬、认定工伤后的工伤保险待遇等责任的，人民法院依法予以支持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (3012002, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第三条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '劳动者被多个存在关联关系的单位交替或者同时用工，其请求确认劳动关系的，人民法院按照下列情形分别处理： （一）已订立书面劳动合同，劳动者请求按照劳动合同确认劳动关系的，人民法院依法予以支持； （二）未订立书面劳动合同的，根据用工管理行为，综合考虑工作时间、工作内容、劳动报酬支付、社会保险费缴纳等因素确认劳动关系。 劳动者请求符合前款第二项规定情形的关联单位共同承担支付劳动报酬、福利待遇等责任的，人民法院依法予以支持，但关联单位之间依法对劳动者的劳动报酬、福利待遇等作出约定且经劳动者同意的除外。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (3012003, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第四条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '外国人与中华人民共和国境内的用人单位建立用工关系，有下列情形之一，外国人请求确认与用人单位存在劳动关系的，人民法院依法予以支持： （一）已取得永久居留资格的； （二）已取得工作许可且在中国境内合法停留居留的； （三）按照国家有关规定办理相关手续的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (3012004, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第五条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '依法设立的外国企业常驻代表机构可以作为劳动争议案件的当事人。当事人申请追加外国企业参加诉讼的，人民法院依法予以支持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (3012005, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第六条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '用人单位未依法与劳动者订立书面劳动合同，应当支付劳动者的二倍工资按月计算；不满一个月的，按该月实际工作日计算。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (3012006, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第七条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '劳动者以用人单位未订立书面劳动合同为由，请求用人单位支付二倍工资的，人民法院依法予以支持，但用人单位举证证明存在下列情形之一的除外： （一）因不可抗力导致未订立的； （二）因劳动者本人故意或者重大过失未订立的； （三）法律、行政法规规定的其他情形。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (3012007, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第八条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '劳动合同期满，有下列情形之一的，人民法院认定劳动合同期限依法自动续延，不属于用人单位未订立书面劳动合同的情形： （一）劳动合同法第四十二条规定的用人单位不得解除劳动合同的； （二）劳动合同法实施条例第十七条规定的服务期尚未到期的； （三）工会法第十九条规定的任期未届满的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (3012008, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第九条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '有证据证明存在劳动合同法第十四条第三款规定的“视为用人单位与劳动者已订立无固定期限劳动合同”情形，劳动者请求与用人单位订立书面劳动合同的，人民法院依法予以支持；劳动者以用人单位未及时补订书面劳动合同为由，请求用人单位支付视为已与劳动者订立无固定期限劳动合同期间二倍工资的，人民法院不予支持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (3012009, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第十条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '有下列情形之一的，人民法院应认定为符合劳动合同法第十四条第二款第三项“连续订立二次固定期限劳动合同”的规定： （一）用人单位与劳动者协商延长劳动合同期限累计达到一年以上，延长期限届满的； （二）用人单位与劳动者约定劳动合同期满后自动续延，续延期限届满的； （三）劳动者非因本人原因仍在原工作场所、工作岗位工作，用人单位变换劳动合同订立主体，但继续对劳动者进行劳动管理，合同期限届满的； （四）以其他违反诚信原则的规避行为再次订立劳动合同，期限届满的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (3012010, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第十一条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '劳动合同期满后，劳动者仍在用人单位工作，用人单位未表示异议超过一个月，劳动者请求用人单位以原条件续订劳动合同的，人民法院依法予以支持。 符合订立无固定期限劳动合同情形，劳动者请求用人单位以原条件订立无固定期限劳动合同的，人民法院依法予以支持。 用人单位解除劳动合同，劳动者请求用人单位依法承担解除劳动合同法律后果的，人民法院依法予以支持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (3012011, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第十二条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '除向劳动者支付正常劳动报酬外，用人单位与劳动者约定服务期限并提供特殊待遇，劳动者违反约定提前解除劳动合同且不符合劳动合同法第三十八条规定的单方解除劳动合同情形时，用人单位请求劳动者承担赔偿损失责任的，人民法院可以综合考虑实际损失、当事人的过错程度、已经履行的年限等因素确定劳动者应当承担的赔偿责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (3012012, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第十三条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '劳动者未知悉、接触用人单位的商业秘密和与知识产权相关的保密事项，劳动者请求确认竞业限制条款不生效的，人民法院依法予以支持。 竞业限制条款约定的竞业限制范围、地域、期限等内容与劳动者知悉、接触的商业秘密和与知识产权相关的保密事项不相适应，劳动者请求确认竞业限制条款超过合理比例部分无效的，人民法院依法予以支持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (3012013, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第十四条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '用人单位与高级管理人员、高级技术人员和其他负有保密义务的人员约定在职期间竞业限制条款，劳动者以不得约定在职期间竞业限制、未支付经济补偿为由请求确认竞业限制条款无效的，人民法院不予支持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (3012014, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第十五条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '劳动者违反有效的竞业限制约定，用人单位请求劳动者按照约定返还已经支付的经济补偿并支付违约金的，人民法院依法予以支持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (3012015, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第十六条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '用人单位违法解除或者终止劳动合同后，有下列情形之一的，人民法院可以认定为劳动合同法第四十八条规定的“劳动合同已经不能继续履行”： （一）劳动合同在仲裁或者诉讼过程中期满且不存在应当依法续订、续延劳动合同情形的； （二）劳动者开始依法享受基本养老保险待遇的； （三）用人单位被宣告破产的； （四）用人单位解散的，但因合并或者分立需要解散的除外； （五）劳动者已经与其他用人单位建立劳动关系，对完成用人单位的工作任务造成严重影响，或者经用人单位提出，不与其他用人单位解除劳动合同的； （六）存在劳动合同客观不能履行的其他情形的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (3012016, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第十七条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '用人单位未按照国务院安全生产监督管理部门、卫生行政部门的规定组织从事接触职业病危害作业的劳动者进行离岗前的职业健康检查，劳动者在双方解除劳动合同后请求继续履行劳动合同的，人民法院依法予以支持，但有下列情形之一的除外： （一）一审法庭辩论终结前，用人单位已经组织劳动者进行职业健康检查且经检查劳动者未患职业病的； （二）一审法庭辩论终结前，用人单位组织劳动者进行职业健康检查，劳动者无正当理由拒绝检查的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (3012017, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第十八条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '用人单位违法解除、终止可以继续履行的劳动合同，劳动者请求用人单位支付违法解除、终止决定作出后至劳动合同继续履行前一日工资的，用人单位应当按照劳动者提供正常劳动时的工资标准向劳动者支付上述期间的工资。 用人单位、劳动者对于劳动合同解除、终止都有过错的，应当各自承担相应的责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (3012018, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第十九条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '用人单位与劳动者约定或者劳动者向用人单位承诺无需缴纳社会保险费的，人民法院应当认定该约定或者承诺无效。用人单位未依法缴纳社会保险费，劳动者根据劳动合同法第三十八条第一款第三项规定请求解除劳动合同、由用人单位支付经济补偿的，人民法院依法予以支持。 有前款规定情形，用人单位依法补缴社会保险费后，请求劳动者返还已支付的社会保险费补偿的，人民法院依法予以支持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (3012019, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第二十条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '当事人在仲裁期间因自身原因未提出仲裁时效抗辩，在一审或者二审诉讼期间提出仲裁时效抗辩的，人民法院不予支持。当事人基于新的证据能够证明对方当事人请求权的仲裁时效期间届满的，人民法院应予支持。 当事人未按照前款规定提出仲裁时效抗辩，以仲裁时效期间届满为由申请再审或者提出再审抗辩的，人民法院不予支持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (3012020, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第二十一条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '本解释自2025年9月1日起施行。《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》（法释〔2020〕26号）第三十二条第一款同时废止。最高人民法院此前发布的司法解释与本解释不一致的，以本解释为准。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
